class BIT{
        ll n;
  		vector<ll> bitree;
    public:
    	BIT(unsigned long _n) : bitree(_n + 1, 0){
          n = _n;
        }
    	void add(ll id, ll x){
          while(id <= n){
            bitree[id] += x;
            id += id & -id;
          }
          return;
        }
    	ll sum(ll id){
          ll temp = 0;
          while(id > 0){
            temp += bitree[id];
            id -= id & -id;
          }
          return temp;
        }
  };

