struct UnionFind {
  vector<int> data;
  UnionFind(int size) : data(size, -1) { }
  bool unionSet(int x, int y) {
    x = root(x); y = root(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y]; data[y] = x;
    }
    return x != y;
  }
  bool findSet(int x, int y) {
    return root(x) == root(y);
  }
  int root(int x) {
    return data[x] < 0 ? x : data[x] = root(data[x]);
  }
  int size(int x) {
    return -data[root(x)];
  }
};

int N;
int x[200000], y[200000];
int a[200000];
int r_min[200000];

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << setprecision(10) << fixed;
    cin >> N;
    for(int i = 0; i < N; i++) {
        cin >> x[i] >> y[i]; x[i]--; y[i]--;
    }

    for(int i = 0; i < N; i++){
        a[x[i]] = y[i];
        r_min[x[i]] = y[i];
    }
    UnionFind uf(N);
    set<P> st;
    for(int i = 0; i < N; i++){
        auto p = st.begin();
        vector<P> smaller;
        while(p != st.end()){
            if(p->first < a[i]){
                smaller.push_back(*p);
            }else{
                break;
            }
            p++;
        }
        for(P p : smaller){
            st.erase(p);
            int idx = p.second;
            uf.unionSet(i, idx);
            int r = uf.root(i);
            r_min[i] = min(r_min[r], r_min[idx]);
            r_min[r] = min(r_min[r], r_min[idx]);
            r_min[idx] = min(r_min[r], r_min[idx]);
        }
        int r = uf.root(i);
        st.insert(P(r_min[r], r));
    }
    for(int i = 0; i < N; i++) cout << uf.size(x[i]) << endl;
}

