union_find::union_find(ll n){
    par.resize(n);
    ran.resize(n, 0);
    m_size.resize(n, 1);
    rep(i,n) par[i] = i;
};

ll union_find::find(ll x) {
    if (par[x] == x) return x;
    else return par[x] = find(par[x]);
};

void union_find::unite(ll x, ll y) {
    x = find(x);
    y = find(y);
    if (x == y) return;
    ll t = size(x)+size(y);
    m_size[x] = m_size[y] = t;
    if (ran[x] < ran[y]) {
        par[x] = y;
        //size[y] += size[x];
    } else {
        par[y] = x;
        //ize[x] += size[y];
        if (ran[x]==ran[y]) ran[x]++;
    }
};

ll union_find::size(ll x) {
    if (par[x] == x) return m_size[x];
    return size(par[x] = find(par[x]));
}

bool union_find::same(ll x, ll y) {
    return (find(x) == find(y));
};

typedef tuple<ll, ll, ll> T;
int main(int argc, char const *argv[]) {
    int n; cin>>n;
    vector<T> a;
    union_find uf(n);
    vector<int> id(n+1);
    rep(i,n) {
        ll x,y; cin>>x>>y;
        id[y] = i;
        a.emplace_back(x,y,i);
    }
    sort(a.begin(), a.end());
    SegTree<ll> lef((size_t)n, INF, [](ll a, ll b) { return min(a, b); }, [](ll i, ll x) { return x; });
    SegTree<ll> rig((size_t)n, -INF, [](ll a, ll b) { return max(a, b); }, [](ll i, ll x) { return x; });

    rep(i,n) {
        int y = get<1>(a[i]);
        lef.change(i, y);
    }

    vector<ll> ans(n);
    for (int i = n-1; i >= 0; --i) {
        int y = get<1>(a[i]);
        int idx = get<2>(a[i]);
        ll mini = lef.query(0, i);
        ll maxi = rig.query(i, n+1);
        /*
        cout << "y = " << y << '\n';
        cout << "mini = " << mini << '\n';
        cout << "maxi = "<< maxi << '\n';
