void unite(int a, int b) {
	a = get(a), b = get(b);
	if (sz[a] < sz[b]) {
		swap(a, b);
	}
	sz[a] += sz[b];
	p[b] = a;
}

void solve() {
	cin >> n;
	for (int i = 1; i <= n; ++i) {
		p[i] = i;
		sz[i] = 1;
	}
	for (int i = 1; i <= n; ++i) {
		cin >> x[i] >> y[i];
	}
	vector <pair <pair <int, int>, int> > pr;
	for (int i = 1; i <= n; ++i) {
		pr.push_back({{x[i], y[i]}, i});
	}
	sort(pr.begin(), pr.end());
	set <pair <pair <int, int>, int> > st;
	for (int i = n - 1; i >= 0; i--) {
		auto p = pr[i].first;
		auto it = st.upper_bound({{p.second, 0}, 0});
		while (it != st.end() && get(pr[i].second) != get(it -> second)) {
			unite(pr[i].second, it -> second);
			++it;
		}
		st.insert({{p.second, p.first}, pr[i].second});

	}
	pr.clear();
	st.clear();
	for (int i = 1; i <= n; ++i) {
		pr.push_back({{y[i], x[i]}, i});
	}
	sort(pr.begin(), pr.end());
	for (int i = n - 1; i >= 0; i--) {
		auto p = pr[i].first;
		auto it = st.upper_bound({{p.second, 0}, 0});
		while (it != st.end() && get(pr[i].second) != get(it -> second)) {
			unite(pr[i].second, it -> second);
			++it;
		}
		st.insert({{p.second, p.first}, pr[i].second});

	}
	for (int i = 1; i <= n; ++i) {
		cout << sz[get(i)] << '\n';
	}
}

main() {
	ios :: sync_with_stdio(0);		
	cin.tie(0);
	int tt = 1;
	//cin >> tt;
	while (tt--) {
		solve();
		cout << '\n';
	} 
	return 0;
}

