    for (ll i = 0; i < N; i++) {
        ll x, y;
        cin >> x >> y;
        x--;
        y--;
        points[i] = {i, x, y};
        pmap_xl.insert({i, x, y});
        pmap_xs.insert({i, x, y});
        pmap_yl.insert({i, x, y});
    }
    {
        // x座標が小さい順
        sort(points.begin(), points.end(), [](point_y a, point_y b) { return a.x < b.x; });

        for (ll i = 0; i < N; i++) {
            // y座標が自分より大きい点があれば、それと同じクラスタ
            point_y pt = points[i];
            point_revy pt_y_large = *(pmap_xs.begin());

            if (pt_y_large.id != pt.id) {
                uf.unite(pt.id, pt_y_large.id);
            }

            // 以降現れないよう消す
            pmap_xs.erase({pt.id, pt.x, pt.y});
        }
    }
    {
        // y座標が大きい順
        sort(points.begin(), points.end(), [](point_y a, point_y b) { return a.y > b.y; });

