struct uf {
    vector<int> s;
    uf (int n) : s(n, -1) {}
    int find(int i) {
        return s[i] < 0 ? i : (s[i] = find(s[i]));
    }
    bool join(int i, int j) {
        i = find(i), j = find(j);
        if (i == j) return 1;
        if (s[i] > s[j]) swap(i, j);
        s[i] += s[j], s[j] = i;
        return 0;
    }
};

