vector<int> parent;

int getRoot(int idx) {
    if(parent[idx] != idx) {
        parent[idx] = getRoot(parent[idx]);
    }
    return parent[idx];
}


void fusion(vector<tuple<int,int,int> > &coordinates, int left, int right) {

    if(right-left <= 0) {
        return  ;
    }
    int mid = (left + right+1) / 2;


    fusion(coordinates, left, mid-1);
    fusion(coordinates, mid, right);

    pair<int,int> miniY = make_pair(1e8,0), maxiY = make_pair(-1e8,0);

    for(int c=left;c<mid;c++) {
        miniY = min(miniY, make_pair(get<1>(coordinates[c]),get<2>(coordinates[c])));
    }

    for(int c=mid;c<=right;c++) {
        maxiY = max(maxiY, make_pair(get<1>(coordinates[c]),get<2>(coordinates[c])));
    }


    int rMaxi = getRoot(maxiY.second);
    for(int c=left;c<mid;c++) {
        if(get<1>(coordinates[c]) > maxiY.first) continue;
        int r = get<2>(coordinates[c]);
        parent[r] = rMaxi;
    }

    int rMini = getRoot(miniY.second);
    for(int c=mid;c<=right;c++) {
        if(get<1>(coordinates[c]) < miniY.first) continue;
        int r = get<2>(coordinates[c]);
        parent[r] = rMini;
    }
}

