struct dsu{
    vector < int > p;
    vector < int > sz;
    vector<int> his_val;
    dsu(int n) {
        p.resize(n);
        sz.resize(n, 1);
        his_val.resize(n);
        iota(p.begin(), p.end(), 0);
    }
    int find(int a) {
        if (a == p[a]) return a;
        return p[a] = find(p[a]);
    }
    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return false;
        if (sz[a] < sz[b]) swap(a, b);
        sz[a] += sz[b];
        p[b] = a;
        return true;
    }
    bool are_connected(int a, int b) {
        return find(a) == find(b);
    }
};
int main() {
