map <int, int> mm;

void build(int t, int l, int r) {
    for (int i = l; i < r; ++i) {
        rmq[t].pb(v[i].Y);
    }
    sort(rmq[t].begin(), rmq[t].end());
    if (r - l == 1)
        return;
    int mid = (r + l) / 2;
    build(t * 2 + 1, l, mid);
    build(t * 2 + 2, mid, r);
}

int get(int t, int l, int r, int x, int y, int ll, int rr) {
    if (r <= x || y <= l)
        return 0;
    if (x <= l && r <= y) {
        if (upper_bound(rmq[t].begin(), rmq[t].end(), rr) == lower_bound(rmq[t].begin(), rmq[t].end(), ll))
            return 0;
        mn = min(mn, *lower_bound(rmq[t].begin(), rmq[t].end(), ll));
        mx = max(mx, *(--upper_bound(rmq[t].begin(), rmq[t].end(), rr)));
        return (upper_bound(rmq[t].begin(), rmq[t].end(), rr) - lower_bound(rmq[t].begin(), rmq[t].end(), ll));
    }
    int mid = (r + l) / 2;
    return get(t * 2 + 1, l, mid, x, y, ll, rr) + get(t * 2 + 2, mid, r, x, y, ll, rr);
}

