const int N = 2e5+1;

struct Fen
{
	int f[N];

	Fen() {
		memset(f, 0, sizeof(f));
	}

	void add(int i, int x) {
		while(i < N) {
			f[i] += x;
			i += i&(-i);
		}
	}

	int sum(int i) {
		int ans = 0;
		while(i > 0) {
			ans += f[i];
			i -= i&(-i);
		}
		return ans;
	}

	int sum(int l, int r) {
		if(l > r)return 0;
		return sum(r)-sum(l-1);
	}
}f, r;

