void solve() {
  ll N;
  cin >> N;

  using PT = tuple<ll, ll, ll>;

  V<PT> points(N);

  VL y_to_i(N);

  rep(i, N) {
    ll x, y;
    cin >> x >> y;
    --x, --y;
    y_to_i[y] = i;
    points[i] = {x, y, i};
  }

  sort(all(points), [](PT a, PT b) {
    auto [ax, ay, ai] = a;
    auto [bx, by, bi] = b;
    return ax < bx;
  });

  dsu d(N);

  ll min_y = INF;
  set<ll> ys;

  rep(i, N) {
    auto [x, y, pi] = points[i];

    if (min_y < y) {
      d.merge(y_to_i[min_y], pi);
    } else {
      min_y = y;
      ys.insert(y);
    }

    for (auto it = ys.begin(); it != ys.end();) {
      auto s_y = *it;
      unless(s_y < y) break;
      d.merge(y_to_i[s_y], pi);
      ys.erase(it++);
    }
  }

  rep(i, N) cout << d.size(i) << "\n";
}

