    T sum(int k) {
        // [0, k]
        T res = 0;
        for (k++; k > 0; k -= k & -k) res += data[k];
        return res;
    }
    T sum(int l, int r) {
        // [l, r)
        return sum(r - 1) - sum(l - 1);
    }
    void add(int k, T x) {
        for (k++; k <= sz; k += k & -k) data[k] += x;
    }
    // sum(a1, ... , ax)>=wを満たす最小のx(0-indexed)
    // assert(all ai is non-negative)
    int lower_bound(T w) {
        if (w <= 0) return 0;
        int x = 0;
        int k = 1;
        while ((k << 1) <= sz) k <<= 1;
        for (; k > 0; k >>= 1) {
            if (x + k <= sz && data[x + k] < w) {
                w -= data[x + k];
                x += k;
            }
        }
        return x;
    }
};
// Time Complexity: faster than O(logN)[O(ArkInv(N))]
// UnionFind.data: if minus -> size of subtree (node is root)
// if plus -> parent of the node
struct UnionFind {
    vector<int> data;
    UnionFind(int sz) {
        data.assign(sz, -1);
    }
    int find(int x) {
        if (data[x] < 0) return x;
        return data[x] = find(data[x]);
    }
    bool unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) return false;
        if (data[x] > data[y]) swap(x, y);
        data[x] += data[y];
        data[y] = x;
        return true;
    }
    int size(int x) {
        return (-data[find(x)]);
    }
    bool same(int x, int y) {
        return find(x) == find(y);
    }
};
