struct DSU {
    vi parent, size;

    DSU(ll n) {
        parent.resize(n);
        size.resize(n);
        for (ll i = 0; i < n; i++) {
            parent[i] = i;
            size[i] = 1;
        }
    }

    ll find_parent(ll v) {
        if (parent[v] == v) {
            return v;
        } else {
            return parent[v] = find_parent(parent[v]);
        }
    }

    void union_sets(ll v, ll u) {
        u = find_parent(u);
        v = find_parent(v);
        if (u != v) {
            if (size[u] > size[v]) {
                swap(u, v);
            }
            size[v] += size[u];
            parent[u] = v;
        }
    }
};

ll solve() {
    ll n;
    cin >> n;
    vpii vec(n);

    for (auto &x : vec) {
        cin >> x.ff >> x.ss;
        --x.ff, --x.ss;
    }
    vpii v = vec;
    sort(all(vec));
