    DSU dsu(n);

    for (auto &p : vec) {
        ll x = p.ff;
        ll y = p.ss;
        vpii rmv;
        for (pii ver : s) {
            if (ver.ff < y) {
                dsu.union_sets(x, ver.ss);
            }
        }
        for (pii ver : s) {
            if (dsu.find_parent(x) == dsu.find_parent(ver.ss)) {
                rmv.pb(ver);
            }
        }
        s.insert(make_pair(p.ss, p.ff));
        rmv.pb(p);
        sort(all(rmv));
        for (ll i = 1; i < (ll)rmv.size(); i++) {
            s.erase(rmv[i]);
        }
    }

    for (auto &p : v) {
        cout << dsu.size[dsu.find_parent(p.ff)] << endl;
    }

    return 0;
}

