        while(!s.empty() && p[s.top()].first > low && p[s.top()].first < p[i].first){
            uf.unite(p[i].second, p[s.top()].second);
            low = p[s.top()].first;
            s.pop();
        }
        s.push(i);
    }
    rep(i, N){
        cout << uf.size(i) << endl;
    }
}

