vector<int> func(){
    int n = in();
    vector<int> parent(n);
    vector<int> size(n,1);
    rep(i,n)parent[i] = i;

    method(get_parent,int, int p){
        if(parent[p]==p)return p;
        return parent[p] = get_parent(parent[p]);
    };
    method(merge,void,int a,int b){
        int ap = get_parent(a);
        int bp = get_parent(b);
        if(ap==bp)return;
        size[ap] += size[bp];
        parent[bp] = ap;
    };
    method(get_size,int,int p){
        return size[get_parent(p)];
    };

    method(flow,void,vector<pii> pos){
        using P = pair<pii,int>;
        vector<P> line;
        rep(i,pos.size()){
            line.emplace_back(pos[i],i);
        }
        sort(all(line),lambda(bool,P a,P b){
                return a.first.second > b.first.second;
                });
        set<pii> s;
        foreach(i,line){
            while(true){
                auto itr = s.upper_bound(pii(i.first.first,0));
                if(itr!=s.end()){
                    merge(i.second,itr->second);
                    s.erase(itr);
                }else{
                    break;
                }
            }
            s.emplace(i.first.first,i.second);
        }
    };

    vector<pii> line(n);
    foreach(i,line)i=in<pii>();
    flow(line);
    foreach(i,line)i=pii(-i.first,-i.second);
    flow(line);
    method(check,void,function<int(pii)> f){
        set<int> s;
        foreach(i,line){
            s.emplace(f(i));
        }
        assert(s.size()==n);
    };
    check(lambda(int,pii x){return x.first;});
    check(lambda(int,pii x){return x.second;});

    vector<int> res(n);
    rep(i,n){
        res[i] = get_size(i);
    }

    return res;
}

