	struct Sort_impl {
		template <class F> auto operator()(F&& f) {
			return Callable([&](auto v) {
				sort(begin(v), end(v), f);
				return v;
			});
		}
		template <class T> friend auto operator|(T v, [[maybe_unused]] const Sort_impl& c) {
			sort(begin(v), end(v));
			return v;
		}
	} Sort;
