class unionfind {
    int size = 0;
    int pa[500000];
public:
    void init(int n) {
        size = n;
        for (int i = 0; i <= size; i++) pa[i] = -1;
    }
    int find(int x) {
        if (pa[x] < 0) return x;
        return pa[x] = find(pa[x]);
    }
    bool unite(int x, int y) {
        x = find(x); y = find(y);
        if (x == y) return false;
        if (pa[x] > pa[y]) swap(x, y);
        pa[x] += pa[y];
        pa[y] = x;
        return true;
    }
    bool same(int x, int y) {
        return find(x) == find(y);
    }
    bool isroot(int x) {
        return x == find(x);
    }
    int sz(int x) {
        return -pa[find(x)];
    }
    H operator[](int x) {
        x = find(x);
        return H{ x,-pa[x] };
    }
};
template<typename T>
class BIT {
    int size;
    vector<T>dat;
public:
    BIT() {}
    BIT(vector<T>v) {
        init(v);
    }
    BIT(int n) { init(n); }
    void init(int n) {
        size = n;
        dat.assign(size + 1, 0);
    }
    void init(vector<T>v) {
        init(v.size());
        for (int i = 1; i <= size; i++) {
            dat[i] += v[i - 1];
            if (i + (i & -i) <= size) dat[i + (i & -i)] += dat[i];
        }
    }
    void add(int i, ll x) {
        i++;
        while (i <= size) {
            dat[i] += x;
            i += i & -i;
        }
    }
    void change(int i, ll x) {
        i++; int t = x - dat[i];
        while (i <= size) {
            int k = dat[i];
            dat[i] += t;
            t = dat[i] - k;
            i += i & -i;
        }
    }
    //[l,r)
    void add(int l, int r, ll x) {
        add(l, x); add(r, -x);
    }
    //[0,i]
    T query(int i) {
        i++;
        T sum = 0;
        while (i > 0) {
            sum += dat[i];
            i -= i & -i;
        }
        return sum;
    }
    //[l,r)
    T query(int l, int r) {
        return query(r - 1) - query(l - 1);
    }
    //[0,x) >= w
    int lower_bound(T w) {
        if (w <= 0) return 0;
        int x = 0, k = 1;
        while (k * 2 < size) k *= 2;
        for (; k > 0; k /= 2) {
            if (x + k <= size && dat[x + k] < w) {
                w -= dat[x + k];
                x += k;
            }
        }
        return x;
    }
};//size, 0-indexed

