int n, posx[N], posy[N], idx[N], idy[N], ans[N];
vector <int> seen, adj[N], vec;
deque < pair <int, int> > all[4 * N];
bool mrk[N];
void build(int b = 0, int e = n, int ind = 1){
    for (int i = b; i < e; i++){
        all[ind].pb(make_pair(posy[idx[i]], idx[i]));
    }
    sort(all[ind].begin(), all[ind].end());
    if (b + 1 == e) return;
    int mid = (b + e) / 2;
    build (b, mid, ind * 2);
    build (mid, e, ind * 2 + 1);
    return;
}
void get(int l, int r, int b = 0, int e = n, int ind = 1){
    if (l <= b && e <= r){
        vec.pb(ind);
        return;
    }
    int mid = (b + e) / 2;
    if (l < mid) get(l, r, b, mid, ind * 2);
    if (mid < r) get(l, r, mid, e, ind * 2 + 1);
    return;
}
void dfs(int v){
    mrk[v] = 1, seen.pb(v);
    if (0 < posx[v]) get(0, posx[v]);
    for (int ind : vec){
        while (all[ind].size()){
            int yF = all[ind].front().F;
            int u = all[ind].front().S;
            if (yF < posy[v]){
                if (!mrk[u]) adj[v].pb(u);
                all[ind].pop_front();
            }
            else break;
        }
    }
    vec.clear();
    if (posx[v] < n - 1) get(posx[v] + 1, n);
    for (int ind : vec){
        while (all[ind].size()){
            int yF = all[ind].back().F;
            int u = all[ind].back().S;
            if (posy[v] < yF){
                if (!mrk[u]) adj[v].pb(u);
                all[ind].pop_back();
            }
            else break;
        }
    }
    vec.clear(); 
    for (int u : adj[v]) dfs(u);
    return;
}
