        cin >> posx[i] >> posy[i];
        posx[i]--, posy[i]--;
        idx[posx[i]] = idy[posy[i]] = i;
    }
    build();
    for (int i = 1; i <= n; i++){
        if (!ans[i]){
            dfs(i);
            for (int v : seen){
                ans[v] = seen.size();
            }
            seen.clear();
        }
        cout << ans[i] << '\n';
    }
    return 0;
}

