using namespace std;
using ll = long long;
class UnionFind {
public:
    vector <ll> par; // 各元の親を表す配列
    vector <ll> siz; // 素集合のサイズを表す配列(1 で初期化)
    UnionFind(ll sz_): par(sz_), siz(sz_, 1LL) {
        for (ll i = 0; i < sz_; ++i) par[i] = i; // 初期では親は自分自身
    }
    void init(ll sz_) {
        par.resize(sz_);
        siz.assign(sz_, 1LL);  // resize だとなぜか初期化されなかった
        for (ll i = 0; i < sz_; ++i) par[i] = i; // 初期では親は自分自身
    }
    // Find
    ll root(ll x) { // 根の検索
        while (par[x] != x) {
            x = par[x] = par[par[x]]; // x の親の親を x の親とする
        }
        return x;
    }
    // Union(Unite, Merge)
    bool merge(ll x, ll y) {
        x = root(x);
        y = root(y);
        if (x == y) return false;
        if (x > y) swap(x, y);
        siz[x] += siz[y];
        par[y] = x;
        return true;
    }
    bool issame(ll x, ll y) { // 連結判定
        return root(x) == root(y);
    }
    ll size(ll x) { // 素集合のサイズ
        return siz[root(x)];
    }
};

int main(){
  std::cin.tie(0);
  std::ios::sync_with_stdio(false);

  int32_t N;
  cin >> N; 
  vector<vector<int32_t>> cities(N, vector<int32_t>(3, 0));
  for (int i = 0; i < N; i++) {
    cin >> cities[i][0] >> cities[i][1];
    cities[i][2] = i;
  }
  sort (cities.begin(), cities.end(), [](const vector<int32_t>& r, const vector<int>& l) {return r[0] < l[0];});

  UnionFind uf(N);
  int32_t ymax_idx = 0;
  int32_t ymax = cities[0][1];
  int32_t ymin_idx = 0;
  int32_t ymin = cities[0][1];
  for (int i = 1; i < N; i++) {
    int32_t y = cities[i][1];
    if (y < ymin) {
      ymin_idx = i;
      ymin = y;
    } else {
      uf.merge(ymin_idx, i);
      if (y > ymax) {
        ymax = y;
        ymax_idx = i;
      } else {
        if (cities[uf.root(ymax_idx)][1] < y) {
          uf.merge(ymin_idx, uf.root(ymax_idx));
        }
      }
    }
  }

  ymax_idx = N - 1;
  ymax = cities[N-1][1];
  for (int i = N - 2; i >= 0; i--) {
    int32_t y = cities[i][1];
    if (y < ymax) {
      uf.merge(i, ymax_idx);
    } else {
      ymax_idx = i;
      ymax = y;
    }
  }

  vector<int32_t> res(N, 0);
  for (int i = 0; i < N; i++) {
    res[cities[i][2]] = uf.size(i);
  }
  for (auto r : res) {
    cout << r << endl;
  }

  return 0;
}

