struct UF{
    vector<int> par, rank, size;
    UF(){}
    UF(int n){ init(n); }
    void init(int n){
        par.assign(n, 0);
        rank.assign(n, 0);
        size.assign(n, 1);
        for(int i=0;i<n;i++) par[i] = i;
    }
    int find(int x){
        if(par[x] == x) return x;
        return par[x] = find(par[x]);
    }
    void unite(int x, int y){
        x = find(x);
        y = find(y);
        if(x != y){
            if(rank[x] > rank[y]) swap(x, y);
            par[x] = y;
            size[y] += size[x];
        }
    }
    bool same(int x, int y){ return find(x) == find(y); }
    int get_size(int x){ return size[find(x)]; }
};

