    set< P > s;
    for(P p: v){
        int i = p.second;
        for(;;){
            auto itr = s.lower_bound(P(y[i], 0));
            if(itr == s.begin()) break;
            --itr;
            uf.unite(i, itr->second);
            s.erase(itr, s.end());
        }
        s.insert(P(y[i], i));
    }

    for(int i=0;i<n;i++){
        cout << uf.get_size(i) << endl;
    }
}

