int g(int x) {
	int ans = 0;
	while (x) { ans += t[x]; x -= x&-x; }
	return ans;
}

void add(int x) {
	while (x <= n) { t[x]++; x += x&-x; }
}

int g1(int x) {
	int ans = 0;
	while (x) { ma(ans, t[x]); x -= x&-x; }
	return ans;
}

void modi(int x, int y) {
	while (x <= n) { ma(t[x], y); x += x&-x; }
}

