// Binary Indexed Tree (Fenwick Tree)
template <typename T>
struct BIT {
    int n,p;
    vector<T> d;
    BIT(int n=0) :n(n), d(n+1) {
        p = 1;
        while(p < n)p *= 2;
    }
    //更新
    void add(int i,T x=1){
        for(i++;i <= n;i += i&-i) d[i] += x;
    }
    //[0,i)の和
    T sum(int i){
        T res = 0;
        for(;i;i -= i&-i) res += d[i];
        return res;
    }
    //[l,r)の和
    T sum(int l,int r){ return sum(r) - sum(l);}
    //v0+v1+…vx>=mを満たすmin(x)を返す
    int lower_bound(T w){
        if(w <= 0) return 0;
        T x = 0;
        for ( int i=p;i;i/=2){
            if(i+x <=n &&d[i+x] < w){
                w -= d[i+x];
                x += i;
            }
        }
        return x;
    }
};

struct UnionFind{
private:
    std::vector<int> par;

public:
    UnionFind() = default;

    UnionFind(int n){
        par = std::vector<int>(n, -1);
    }

    int root(int x){
        if(par[x] < 0) return x;
        return par[x] = root(par[x]);
    }
    bool issame(int x, int y){ return root(x) == root(y); }

    bool merge(int x, int y){
        x = root(x);
        y = root(y);
        if(x == y) return false;
        if(par[x] > par[y]) std::swap(x, y);
        par[x] += par[y];
        par[y] = x;
        return true;
    }

    int size(int x){ return -par[root(x)]; }   
};

int n;
UnionFind uf;
void solve(V<pii> xy){
    V<> change(n + 1);
    BIT<int> BT(n + 1);
    REP(i, n) change[xy[i].second] = i;
    sort(all(xy));
    REP(i, n){
        auto [ign, y] = xy[i];
        if(BT.sum(y)){
            int pl = BT.lower_bound(BT.sum(y));
            uf.merge(change[y], change[pl]);
        }
        BT.add(y);
    }
}   

int main(){
    cin >> n;
    uf = UnionFind(n);
