    solve(xy);
    REP(i, n) swap(xy[i].first, xy[i].second);
    solve(xy);
    REP(i, n) xy[i] = {n + 1 - xy[i].first, n + 1 - xy[i].second};
    solve(xy);
    REP(i, n) swap(xy[i].first, xy[i].second);
    solve(xy);
    REP(i, n) print(uf.size(i));
}

