  vector<pair<Pii, int>> xy(N);
  REP(i, N) io.read(xy[i].first);
  REP(i, N) xy[i].second = i;
  sort(ALL(xy));
  vector<int> x(N), y(N);
  REP(i, N) {
    x[i] = xy[i].first.first;
    y[i] = xy[i].first.second;
  }
  vector<Pii> ls;
  REP(i, N) {
    auto itr = ys.lower_bound(Pii(y[i], 0));
    ls.emplace_back(y[i], i);
    while (itr != ys.begin()) {
      itr--;
      uf.unite(i, itr->second);
      ls.emplace_back(itr->first, itr->second);
    }
    sort(ALL(ls));
    ys.insert(Pii(y[i], i));
    for (int j = 1; j < ls.size(); ++j) ys.erase(ls[j]);
    ls.clear();
  }
  vector<int> ans(N);
  REP(i, N) ans[xy[i].second] = uf.size(i);
  REP(i, N) io.writeln(ans[i]);
  return 0;
}

