template <typename T = int>
struct UnionFind
{
    vector<int> data;
    vector<T> sz;
    bool is_default;
    int num;

    UnionFind(int n) : num(n)
    {
        data.assign(n, -1);
        sz.assign(n, 1);
        is_default = true;
    }

    UnionFind(int n, vector<T> &a) : num(n)
    {
        data.assign(n, -1);
        sz = a;
        is_default = false;
    }

    bool unite(int x, int y)
    {
        x = find(x), y = find(y);
        if (x == y)
            return false;
        num--;
        if (data[x] > data[y])
            swap(x, y);
        data[x] += data[y];
        if (!is_default)
            sz[x] += sz[y];
        data[y] = x;
        return true;
    }

    bool same(int x, int y) { return find(x) == find(y); }

    int find(int x)
    {
        if (data[x] < 0)
            return x;
        return (data[x] = find(data[x]));
    }

    T size(int x) { return (is_default ? -data[find(x)] : sz[find(x)]); }
};
