struct DSU
{
	vector<int>par;
	vector<int>sz;

	DSU(int n)
	{
		par.resize(n+1);
		iota(par.begin(),par.end(),0);
		sz.assign(n+1,1);
	}

	int Find(int a)
	{
		return par[a]==a?a:par[a]=Find(par[a]);
	}

	bool same(int a,int b)
	{
		a=Find(a);
		b=Find(b);
		return a==b;
	}

	void Union(int a,int b)
	{
		a=Find(a);
		b=Find(b);

		if(sz[b]>sz[a]) swap(a,b);
		sz[a]+=sz[b];
		par[b]=a;
	}
};


void solve()
{
	int n;
	cin>>n;

	vector<pair<pii,int>>edge(n);
	for(int i=0;i<n;i++)
	{
		pii x;
