		edge[i].first=x;
		edge[i].second=i+1;
	}

	sort(edge.begin(),edge.end());
	map<int,int>parent;
	for(auto it: edge) parent[it.first.second]=it.second;

	//for(auto it: edge) cout<<it.first.first<<" "<<it.first.second<<" "<<it.second<<"\n";

	DSU dsu(n);

	set<int>st;

	for(int i=n-1;i>=0;i--)
	{
		auto it=st.upper_bound(edge[i].first.second);
		if(it!=st.end())
		{
			do
			{
				int u=edge[i].second;
				int v=parent[*it];
				//cout<<u<<" "<<v<<"\n";
