class UFF {
    using Int = int;
    std::vector<Int> parent;
    std::vector<Int> rank;

public:
    explicit UFF(Int n) : parent(n, -1), rank(n, 0) {}

    Int find(Int x) {
        auto &px = parent[x];
        if (px < 0) {
            return x;
        } else {
            return px = find(px);
        }
    }

    bool unite(Int a, Int b) {
        const auto pa = find(a);
        const auto pb = find(b);
        if (pa == pb) return false;

        if (rank[pa] > rank[pb]) {
            parent[pa] += parent[pb];
            parent[pb] = pa;
        } else {
            parent[pb] += parent[pa];
            parent[pa] = pb;

            if (rank[pa] == rank[pb]) {
                rank[pb]++;
            }
        }
        return true;
    };

    Int size(Int x) {
        const auto px = find(x);
        return -parent[px];
    }

    bool is_same(Int a, Int b) {
        const auto pa = find(a);
        const auto pb = find(b);
        return pa == pb;
    }

    vector<Int> get_all_dset() {
        unordered_set<Int> dset;
        for (Int i = 0; i < parent.size(); ++i) {
            dset.insert(find(i));
        } // end i
        vector<Int> v(dset.size());
        Int i = 0;
        for (auto &&d : dset) {
            v[i++] = d;
        } // end d
//        sort(v.begin(), v.end());
        return v;
    }
};


class solver{
    istream& is;
    ostream& os;

public:
    solver(istream& I, ostream& O) :is(I), os(O) {}

    int N;
    vector<pair<int, int>> xy;
    bool input() {
        is >> N;
        xy.resize(N);
        is >> xy;
        return !!is;
    }

    void run();
};

void solver::run(){
    if(!input()) return;
    map<int, int> rx, ry;
    UFF uf(N);
    vector<bool> skip(N, false);
    for (int i = 0; i < N; ++i) {
        rx[xy[i].first] = i;
        ry[xy[i].second] = i;
    } // end i
    for (auto &&xi : rx) {
        int x, y, i;
        tie(x, i) = xi;
        y = xy[i].second;
        if(ry.count(xy[i].second))
            ry.erase(xy[i].second);
        if(skip[i]) continue;
        auto p = ry.lower_bound(y);
        int mx = 0, mxi;
        while(p != ry.end()){
            int tx, ty, ti;
            tie(ty, ti) = *p;
            tx = xy[ti].first;
            if(tx < x){
                auto r = p++;
                ry.erase(r);
                continue;
            }
            uf.unite(i, ti);
//            cerr << "unite:" << xy[i] << ',' << xy[ti] << endl;
            skip[ti] = true;
            if(CHMAX(mx, tx)){
                mxi = ti;
            }
            auto r = p++;
            ry.erase(r);
        }
        if(mx != 0)
            ry[xy[mxi].second] = mxi;
    } // end xi
    for (int i = 0; i < N; ++i) {
        cout << uf.size(i) << '\n';
    } // end i

}

