void bfs(ll node){
	visited[node]=1; vll v;
	queue<ll> q; q.push(node);
	ll c=0;
	while(!q.empty()){
		node=q.front(); q.pop(); c++; v.pb(node);
		for(ll x:adj[node]){
			if(visited[x]) continue; visited[x]=1; q.push(x);
		}
	}
	for(ll x:v) ans[x]=c;
}
