struct dsu {
    vector<int> dsu{};

    void build(int k) {
        dsu.resize(k+1);
        range(i, k + 1) dsu[i] = i;
    }

    int get_dsu(int a) {
        if (dsu[a] == a) return a;
        return dsu[a] = get_dsu(dsu[a]);
    }

    void unio(int a, int b) {
        a = get_dsu(a), b = get_dsu(b);
        if (rand() % 2) swap(a, b);
        dsu[a] = b;
    }
};

void solve() {
    int n; cin >> n;
    vector<pair<pair<int, int>, int>> xy(n);
    range(i, n) cin >> xy[i].first.first >> xy[i].first.second;
    range(i, n) xy[i].second = i;
    sort(all(xy));
    vector<int> ind(n+1);
    range(i, n) ind[xy[i].first.second] = xy[i].second;
    set<int> s;
    dsu d; d.build(n);
    range(i, n) {
        vector<int> todel;
        for(auto &e: s) {
            if (e > xy[i].first.second) break;
            todel.push_back(e);
            d.unio(ind[e], xy[i].second);
        }
        for(int j = 1; j < (int)todel.size(); ++j){
            s.erase(todel[j]);
        }
        if (todel.empty()) {
            s.insert(xy[i].first.second);
        }
    }
    vector<int> cnt(n);
    range(i, n) cnt[d.get_dsu(i)]++;
    range(i, n) cout << cnt[d.get_dsu(i)] << "\n";
}

