int ON2solve(){
    // O(N^2)
    vector<int> Ans(N,0);
    auto cmp_x = [](pii a, pii b){return a.first < b.first;};
    sort(P.begin(),P.end(), cmp_x);
    debug(P);
    atcoder::dsu uf(N+1);
    vector<bool> used(N,false);
    for (int i = 0; i < N; i++)
    {
        if(used[P[i].second]) continue;
        for (int j = i + 1 ; j < N; j++)
        {
            if(P[i].second < P[j].second){
                used[P[j].second] = true;
                uf.merge(i, j);
            }
        }

    }

    for (int i = 0; i < N; i++) Ans[Idx[i]] = uf.size(i);
    for(auto a:Ans) cout << a << "\n";    
    return 0;
}

