#include <bits/stdc++.h>
using namespace std;

const int maxn = 200010;
int n, p[maxn], tmp[maxn], fa[maxn], sz[maxn];
int mn[20][maxn], mx[20][maxn];

int find(int x) {
    return x == fa[x] ? x : fa[x] = find(fa[x]);
}

void unite(int x, int y) {
    x = find(x), y = find(y);
    if (x == y) return;
    fa[x] = y, sz[y] += sz[x];
}

int main() {
    scanf("%d", &n);
    for (int i = 1, x, y; i <= n; i++) {
        scanf("%d %d", &x, &y);
        p[x] = y, tmp[i] = x;
    }
    for (int i = 1; i <= n; i++) {
        fa[i] = i, sz[i] = 1;
        mn[0][i] = mx[0][i] = p[i];
    }
    for (int i = 1; i < 20; i++) {
        for (int j = 1; j + (1 << i) - 1 <= n; j++) {
            mn[i][j] = min(mn[i - 1][j], mn[i - 1][j + (1 << (i - 1))]);
            mx[i][j] = max(mx[i - 1][j], mx[i - 1][j + (1 << (i - 1))]);
        }
    }
    auto qmin = [&](int l, int r) {
        int k = log2(r - l + 1);
        return min(mn[k][l], mn[k][r - (1 << k) + 1]);
    };
    auto qmax = [&](int l, int r) {
        int k = log2(r - l + 1);
        return max(mx[k][l], mx[k][r - (1 << k) + 1]);
    };
    for (int i = 1; i <= n; i++) {
        if (i > 1) {
            int l = 1, r = i - 1, ans = -1;
            while (l <= r) {
                int mid = (l + r) >> 1;
                if (qmin(mid, i - 1) < p[i]) l = (ans = mid) + 1;
                else r = mid - 1;
            }
            if (~ans) unite(i, ans);
        }
        if (i < n) {
            int l = i + 1, r = n, ans = -1;
            while (l <= r) {
                int mid = (l + r) >> 1;
                if (qmax(i + 1, mid) > p[i]) r = (ans = mid) - 1;
                else l = mid + 1;
            }
            if (~ans) unite(i, ans);
        }
    }
    for (int i = 1; i <= n; i++) {
        printf("%d\n", sz[find(tmp[i])]);
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int N=200000;
int Root[N],Rank[N],Size[N];
int find(int x){
    if(Root[x]==x)return x;
    else return Root[x]=find(Root[x]);
}
void unite(int x,int y){
    int X=find(x);
    int Y=find(y);
    if(X==Y)return;
    if(Rank[X]<Rank[Y]){
        Root[X]=Y;
        Size[Y]+=Size[X];
    }
    else{
        Root[Y]=X;
        Size[X]+=Size[Y];
        if(Rank[X]==Rank[Y])Rank[X]++;
    }
    return;
}
int main(){
    int n;
    cin>>n;
    set<int>s;
    for(int i=0;i<n;i++)Root[i]=i,Rank[i]=0,Size[i]=1,s.insert(i);
    pair<int,int>point[n];
    int num[n];
    for(int i=0;i<n;i++){
        int x,y;
        cin>>x>>y;
        point[i]={x-1,y-1};
        num[y-1]=i;
    }
    sort(point,point+n);
    vector<int>v(n);
    for(int i=0;i<n;i++)v[i]=point[i].second;
    int used[n]={};
    for(int i=0;i<n;i++){
        s.erase(v[i]);
        if(used[v[i]])continue;
        bool b=0;
        for(auto itr=s.upper_bound(v[i]);itr!=s.end();itr++){
            if(used[*itr])b=1;
            used[*itr]=1;
            unite(num[v[i]],num[*itr]);
            if(b)break;
        }
    }
    for(int i=0;i<n;i++)cout<<Size[find(i)]<<endl;
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

vector<int> d;

void build(int n) {
    d.resize(n, -1);
}

int find(int x) {
    if (d[x] < 0) return x;
    return d[x] = find(d[x]);
}

void merge(int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y) return;
    if (d[x] > d[y]) swap(x, y);
    d[x] += d[y];
    d[y] = x;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<pair<pair<int, int>, int>> p(n);
    for (int i = 0; i < n; ++i) {
        cin >> p[i].first.first >> p[i].first.second;
        p[i].second = i;
    }
    sort(p.begin(), p.end());
    stack<pair<int, int>> st;
    build(n);
    for (int i = 0; i < n; ++i) {
        stack<pair<int, int>> new_st;
        bool suc = false;
        while (!st.empty()) {
            auto t = st.top();
            st.pop();
            new_st.push(t);
            if (t.first < p[i].first.second) {
                merge(p[i].second, t.second);
                suc = true;
            }
        }
        if (!suc) {
            pair<int, int> tt = make_pair(p[i].first.second, p[i].second);
            new_st.push(tt);
        }
        swap(st, new_st);
    }
    vector<int> ans(n);
    for (int i = 0; i < n; ++i) {
        ans[p[i].second] = -d[find(p[i].second)];
    }
    for (int i = 0; i < n; ++i) {
        cout << ans[i] << '\n';
    }
    return 0;
}

