struct POSITION{
	int x,y,index;
};

const int N=200005;

int n,boss[N],group[N];
POSITION pos[N];

bool cmp(POSITION a,POSITION b)
{
	if(a.x!=b.x)	return a.x>b.x;
	return a.y>b.y;
}

int FIND(int x)
{
	if(boss[x]==x)
		return boss[x];
	else
		return boss[x]=FIND(boss[x]);
}

void merge(int a,int b)
{
	a=FIND(a),b=FIND(b);
	if(a==b)	return;
	if(group[a]>group[b])	swap(a,b);
	group[b]+=group[a];
	boss[a]=b;
}

void init()
{
	cin >> n;
	for(int i=0;i<n;++i){
		boss[i]=i,group[i]=1;
		cin >> pos[i].x >> pos[i].y;
		pos[i].index=i;
	}
	sort(pos,pos+n,cmp);
}

void solve()
{
	set<int> s;
	int y_map[N];

	for(int i=0;i<n;++i){
		if(!s.empty() && *prev(s.end())>pos[i].y)
			merge(y_map[*s.upper_bound(pos[i].y)],pos[i].index);
		s.insert(pos[i].y);
		y_map[pos[i].y]=pos[i].index;
	}

	for(int i=0;i<n;++i)
		cout << group[FIND(i)] << endl;
}

