#include <bits/stdc++.h>
using namespace std;

#define int long long

class DSU
{
	private:
	int sz;
	vector<int> rank, parent;

	void printComponent(int id)
	{
		cout << "Component " << id << " : ";
		int p_id = Find(id);
		for(int i = 0; i < sz + 1; i++)
		{
			if(p_id == parent[i])
			{
				cout << i << " ";
			}
		}

		cout << endl;
	}

	public:
	DSU(int n)
	{
		sz = n;
		rank.resize(n + 1, 0);
		parent.resize(n + 1);

		for(int i = 0; i < n + 1; i++)
		{
			parent[i] = i;
		}
	}

	int Find(int i)
	{
		// use path compression
		if(i != parent[i])
		{
			parent[i] = Find(parent[i]);
		}

		return parent[i];
	}

	void Union(int i, int j)
	{
		int i_id = Find(i);
		int j_id = Find(j);

		if(rank[i_id] >= rank[j_id])
		{
			parent[j_id] = i_id;

			if(rank[i_id] == rank[j_id])
				rank[i_id] += 1;
		}
		else
		{
			parent[i_id] = j_id;
		}
	}

	void Print()
	{
		for(int i = 0; i < sz + 1; i++)
		{
			printComponent(i);
		}
	}

	int getSize(int id)
	{
		int p_id = Find(id);
		int cnt = 0;
		for(int i = 0; i < sz + 1; i++)
		{
			if(parent[i] == p_id)
			{
				cnt++;
			}
		}

		return cnt;
	}

};

int32_t main()
{
	int n;
	cin >> n;

	vector< pair<int, int> > arr(n);
	for(int i = 0; i < n; i++)
	{
		cin >> arr[i].first >> arr[i].second;
	}

	vector< pair<int, int> > temp = arr;

	sort(temp.begin(), temp.end());

	DSU dsu(n);

	// left pass
	int minm = temp[0].second;

	for(int i = 1; i < n; i++)
	{
		if(minm < temp[i].second)
		{
			dsu.Union(minm, temp[i].second);
		}
		else
		{
			minm = temp[i].second;
		}
	}

	// right pass
	int maxm = temp[n-1].second;
	for(int i = n-2; i >= 0; i--)
	{
		if(maxm > temp[i].second)
		{
			dsu.Union(maxm, temp[i].second);
		}
		else
		{
			maxm = temp[i].second;
		}

	}

	for(int i = 0; i < n; i++)
	{
		cout << dsu.getSize(arr[i].second) << endl;
	}

	return 0;
}

