int root(int v){
    if(v == p[v])
        return v;
    return p[v] = root(p[v]);
}

void merge(int a, int b){
    a = root(a), b = root(b);
    if(a == b)
        return;
    if(sz[a] < sz[b])
        swap(a, b);
    sz[a] += sz[b];
    p[b] = a;
}

void solve()
{
    int n;cin>>n;
    vii pairs(n);
    p.resize(n), sz.assign(n, 1);
    rep(i, 0, n){
        cin>>pairs[i].first>>pairs[i].second;
        p[i] = i;
    }
    sort(pairs.begin(), pairs.end());

    stack<int> left, right;
    int lind[n], rind[n];
    rep(i, 0, n)
        lind[i] = rind[i] = -1;
    rep(i, 0, n){
        while(left.size() && pairs[left.top()].second > pairs[i].second)
            left.pop();
        if(left.size()) 
            lind[i] = left.top();
        left.push(i);

        while(right.size() && pairs[right.top()].second < pairs[n-1-i].second)
            right.pop();
        if(right.size()) 
            rind[n-i-1] = right.top();
        right.push(n-1-i);
    }

    rep(i, 0, n){
        if(lind[i] != -1)
            merge(i, lind[i]);
        if(rind[i] != -1)
            merge(i, rind[i]);
    }

    rep(i, 0, n)
        cout<<sz[root(i)]<<endl;


}

