struct UFT {
	vector< int > par;
	int getpar(int i) {
		if (par[i] == i)
			return i;
		return par[i] = getpar(par[i]);
	}
	void unite(int i, int j) {
		int t = getpar(i);
		par[t] = getpar(j);
	}
	bool uf(int i, int j) {
		return getpar(i) == getpar(j);
	}
	UFT(int n) {
		par = vector< int >(n);
		for (int i = 0; i < n; i++)
			par[i] = i;
	}
};
template < class Monoid >
struct SegT {
	//to be set--------------------------------------------------
	const static inline Monoid UNITY = pii(-LINF, -LINF); //UNITY=0
	Monoid merge(const Monoid &a, const Monoid &b) {
		return max(a, b); //a+b;
	}
	//kokomade----------------------------------------------------
	struct node {
		int l2, r2, k;
		inline bool leaf() {
			return l2 + 1 == r2;
		}
		pair< node, node > childs() {
			node hidari(l2, mid(), left()), migi(mid(), r2, right());
			return make_pair(hidari, migi);
		}
		node(int _l2, int _r2, int _k) : l2(_l2), r2(_r2), k(_k) {}
		node() {
		}

	private:
		inline int left() {
			return 2 * k + 1;
		}
		inline int right() {
			return 2 * k + 2;
		}
		inline int mid() {
			return (l2 + r2) / 2;
		}
	};
	vector< Monoid > A;
	int n;
	void update(int k, Monoid x) {
		int kk = k + n - 1;
		A[kk] = x;
		while (kk > 0) {
			kk = (kk - 1) / 2;
			A[kk] = merge(A[2 * kk + 1], A[2 * kk + 2]);
		}
	}
	Monoid get(int l, int r, node &o) {
		//sotogawa
		if (o.r2 <= l || r <= o.l2)
			return UNITY;
		//uchigawa
		if (l <= o.l2 && o.r2 <= r)
			return A[o.k];
		//sonota
		auto c = o.childs();
		Monoid vl = get(l, r, c.first);
		Monoid vr = get(l, r, c.second);

		return merge(vl, vr);
	}
	Monoid get(int l, int r) {
		node o(0, n, 0);
		return get(l, r, o);
	}
	void init(vector< Monoid > &B) {
		n = 1;
		while (n < B.size())
			n <<= 1;
		A = vector< Monoid >(2 * n - 1, UNITY);
		for (int i = 0; i < B.size(); i++)
			A[i + n - 1] = B[i];
		for (int k = n - 2; k >= 0; k--) {
			A[k] = merge(A[2 * k + 1], A[2 * k + 2]);
		}
	}
	SegT(vector< Monoid > &B) {
		init(B);
	}
	SegT(int _n) {
		vector< Monoid > B(_n, UNITY);
		init(B);
	}
};
