const int N=200005;
int n;
vector<array<int,2>> treea(4*N,{N,0});
vector<array<int,2>> treeb(4*N,{0,0});

void updatea(int idx,int l,int r,int pos,array<int,2> val)
{
    if(l==r) treea[idx]=val;
    else
    {
        int m=(l+r)/2;
        if(pos<=m) updatea(2*idx,l,m,pos,val);
        else updatea(2*idx+1,m+1,r,pos,val);
        treea[idx]=min(treea[2*idx],treea[2*idx+1]);
    }
}

array<int,2> querya(int idx,int l,int r,int ql,int qr)
{
    if(ql>qr) return {N,0};
    if(l==ql&&r==qr) return treea[idx];
    int m=(l+r)/2;
    return min(querya(2*idx,l,m,ql,min(qr,m)),querya(2*idx+1,m+1,r,max(ql,m+1),qr));
}

void updateb(int idx,int l,int r,int pos,array<int,2> val)
{
    if(l==r) treeb[idx]=val;
    else
    {
        int m=(l+r)/2;
        if(pos<=m) updateb(2*idx,l,m,pos,val);
        else updateb(2*idx+1,m+1,r,pos,val);
        treeb[idx]=max(treeb[2*idx],treeb[2*idx+1]);
    }
}

array<int,2> queryb(int idx,int l,int r,int ql,int qr)
{
    if(ql>qr) return {0,0};
    if(l==ql&&r==qr) return treeb[idx];
    int m=(l+r)/2;
    return max(queryb(2*idx,l,m,ql,min(qr,m)),queryb(2*idx+1,m+1,r,max(ql,m+1),qr));
}

void upd(int pos,array<int,2> val)
{
    updatea(1,1,n,pos,val);
    updateb(1,1,n,pos,val);
}

void rm(int pos)
{
    updatea(1,1,n,pos,{N,0});
    updateb(1,1,n,pos,{0,0});
}

