vi S(N);
void ms(int u){
    P[u]=u;
    S[u]=1;
}
int fs(int u){
    return P[u]=u==P[u]?u:fs(P[u]);
}
void me(int u, int v){
    u=fs(u);
    v=fs(v);
    if(u!=v){
        if(S[u]>S[v])
            swap(u,v);
        P[u]=v;
        S[v]+=S[u];
    }

}

