class Trees{
  vector<int> par;
  vector<int> rank;
  public:
  int root(int i){
    int rt;
    if(par[i]==i){rt=i;rank[i]=1;}
    else{rt=root(par[i]);par[i]=rt;rank[i]=2;}
    return rt;
  }
  void unite(int i,int j){
    int rki=rank[i];int rkj=rank[j];
    if(rki<rkj){par[root(i)]=root(j);rank[i]++;}
    else{par[root(j)]=root(i);rank[j]++;}
  }
  bool same(int i,int j){
    return root(i)==root(j);
  }
  Trees(int n){
    for(int i=0;i<n;i++) {par.push_back(i);rank.push_back(1);};
  }
  void solve(){
    vector<int>s(par.size());
    for(long i=0;i<s.size();i++)s[root(i)]++;
    for(long i=0;i<s.size();i++)cout<<s[root(i)]<<endl;
  }
};
struct S{
  long x,y,id;
};
bool cmpx(S a,S b){return a.x<b.x;}
bool cmpy(S a,S b){return a.y<b.y;}
bool cmpid(S a,S b){return a.id<b.id;}
int main(){
  long N;cin>>N;
  vector<S> A(N);
  Trees tree(N);
  for(long i=0;i<N;i++){
    long x,y;cin>>x>>y;
    A[i]={x,y,i};
  }
  sort(A.begin(),A.end(),cmpx);
  vector<S> maxy(N);
  for(long i=N-1;i>=0;i--){
    if(i!=N-1)maxy[i]=maxy[i+1];
    if(A[i].y>maxy[i].y)maxy[i]=A[i];
  }
  for(long i=0;i<N-1;i++){
    if(A[i].y<maxy[i+1].y){
      //cout<<"y: "<<A[i].y<<" "<<maxy[i+1].y<<" "<<A[i].id<<" "<<maxy[i+1].id<<endl;
      tree.unite(A[i].id,maxy[i+1].id);
    }
  }

  sort(A.begin(),A.end(),cmpy);
  vector<S> maxx(N);
  for(long i=N-1;i>=0;i--){
    if(i!=N-1)maxx[i]=maxx[i+1];
    if(A[i].x>maxx[i].x)maxx[i]=A[i];
  }
  for(long i=0;i<N-1;i++){
    if(A[i].x<maxx[i+1].x){
      //cout<<"x: "<<A[i].x<<" "<<maxx[i+1].x<<" "<<A[i].id<<" "<<maxx[i+1].id<<endl;    
      tree.unite(A[i].id,maxx[i+1].id);
    }
  }
  tree.solve();
}

