using namespace atcoder;
using namespace std;

int myfind(int a, vector<int>& relation) {
    if (relation[a] == a) return a;
    int res = myfind(relation[a], relation);
    relation[a] = res;
    return res;
}

void myunion(int a, int b, vector<int>& relation) {
    int ta = myfind(a, relation);
    int tb = myfind(b, relation);
    if (ta == tb) return;
    relation[ta] = tb;
}

int main() {
    int n;
    cin >> n;
    vector<pair<int, pair<int, int>>> v;
    for (int i = 0; i < n; i++) {
    	int x, y;
    	cin >> x >> y;

    	v.push_back(make_pair(x - 1, make_pair(y - 1, i)));
    }
    sort(v.begin(), v.end());
    vector<int> relation(n, 0);
    for (int i = 0; i < n; i++) {
    	relation[i] = i;
    }
    map<int, int> m;
    for (int i = 0; i < n; i++) {
    	if (m.size() > 0 && m.begin()->first < v[i].second.first) {
    		vector<int> d;
    		for (auto it = m.begin(); it != m.end() && it->first < v[i].second.first; it++) {
    			d.push_back(it->first);
    			myunion(v[i].second.second, it->second, relation);
    		}
    		for (int i = 1; i < d.size(); i++) {
    			m.erase(d[i]);
    		}
    	} else {
    		m.insert(make_pair(v[i].second.first, v[i].second.second));	
    	}
    }
    unordered_map<int, int> um;
    for (int i = 0; i < n; i++) {
    	um[myfind(i, relation)]++;
    }
    for (int i = 0; i < n; i++) {
    	cout << um[myfind(i, relation)] << endl;
    }
}

