int a[N];
int b[N];

map<int,int> mp;
struct pp{
    int x;
    int y;
    int index;
}p[N];

int cmp(pp a, pp b){
    return a.x<b.x;
}
int num[N];
int ans[N];
int parent[N];
stack<int> s;
void Init()
{
    for(int i = 1;i <= n+10;i++){
        parent[i] = i;
        num[i]=1;
    }
    return;
}

int get_boss(int v)
{
    if(parent[v] == v)
        return v;
    else
    {
        //路径压缩(使搜索祖宗的过程中，路径中搜索的结点的父亲的变为祖宗)
        parent[v] = get_boss(parent[v]);
        return parent[v];
    }
}

void Merge(int v,int u) //u合并到v
{
    int t1 = get_boss(v);
    int t2 = get_boss(u);
    parent[t2] = t1;
    num[t1]+=num[t2];
    return;
}

int main()
{
    cin>>n;
    Init();
    for(int i=1;i<=n;i++){
        cin>>p[i].x>>p[i].y;
        p[i].index=i;
