    sort(p+1,p+1+n,cmp);
    for(int i=1;i<=n;i++){
        mp[p[i].y]=i;
    }



    for(int i=1;i<=n;i++){
        int mn=p[i].y;
        while(!s.empty()&&s.top()<p[i].y){
            Merge(mp[s.top()],mp[p[i].y]);
            mn=s.top();
            s.pop();
        }
        p[i].y=mn;
        s.push(mn);
    }

    for(int i=1;i<=n;i++){
        ans[p[i].index]=num[get_boss(mp[p[i].y])];
    }
    for(int i=1;i<=n;i++)cout<<ans[i]<<
        endl;


}

