    vector<P> xy(N);
    vector<ll> original(N), xPlaceAtY(N);
    set<ll> yset;
    rep(i, N) {
        cin >> xy[i].first >> xy[i].second;
        --xy[i].first;
        --xy[i].second;
        yset.insert(xy[i].second);
        xPlaceAtY[xy[i].second] = xy[i].first;
        original[i] = xy[i].first;
    }

    sort(xy.begin(), xy.end());
    UnionFind uf = UnionFind(N);
    rep(i, N) {
        for (auto itr = yset.upper_bound(xy[i].second); itr != yset.end(); ++itr) {
            uf.unite(i, xPlaceAtY[*itr]);
        }
        yset.erase(xy[i].second);
    }

    rep(i, N) {
        cout << uf.size(original[i]) << "\n";
    }

    return 0;
}

