struct UnionFind {
    vl parents, set_size;
    set<ll> root_idx;
    ll n_groups;

    UnionFind(ll n){
        parents = set_size = vl(n);
        n_groups = n;
        rep(i, n){
            parents[i] = i;
            set_size[i] = 1LL;
            root_idx.insert(i);
        }
    }

    ll root_find(ll x){
        if (parents[x] == x) return x;
        return parents[x] = root_find(parents[x]);
    }

    void unite(ll x, ll y){
        // priority for x is larger than that of y
        x = root_find(x); y = root_find(y);
        if (x == y) return;
        parents[y] = x, set_size[x] += set_size[y];
        root_idx.erase(y);
        n_groups--;
    }

    // connected or not
    bool is_same(ll x, ll y){return root_find(x) == root_find(y);}
    ll size(ll x){return set_size[root_find(x)];}
};

void solve(){
    ll n;
    scan(n);
    vl ord(n), vs(n), ans(n);
    UnionFind uf(n);
    rep(i, n){
        ll x, y; scan(x, y);
        --x, --y;
        vs[x] = y;
        ord[x] = i;
    }

    set<pair<ll, ll>> ss;
    ss.insert({vs[0], 0});
    For(i, 1, n){
        auto it = ss.begin();
        if ((*it).first > vs[i]) {ss.insert({vs[i], i}); continue;}
        while (it != ss.end() && (*it).first < vs[i]){
            ll val, par;
            tie(val, par) = *it;
            uf.unite(par, i);
            ++it;
            if (uf.parents[par] != par)
                ss.erase({val, par});
        }
    }

    rep(i, n) ans[ord[i]] = uf.size(i);
    println(ans);
}

