#define sz(a) ll(a.size())
ll x[200005],y[200005],ind[200005],par[200005],sz[200005];
bool comp(ll i,ll j){
	return x[i]<x[j];
}
ll find(ll i){
	if(par[i]==i)
		return i;
	return par[i]=find(par[i]);
}
void merge(ll x,ll y){
	x=find(x),y=find(y);
	if(x==y)
		return;
	if(sz[x]<sz[y])
		swap(x,y);
	par[y]=x;
	sz[x]+=sz[y];
}
void solve(){
	ll n;
	cin>>n;
	for(ll i=1;i<=n;i++){
		cin>>x[i]>>y[i];
		ind[i]=i;
		par[i]=i;
		sz[i]=1;
	}
	sort(ind+1,ind+n+1,comp);
	set<p2> s;
	for(ll i=1;i<=n;i++)
		s.insert({y[ind[i]],ind[i]});
	for(ll qc=1;qc<=n;qc++){
		ll i=ind[qc];
		auto it=s.find({y[i],i});
		if(it==s.end())
			continue;
		s.erase(it);
		it=s.lower_bound({y[i]+1,0});
		if(s.empty())
			continue;
		set<p2> dum;
		while(it!=s.end()){
			merge(i,it->second);
			it++;
		}
		for(auto ut=dum.begin();ut!=dum.end();ut++)
			s.erase(*ut);
	}
	for(ll i=1;i<=n;i++)
		cout<<sz[find(i)]<<"\n";
}
int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cout.tie(NULL);
    #ifndef ONLINE_JUDGE
    freopen("input.txt", "r" , stdin);
    freopen("output.txt", "w", stdout);
    #endif
    clock_t z=clock();
    ll qc=1;
    //cin>>qc;
    for(ll i=1;i<=qc;i++){
        solve();
    }
    debug("Total Time:%.4Lf\n",(ld)(clock()-z)/CLOCKS_PER_SEC);
}

