struct UnionFind {
    vector<int> par;

    UnionFind(int n) : par(n, -1) {}

    int find(int x) {
        if (par[x] < 0) return x;
        return par[x] = find(par[x]);
    }

    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) return;
        if (par[x] > par[y]) swap(x, y);
        par[x] += par[y];
        par[y] = x;
    }

    bool same(int x, int y) {
        return find(x) == find(y);
    }

    int size(int x) {
        return -par[find(x)];
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    int N;
    cin >> N;
    vector<int> loc(N), ind(N);
    for (int i = 0; i < N; i++) {
        int x, y;
        cin >> x >> y;
        x--; y--;
        loc[x] = y;
        ind[y] = i;
    }
    set<int> ys;
    UnionFind uf(N);
    for (int x = 0; x < N; x++) {
        auto lb = ys.lower_bound(loc[x]);
        for (auto it = ys.begin(); it != lb; it++) {
            uf.unite(*it, loc[x]);
        }
        ys.erase(ys.begin(), lb);
        ys.insert(loc[x]);
    }
    ys.clear();
    for (int x = N - 1; x >= 0; x--) {
        auto lb = ys.lower_bound(loc[x]);
        for (auto it = lb; it != ys.end(); it++) {
            uf.unite(*it, loc[x]);
        }
        ys.erase(lb, ys.end());
        ys.insert(loc[x]);
    }
    vector<int> ans(N);
    for (int i = 0; i < N; i++) ans[ind[i]] = uf.size(i);
    for (int i = 0; i < N; i++) cout << ans[i] << "\n";
}

