int find(int x)
{
    return x==pre[x]?x:pre[x]=find(pre[x]);
}

void unite(int x,int y)
{
    x = find(x);y = find(y);
    if(x == y) return;
    sz[x] += sz[y];
    pre[y] = x;
}

