int calc(pair<int, int>& town, vector< pair<int, int> >& towns) {
  int ret = 0;
  int x1 = town.first, y1 = town.second;
  for (size_t i = 0; i < towns.size(); i++) {
    int x2 = towns[i].first, y2 = towns[i].second;
    if ( (x2 - x1) * (y2 - y1) >= 0 ) {
        ret++;
    }
  }
  return ret;
}


