const int maxn = 2e5 + 5;
const int LG = 20;
int sparse[maxn][LG], a[maxn], n;

struct UF{
  vi sz, p;
  int comps;

  UF(int s) : comps(s) {
    sz.resize(comps + 1);
    p.resize(comps + 1);
    init();
  }

  void init(){
    for(int i = 0; i <= comps; i++){
      sz[i] = 1;
      p[i] = i;
    }
  }

  int fset(int u){
    return u == p[u] ? u : p[u] = fset(p[u]);
  }

  bool connect(int u, int v){
    u = fset(u);
    v = fset(v);
    if(u != v){
      if(sz[v] > sz[u]){
        swap(u, v);
      }
      sz[u] += sz[v];
      p[v] = u;
      comps--;
      return true;
    }
    return false;
  }
};

void build() {
  for(int k = 1; k < LG; k++) {
    for(int i = 0; i < n; i++) {
      if(i + (1 << k) > n) break;
      if(a[sparse[i][k - 1]] <= a[sparse[i + (1 << (k - 1))][k - 1]]) {
        sparse[i][k] = sparse[i][k - 1];
      } else {
        sparse[i][k] = sparse[i + (1 << (k - 1))][k - 1];
      }
    }
  }
}

int get(int l, int r, int x = 1) {
  int highest = 31 - __builtin_clz(r - l + 1);
  if(a[sparse[l][highest]] < a[sparse[r - (1 << highest) + 1][highest]]) {
    return sparse[l][highest];
  } else {
    return sparse[r - (1 << highest) + 1][highest];
  }
}

void build2() {
  for(int k = 1; k < LG; k++) {
    for(int i = 0; i < n; i++) {
      if(i + (1 << k) > n) break;
      if(a[sparse[i][k - 1]] > a[sparse[i + (1 << (k - 1))][k - 1]]) {
        sparse[i][k] = sparse[i][k - 1];
      } else {
        sparse[i][k] = sparse[i + (1 << (k - 1))][k - 1];
      }
    }
  }
}

int get2(int l, int r) {
  int highest = 31 - __builtin_clz(r - l + 1);
  if(a[sparse[l][highest]] > a[sparse[r - (1 << highest) + 1][highest]]) {
    return sparse[l][highest];
  } else {
    return sparse[r - (1 << highest) + 1][highest];
  }
}

int main() {
  ios_base::sync_with_stdio(false); cin.tie(0);
  #ifdef LOCAL
  freopen("input.txt", "r", stdin);
  freopen("output.txt", "w", stdout);
  #endif

  cin >> n;
  vector <tuple<int, int, int>> vec(n);
  for(int i = 0; i < n; i++) {
    cin >> get<0>(vec[i]) >> get<1>(vec[i]);
    get<2>(vec[i]) = i;
  }
  sort(all(vec));
  for(int i = 0; i < n; i++) {
    a[i] = get<1>(vec[i]);
    sparse[i][0] = i;
  }
  build();
  UF uf(n);
  for(int i = 0; i < n; i++) {
    int lo = 0, hi = i - 1;
    while(lo < hi) {
      int mid = (lo + hi + 1) / 2;
      if(a[get(mid, i - 1)] > a[i]) hi = mid - 1;
      else lo = mid;
    }
    if(a[lo] <= a[i]) {
      uf.connect(get<2>(vec[lo]), get<2>(vec[i]));
    } 
  }
  reverse(all(vec));
  for(int i = 0; i < n; i++) {
    a[i] = get<1>(vec[i]);
    sparse[i][0] = i;
  }
  build2();
  for(int i = 0; i < n; i++) {
    int lo = 0, hi = i - 1;
    while(lo < hi) {
      int mid = (lo + hi + 1) / 2;
      if(a[get2(mid, i - 1)] < a[i]) hi = mid - 1;
      else lo = mid;
    }
    if(a[lo] >= a[i]) {
      uf.connect(get<2>(vec[lo]), get<2>(vec[i]));
    } 
  }
  vi res(n);
  for(int i = 0; i < n; i++) {
    res[get<2>(vec[i])] = uf.sz[uf.fset(get<2>(vec[i]))];
  }
  for(int i = 0; i < n; i++) {
    cout << res[i] << "\n";
  } 
}

