int main() {
    ll N;
    cin >> N;

    auto uf = iunionfind(N);
    vector<point_x> points(N);
    set<point_revy> pmap_xs;
    set<point_x> pmap_yl;
    for (ll i = 0; i < N; i++) {
        ll x, y;
        cin >> x >> y;
        x--;
        y--;
        points[i] = {i, x, y};
        pmap_xs.insert({i, x, y});
        pmap_yl.insert({i, x, y});
    }
    {
        // x座標が小さい順
        sort(points.begin(), points.end(), [](point_x a, point_x b) { return a.x < b.x; });

        for (ll i = 0; i < N; i++) {
            // y座標が自分より大きい点があれば、それと同じクラスタ
            point_x pt = points[i];
            point_revy pt_y_large = *(pmap_xs.begin());

            if (pt_y_large.id != pt.id) {
                uf.unite(pt.id, pt_y_large.id);
            }

            // 以降現れないよう消す
            pmap_xs.erase({pt.id, pt.x, pt.y});
        }
    }
    {
        // y座標が大きい順
        sort(points.begin(), points.end(), [](point_x a, point_x b) { return a.y > b.y; });

        for (ll i = 0; i < N; i++) {
            // x座標が自分より小さい点があれば、それと同じクラスタ
            point_x pt = points[i];
            point_x pt_x_small = *(pmap_yl.begin());

            if (pt_x_small.id != pt.id) {
                uf.unite(pt.id, pt_x_small.id);
            }

            // 以降現れないよう消す
            pmap_yl.erase({pt.id, pt.x, pt.y});
        }
    }
    vector<vector<ll>> clusters(N);
    for (ll i = 0; i < N; i++) {
        clusters[uf.find(i)].push_back(i);
    }
    for (ll i = 0; i < N; i++) {
        print(clusters[uf.find(i)].size());
    }
}

