  UnionFind uf(n);
  vector<P> p;
  vector<int> idx(n, -1), idy(n, -1);
  rep(i,n) {
    int x, y;
    cin >> x >> y;
    x--; y--;
    idx[x] = idy[y] = i;
    p.emplace_back(make_pair(x, y));
  }
