struct DSU {
	int fa[1 << 18];
	void inline init() {memset(fa, -1, sizeof(fa));}
	int inline root(int x) {return fa[x] < 0 ? x : fa[x] = root(fa[x]);}
	void inline conn(int a, int b) {
		a = root(a); b = root(b);
		if(a == b) return;
		fa[a] += fa[b]; fa[b] = a;
	}
} dsu;

