{
public:
    vector<ll> par;
    vector<ll> siz;

    // Constructor
    UnionFind(ll sz_) : par(sz_), siz(sz_, 1LL)
    {
        for (ll i = 0; i < sz_; ++i)
            par[i] = i;
    }
    void init(ll sz_)
    {
        par.resize(sz_);
        siz.assign(sz_, 1LL);
        for (ll i = 0; i < sz_; ++i)
            par[i] = i;
    }

    // Member Function
    // Find
    ll root(ll x)
    {
        while (par[x] != x)
        {
            x = par[x] = par[par[x]];
        }
        return x;
    }

    // Union(Unite, Merge)
    bool merge(ll x, ll y)
    {
        x = root(x);
        y = root(y);
        if (x == y)
            return false;
        if (siz[x] < siz[y])
            swap(x, y);
        siz[x] += siz[y];
        par[y] = x;
        return true;
    }

    bool issame(ll x, ll y)
    {
        return root(x) == root(y);
    }

    ll size(ll x)
    {
        return siz[root(x)];
    }
};

int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);
    ll n;
    cin >> n;
    lvec x(n), y(n), indx(n);
    map<ll, ll, greater<ll>> m;
    for (int i = 0; i < n; i++)
    {
        cin >> x[i] >> y[i];
        indx[i] = i;
        m[y[i]] = x[i];
    }
    sort(indx.begin(), indx.end(), [&x](ll a, ll b) {
        return x[a] < x[b];
    });

    lvec xx(n + 1);
    for (int i = 0; i < n; i++)
    {
        xx[x[indx[i]]] = indx[i];
    }
    UnionFind u(n);
    bvec li(n, false);
    for (int i = 0; i < n - 1; i++)
    {
        ll idx = indx[i];
        m.erase(y[idx]);
        if (li[idx])
        {
            continue;
        }
        for (auto p : m)
        {
            ll k = p.first, v = p.second;
            if (y[idx] < k)
            {
                u.merge(idx, xx[v]);
                li[k] = true;
            }
            else
            {
                break;
            }
        }
    }
    for (int i = 0; i < n; i++)
    {
        cout << u.size(i) << endl;
    }
}

