int fin(int v) 
{
	if(par[v]==-1) return par[v]=v;
    if (v == par[v])    return v;
    return par[v] = fin(par[v]);
}
//union by size
void make_set(int v) {
    par[v] = -1;
    sz[v] = 1;
}

void uni(int a, int b) 
{
    a = fin(a);
    b = fin(b);
    if(a == b) return;
    if(sz[a] < sz[b]) swap(a, b);
    par[b] = a;
    sz[a] += sz[b];
}
int nxt[200009],prv[200009];
void solve()
{
	int n;
	cin>>n;
	for(int i=0;i<n;i++) cin>>p[i].fi>>p[i].se;
	iota(ind,ind+n,0);
	sort(ind,ind+n,[](int A, int B){return p[A]<p[B];});
	for(int i=0;i<n;i++)
	make_set(i);
	for(int i=0;i<n;i++) nxt[i]=i+1,prv[i]=i-1;
	for(int i=0;i<n;i++)
	{
		if(par[ind[i]]!=-1) continue;
		par[ind[i]]=ind[i];
		if(prv[i]>=0)
		nxt[prv[i]]=nxt[i];
		prv[nxt[i]]=prv[i];
