void build(int in,int l,int r){
    if(l==r){
        seg[in] = 0;
        return ;
    }
    int mid = (l+r)/2;
    build(2*in,l,mid);
    build(2*in+1,mid+1,r);
    seg[in] = max(seg[2*in] , seg[2*in+1]);
