void update(int in,int l,int r,int lt,int rt,int val){
	if(rt<l || lt>r){
		return;
	}
	if(l>=lt && r<=rt){
        seg[in] = val;
		return ;
	}
	int mid = (l+r)/2;
	update(2*in,l,mid,lt,rt,val);
	update(2*in+1,mid+1,r,lt,rt,val);
	seg[in] = max(seg[2*in+1] , seg[2*in]);
}

int query(int in,int l,int r,int lt,int rt){
	if(rt<l || lt>r) return 0;
	if(l>=lt && r<=rt){
		return seg[in];
	}
	int mid = (l+r)/2;
	if(rt<=mid) return query(2*in,l,mid,lt,rt);
	else if(lt > mid) return query(2*in+1,mid+1,r,lt,rt);
	else{
