	vector<int> id(n);
	iota(id.begin(),id.end(),0);
  sort(id.begin(),id.end(),[&](int i,int j) {
  	return x[i] < x[j];
	});
  dsu d(n);
  vector<int> s;
  for (int i = 0; i < n; i++) {
  	int mx = -1;
  	while ((int)s.size() && y[s.back()] <= y[id[i]]) {
  		if (mx == -1) mx = s.back();
  		d.combine(id[i],s.back());
  		s.pop_back();
		}
		if (mx == -1) s.push_back(id[i]);
		else s.push_back(mx);
	}
	s.clear();
	for (int i = n-1; i >= 0; i--) {
		int mx = -1;
  	while ((int)s.size() && y[s.back()] >= y[id[i]]) {
  		if (mx == -1) mx = s.back();
  		d.combine(id[i],s.back());
  		s.pop_back();
		}
		if (mx == -1) s.push_back(id[i]);
		else s.push_back(mx);
	}
	for (int i = 0; i < n; i++) cout << -d.chot[d.find(i)] <<"\n";
}

