void make(vector<pair<int, pii> > &p){
	sort(all(p));
	int j = 0, id = 0;
	rep(i, sz(p)){
		while(j < sz(p) and p[i].F > p[j].F){
			if(p[j].S.F < p[id].S.F) id = j;
			j++;
		}
		if(p[id].S.F < p[i].S.F and p[id].F != p[i].F){
			g[p[i].S.S].pb(p[id].S.S);
			g[p[id].S.S].pb(p[i].S.S);
		}
	}
	j = 0;
	id = 0;
	reverse(all(p));
	rep(i, sz(p)){
		while(j < sz(p) and p[i].F < p[j].F){
			if(p[j].S.F > p[id].S.F) id = j;
