                connected.push_back(e);
            }
        }
        if (connected.empty()) {
            st.insert({xy[i].first.second, i});
        } else {
            pair<int, int> repr = {INT_MAX, -1};
            for (auto g : connected) {
                if (repr.first > g.first) {
                    repr = g;
                }
            }
            for (auto g : connected) {
