class UnionFind
{
public:
  int n;
  vector<int> par, rnk;

  UnionFind(int n_)
  {
    n = n_;
    par.resize(n);
    rnk.resize(n);
    for (int i = 0; i < n; i++)
    {
      par[i] = i;
      rnk[i] = 0;
    }
  }

  int find(int x)
  {
    if (par[x] == x)
      return x;
    return par[x] = find(par[x]);
  }

  void unite(int x, int y)
  {
    x = find(x);
    y = find(y);
    if (x == y)
      return;

    if (rnk[x] < rnk[y])
    {
      par[x] = y;
    }
    else
    {
      par[y] = x;
      if (rnk[x] == rnk[y])
        rnk[x]++;
    }
  }

  bool same(int x, int y)
  {
    return find(x) == find(y);
  }
};

int main()
{
  int n;
  cin >> n;

  vector<int> x(n), y(n);
  rep(i, 0, n) cin >> x[i] >> y[i];

  vector<int> z(n);
  iota(z.begin(), z.end(), 0);

  UnionFind uf(n);
  sort(z.begin(), z.end(), [&](int a, int b) {
    return x[a] < x[b];
  });

  vector<bool> used(n);
  rep(i, 0, n - 1)
  {
    int j = z[i];
    if (used[i])
      continue;
    rep(ii, i + 1, n)
    {
      int k = z[ii];
      if (y[j] < y[k])
      {
        uf.unite(j, k);
        used[ii] = true;
      }
    }
  }

  sort(z.begin(), z.end(), [&](int a, int b) {
    return y[a] < y[b];
  });

  used.assign(n, false);
  rep(i, 0, n - 1)
  {
    int j = z[i];
    if (used[i])
      continue;
    rep(ii, i + 1, n)
    {
      int k = z[ii];
      if (x[j] < x[k])
      {
        uf.unite(j, k);
        used[ii] = true;
      }
    }
  }

  vector<int> cnt(n);
  rep(i, 0, n)
  {

    int j = uf.find(i);
    cnt[j]++;
  }

  rep(i, 0, n)
  {
    int j = uf.find(i);
    cout << cnt[j] << endl;
  }

  return 0;
}

