struct UnionFind {
    vector<int> d;
    UnionFind(int n = 0) : d(n, -1) {}
    int find(int x) {
        if (d[x] < 0) return x;
        return d[x] = find(d[x]);
    }
    bool unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) return false;
        if (d[x] > d[y]) swap(x, y);
        d[x] += d[y];
        d[y] = x;
        return true;
    }
    bool same(int x, int y) { return find(x) == find(y); }
    int size(int x) { return -d[find(x)]; }
};

int main() {
    ll N;
    cin >> N;
    vector<P> xy(N);
    vector<ll> original(N), xPlaceAtY(N);
    set<ll> yset;
    rep(i, N) {
        cin >> xy[i].first >> xy[i].second;
        --xy[i].first;
        --xy[i].second;
        yset.insert(xy[i].second);
        xPlaceAtY[xy[i].second] = xy[i].first;
        original[i] = xy[i].first;
    }

    sort(xy.begin(), xy.end());
    UnionFind uf = UnionFind(N);
    rep(i, N) {
        yset.erase(xy[i].second);
        if (uf.size(i) > 1) {
            continue;
        }
        // cerr << "i=" << i << "xy[i].first=" << xy[i].first << "xy[i].second=" << xy[i].second << endl;
        for (auto itr = yset.upper_bound(xy[i].second); itr != yset.end(); ++itr) {
            uf.unite(i, xPlaceAtY[*itr]);
        }
    }

    rep(i, N) {
        cout << uf.size(original[i]) << "\n";
    }

    return 0;
}

