		pos[a]=b;
		ind[a]=i;
		inv[b]=a;
		s.insert(b);
		par[i]=i;
		sz[i]=1;
		g[i]=b;
	}
	set<int> small;
	for(int i=1;i<=n;i++)
	{
		auto it = small.upper_bound(pos[i]);
		while(!small.empty() && it != small.begin())
		{
			it--;
			assert(pos[i]>*it);
			uni(ind[i],ind[inv[*it]]);
			small.erase(it);
			it = small.upper_bound(pos[i]);
		}
		small.insert(g[fin(ind[i])]);
	}
	for(int i=1;i<=n;i++) cout<<sz[fin(i)]<<'\n';
}

