            int p = min_bit.lower_bound(S);
            uf.unite(idx[y[i]], idx[p]);
        }
        min_bit.add(y[i], 1);
    }
    for(int i = 0; i < N; ++i)  cout << uf.get_cnt(uf.find(i)) << endl;
}

