vector<int> parent;
vector<int> sizes;

void init(int n) {
    parent.resize(n);
    sizes.resize(n);
    for (int i = 0; i < n; ++i) {
        parent[i] = i;
        sizes[i] = 1;
    }
}

int find_set (int v) {
    if (v == parent[v])
        return v;
    return parent[v] = find_set (parent[v]);
}

void union_sets (int a, int b) {
    a = find_set (a);
    b = find_set (b);
    if (a != b) {
        if (a > b)
            swap (a, b);
        parent[b] = a;
        sizes[a] += sizes[b];
    }
}

void solve() {
    int n;
    cin >> n;
    vector<pair<int, int> > points(n);
    vector<int> order(n);
    for (int i = 0; i < n; ++i) {
        order[i] = i;
        cin >> points[i].first >> points[i].second;
    }

    sort(order.begin(), order.end(), [&](int a, int b) {return points[a] < points[b];});
    vector<int> res;

    init(n);
    set<int> st;

    for (int i = 0; i < n; ++i) {
        int val = points[order[i]].second - 1;
        auto it = st.upper_bound(val);
        int uns = 0;
        while (it != st.begin()) {
            --it;
            union_sets(*it, val);
            ++uns;
            st.erase(it);
            it = st.upper_bound(val);
        }
        if (uns == 0) {
            st.insert(val);
        }
    }

    for (int i = 0; i < n; ++i) {
        int val = points[i].second - 1;
        cout << sizes[find_set(val)] << '\n';
    }
}

