using namespace std;

int n;
vector<int> p, sz;
int par(int x) {
	while (x != p[x]) x = p[x];
	return x;
}
void uni(int x, int y) {
	x = par(x);
	y = par(y);
	if (x==y) return;
	if (sz[x] < sz[y]) {
		p[x] = y;
		sz[y] += sz[x];
	}
	else {
		p[y] = x;
		sz[x] += sz[y];
	}
}

int get(int a, int b, int tp) {
	if (tp==0) return min(a, b);
	else return max(a, b);
}

struct st {
	vector<int> t;
	int tp;
	st(int type) {
		tp = type;
		if (tp==0) t = vector<int>(2*n, n);
		else t = vector<int>(2*n, -1);
	}
	void upd(int pos, int val) {
		for (t[pos+=n]=val; pos>1; pos>>=1)
			t[pos>>1] = get(t[pos], t[pos^1], tp);
	}
	int qry(int l, int r) {
		int ans;
		if (tp==0) ans = n;
		else ans = -1;
		for (l+=n, r+=n; l<r; l>>=1, r>>=1) {
			if (l&1) ans = get(ans, t[l++], tp);
			if (r&1) ans = get(ans, t[--r], tp);
		}
		return ans;
	}
};

