int main() {
  scanf("%d", &N);
  for (int i = 0; i < N; ++i) {
    int a, b;
    scanf("%d %d", &a, &b);
    mm[{a, b}] = i;
    xy[a] = b;
    yx[b] = a;
  }

  while (xy.size()) {
    int count = 0;

    std::vector<std::pair<int, int>> found;
    auto first_y = xy.begin()->second;
    while (1) {
      auto y_st = yx.lower_bound(first_y);
      int prev_count = count;

      int furthest_x = y_st->second;
      for (auto y = y_st; y != yx.end(); ++y) {
        furthest_x = std::max(furthest_x, y->second);
        xy.erase(y->second);  // Erase X coord val.
        found.push_back({y->second, y->first});
        count++;
      }
      yx.erase(y_st, yx.end());  // Erase Y-range.
      if (count == prev_count) break;

      prev_count = count;
      auto x_en = xy.upper_bound(furthest_x);
      int lowest_y = xy.begin()->second;
      for (auto x = xy.begin(); x != x_en; ++x) {
        lowest_y = std::min(lowest_y, x->second);
        yx.erase(x->second);
        found.push_back({x->first, x->second});
        count++;
      }
      xy.erase(xy.begin(), x_en);
      first_y = lowest_y;
      if (count == prev_count) break;
    }
    for (auto p : found) {
      ans[mm[p]] = count;
    }
  }
  for (int i = 0; i < N; ++i) {
    printf("%d\n", ans[i]);
  }
}

