    UF uf(n);
    for(int i = 0; i < n; i++){
        int ind = xrev[i];
        if(!s.empty() && *s.begin() < y[ind]){
            uf.unite(yrev[*s.begin()], ind);
            auto it = s.begin()++;
            while(it != s.end() && *it < y[ind]){
                uf.unite(yrev[*it], ind);
                it = s.erase(it);
            }
        }
        s.insert(y[ind]);
    }
    for(int i = 0; i < n; i++)  cout << uf.m[uf.parent(i)] << endl;
    return 0;
}

