    vector<int> xtoi(n);
    for (int i = 0; i < n; i++) {
        cin >> x[i] >> y[i];
        --x[i]; --y[i];
        xtoi[x[i]] = i;
    }

    map<int, int> memo;
    UnionFind uf(n);
    for (int xx = n - 1; xx >= 0; --xx) {
        int i = xtoi[xx];
        auto it = memo.lower_bound(y[i]);
        if (it != memo.end()) uf.unite(i, it->second);
        memo[y[i]] = i;
    }

    for (int i = 0; i < n; i++) {
        cout << uf.size(i) << newl;
    }

    return 0;
}

