ll NcR(int n, int r) 
{ 

    ll p = 1, k = 1; 
    if (n - r < r) 
        r = n - r; 

    if (r != 0) { 
        while (r) { 
            p *= n; 
            k *= r; 

            ll m = __gcd(p, k); 
            p /= m; 
            k /= m; 
            n--; 
            r--; 
        } 
    } 

    else
        p = 1; 
    return p;
} 

ll find(ll a)
{
    if(parent[a]!= a) parent[a] = find(parent[a]);
    return parent[a];
}

void make_set(ll a)
{
    parent[a]=a;
    Size[a] = 1;
}

void Union(ll x, ll y)
{
    x = find(x);
    y = find(y);
    if(x != y) 
    {
        if(Size[x] > Size[y]) swap(x,y);
        parent[y] = x;
        Size[x] += Size[y];
    }
}

