struct fenwick_tree {
	vector<int> tree;
	int size;
	fenwick_tree(int size) {
		this->size = size;
		tree.resize(size + 1);
	}
	void add(int pos, int val) {
		pos++;
		while (pos <= size) {
			tree[pos] += val;
			pos += pos & -pos;
		}
	}
	int get(int pos) {
		pos++;
		int res = 0;
		while (pos) {
			res += tree[pos];
			pos -= pos & -pos;
		}
		return res;
	}
};

