struct ufds{
    int numsets;
    vector<int> p, rank, setsize;
    ufds(int n){
        numsets = n;
        rank.assign(n, 0);
        setsize.assign(n, 1);
        p.resize(n);
        iota(p.begin(), p.end(), 0);
    }
    int findset(int x){
        return (p[x] == x ? x : (p[x] = findset(p[x])));
    }
    bool same(int x, int y){
        return findset(x) == findset(y);
    }
    void combine(int x, int y){
        if(!same(x, y)){
            x = findset(x);
            y = findset(y);
            --numsets;
            if(rank[x] > rank[y]){
                setsize[x] += setsize[y];
                p[y] = x;
            }
            else{
                setsize[y] += setsize[x];
                p[x] = y;
                if(rank[x] == rank[y])rank[x]++;
            }
        }
    }
    int sz(int x){
        return setsize[findset(x)];
    }
};
void solve(){
    int n;
    cin >> n;
    vector<pair<pair<int,int>, int>> p(n);
    for(int i = 0; i < n; ++i){
        cin >> p[i].first.first;
        p[i].second = i;
    }
    for(int i = 0; i < n; ++i){
        cin >> p[i].first.second;
    }
    sort(p.begin(), p.end());
    for(auto i : p){
        cerr << i.first.second << " ";
    }
    cout << endl;
    vector<pair<int,int>> st;
    vector<int> left_idx(n);
    for(int i = 0; i < n; ++i){
        while(!st.empty() && st.back().first >= p[i].first.second){
            st.pop_back();
        }
        if(st.empty()){
            left_idx[i] = -1;
        }
        else{
            left_idx[i] = st.back().second;
        }
        st.push_back({p[i].first.second, i});
    }
    vector<int> right_idx(n);
    st.clear();
    for(int i = n - 1; i >= 0; --i){
        while(!st.empty() && st.back().first <= p[i].first.second){
            st.pop_back();
        }
        if(st.empty()){
            right_idx[i] = -1;
        }
        else{
            right_idx[i] = st.back().second;
        }
        st.push_back({p[i].first.second, i});
    }
    ufds U(n);
    for(int i = 0; i < n; ++i){
        if(left_idx[i] == -1){
            continue;
        }
        U.combine(i, left_idx[i]);
    }
    for(int i = n - 1; i >= 0; --i){
        if(right_idx[i] == -1){
            continue;
        }
        U.combine(i, right_idx[i]);
    }
    vector<int> ans(n);
    for(int i = 0; i < n; ++i){
        ans[p[i].second] = U.sz(i);
    }
    for(auto i : ans){
        cout << i << endl;
    }

}
