void update(int idx , int b , int e , int i , int x)
{
    if(i<b || i>e) return;
    if(b == e){
        trr[idx] = {x,i};
        return;
    }

    int mid = (b+e)>>1;
    update(LEF,b,mid,i,x);
    update(RIG,mid+1,e,i,x);
    trr[idx] = trr[RIG];
    if(trr[LEF] > trr[idx]) trr[idx] = trr[LEF];
}

pair < int , int > get(int idx , int b , int e , int i , int j )
{
    if(j<b || e<i || i>j) return {0,0};
    if(i<=b && j>=e) return trr[idx];
    int mid = (b+e)>>1;
    pair < int , int > ans = get(RIG,mid+1,e,i,j) , tmp = get(LEF,b,mid,i,j);
    if(ans >= tmp) return ans;
    return tmp;
}

