      void build(vector <int> &arr) {
            for (int i = 0; i < n; i++) Table[0][i] = arr[i];
            for (int k = 1; (1 << k) <= n; k++) {
                  for (int i = 0; i + (1 << (k - 1)) < n; i++) {
                        T x = Table[k - 1][i];
                        T y = Table[k - 1][i + (1 << (k - 1))];
                        Table[k][i] = min(x, y);
                  }
            }
      }
      T query(int i, int j) {
            int k = log2(j - i + 1);
            T x = Table[k][i];
            T y = Table[k][j + 1 - (1 << k)];
            return min(x, y);
      }
};

signed main()
{
      ios_base::sync_with_stdio(false);
      cin.tie(nullptr); cout.tie(nullptr);
      cout.precision(12);

      bool FILEIO = 1;
      if (FILEIO and fopen("in.txt", "r")) {
            freopen("in.txt", "r", stdin);
      }

      int n;
      cin >> n;
      vector <Node> vec;
      for (int i = 0; i < n; i++) {
            int x, y;
            cin >> x >> y;
            vec.eb(x, y, i);
      }
      sort(all(vec));
      vector <int> ans(n);
      vector <int> arr;
      for (int i = 0; i < n; i++) {
            arr.pb(vec[i].y);
      }
      SparseTableMax <int> maxt; maxt.init(n); maxt.build(arr);
      SparseTable <int> mint; mint.init(n); mint.build(arr);
      for (int i = 0; i < n; i++) {
            int lo = i;
            int hi = n - 1;
            int id = i;
            while (lo <= hi) {
                  int mid = lo + hi >> 1;
                  int maxi = maxt.query(mid, n - 1);
                  if (maxi > vec[i].y) {
                        id = mid;
                        lo = mid + 1;
                  }
                  else {
                        hi = mid - 1;
                  }
            }
            int rgt = id - i;
            int mymax = maxt.query(i, id);
            int sum = rgt;

            {
                  int lo = 0;
                  int hi = i - 1;
                  int id = i;
                  while (lo <= hi) {
                        int mid = lo + hi >> 1;
                        int mini = mint.query(0, mid);
                        if (mini < mymax) {
                              id = mid;
                              hi = mid - 1;
                        }
                        else {
                              lo = mid + 1;
                        }
                  }
                  int lft = i - id;
                  sum += lft;
            }
            ans[ vec[i].id ] = sum;
      }
      for (int i = 0; i < n; i++) {
            cout << ans[i] + 1 << endl;
      }
}

