class union_find{
public:
	vector<int> arr;
	union_find(int n){
		arr.resize(n);
		fill(arr.begin(),arr.end(),-1);
	}
	int find(int x){
		return arr[x]<0?x:arr[x]=find(arr[x]);
	}
	void unite(int x,int y){
		x=find(x),y=find(y);
		if(x==y) return;
		if(arr[x]>arr[y]) swap(x,y);
		arr[x]+=arr[y];
		arr[y]=x;
	}
	bool connected(int x,int y){
		return find(x) == find(y);
	}
	int size(int x){
		return -arr[find(x)];
	}
};
