template <typename T = int>
struct UnionFind
{
    vector<int> data;
    vector<T> sz;
    bool is_default;
    int num;

    UnionFind(int n) : num(n)
    {
        data.assign(n, -1);
        sz.assign(n, 1);
        is_default = true;
    }

    UnionFind(int n, vector<T> &a) : num(n)
    {
        data.assign(n, -1);
        sz = a;
        is_default = false;
    }

    bool unite(int x, int y)
    {
        x = find(x), y = find(y);
        if (x == y)
            return false;
        num--;
        if (data[x] > data[y])
            swap(x, y);
        data[x] += data[y];
        if (!is_default)
            sz[x] += sz[y];
        data[y] = x;
        return true;
    }

    bool same(int x, int y) { return find(x) == find(y); }

    int find(int x)
    {
        if (data[x] < 0)
            return x;
        return (data[x] = find(data[x]));
    }

    T size(int x) { return (is_default ? -data[find(x)] : sz[find(x)]); }
};
template <typename T = long long>
struct SegmentTree
{
    using F = function<T(T, T)>;
#define clz(x) __builtin_clz(x)

    SegmentTree(int n, const F f, const T &unit) : f(f), unit(unit), sz(n - 1 ? 1 << (32 - clz(n - 1)) : 1)
    {
        seg.assign(2 * sz, unit);
    }

    SegmentTree(vector<T> &a, const F f, const T &unit) : f(f), sz((int)a.size() > 1 ? 1 << (32 - clz(a.size() - 1)) : 1), unit(unit)
    {
        int n0 = a.size();
        seg.assign(2 * sz, unit);
        for (int i = 0; i < n0; ++i)
            seg[i + sz] = a[i];
        for (int i = sz - 1; i > 0; --i)
            seg[i] = f(seg[i << 1], seg[(i << 1) | 1]);
    }
    const int sz;
    vector<T> seg;
    const F f;
    const T unit;

    void set(int k, T x) { seg[k + sz] = x; }

    void build()
    {
        for (int i = sz - 1; i > 0; --i)
            seg[i] = f(seg[i << 1], seg[(i << 1) | 1]);
    }

    T query(int l, int r)
    {
        T x = unit;
        for (int d = r - l; d >= 1; d = r - l)
        {
            int L = l | ((1U << 31) >> clz(d));
            int k = __builtin_ctz(L);
            x = f(x, seg[(sz | l) >> k]);
            l += L & (-L);
        }
        return x;
    }

    void update(int i, T x)
    {
        int k = i + sz;
        seg[k] = x;
        for (k = k >> 1; k > 0; k >>= 1)
        {
            seg[k] = f(seg[k << 1], seg[(k << 1) | 1]);
        }
    }

    void add(int i, T x)
    {
        int k = i + sz;
        seg[k] += x;
        for (k = k >> 1; k > 0; k >>= 1)
        {
            seg[k] = f(seg[k << 1], seg[(k << 1) | 1]);
        }
    }
    SegmentTree() = default;
    T operator[](int k) const { return seg[sz + k]; }
};

