struct UnionFind {
  private:
  vector<int> child,tree;
  vector<vector<int>> list;

public:
  UnionFind(int v) {
    tree.resize(v);
    list.resize(v);
    REP(i,v) tree[i] = i, list[i].push_back(i);
  }

  int root(int i){
    if(i == tree[i]){
      REP(j,child.size()) tree[child[j]] = i;
      child.clear(); 
      return i;
    }
    else{
      child.push_back(i);
      return i = root(tree[i]);
    }
  }

  int size(int i){
    return list[root(i)].size();
  }

  vector<int> nodes(int no){
    return list[root(no)];
  }

  bool unit(int x, int y){
    x = root(x);
    y = root(y);
    if(x==y) return false;
    if(list[x].size() < list[y].size()) swap(x,y);
    for(int no:list[y]) list[x].emplace_back(no);
    tree[y] = x;
    return true;
  }

  bool isUnit(int x, int y){
    return root(x) == root(y);
  }
};

void solve(){
  int N;
  cin >> N;

  vector<int> a(N), id(N);
  UnionFind uf(N);
  REP(i,N){
    int x,y;
    cin >> x >> y;
    a[x-1] = y-1;
    id[i] = x-1;
  }

  priority_queue<P,vector<P>,greater<P>> que;
  REP(i,N){
    P p;
    if(que.size()) p = que.top(); 
    bool flag = true;
    while(que.size()&&que.top().fs < a[i]){
      uf.unit(i,que.top().sc);
      que.pop();
      flag = false;
    }
    if(flag) que.push(P(a[i],i));
    else que.push(p);
  }

  REP(i,N) cout << uf.size(id[i]) << endl;

}

