struct Dsu
{
	int par[N], siz[N];
	Dsu() {
		for(int i = 0; i < N; i++) {
			par[i] = i, siz[i] = 1;
		}
	}
	int root(int x) {
		return (x == par[x] ? x : (par[x]=root(par[x])));
	}
	void merge(int u, int v) {
		u = root(u), v = root(v);
		if(u == v) return;
		if(siz[v] > siz[u])swap(u, v);
		siz[u] += siz[v];
		par[v] = u;
	}
}ds;

