    P.at(i) = {X.at(i), Y.at(i), i};
    y_to_index.at(Y.at(i)) = i;
    y_remain.insert(Y.at(i));
  }
  sort(P.begin(), P.end());
  for (ll i = 0; i < N; ++i) {
    vector<ll> now = P.at(i);
    ll x = now.at(0), y = now.at(1), index = now.at(2);
    auto itr1 = y_remain.lower_bound(y);
