        id[x] = i;
    }
    union_find uf;
    uf.init(n);
    set<P> st;
    REP(i,n){
        while (!st.empty() && st.begin()->first < y[i]){
            P p = *st.begin();
            st.erase(p);
            uf.merge(id[i], p.second);
        }
        st.insert(P(y[i], id[i]));
    }
    REP(i,n){
        printf("%d\n", uf.size(i));
    }

    return 0;
}

