const int N = (int) 2e5 + 7;
int n;
int t[N];
int sz[N];
int mn[N];

int root(int a)
{
    if (t[a] == a)
    {
        return a;
    }
    else
    {
        return t[a] = root(t[a]);
    }
}

void unite(int a, int b)
{
    a = root(a);
    b = root(b);
    if (a != b)
    {
        t[a] = b;
        sz[b] += sz[a];
        mn[b] = min(mn[b], mn[a]);
    }
}

struct T
{
    int x;
    int y;
    int i;
};

bool cmp(T a, T b)
{
    return a.x < b.x;
}

T a[N];
