int main()
{
    ios::sync_with_stdio(0);
    cin.tie(0);

    cin >> n;
    for (int i = 1; i <= n; i++)
    {
        t[i] = i;
        sz[i] = 1;
        mn[i] = i;
        cin >> a[i].x >> a[i].y;
        a[i].i = i;
    }
    sort(a + 1, a + n + 1, cmp);
    for (int i = 1; i <= n; i++)
    {
        pos[a[i].y] = i;
    }
    set<int> s;
    for (int i = 1; i <= n; i++)
    {
        int val = a[i].y;
        auto it = s.lower_bound(val);
        if (it != s.begin())
        {
            it--;
            unite(i, pos[*it]);
        }
        s.insert(val);
    }
    s.clear();
    for (int i = n; i >= 1; i--)
    {
        int val = a[i].y;
        auto it = s.lower_bound(val);
        if (it != s.end())
        {
            unite(i, pos[*it]);
        }
        s.insert(val);
    }
    for (int i = 1; i <= n; i++)
    {
        sol[a[i].i] = sz[root(i)];
    }
    for (int i = 1; i <= n; i++)
    {
        cout << sol[i] << "\n";
    }
}

