using namespace std;
const int N=200000;
int Root[N],Rank[N],Size[N];
int find(int x){
    if(Root[x]==x)return x;
    else return Root[x]=find(Root[x]);
}
void unite(int x,int y){
    int X=find(x);
    int Y=find(y);
    if(X==Y)return;
    if(Rank[X]<Rank[Y]){
        Root[X]=Y;
        Size[Y]+=Size[X];
    }
    else{
        Root[Y]=X;
        Size[X]+=Size[Y];
        if(Rank[X]==Rank[Y])Rank[X]++;
    }
    return;
}
int main(){
    int n;
    cin>>n;
    for(int i=0;i<n;i++)Root[i]=i,Rank[i]=0,Size[i]=1;
    int x[n],y[n];
    for(int i=0;i<n;i++)cin>>x[i]>>y[i];
    if(n==1){
        cout<<"1"<<endl;
        return 0;
    }
    tuple<int,int,int> a[n],b[n];
    for(int i=0;i<n;i++){
        a[i]={x[i],y[i],i};
        b[i]={y[i],x[i],i};
    }
    sort(a,a+n);
    sort(b,b+n);
    int ays=get<1>(a[0]),ais=get<2>(a[0]),bxs=get<1>(b[0]),bis=get<2>(b[0]),
        ays2=get<1>(a[1]),ais2=get<2>(a[1]),bxs2=get<1>(b[1]),bis2=get<2>(b[1]),
        ayg=get<1>(a[n-1]),aig=get<2>(a[n-1]),bxg=get<1>(b[n-1]),big=get<2>(b[n-1]),
        ayg2=get<1>(a[n-2]),aig2=get<2>(a[n-2]),bxg2=get<1>(b[n-2]),big2=get<2>(b[n-2]);
    for(int i=0;i<n-1;i++){
        int ay0=get<1>(a[i]),ai0=get<2>(a[i]),
            ay1=get<1>(a[i+1]),ai1=get<2>(a[i+1]),
            bx0=get<1>(b[i]),bi0=get<2>(b[i]),
            bx1=get<1>(b[i+1]),bi1=get<2>(b[i+1]);
        if(ay0<ay1)unite(ai0,ai1);
        if(bx0<bx1)unite(bi0,bi1);
        if(ays<ay1)unite(ais,ai1);
        if(ays2<ay1)unite(ais2,ai1);
        if(bxs<bx1)unite(bis,bi1);
        if(bxs2<bx1)unite(bis2,bi1);
        if(ay0<ayg)unite(ai0,aig);
        if(ay0<ayg2)unite(ai0,aig2);
        if(bx0<bxg)unite(bi0,big);
        if(bx0<bxg2)unite(bi0,big2);
    }
    for(int i=0;i<n;i++)cout<<Size[find(i)]<<endl;
    return 0;
}

