using namespace std;

class UnionFindTree {
private:
    vector<int> parent;
    vector<int> count;

public:
    UnionFindTree(int n) : parent(n), count(n, 1) {
        // 最初は全てを根として初期化
        for (int i = 0; i < n; i++) parent[i] = i;
    }
    int get_root(const int x) {
        // データxが属する木の根を取得する
        if (parent[x] == x) return x;
        // 取得したものは直接木の根をつなぐ(経路圧縮)
        return parent[x] = get_root(parent[x]);
    }
    void unite(const int x, const int y) {
        // xとyの木を併合する
        int rx = get_root(x);
        int ry = get_root(y);
        // 元から同じ木に属している場合は何もしない
        if (rx == ry) return;
        // xの属する木をyの属する木につける
        parent[rx] = ry;
        count[ry] += count[rx];
        count[rx] = 0;
    }
    bool is_same_root(const int x, const int y) {
        return get_root(x) == get_root(y);
    }
    int get_size(const int x) { return count[get_root(x)]; }
    void print() {
        for (auto elm : parent) cout << elm << " ";
        cout << endl;
        for (auto elm : count) cout << elm << " ";
        cout << endl;
    }
};
int main() {
    int n;
    cin >> n;
    vector<pair<int, int>> p(n);
    UnionFindTree tree(n);
    for (auto i = 0; i < n; i++)
        cin >> p[i].first >> p[i].second;
    for (auto i = 0; i < n; i++) {
        for (auto j = i + 1; j < n; j++) {
            if ((p[i].first < p[j].first and
                 p[i].second < p[j].second) or
                (p[i].first > p[j].first and
                 p[i].second > p[j].second))
                tree.unite(i, j);
        }
        cout << tree.get_size(i) << endl;
    }
    return 0;
}

