vector<int>S;
void init(int N) {
  par.resize(N + 1);
  S.resize(N + 1);
  for (int i = 0; i <= N; i ++) {
    par[i] = i;
    S[i] = 1;
  }
}
int root(int v) {
  if (v == par[v]) return v;
  return par[v] = root(par[v]);
}
int siz(int v) {
  return S[root(v)];
}
void merge(int a, int b) {
  a = root(a);
  b = root(b);
  if (a == b) return;
  if (siz(a) < siz(b)) swap(a, b);
  par[b] = a;
  S[a] += S[b];
}

int main () {
  int N;
  cin >> N;
  init(N);
  vector<tuple<int, int, int>> X_yu(N);
  vector<tuple<int, int, int>> Y_yu(N);
  for (int i = 0; i < N; i ++) {
    int x, y;
    cin >> x >> y;
    X_yu[i] = make_tuple(x, y, i);
    Y_yu[i] = make_tuple(y, x, i);
  }
  sort(X_yu.begin(), X_yu.end());
  sort(Y_yu.begin(), Y_yu.end());
  int fl = N;
  for (int i = 0; i < N; i ++) {
    int x, y, i_;
    tie(x, y, i_) = X_yu[i];
    for (int j = y; j < fl; j ++) {
      merge(i_, get<2>(Y_yu[j]));
      //cout << i_ << ' ' << get<2>(Y_yu[j]) << endl;
    }
    fl = min(fl, y - 1);
  }
  fl = -1;
  for (int i = N - 1; i >= 0; i --) {
    int x, y, i_;
    tie(y, x, i_) = Y_yu[i];
    for (int j = x - 1; j > fl; j --) {
      merge(i_, get<2>(X_yu[j]));
      //cout << i_ << ' ' << get<2>(X_yu[j]) << endl;
    }
    fl = max(fl, x);
  }
  for (int i = 0; i < N; i ++) cout << siz(i) << endl;
}

