        --x[i]; --y[i];
        xtoi[x[i]] = i;
    }

    map<int, int> memo;
    UnionFind uf(n);
    for (int xx = n - 1; xx >= 0; --xx) {
        int i = xtoi[xx];
        int lasti = i;
        for (auto it = memo.lower_bound(y[i]); it != memo.end(); ) {
            uf.unite(i, it->second);
            lasti = it->second;
            it = memo.erase(it);
        }
        memo[y[lasti]] = lasti;
    }

    for (int i = 0; i < n; i++) {
        cout << uf.size(i) << newl;
    }

    return 0;
}

