struct UnionFind {
    vector<int> par, w;

    UnionFind(int n) : par(n, -1), w(n, 0) { }
    void init(int n) { par.assign(n, -1); w.assign(n, 0); }

    int root(int x) {
        if (par[x] < 0) return x;
        else return par[x] = root(par[x]);
    }

    bool issame(int x, int y) {
        return root(x) == root(y);
    }

    bool merge(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) {
            ++w[x];
            return false;
        }
        if (par[x] > par[y]) swap(x, y); // merge technique
        par[x] += par[y];
        par[y] = x;
        w[x] += w[y];
        ++w[x];
        return true;
    }

    int size(int x) {
        return -par[root(x)];
    }

    int wei(int x) {
        return w[root(x)];
    }
};

void solve() {
	int n; cin >> n;
    vector<int> x(n), y(n);
    rep(i, n) {
        cin >> x[i] >> y[i];
        -- x[i], -- y[i];
    }
    vector<int> ids(n);
    iota(all(ids), 0);
    sort(all(ids), [&](int i, int j){ return y[i] > y[j];});
    UnionFind uf(n);
    set<P> se;
    rep(i, n) {
        int id = ids[i];
        int curx = x[id];
        auto ite = se.lower_bound(P{curx, -inf});
        if(ite != se.end()) {
            P p = *ite;
            int id2 = p.sc;
            uf.merge(id, id2);
        }
        se.insert(P{x[id], id});
    }
    se.clear();
    per(i, n) {
        int id = ids[i];
        int curx = x[id];
        auto ite = se.lower_bound(P{-curx, -inf});
        if(ite != se.end()) {
            P p = *ite;
            int id2 = p.sc;
            uf.merge(id, id2);
        }
        se.insert(P{-x[id], id});
    }
    rep(i, n) {
        cout << (int)uf.size(i) << endl;
    }
}

