struct SegTree2d {
    vector<ivec> data;
    int N;
    int idVal;
    // function<T(T const&, T const&)> combine;
    // function<void(T &, T const&)> leafMod;
    ivec combine(const ivec& a, const ivec& b) {
        ivec res;
        int ap = 0;
        int bp = 0;
        while (ap < a.size() && bp < b.size()) {
            if (a[ap] < b[bp]) {
                res.push_back(a[ap]);
                ap++;
            } else {
                res.push_back(b[bp]);
                bp++;
            }
        }
        while (ap < a.size()) {
            res.push_back(a[ap]);
            ap++;
        }
        while (bp < b.size()) {
            res.push_back(b[bp]);
            bp++;
        }
        return res;
    }

    int county(const ivec& a, int ly, int ry) {
        auto it1 = lower_bound(a.begin(), a.end(), ly);
        auto it2 = lower_bound(a.begin(), a.end(), ry);
        return distance(it1, it2);
    }

    ivec gety(const ivec& a, int ly, int ry) {
        ivec res;
        auto it1 = lower_bound(a.begin(), a.end(), ly);
        auto it2 = lower_bound(a.begin(), a.end(), ry);
        for (auto it = it1; it != it2; ++it) {
            res.push_back(*it);
        }
        return res;
    }

    SegTree2d(vector<ivec> const&base): N(base.size()), idVal(0) {
        data.resize(2*N);
        copy(base.begin(), base.end(), data.begin()+N);
        for(int i=N-1;i>=0;--i){
            data[i]=combine(data[i<<1], data[i<<1|1]);
        }
    }
    ivec query(int lx, int rx, int ly, int ry) {
        int l = lx;
        int r = rx;
        ivec retL, retR;
        for(l+=N, r+=N;l<r;l>>=1, r>>=1){
            if(l&1) {
                retL = combine(retL, gety(data[l++], ly, ry));
                // int cc = county(data[l++], ly, ry);
                // retL += cc;
            }
            if(r&1) {
                retR = combine(retR, gety(data[--r], ly, ry));
            }
        }
        return combine(retL, retR);
    }
};

