struct UnionFind{
    vector<int> data;

    UnionFind(int sz){
        data.assign(sz, -1);
    }

    int find(int k){
        if(data[k] < 0) return k;
        return data[k] = find(data[k]);
    }

    bool unite(int x, int y){
        x = find(x), y = find(y);
        if(x == y) return false;
        if(data[x] > data[y]) swap(x, y);
        data[x] += data[y];
        data[y] = x;
        return true;
    }

    bool same(int x, int y){
        return find(x) == find(y);
    }

    int size(int k){
        return -data[find(k)];
    }

};

int main(){
    int n;cin >> n;
    vector<pair<P,int>> v(n);
    for (int i = 0; i < n; i++) {
        int x,y;cin >> x >> y;
        x--,y--;
        v[i] = mp(mp(x, y),i);
    }
    sort(ALL(v));
    priority_queue<P ,vector<P>, greater<P>> pq;
    UnionFind uf(n);
    for (int i = 0; i < n; i++) {
        int id = v[i].sc;
        ll mini = v[i].fs.sc;
        while(not pq.empty() and pq.top().fs < v[i].fs.sc){
            auto pp = pq.top(); pq.pop();
            chmin(mini, pp.fs);
            uf.unite(pp.sc, id);
        }
        pq.push(mp(mini, id));
    }
    for (int i = 0; i < n; i++) {
        cout << uf.size(i) << endl;
    }
    return 0;
