        ll x, y; scan(x, y);
        --x, --y;
        vs[x] = y;
        ord[x] = i;
    }

    set<pair<ll, ll>> ss;
    ss.insert({vs[0], 0});
    For(i, 1, n){
        auto it = ss.begin();
        if ((*it).first > vs[i]) {ss.insert({vs[i], i}); continue;}
        m = (*it).first;
        while (it != ss.end() && (*it).first < vs[i]){
            tie(val, par) = *it;
            ss.erase(it++);
            uf.unite(i, par);
        }
        ss.insert({m, uf.parents[i]});
    }

    rep(i, n) ans[ord[i]] = uf.size(i);
    println(ans);
}

