const int maxn = 2e5 + 10;
int N, ans[maxn];

struct node {
  int x, y, tid;
} A[maxn];

int par[maxn], sz[maxn];

int find(int x) {
  return par[x] == x ? x : par[x] = find(par[x]);
}

void unite(int x, int y) {
  if ((x = find(x)) != (y = find(y))) {
    par[x] = y, sz[y] += sz[x];
  }
}

bool check(int i, int j) {
  return (A[i].x < A[j].x && A[i].y < A[j].y) || (A[i].x > A[j].x && A[i].y > A[j].y);
}

struct cmp {
  bool operator () (int P, int Q) const {
    return A[P].y < A[Q].y;
  }
};

void calc() {
  sort(A + 1, A + N + 1, [] (node P, node Q) {
    return P.x < Q.x;
  });
  set <int, cmp> S;
  rep(i, 1, N) {
    while (!S.empty() && check(*S.begin(), i)) {
      unite(*S.begin(), i), S.erase(S.begin());
    }
    S.insert(i);
  }
  S.clear();
  per(i, N, 1) {
    while (!S.empty() && check(*S.rbegin(), i)) {
      unite(*S.rbegin(), i), S.erase(*S.rbegin());
    }
    S.insert(i);
  }
  rep(i, 1, N) ans[A[i].tid] = sz[find(i)];
}

void solve() {
  cin >> N;
  rep(i, 1, N) {
    par[i] = i, sz[i] = 1;
    A[i].x = read(), A[i].y = read(), A[i].tid = i;
  }
  calc();
  rep(i, 1, N) printf("%d\n", ans[i]);
}

