int par[MAXN],sz[MAXN];
void make_set(int s)
{
    par[s]=s;
    sz[s]=1;
}
int find_set(int s)
{
    if (par[s]==s)
        return s;
    return par[s]=find_set(par[s]);
}
void union_sets(int u,int v)
{
    u=find_set(u);
    v=find_set(v);
    if (u!=v)
    {
        if (sz[u]<sz[v])
            swap(u,v);
        par[v]=u;
        sz[u]+=sz[v];
    }
}
pii t[4*MAXN];
int a[MAXN];
void build(int v,int vl,int vr)
{
    if (vl==vr)
    {
        t[v]={a[vl],a[vl]};
        return;
    }
    int mid=((vl+vr)>>1);
    build(2*v+1,vl,mid);
    build(2*v+2,mid+1,vr);
    t[v]={min(t[2*v+1].fi,t[2*v+2].fi),max(t[2*v+1].se,t[2*v+2].se)};
}
void update(int v,int vl,int vr,int pos,int x,int y)
{
    if (vl==vr)
    {
       t[v]={x,y};
       return;
    }
    int mid=((vl+vr)>>1);
    if (pos<=mid)
        update(2*v+1,vl,mid,pos,x,y);
    else
        update(2*v+2,mid+1,vr,pos,x,y);
    t[v]={min(t[2*v+1].fi,t[2*v+2].fi),max(t[2*v+1].se,t[2*v+2].se)};
}
pii query(int v,int vl,int vr,int l,int r)
{
    if (vl>r||vr<l)
        return {INF,-1};
    if (l<=vl&&vr<=r)
        return t[v];
    int mid=((vl+vr)>>1);
    pii x=query(2*v+1,vl,mid,l,r);
    pii y=query(2*v+2,mid+1,vr,l,r);
    return {min(x.fi,y.fi),max(x.se,y.se)};
}
