                    y_down=max(y_down,a[ind]);
                    a[ind]=INF;
                    update(0,0,n-1,ind,INF,-1);
                }
            }
            if (!ok)
                break;
        }
    }
    for (int i=0;i<n;i++)
    {
        ans[what[i]]=sz[find_set(i)];
    }
    for (auto to:ans)
        cout<<to<<'\n';
}

