using LL = long long;
using P = pair<int,int>;
using E = pair<P,int>;

class UnionFind {
public:
    vector <LL> par;
    vector <LL> siz;

    UnionFind(LL sz_): par(sz_), siz(sz_, 1LL) {
        for (LL i = 0; i < sz_; ++i) par[i] = i;
    }
    void init(LL sz_) {
        par.resize(sz_);
        siz.assign(sz_, 1LL);
        for (LL i = 0; i < sz_; ++i) par[i] = i;
    }

    LL root(LL x) {
        while (par[x] != x) {
            x = par[x] = par[par[x]];
        }
        return x;
    }

    bool unite(LL x, LL y) {
        x = root(x);
        y = root(y);
        if (x == y) return false;
        if (siz[x] < siz[y]) swap(x, y);
        siz[x] += siz[y];
        par[y] = x;
        return true;
    }

    bool same(LL x, LL y) {
        return root(x) == root(y);
    }

    LL size(LL x) {
        return siz[root(x)];
    }
};

int main(){
	int N;
	cin >> N;
	vector<P> c(N);
	rep(i,N){
		int x, y;
		cin >> x >> y;
		c[i]=P(x,y);
	}
	vector<E> v(N);
	rep(i,N) v[i]=E(c[i],i);
	sort(v.begin(),v.end());
	sort(c.begin(),c.end());
	vector<P> min_left(N), max_right(N);
	min_left[0]=P(c[0].second,v[0].second);
	max_right[N-1]=P(c[N-1].second,v[N-1].second);
	rep(i,N-1){
		int m=min_left[i].first;
		if(c[i+1].second<m){
			min_left[i+1]=P(c[i+1].second,v[i+1].second);
		}
		else min_left[i+1]=min_left[i];
		int M=max_right[N-1-i].first;
		if(c[N-2-i].second>M){
			max_right[N-2-i]=P(c[N-2-i].second,v[N-2-i].second);
		}
		else max_right[N-2-i]=max_right[N-1-i];
	}
	UnionFind uf(N);
	rep(i,N){
		P m=min_left[i], M=max_right[i];
		if(m.first<c[i].second){
			uf.unite(m.second,v[i].second);
