int N;
V<tiii> XYi;
SegmentTree<int> seg1, seg2;
UnionFind uf;
V<bool> isUsed;
V<> valToIndY;  // Y 座標からソート後のインデックスへ
V<> indToInd;   // ソート後のインデックスからソート前のインデックスへ

void dfs(int i) {
    if(isUsed[i]) { return; }
    isUsed[i] = true;
    // 自分より右上に行く
    if(i + 1 < N) {
        int res = seg1.Query(i + 1, N);
        if(res > get<1>(XYi[i])) {
            int next_ind = valToIndY[res];
            uf.Unite(get<2>(XYi[i]), indToInd[next_ind]);
            dfs(next_ind);
        }
    }
    // 自分より左下に行く
    {
        int res = seg2.Query(0, i);
        if(res < get<1>(XYi[i])) {
            int next_ind = valToIndY[res];
            uf.Unite(get<2>(XYi[i]), indToInd[next_ind]);
            dfs(next_ind);
        }
    }
}

