const int maxn = 2e5;

int n;
vector<int> a;
vector<pair<int, int>> city;
vector<int> ind;

vector<int> parent(maxn + 1);
vector<int> sze(maxn + 1, 1);

int find_parent(int v) {
	if (v == parent[v]) return v;
	return parent[v] = find_parent(parent[v]);
}

void union_set(int a, int b) {
	a = find_parent(a);
	b = find_parent(b);

	if (a != b) {
		if (sze[a] < sze[b]) swap(a, b);

		parent[b] = a;
		sze[a] += sze[b];
	}
	return;
}

int main() {

	iota(parent.begin(), parent.end(), 0);

	cin >> n;
	ind.resize(n + 1);
	city.resize(n); for (int i = 0; i <= n - 1; i++) cin >> city[i].ff >> city[i].ss, ind[city[i].ff] = i + 1;

	a.resize(n + 1, 0);
	for (auto p : city) a[p.ff] = p.ss;
	debug() << imie(a);
	vector<int> st;

	for (int i = 1; i <= n; i++) {
		while (!st.empty() and a[st.back()] < a[i]) {
			union_set(ind[i], ind[st.back()]);
			st.pop_back();
		}
		st.push_back(i);
	}

	for (int i = 1; i <= n; i++) cout << sze[find_parent(i)] << "\n";

	return 0;
}

