const ll N   =  500005;

	// Disjoint Set DataStructure
	ll par[N]; 		// reserve space for map if n > 10000
	ll urank[N];



	ll find(ll x){

		if( par[x] != x )	//path compression
		{
			par[x] = find(par[x]) ;
		}
		return par[x];
	}

	void merge(ll x, ll y)
	{
		ll xroot = find(x);
		ll yroot = find(y);
		if(xroot == yroot)
			return;

		if( urank[xroot] <= urank[yroot] )	// Union by rank
		{
			par[xroot] = yroot ;
			urank[yroot] = urank[yroot] + urank[xroot] ;
		}
		else
		{
			par[yroot] = xroot;
			urank[xroot] = urank[xroot] + urank[yroot] ;
		}
	}


