//    for (int64_t i = 0; i < N; i++) {
//        points[i].x = i;
//        points[i].y = i;
//        points[i].index = i;
//    }

    dsu d(N);

    //y順に昇順ソート
    sort(points.begin(), points.end(), [](Point& lhs, Point& rhs) {
        return lhs.y < rhs.y;
    });
    set<pair<int64_t, int64_t>> st;
    for (const Point p : points) {
        auto itr_end = st.upper_bound(make_pair(p.x, p.index));
        bool merge = false;
        for (auto itr = st.begin(); itr != itr_end; itr++) {
            d.merge(itr->second, p.index);
            merge = true;
        }
        if (!merge) {
            st.insert(make_pair(p.x, p.index));
        }
    }

    //y順に降順ソート
    sort(points.begin(), points.end(), [](Point& lhs, Point& rhs) {
      return lhs.y > rhs.y;
    });
