template<class T>
struct FenwickTree1D 
{
    vector<T> bit;  // binary indexed tree
    int n;

    FenwickTree1D(int a) {
        this->n = a + 1;
        bit.assign(a + 1, 0);
    }

    FenwickTree1D(vector<T> a): FenwickTree1D(a.size()) 
    {
        for (size_t i = 0; i < a.size(); i++)
        add(i, a[i]);
    }

    T sum(int idx) 
    {
        T ret = 0;
        for (++idx; idx > 0; idx -= idx & -idx)
        ret += bit[idx];
        return ret;
    }

    T sum(int l, int r) 
    {
        return sum(r) - sum(l - 1);
    }

    void add(int idx, T delta) 
    {
        for (++idx; idx < n; idx += idx & -idx)
            bit[idx] += delta;
    }
};
