class dsu {
	public:
	vector<int> p;
	vector<int> size;
	int n;

	dsu(int _n) : n(_n) {
		p.resize(n+1);
		iota(p.begin(), p.end(), 0);
		size.assign(n+1,1LL);
	}

	inline int get(int x) {
		return (x == p[x] ? x : (p[x] = get(p[x])));
	}

	inline bool unite(int x, int y) {
		x = get(x);
		y = get(y);
		if (x != y) {
			p[x] = y;
			size[y]+=size[x];
			return true;
		}
		return false;
	}

	inline int sz(int x){
		x = get(x);
		return size[x];
	}
};

