            if(!pq.empty()) nval = pq.top().first;
            else nval = z[i].first.second;
            while(!pq.empty() && pq.top().first <= z[i].first.second) {
                uf.unite(pq.top().second, z[i].second);
                pq.pop();
            }
            pq.push({nval, z[i].second});
        }
    }
    REP(i, N) {
        cout << uf.size(i) << endl;
    }
    return 0;
}

