}

using min_segtree = atcoder::segtree<li, li_min, li_min_e>;
using max_segtree = atcoder::segtree<li, li_max, li_max_e>;

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    li n;
    cin >> n;
    min_segtree ys(n);
    max_segtree xs(n);
    set<pair<li, li>> xis;
    set<pair<li, li>> yis;
    vector<li> ans(n), ixs, iys;

    for (int i = 0; i < n; ++i) {
        li x, y;
        cin >> x >> y;
        x--; y--;
        xis.emplace(x, i);
        yis.emplace(y, i);
        xs.set(y, x);
        ys.set(x, y);
        ixs.push_back(x);
        iys.push_back(y);
    }

    while (not xis.empty()) {
        const li leftmost_x = xis.begin()->first;
        li cur_y = ys.get(leftmost_x);
        li cur_x = leftmost_x;
        while (true) {
            li next_x = xs.prod(cur_y + 1, n);
            if (next_x <= cur_x) {
                break;
            }
            cur_x = next_x;

            li next_y = ys.prod(0, cur_x);
            if (next_y >= cur_y) {
                break;
            }
            cur_y = next_y;
        }

        set<li> uni;
        for (auto p : xis) {
            const li x = p.first;
            if (x <= cur_x) {
                uni.emplace(p.second);
            } else {
                break;
            }
        }
        for (auto p : yis) {
            const li y = p.first;
            if (y >= cur_y) {
                uni.emplace(p.second);
            } else {
                break;
            }
        }
        for (auto i: uni) {
            const li x = ixs[i];
            const li y = iys[i];
            ans[i] = uni.size();
            xis.erase(make_pair(x, i));
            yis.erase(make_pair(y, i));
        }
    }
    for (int i = 0; i < n; ++i) {
        cout << ans[i] << endl;
    }

    return 0;
}

