using namespace std;

struct DSU {
  int yy[maxn+5], sy[maxn+5];
  void rest (int n) {
    for (int i = 1; i <= n; i++) {
      yy[i] = i;
      sy[i] = 1;
    }
  }
  int afla (int x) {
    int r = x, aux;
    while (yy[r] != r) r = yy[r];
    while (x != r) {
      aux = yy[x];
      yy[x] = r;
      x = aux;
    }
    return r;
  }
  void uneste (int x, int y) {
    x = afla(x);
    y = afla(y);
    if (x == y) return;
    if (sy[x] < sy[y]) swap(x, y);
    sy[x] += sy[y];
    yy[y] = x;
    sy[y] = 0;
  }
  int marime (int x) {
    return sy[afla(x)];
  }
};

