    int x, y;
    scanf("%d%d", &x, &y);
    in.PB(MP(MP(x, y), i));
  }
  sort(ALL(in));
  atcoder::dsu d(N + 1);
  vector<PII> st;
  for (auto t : in) {
    while (!st.empty() && st.back().F < t.F.S) {
      d.merge(t.S, st.back().S);
      st.pop_back();
    }
    st.push_back(MP(t.F.S, t.S));
  }
  reverse(ALL(in));
  st.clear();
  for (auto t : in) {
    while (!st.empty() && st.back().F > t.F.S) {
      d.merge(t.S, st.back().S);
      st.pop_back();
    }
    st.push_back(MP(t.F.S, t.S));
  }
  for (int i = 1; i <= N; i++) {
    printf("%d\n", d.size(i));
  }
  return 0;
}

