void solve(){
    int n;
    cin>>n;
    vector<int> x(n), y(n);
    for(int i=0;i<n;i++){
        cin>>x[i]>>y[i];
        --x[i];--y[i];
    }
    dsu comp(n);
    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int l,int r){
        return x[l] < x[r];
    });
    set<int> roots;
    for(const auto &i : order){
        roots.insert(y[i]);
        vector<int> toremove = {y[i]};
        for(const auto &x : roots){
            if(x < y[i]){
                toremove.pb(x);
            }
            else{
                break;
            }
        }
        int left = *min_element(toremove.begin(), toremove.end());
        for(const auto &x : toremove){
            comp.merge(left, x);
            if(x!=left){
                roots.erase(x);
            }
        }
    }
    for(int i=0;i<n;i++){
        cout<<comp.size(y[i])<<"\n";
    }
}
