template <typename T>
class SegmentTree {
  vector<T> data_;
  int size_;

  T QuerySub(int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) {
      return -1;
    } else if (a <= l && r <= b) {
      return data_[k];
    } else {
      return max(QuerySub(a, b, k * 2 + 1, l, (l + r) / 2),
                 QuerySub(a, b, k * 2 + 2, (l + r) / 2, r));
    }
  }

 public:
  SegmentTree(int size) : data_() {
    int n = 1;
    while (size > n) {
      n *= 2;
    }

    size_ = n;
    data_.resize(n * 2 - 1);
    fill(data_.begin(), data_.end(), 0);
  }

  void Update(int a, T x) {
    a += size_ - 1;
    data_[a] = max(data_[a], x);
    while (a > 0) {
      a = (a - 1) / 2;
      data_[a] = max(data_[2 * a + 1], data_[2 * a + 2]);
    }
  }
  T Query(int a, int b) { return QuerySub(a, b, 0, 0, size_); }
  T Query(int a) { return Query(a, a + 1); }
};

class UnionFind {
  vector<int> graph_;
  vector<int> sizes_;

 public:
  UnionFind(int n) : sizes_(n, 1), graph_(n) {
    for (int i = 0; i < n; ++i) {
      graph_[i] = i;
    }
  };

  int Root(int key) {
    if (graph_[key] == key) {
      return key;
    } else {
      return graph_[key] = Root(graph_[key]);
    }
  }

  bool Same(int key1, int key2) { return Root(key1) == Root(key2); }

  void Unite(int key1, int key2) {
    if (Same(key1, key2)) {
      return;
    }

    int root1 = Root(key1);
    int root2 = Root(key2);
    int size = Size(root1) + Size(root2);
    graph_[root1] = root2;
    sizes_[root2] = size;
  }

  int Size(int key) {
    int root = Root(key);
    return sizes_[root];
  }
};

int main(int argc, const char *argv[]) {
