  void join(int u, int v){
    if((u = par(u)) == (v = par(v))) return;
    if(p[u] > p[v]) swap(u, v);
    int lower = min(val[u], val[v]);
    p[u] += p[v];
    p[v] = u;
    val[u] = lower;
  }
};
