int main(){
	int n;
	cin>>n;
	vector<int> x(n), y(n);
	vector<P> xp(n), yp(n);
	rep(i, n){
		cin>>x[i]>>y[i];
		x[i]= -x[i];
		xp[i]=make_pair(x[i], i);
		yp[i]=make_pair(y[i], i);
	}

	sort(xp.begin(), xp.end());
	sort(yp.begin(), yp.end());

	int xi=0, yi=0;
	int xm=xp[0].first, ym=yp[0].first, xv=xp[0].second, yv=yp[0].second;
	int c=0;
	vector<int> g(n, -1);
	while(xi<n){
		xm=xp[xi].first, ym=yp[yi].first;
		xv=xp[xi].second, yv=yp[yi].second;
		g[xv]=g[yv]=c;
		if(xv==yv){//shougai kodoku
			xi++; yi++;
		}
		else{
			xm=max(xm, x[yv]);
			ym=max(ym, y[xv]);
			while(1){
				bool updated=false;
				for(; xp[xi].first<=xm; xi++){
					xv=xp[xi].second;
					if(g[xv]== -1) g[xv]=c;
					ym=max(ym, y[xv]);
					updated=true;
				}
				for(; yp[yi].first<=ym; yi++){
					yv=yp[yi].second;
					if(g[yv]== -1) g[yv]=c;
					xm=max(xm, x[yv]);
					updated=true;
				}
				if(!updated) break;
			}
		}
		c++;
	}

	map<int, int> his;
	rep(i, n) his[g[i]]++;

	rep(i, n) cout<< his[g[i]] <<endl;
	return 0;
}

