struct UnionFind {
    vector<int> data;

    UnionFind(int n) {
        data.resize(n);
        rep(i, n) data[i] = -1;
    }

    int root(int x) {
        if (data[x] < 0) return x;
        return data[x] = root(data[x]);
    }

    void unite(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y) return;
        if (data[x] > data[y]) swap(x, y);
        data[x] += data[y];
        data[y] = x;
    }

    bool same(int x, int y) {
        return root(x) == root(y);
    }

    int size(int x) {
        return -data[root(x)];
    }
};

