const int MAX = 200002;

struct Point {
    int idx;
    int x, y;
    bool operator < (const Point& r) const {
        return x != r.x ? x < r.x : y < r.y;
    }
};

int n;
Point a[MAX];
int indexer[MAX];
vector <int> v[MAX];
int inComp[MAX], compSize[MAX];

void color(int node, int comp) {
    compSize[comp]++;
    inComp[node] = comp;
    for (int i = 0; i < (int)v[node].size(); i++) {
        if (inComp[v[node][i]] == 0) {
            color(v[node][i], comp);
        }
    }
}

void solve() {
    sort(a, a + n);
    for (int i = 0; i < n; i++)
        indexer[a[i].y] = a[i].idx;

    set <int> smaller;
    for (int i = 0; i < n; i++) {
        vector <int> toErase;
        for (auto it = smaller.begin(); it != smaller.end() && *it < a[i].y; it++) {
            toErase.push_back(*it);
            int idx = indexer[*it];
            v[idx].push_back(a[i].idx);
            v[a[i].idx].push_back(idx);
        }
        if (toErase.empty()) {
            smaller.insert(a[i].y);
        } else {
            for (int i = 1; i < (int)toErase.size(); i++)
                smaller.erase(toErase[i]);
        }
    }
    int nextComp = 1;
    for (int node = 0; node < n; node++) {
        if (inComp[node] == 0) {
            color(node, nextComp++);
        }
    }

    for (int node = 0; node < n; node++)
        fprintf(out, "%d\n", compSize[inComp[node]]);
}

int main(void) {
	// in = fopen("A.in", "rt");

	fscanf(in, "%d", &n);
	for (int i = 0; i < n; i++) {
	    a[i].idx = i;
	    fscanf(in, "%d %d", &a[i].x, &a[i].y);
    }

    solve();

	return 0;
}

