int min_query(int tree[],int start,int end,int left,int right,int index)
{
	if(left>end||start>right)
	  return 1000000000;
	if(start>=left&&end<=right)
	  return tree[index];
	else
	{
		int mid=(start+end)/2;
		int x=min_query(tree,start,mid,left,right,2*index);
		int y=min_query(tree,mid+1,end,left,right,2*index+1);
		return min(x,y);
	}
}
int max_query(int tree[],int start,int end,int left,int right,int index)
{
	if(left>end||start>right)
	  return -1000000000;
	if(start>=left&&end<=right)
	  return tree[index];
	else
	{
		int mid=(start+end)/2;
		int x=max_query(tree,start,mid,left,right,2*index);
		int y=max_query(tree,mid+1,end,left,right,2*index+1);
		return max(x,y);
	}
}
void update(int tree[],int start,int end,int point,int pos,int index)
{
	if(point>end||point<start)
	  return ;
	if(start==end)
	{
		tree[index]=pos;
		return ;
	}
	else
	{
		int mid=(start+end)/2;
		update(tree,start,mid,point,pos,2*index);
		update(tree,mid+1,end,point,pos,2*index+1);
		tree[index]=min(tree[2*index],tree[2*index+1]);
	}
}
void dfs(int src,vector<int> adj[],vector<int> &vec,bool visited[])
{
	if(visited[src])
	  return ;
	visited[src]=true;
	vec.push_back(src);
	for(int x:adj[src])
	  dfs(x,adj,vec,visited);
}
