struct UnionFind {
    int n, cc, *u;
    UnionFind() : n(0), cc(0), u(NULL) {}
    UnionFind(int n_) : n(n_), cc(n_) {
	u = new int[n_];
	memset(u, -1, sizeof (int) * n);
    }
    UnionFind(const UnionFind &y) : n(y.n), cc(y.cc) {
	u = new int[y.n];
	memcpy(u, y.u, sizeof (int) * n);
    }
    ~UnionFind() {
	delete[] u; u = NULL;
	n = cc = 0;
    }
    friend void swap(UnionFind &x, UnionFind &y) {
	swap(x.n, y.n); swap(x.cc, y.cc); swap(x.u, y.u);
    }
    UnionFind& operator=(UnionFind y) { 
	swap(*this, y);
	return *this;
    }
    int root(int x) {
	int y = x, t;
	while (u[y] >= 0) y = u[y];
	while (x != y) { t = u[x]; u[x] = y; x = t; }
	return y;
    }
    bool link(int x, int y) {
	x = root(x); y = root(y);
	if (x == y) return false;
	if (u[y] < u[x]) swap(x, y);
	u[x] += u[y]; u[y] = x; cc--;
	return true;
    }
    bool same(int x, int y) { return root(x) == root(y); }
    int count_node(int x) { return -u[root(x)]; }
    int count_tree() { return cc; }
};

int N;
int X[200011], Y[200011];
int P[200011];

void MAIN() {
    scanf("%d", &N);
    REP (i, N) {
	int x,y;
	scanf("%d%d", &x, &y);
	x--; y--;
	X[i] = x;
	Y[i] = y;
	P[x] = i;
    }

    UnionFind U(N);
    VI stk;
    REP (x, N) {
	int idx = P[x];
	int y = Y[idx];

	if (!stk.empty() && Y[stk.back()] < y) {
	    int last = stk.back();
	    while (!stk.empty() && Y[stk.back()] < y) {
		U.link(stk.back(), idx);
		stk.pop_back();
	    }

	    stk.push_back(last);
	} else {
	    stk.push_back(idx);
	}
    }


    REP (i, N) printf("%d\n", U.count_node(i));
}

