int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);

  int n;
  cin>>n;

  vector<pair<ll,ll>> p(n);
  map<ll,ll> m;
  rep(i,n){
    cin>>p[i].fi>>p[i].se;
    p[i].fi--;
    p[i].se--;
    m[p[i].se]=i;
  }

  sort(all(p));

  UF uf(n);

  priority_queue<ll,vector<ll>,greater<ll>> que;
  rep(i,n){
    if(i==0 || p[i].se<que.top()) que.push(p[i].se);
    else {
      ll memo=que.top();
      while(!que.empty() && p[i].se>que.top()){
        ll x=que.top();
        que.pop();
        uf.unite(m[p[i].se],m[x]);
      }
      que.push(memo);
    }
  }

  rep(i,n){
    cout << uf.size(i) << endl;
  }

}

