int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);

  int n; cin>>n;
  struct City {
    int x,y,i;
  };

  vector<City> C(n);
  for (int i = 0; i < n; i++) {
    int a,b; cin>>a>>b;
    C[i] = {a,b,i};
  }

  sort(C.begin(), C.end(), [](auto l, auto r) {return l.x<r.x;});
  atcoder::dsu cdsu(n);
  {
    vector<City> tc;
    for (int i = 0; i < n; i++) {
      auto c = C[i];
      bool updated = false;
      for (auto& [x,y,j]:tc) {
        if (y < c.y) {
          cdsu.merge(j, c.i);
          x = c.x;
          y = c.y;
          j = c.i;
          updated = true;
        }
      }
      if (!updated) {
        tc.push_back(c);
      }
    }
  }
  for (int i = 0; i < n; i++) {
    cout << cdsu.size(i) << endl;
  }

  return 0;
}

