const int N = 2e5 + 7;

tuple <int, int, int> pt[N];

int aa[N], cnt[N];

int32_t main() {
	ios_base :: sync_with_stdio(0); cin.tie(0); cout.tie(0);
	int n; cin >> n;
	set <int> st;
	for(int i = 1; i <= n; ++i) {
		int x, y; cin >> x >> y;
		pt[i] = make_tuple(x, y, i);
		st.insert(i);
	}

	sort(pt + 1, pt + n + 1);

	vector <pair <int, int> > v;

	for(int i = n; i >= 1; i--) {
		int x, y, j; tie(x, y, j) = pt[i];
		v.push_back(make_pair(*st.begin(), y));
		st.erase(y);
	}

	sort(v.begin(), v.end());

	vector <pair <int, int> > ans;

	for(auto z: v) {
		if(ans.empty() || ans.back().second < z.first) ans.push_back(z);
		else {
			ans[ans.size() - 1].second = max(ans[ans.size() - 1].second, z.second);
		}
	}

	for(auto z: ans) {
		for(int i = z.first; i <= z.second; ++i) {
			aa[i] = z.second - z.first + 1;
		}
	}
	for(int i = 1; i <= n; i++) {
		int x, y, j; tie(x, y, j) = pt[i];
		cnt[j] = aa[y];
	}

	for(int i = 1; i <= n; i++) cout << cnt[i] << endl;
}

