struct UnionFind {
    vector<int> par, w;

    UnionFind(int n) : par(n, -1), w(n, 0) { }
    void init(int n) { par.assign(n, -1); w.assign(n, 0); }

    int root(int x) {
        if (par[x] < 0) return x;
        else return par[x] = root(par[x]);
    }

    bool issame(int x, int y) {
        return root(x) == root(y);
    }

    bool merge(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) {
            ++w[x];
            return false;
        }
        if (par[x] > par[y]) swap(x, y); // merge technique
        par[x] += par[y];
        par[y] = x;
        w[x] += w[y];
        ++w[x];
        return true;
    }

    int size(int x) {
        return -par[root(x)];
    }

    int wei(int x) {
        return w[root(x)];
    }
};

void solve() {
	int n; cin >> n;
    vector<int> x(n), y(n);
    rep(i, n) {
        cin >> x[i] >> y[i];
        // x[i] = i + 1, y[i] = i + 1;
        -- x[i], -- y[i];
    }
    vector<int> ids(n);
    iota(all(ids), 0);
    sort(all(ids), [&](int i, int j){ return x[i] < x[j];});
    UnionFind uf(n);
    set<P> se;
    rep(i, n) {
        se.insert(P{y[i], i});
    }
    vector<bool> used(n, 0);
    rep(i, n) {
        int id = ids[i];
        if(used[id]) continue;
        auto ite = se.lower_bound(P{y[id], -inf});
        int id2 = -1, xma = -1;
        for(; ite != se.end(); ) {
            int cury = (*ite).fr, idd = (*ite).sc;
            if(x[id] < x[idd]) uf.merge(id, idd);
            used[idd] = 1;
            if(chmax(xma, x[idd])) {
                id2 = idd;
            }
            ite = se.erase(ite);
        }
        if(id2 != -1) {
            se.insert(P{y[id2], id2});
        }
        if(se.find(P{y[id], id}) != se.end()) {
            se.erase(P{y[id], id});
        }
    }
    rep(i, n) {
        cout << (int)uf.size(i) << endl;
    }
}

