char viz[NMAX];
vector<int> graph[NMAX];
int answer[NMAX], n, index_of[NMAX], ycoord[NMAX];

struct point {
    int x, y, index;  

    bool operator<(point B) {
        return x < B.x;
    }
};
point v[NMAX];

int dfs(int node) {
    if(viz[node])
        return 0;
    viz[node] = 1;
    int ans = 0;
    for(auto neight : graph[node]) {
        ans += dfs(neight);
    }
    return ans + 1;
}

void dfs2(int node, int val) {
    if(viz[node] == 2)
        return ;
    viz[node] = 2;
    answer[node] = val;
    for(auto neight : graph[node]){
        dfs2(neight, val);
    }
}

int main () {
    int cnt = 0;

    scanf("%d", &n);
    for(int i = 1; i <= n; i++) {
        scanf("%d%d", &v[i].x, &v[i].y);
        v[i].index = i;
    }
    sort(v + 1, v + n + 1);
    int last = 0;
    for(int i = 1; i <= n; i++) {
        int j = 0;
        for(j = last; j > 0; j--) {
            if(ycoord[j] < v[i].y) {
                graph[v[i].index].push_back(index_of[j]);
                graph[index_of[j]].push_back(v[i].index);
            }
            else {
                break;
            }
        }
        if(j == last) {
            ycoord[++last] = v[i].y;
            index_of[last] = v[i].index;
        }
        else {
            ycoord[j + 1] = ycoord[last];
            index_of[j + 1] = index_of[last];
        }
    }
    for(int i = 1; i <= n; i++) {
        if(!viz[i]) {
            cnt = dfs(i);
        }
        dfs2(i, cnt);
    }

    for(int i = 1; i <= n; i++) {
        printf("%d\n", answer[i]);
    }

    return 0;
}

