using namespace std;
using T = tuple<int,int,int>;
using P = pair<int,int>;

struct UnionFind{
  vector<int> d;
  UnionFind(int n){
    d.resize(n,-1);
  }
  int find(int x){
    if(d[x] < 0) return x;
    return d[x] = find(d[x]);
  }
  void unite(int x, int y){
    x = find(x);
    y = find(y);
    if(x == y) return;
    if(d[x] > d[y]) swap(x,y);
    d[x] += d[y];
    d[y] = x;
    return;
  }
  int size(int x){return -d[find(x)];}
};

int main(){
  int n;
  cin >> n;
  UnionFind uf(n);
  vector<T> town(n);
  int xi, yi;
  for(int i=0; i<n; ++i){
    cin >> xi >> yi;
    town[i] = make_tuple(xi,yi,i);
  }
  sort(town.begin(),town.end());
  priority_queue<P,vector<P>,greater<P>> que;
  int minnum = get<1>(town[0]), townnum = get<2>(town[0]);
  que.push(P(minnum,townnum));
  for(int i=1; i<n; ++i){
    int nowy = get<1>(town[i]);
    int nowt = get<2>(town[i]);
    if(nowy < minnum){
      que.push(P(minnum,townnum));
      minnum = nowy;
      townnum = nowt;
    }else{
      uf.unite(nowt,townnum);
      while(!que.empty() && que.top().first < nowy){
        uf.unite(nowt, que.top().second);
        que.pop();
      }
      que.push(P(minnum,townnum));
    }
  }
  for(int i=0; i<n; ++i){
    printf("%d\n",uf.size(i));
  }
}

