template<typename T>
struct FenwickTree
{
    vector<T> tree;
    const int n;
    FenwickTree(int n=0) : tree(n+1), n(n) {}
    void add(int i, T x=1)
    {
        for(i++; i<=n; i += i&-i) tree[i] += x;
    }
    T sum(int i)
    {
        T x = 0;
        for(i++; i; i -= i&-i) x += tree[i];
        return x;
    }
    T sum(int l, int r)
    {
        return sum(r) - sum(l-1);
    }
};

