using namespace std;
using TPoint = pair<int, int>;
using TTown = pair<TPoint, int>;

struct TNode{
    bool isX;
    TTown median;
    TNode* less;
    TNode* more;
};

struct TTree{
    TTown median;
    TNode* root;
};

vector<TTown> TownRightDown;
vector<bool> Visited;

void InitTree(TTree* pTree){
    pTree->median = TTown(TPoint(0, 0), -1);
    pTree->root = NULL;
    return;
}

void InitNode(TNode* pNode, bool isX){
    pNode->median = TTown(TPoint(0, 0), -1);
    pNode->less = NULL;
    pNode->more = NULL;
    pNode->isX = isX;
    return;
}

TNode* Rec_Insert(TNode** pNode, TTown newTown, bool isX){
    if(*pNode == NULL){
        *pNode = new TNode;
        InitNode(*pNode, isX);
        return *pNode;
    }
    if(isX){
        if(newTown.first.first > (*pNode)->median.first.first){
            return Rec_Insert(&(*pNode)->more, newTown, false);
        }else{
            return Rec_Insert(&(*pNode)->less, newTown, false);
        }
    }else{
        if(newTown.first.second > (*pNode)->median.first.second){
            return Rec_Insert(&(*pNode)->more, newTown, true);
        }else{
            return Rec_Insert(&(*pNode)->less, newTown, true);
        }
    }
}

void Insert(TTree *pRoot, TTown newTown){
    TNode* pAdd = Rec_Insert(&pRoot->root, newTown, true);
    pAdd->median = newTown;
}


void Rec_FreeNode(TNode* pParent){
    if(pParent->less != NULL)Rec_FreeNode(pParent->less);
    if(pParent->more != NULL)Rec_FreeNode(pParent->more);
    delete pParent;
    return;
}

void FreeNode(TTree* pTree){
    if(pTree->root != NULL)Rec_FreeNode(pTree->root);
}

void RecRightDown(TNode* pParent, int X, int Y){
    if(pParent == NULL)return;
    if(pParent->isX){
        if(pParent->median.first.first > X){
            if(pParent->median.first.second > Y){
                TownRightDown.push_back(pParent->median);
                if(Visited[pParent->median.second])return;
                Visited[pParent->median.second] = true;
            }
            RecRightDown(pParent->less, X, Y);
            RecRightDown(pParent->more, X, Y);
        }else{
            RecRightDown(pParent->more, X, Y);
        }
    }else{
        if(pParent->median.first.second > Y){
            if(pParent->median.first.first > X){
                TownRightDown.push_back(pParent->median);
                if(Visited[pParent->median.second])return;
                Visited[pParent->median.second] = true;
            }
            RecRightDown(pParent->less, X, Y);
            RecRightDown(pParent->more, X, Y);
        }else{
            RecRightDown(pParent->more, X, Y);
        }
    }
    return;
}

void RightDown(TTree* pTree, TTown curTown){
    TownRightDown.clear();
    RecRightDown(pTree->root, curTown.first.first, curTown.first.second);
}

bool compareY(TTown Town1, TTown Town2){
    return Town1.first.second < Town2.first.second;
}

void MakeTree(const vector<TTown>::iterator begin, const vector<TTown>::iterator end, TTree* pTree, bool isX){
    if(begin >= end)return;
    if(isX){
        sort(begin, end);
    }else{
        sort(begin, end, compareY);
    }
    int length = end - begin;
    int forelength = (length - 1)/2;
    int backlength = length - 1 - forelength;
    Insert(pTree, *(begin+length-1));
    if(forelength > 0)MakeTree(begin, begin+forelength, pTree, !isX);
    if(backlength > 0)MakeTree(end-backlength, end, pTree, !isX);
    return;
}

int main(void){
    int N, xbuf, ybuf;
    vector<TTown> Towns;
    cin >> N;
    Visited.assign(N, false);
    for(int i=0; i<N; i++){
        cin >> xbuf >> ybuf;
        Towns.push_back(TTown(TPoint(xbuf, ybuf), i));
    }

    TTree Tree;
    InitTree(&Tree);
    MakeTree(Towns.begin(), Towns.end(), &Tree, true);
    vector<vector<int>> Graph(N);
    for(int i=0; i<N; i++){
        if(Visited[i])continue;
        Visited[i] = true;
        RightDown(&Tree, Towns[i]);
        for(TTown nxtTown: TownRightDown){
            Graph[Towns[i].second].push_back(nxtTown.second);
            Graph[nxtTown.second].push_back(Towns[i].second);
        }
    }

    vector<bool> Visited2(N, false);
    vector<int> ClusterSize(N, 0);
    for(int i=0; i<N; i++){
        queue<int> que;
        if(Visited2[i])continue;
        vector<int> Belongings;
        que.push(i);
        int curClusterSize = 0;
        while(!que.empty()){
            int curTown = que.front();
            que.pop();
            if(Visited2[curTown])continue;
            Visited2[curTown]=true;
            Belongings.push_back(curTown);
            curClusterSize++;
            for(int nxtTown: Graph[curTown]){
                if(Visited2[nxtTown])continue;
                que.push(nxtTown);
            }
        }
        for(int Town: Belongings){
            ClusterSize[Town] = curClusterSize;
        }
    }

    for(int i=0; i<N; i++)cout << ClusterSize[i] << endl;

    FreeNode(&Tree);

    return 0;
}

