struct UnionFind {
    vector<int> r;

    UnionFind(const int N) : r(N, -1) {}

    inline int root(int x) {
        if (r[x] < 0) {
            return x;
        }
        return r[x] = root(r[x]);
    }

    inline bool unite(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y) {
            return false;
        }
        if (r[x] > r[y]) swap(x, y);
        r[x] += r[y];
        r[y] = x;
        return true;
    }

    inline int size(int x) { return -r[root(x)]; }
};

int main() {
