    for (int i = 0; i < N; ++i) {
        for (int j = i + 1; j < N; ++j) {
            if (X[i].first < X[j].first) {
                ans.unite(X[i].second, X[j].second);
            }
        }
    }
    rep(i, N) { printf("%d\n", ans.size(i)); }
}

