struct UnionFind {
    vector<int> par, sz;

    UnionFind(int n) : par(n), sz(n, 1) {
        for (int i = 0; i < n; ++i) par[i] = i;
    }

    int root(int x) {
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void merge(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y) return;
        if (sz[x] < sz[y]) swap(x, y);
        par[y] = x;
        sz[x] += sz[y];
        sz[y] = 0;
    }

    bool issame(int x, int y) {
        return root(x) == root(y);
    }

    int size(int x) {
        return sz[root(x)];
    }
};

void solve() {
    int N;
    cin >> N;
    vector<pair<int, int>> xy(N);
    vector<int> xi(N); // xiは何番目に登場するか?
    REP(i, N) {
        cin >> xy[i].first >> xy[i].second;
        xy[i].first--;
        xy[i].second--;
        xi[xy[i].first] = i;
    }

    sort(ALL(xy));
    vector<int> A(N);
    REP(i, N) {
        A[i] = xy[i].second;
    }

    UnionFind uf(N);
    set<int> neri;

    for (int i = 0; i < N; ++i) {
        vector<int> idx;
        int min_idx = -1;
        for (auto j : neri) {
            if (A[i] > A[j]) {
                idx.push_back(j);
                if (min_idx == -1) min_idx = j;
                if (A[min_idx] > A[j]) min_idx = j;
                uf.merge(i, j);
            }
        }
        if (idx.empty()) {
            neri.insert(i);
        } else {
            for (auto j : idx) {
                if (j == min_idx) continue;
                neri.erase(j);
            }
        }
    }

    vector<int> ans(N);
    for (int i = 0; i < N; ++i) {
        ans[xi[i]] = uf.size(i);
    }
    for (auto e : ans) {
        cout << e << endl;
    }


}


