struct BIT {
  int n;
  std::vector<T> d;
  BIT(int n=0):n(n),d(n+1) {}
  void add(int i, T x=1) {
    for (i++; i <= n; i += i&-i) {
      d[i] += x;
    }
  }
  T sum(int i) {
    T x = 0;
    for (i++; i; i -= i&-i) {
      x += d[i];
    }
    return x;
  }
  T sum(int l, int r) {
    return sum(r-1) - sum(l-1);
  }
};

using Tup = std::tuple<ll, ll, ll>;

struct UnionFind {
  std::vector<int> d;
  UnionFind(int n=0): d(n,-1) {}
  int find(int x) {
    if (d[x] < 0) return x;
    return d[x] = find(d[x]);
  }
  bool unite(int x, int y) {
    x = find(x); y = find(y);
    if (x == y) return false;
    if (d[x] > d[y]) std::swap(x,y);
    d[x] += d[y];
    d[y] = x;
    return true;
  }
  bool same(int x, int y) { return find(x) == find(y);}
  int size(int x) { return -d[find(x)];}
};

UnionFind uf( 200010 );

void solve( const std::vector<ll> &x, const std::vector<ll> &y ) {
  std::vector<Tup> ps;

  rep( i, N )
    ps.emplace_back( x[i], y[i], i );

  std::sort(all(ps));

  std::set<P> prs;

  rep( i, N ) {
    auto [px, py, pi] = ps[i];

    if( !prs.empty() ) {
      auto bound = prs.lower_bound( P( -py, -INF ) );

      for( auto it = bound; it != prs.end(); ) {
        uf.unite( it->second, pi );

        it = prs.erase(it);
      }
    }

    prs.emplace( -py, pi );
  }

  return;
}

