struct DSU {
    vi parent, sz;
    DSU(int n) {
        parent.resize(n);
        sz.resize(n);
        fori (i, n) {
            parent[i] = i;
            sz[i] = 1;
        }
    }

    int find_set(int v) {
        return parent[v] == v ? v : parent[v] = find_set(parent[v]);
    }

    void union_set(int u, int v) {
        u = find_set(u);
        v = find_set(v);
        if (u == v)
            return;
        if (sz[u] < sz[v])
            swap(u, v);
        swap(u, v);
        sz[u] += sz[v];
        parent[v] = u;
    }
};


