struct Union_Find_Tree{
    vector<int> par, rank, num;
    const int n;

    Union_Find_Tree(int n) : n(n){
        par.assign(n, -1), rank.assign(n, 0), num.assign(n, 1);
    }

    int root(int x){
        if(par[x] < 0 || par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    bool unite(int x, int y){
        x = root(x), y = root(y);
        if(x == y) return false;
        if(rank[x] < rank[y]) swap(x, y);
        if(rank[x] == rank[y]) rank[x]++;
        par[y] = x, num[x] += num[y];
        return true;
    }

    int size(int x) {return num[root(x)];}

    bool same(int x, int y) {return root(x) == root(y);}

    void clear(){
        fill(all(par), -1), fill(all(rank), 0), fill(all(num), 1);
    }
};

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N;
    cin >> N;
    Union_Find_Tree uf(N);
    pii p[N];
    rep(i, N){
        int x, y; cin >> x >> y; x--, y--;
        p[x] = {y, i};
    }
    stack<int> s;
    int h[N];
    rep(i, N){
        h[i] = p[i].first;
        while(!s.empty() && p[s.top()].first < p[i].first){
            uf.unite(p[i].second, p[s.top()].second);
            chmin(h[i], h[s.top()]);
            s.pop();
        }
        if(!s.empty()){
            if(h[s.top()] < p[i].first){
                uf.unite(p[i].second, p[s.top()].second);
                chmin(h[i], h[s.top()]);
            }
        }
        s.push(i);
    }
    rep(i, N){
        cout << uf.size(i) << endl;
    }
}

