const int MAX_N = 200000;

/* typedef */

struct Trpl {
  int y, x, i;
  Trpl() {}
  Trpl(int _y, int _x, int _i): y(_y), x(_x), i(_i) {}

  bool operator<(const Trpl &t) const { return y < t.y; }
};

struct UFT {
  int links[MAX_N], ranks[MAX_N], sizes[MAX_N];
  UFT() {}

  void init(int n) {
    for (int i = 0; i < n; i++) links[i] = i, ranks[i] = sizes[i] = 1;
  }

  int root(int i) {
    int i0 = i;
    while (links[i0] != i0) i0 = links[i0];
    return (links[i] = i0);
  }

  int rank(int i) { return ranks[root(i)]; }
  int size(int i) { return sizes[root(i)]; }
  bool same(int i, int j) { return root(i) == root(j); }

  int merge(int i0, int i1) {
    int r0 = root(i0), r1 = root(i1), mr;
    if (r0 == r1) return r0;
    if (ranks[r0] == ranks[r1]) {
      links[r1] = r0;
      sizes[r0] += sizes[r1];
      ranks[r0]++;
      mr = r0;
    }
    else if (ranks[r0] > ranks[r1]) {
      links[r1] = r0;
      sizes[r0] += sizes[r1];
      mr = r0;
    }
    else {
      links[r0] = r1;
      sizes[r1] += sizes[r0];
      mr = r1;
    }
    return mr;
  }
};

/* global variables */

Trpl ts[MAX_N];
UFT uft;
int q[MAX_N], cs[MAX_N];

/* subroutines */

/* main */

int main() {
  int n;
  scanf("%d", &n);

  for (int i = 0; i < n; i++)
    scanf("%d%d", &ts[i].x, &ts[i].y), ts[i].i = i;
  sort(ts, ts + n);

  uft.init(n);

  int qt = 0;
  for (int i = 0; i < n; i++) {
    int xi = ts[i].x;
    while (qt > 0 && ts[q[qt - 1]].x < xi)
      uft.merge(ts[q[--qt]].i, ts[i].i);
    q[qt++] = i;
  }

  qt = 0;
  for (int i = n - 1; i >= 0; i--) {
    int xi = ts[i].x;
    while (qt > 0 && ts[q[qt - 1]].x > xi)
      uft.merge(ts[q[--qt]].i, ts[i].i);
    q[qt++] = i;
  }

  for (int i = 0; i < n; i++) cs[ts[i].i] = uft.size(ts[i].i);
  for (int i = 0; i < n; i++) printf("%d\n", cs[i]);
  return 0;
}

