int getCount(int i, vector<set<int>> point2Points, set<int> log)
{
  log.insert(i);
  set<int> validPoints;
  set_difference(ALL(point2Points[i]), ALL(log), inserter(validPoints, validPoints.end()));
  int count = validPoints.size();  
  for (const auto& j : validPoints) {
    count += getCount(j, point2Points, log);
  }
  return count;
}

