int root[SIZE];
int sz[SIZE];

void init() {
    for(int i = 0; i < SIZE; ++i) {
        root[i] = i;
        sz[i] = 1;
    }
}

int Root(int x) {
    if(x == root[x]) return x;

    int rt = Root(root[x]);
    sz[x] = sz[rt];
    return rt;
}

bool Unite(int x, int y) {
    int rx, ry;
    rx = Root(x);
    ry = Root(y);

    if(rx == ry) return false;
    if(sz[rx] > sz[ry]) {
        root[ry] = rx;
    } else {
        root[rx] = ry;
    }

    sz[rx] += sz[ry];
    sz[ry] = sz[rx];
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int N;
    cin >> N;
    vector<P> v(N);
    int p[SIZE];
    init();
    for(int i = 0; i < N; ++i) {
        cin >> v[i].F >> v[i].S;
        p[v[i].S] = i;
    }
    sort(all(v));

    set<int> st;
    for(int i = 0; i < N; ++i) {
        int b = v[i].S;
        st.insert(b);
        auto it = st.lower_bound(b);
        if(it == st.begin()) {
            continue;
        }
        --it;
        do {
            int a = (*it);
            if(!Unite(p[a], p[b])) {
                break;
            }
            b = (*it);
        } while(it != st.begin());

        for(it = st.begin(); it != st.end(); ++it) {
            if(*it == v[i].S) {
                break;
            }
            if(it != st.begin() && !Unite(p[*it], p[b])) {
                break;
            }
            b = *it;
        }
    }

    st.clear();
    for(int i = N - 1; i >= 0; --i) {
        int b = v[i].S;
        st.insert(b);
        auto it = st.upper_bound(b);
        while(it != st.end()) {
            int a = (*it);
            if(!Unite(p[a], p[b])) {
                break;
            }
            b = (*it);
            ++it;
        }

        b = INF;
        it = st.end();
        if(it == st.begin()) {
            continue;
        }
        --it;
        do {
            if(b != INF && !Unite(p[*it], p[b])) {
                break;
            }
            b = *it;
        } while(it != st.begin());
    }

    for(int i = 0; i < N; ++i) {
        Root(i);
        cout << sz[i] << endl;
    }
    return 0;
}

