class UnionFind {
private:
    int n;
    vector<int> a;
public:
    UnionFind(int n) : n(n), a(n, -1) {}
    int find(int x) { return a[x] < 0 ? x : (a[x] = find(a[x])); }
    bool same(int x, int y) { return find(x) == find(y); }
    bool same(Pii& p) { return same(p.first, p.second); }
    bool unite(int x, int y) {
        x = find(x), y = find(y);
        if (x == y) return false;
        if (a[x] > a[y]) swap(x, y);
        a[x] += a[y];
        a[y] = x;
        n--;
        return true;
    }
    bool unite(Pii& p) { return unite(p.first, p.second); }
    int size() const { return n; }
    int size(int x) { return -a[find(x)]; }
};

vector<int> solve(vector<tuple<int, int, int>> vp) {
    const int n = sz(vp);
    sort(vp.begin(), vp.end());

    UnionFind uf(n);
    int topId = 0;
    vector<int> q;
    for (int i = 1; i < n; i++) {
        int y = get<1>(vp[i]);
        if (get<1>(vp[topId]) < y) {
            uf.unite(i, topId);
        } else {
            q.push_back(topId);
            topId = i;
            continue;
        }

        while (sz(q)) {
            int cur = q.back();
            if (get<1>(vp[cur]) < y) {
                uf.unite(cur, i);
                q.pop_back();
                continue;
            }
            break;
        }
    }
    vector<int> ans(n);
    FOR(i, n) ans[get<2>(vp[i])] = uf.size(i);
    return ans;
}

