class DSU {
	private:
		vector<int> comp, siz;
	public:
		DSU(int n) : comp(n), siz(n, 1) {
			for (int i = 0; i < n; ++i) comp[i] = i;
		}
		int getc(int i) {
			if (comp[i] != i) comp[i] = getc(comp[i]);
			return comp[i];
		}
		bool join(int a, int b) {
			a = getc(a);
			b = getc(b);
			if (a == b) return false;

			if (siz[a] < siz[b]) swap(a, b);
			siz[a] += siz[b];
			comp[b] = a;
			return true;
		}
		int compSize(int i) { return siz[getc(i)]; }
};

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	int n;
	cin >> n;

	// Loop points left to right, maintain for every component the lowest y

	vector<pair<pair<int, int>, int>> points(n);
	for (int i = 0; i < n; ++i) {
		cin >> points[i].first.first >> points[i].first.second;
		points[i].second = i;
	}
	sort(points.begin(), points.end());

	DSU dsu(n);
	vector<pair<int, int>> que;
	for (auto pr : points) {
		int y = pr.first.second;
		int ind = pr.second;
		int comp_y = y;
		while(! que.empty() && que.back().first <= y) {
			comp_y = min(comp_y, que.back().first);
			dsu.join(ind, que.back().second);
			que.pop_back();
		}
		que.push_back({comp_y, ind});
	}
	for (int i = 0; i < n; ++i) cout << dsu.compSize(i) << '\n';
}

