void read(istream& cin) {
	cin >> n;
	x.resize(n);
	y.resize(n);
	for (int i = 0; i < n; i++) {
		cin >> x[i] >> y[i];
		--x[i]; --y[i];
	}
}

struct ST {
	int n;
	vector<pair<int, int>> t;
	function<pair<int, int>(pair<int, int>, pair<int, int>)> op;

	ST(int n, function<pair<int, int>(pair<int, int>, pair<int, int>)> op) : n(n), t(2 * n), op(op) {}

	void upd(int v, pair<int, int> x) {
		t[v += n] = x;
		for (v >>= 1; v; v >>= 1) {
			t[v] = op(t[v << 1], t[v << 1 | 1]);
		}
	}

	int get(int l, int r, pair<int, int> ret) {
		for (l += n, r += n; l <= r; l = (l + 1) >> 1, r = (r - 1) >> 1) {
			if (l & 1) {
				ret = op(ret, t[l]);
			}
			if (!(r & 1)) {
				ret = op(ret, t[r]);
			}
		}
		return ret.second;
	}
};

vector<bool> was;
vector<int> cur;

const int inf = 1e9 + 228;

void dfs(int i, ST& t, ST& t1) {
	was[i] = true;
	cur.push_back(i);
	t.upd(x[i], { inf, -1 });
	t1.upd(x[i], { -inf, -1 });
	while (true) {
		int j = t.get(0, x[i], { inf, -1 });
		if (j == -1 || y[j] > y[i]) {
			break;
		}
		dfs(j, t, t1);
	}
	while (true) {
		int j = t1.get(x[i], n - 1, { -inf, -1 });
		if (j == -1 || y[j] < y[i]) {
			break;
		}
		dfs(j, t, t1);
	}
}

void solve(ostream& cout) {
	vector<int> ans(n);
	was.resize(n);
	auto f = [&](pair<int, int> x, pair<int, int> y) { return min(x, y); };
	auto f1 = [&](pair<int, int> x, pair<int, int> y) { return max(x, y); };
	ST t(n, f), t1(n, f1);
	for (int i = 0; i < n; i++) {
		t.upd(x[i], { y[i], i });
		t1.upd(x[i], { y[i], i });
	}
	for (int i = 0; i < n; i++) {
		if (!was[i]) {
			cur.clear();
			dfs(i, t, t1);
			for (int v : cur) {
				ans[v] = cur.size();
			}
		}
	}
	for (int x : ans) {
		cout << x << '\n';
	}
}

int32_t main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	int T = 1;
	// cin >> T;
	while (T--) {
		read(cin);
		solve(cout);
	}
}

