    }

    for(int i = 0; i < N; i++){
        a[x[i]] = y[i];
        r_min[x[i]] = y[i];
    }
    UnionFind uf(N);
    set<P> st;
    for(int i = 0; i < N; i++){
        auto p = st.begin();
