struct UnionFind {
	VI par, s;
	UnionFind(int N) :par(N), s(N) {
		REP(i, N)par[i] = i;
		REP(i, N)s[i] = 1;
	}
	int root(int x) {
		if (par[x] == x)return x;
		return par[x] = root(par[x]);
	}
	void unite(int x, int y) {
		int rx = root(x);
		int ry = root(y);
		if (rx == ry)return;
		if (!(same(x, y)))s[ry] += s[rx];
		par[rx] = ry;
	}
	bool same(int x, int y) {
		int rx = root(x);
		int ry = root(y);
		return rx == ry;
	}
	int size(int x) {
		return s[root(x)];
	}
};

signed main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	int N; cin >> N;
	VP A(N);
	UnionFind uni(N);
	REP(i, N) {
		cin >> A[i].first >> A[i].second;
		A[i].first--;
		A[i].second--;
	}
	SORT(A);

	set<int>S;
	VI to(N);
	REP(i, N)to[A[i].second] = i;

	REP(i, N) {
		int now = A[i].second;
		auto it = S.begin();

		VI tmp;
		while (it != S.end() && *it < now) {
			uni.unite(to[now], to[*it]);
			tmp.push_back(to[*it]);
			it++;
		}
		fore(j, tmp)S.erase(j);
		S.insert(now);
	}



	REP(i, N) cout << uni.size(i) << '\n';
	return 0;
}

