            group.push_back({});
            group.back().bottom = y - 1;
            continue;
        }

        auto&& g = group.back();
        g.xs.push_back(x);
        g.bottom = min(g.bottom, y);
    }

    for (auto&& g : group) {
        for (auto x : g.xs) {
            ans[ord_x[x]] = int(g.xs.size());
        }
    }
    for (int i = 0; i < n; ++i) {
