typedef long long int64;
const int maxn = 200009;
int A[maxn << 2], B[maxn << 2];
void upd1(int rt, int l, int r, int p, int v) {
  if (l == r) {
    B[rt] = v;
    return;
  }
  int mid = (l + r) >> 1;
  if (p <= mid)
    upd1(rt << 1, l, mid, p, v);
  else
    upd1(rt << 1 | 1, mid + 1, r, p, v);
  B[rt] = max(B[rt << 1], B[rt << 1 | 1]);
}
void upd(int rt, int l, int r, int p, int v) {
  if (l == r) {
    A[rt] = v;
    return;
  }
  int mid = (l + r) >> 1;
  if (p <= mid)
    upd(rt << 1, l, mid, p, v);
  else
    upd(rt << 1 | 1, mid + 1, r, p, v);
  A[rt] = min(A[rt << 1], A[rt << 1 | 1]);
}
int query(int rt, int l, int r, int ll, int rr) {
  if (ll > rr) return maxn;
  if (ll <= l && rr >= r) return A[rt];
  int mid = (l + r) >> 1, res = maxn;
  if (ll <= mid) res = min(res, query(rt << 1, l, mid, ll, rr));
  if (rr > mid) res = min(res, query(rt << 1 | 1, mid + 1, r, ll, rr));
  return res;
}
int query1(int rt, int l, int r, int ll, int rr) {
  if (ll > rr) return -1;
  if (ll <= l && rr >= r) return B[rt];
  int mid = (l + r) >> 1, res = -1;
  if (ll <= mid) res = max(res, query1(rt << 1, l, mid, ll, rr));
  if (rr > mid) res = max(res, query1(rt << 1 | 1, mid + 1, r, ll, rr));
  return res;
}
