    std::sort(is.begin(), is.end(),
              [&](int i, int j) { return ps[i] < ps[j]; });

    int pmax = -1, max = 0, cnt = 0;
    std::vector<int> ans(n);
    for (int l = 0; l < n; ++l) {
        ++cnt;
        max = std::max(max, ps[is[l]].second);
        if (max - pmax == cnt) {
            for (int i = 0; i < cnt; ++i) ans[is[l - i]] = cnt;
            pmax = max;
            max = 0;
            cnt = 0;
        }
    }

    for (auto a : ans) std::cout << a << "\n";
}

int main() {
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);

    solve();

    return 0;
}

