struct UnionFind {
    vector<int> par; // par[i]:iの親の番号　(例) par[3] = 2 : 3の親が2
    vector<int> rank;

    UnionFind(int N) : par(N), rank(N) { //最初は全てが根であるとして初期化
        for(int i = 0; i < N; i++){
            par[i] = i;
            rank[i] = 0;
        }
    }

    int root(int x) { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void unite(int x, int y) { // xとyの木を併合
        int rx = root(x); //xの根をrx
        int ry = root(y); //yの根をry
        if (rx == ry) return; //xとyの根が同じ(=同じ木にある)時はそのまま
        if(rank[x] < rank[y]){
            par[rx] = ry;
        }else{
            par[ry] = rx;
            if(rank[x] == rank[y]){
                rank[x]++;
            }
        }
        // par[rx] = ry; //xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
    }

    bool same(int x, int y) { // 2つのデータx, yが属する木が同じならtrueを返す
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }

};


int main(){
    int N;
    cin >> N;
    vector<int> X(N), Y(N);
    vector<int> xId(N+1), yId(N+1);
    UnionFind tree(N);

    REP(i,N){
        cin >> X[i] >> Y[i];
        xId[X[i]]=i;
        yId[Y[i]]=i;
    }

    int id = xId[1];
    while(true){
        int kx = X[id];
        int y_tmp = Y[id];

        for(int ky=y_tmp+1; ky <= N+1-kx; ky++){
            int id_y = yId[ky];
            tree.unite(id, id_y);
        }

        if(y_tmp==1){break;}
        id = yId[y_tmp - 1];
    }

    vector<int> count(N, 0);
    REP(i, N){
        count[tree.root(i)] += 1;
    }

    REP(i,N){
        cout << count[tree.root(i)] << endl;
    }
    return 0;

}

