struct unionfind {
	int N;
	vector<ll> par;
	vector<ll> size;
	unionfind(int N) : N(N) {
		par.resize(N);
		size.resize(N);
		REP(i, 0, N) {
			par[i] = i;
			size[i] = 1;
		}
	}

	ll getpar(ll ind) {
		while (par[ind] != ind) {
			ind = par[ind];
		}
		return ind;
	}

	void merge(ll ind1, ll ind2) {
		ll p1 = getpar(ind1);
		ll p2 = getpar(ind2);
		if (p1 == p2)return;
		if (size[p1] <= size[p2])par[p1] = p2;
		else par[p2] = p1;
		size[p1] = size[p1] + size[p2];
		size[p2] = size[p1];
	}
};


int main() {
	ll N;
	cin >> N;
	vector<pair<ll, ll>> p(N);
	unionfind t{ (int)N };
	REP(i, 0, N) cin >> p[i].first >> p[i].second;
	vector<ll> ind(N); REP(i, 0, N)ind[i] = i;
	auto scmp = [&](ll a, ll b) {return p[a].first < p[b].first; };
	set<ll, decltype(scmp)> s(scmp);
	auto cmp = [&](ll a, ll b) { return p[a].second > p[b].second; };
	sort(ind.begin(), ind.end(), cmp);
	REP(aaa, 0, N) {
		ll i = ind[aaa];
		auto itr = s.upper_bound(i);
		if (itr != s.end()) {
			t.merge(i, *itr);
		}
		s.insert(i);
	}
	REP(i, 0, N)PRI(t.size[t.getpar(i)]);
	return 0;
}

