struct UnionFind {
    vector<int> rank, parent, num;
    UnionFind(){};
    UnionFind(int size) : rank(size, 0), parent(size, 0), num(size, 0) {
        for (int i = 0; i < size; i++)
            makeset(i);
    }
    void makeset(int x) {
        parent[x] = x;
        rank[x] = x;
        num[x] = 1;
    }
    int size(int x) {
        return num[findset(x)];
    }
    bool same(int x, int y) {
        return findset(x) == findset(y);
    }
    int findset(int x) {
        if (x != parent[x]) {
            parent[x] = findset(parent[x]);
        }
        return parent[x];
    }
    void unite(int x, int y) {
        if (!same(x, y))
            link(findset(x), findset(y));
    }
    void link(int x, int y) {
        if (rank[x] > rank[y]) {
            parent[y] = x;
            num[x] += num[y];
        } else {
            parent[x] = y;
            num[y] += num[x];
            if (rank[x] == rank[y])
                rank[y]++;
        }
    }
};

