int lead[MAXN], sz[MAXN], par[MAXN];

int find(int x) {
    return x == par[x] ? x : par[x] = find(par[x]);
}

void merge(int x, int y) {
    x = find(x), y = find(y);
    if (x == y) return;
    par[x] = y;
    sz[y] += sz[x];
    lead[y] = min(lead[y], lead[x]);
}

int main() {
