    for (int i = 0; i < N; i++) {
        int y = V1[i].first.second;
        int idx = V1[i].second;
        par[idx] = idx;
        sz[idx] = 1;
        lead[idx] = y;
    }
    for (int i = 0; i < N; i++) {
        int y = V1[i].first.second;
        auto it = st.upper_bound(make_pair(y, 0));
        int idx = V1[i].second;
        if (it != st.begin()) {
            it = prev(it);
            while (1) {
                auto nit = it;
                bool OK = false;
                if (it != st.begin()) {
                    nit = prev(it);
                    OK = true;
                }
                merge(idx, it->second);
                st.erase(it);
                if (!OK) break;
                it = nit;
            }
        }
        idx = find(idx);
        st.insert(make_pair(lead[idx], idx));
    }
    for (int i = 0; i < N; i++) {
        printf("%d\n", sz[find(i)]);
    }
