set<int> s;
void Init()
{
    for(int i = 1;i <= n+10;i++){
        parent[i] = i;
        num[i]=1;
    }
    return;
}

int get_boss(int v)
{
    if(parent[v] == v)
        return v;
    else
    {
        //路径压缩(使搜索祖宗的过程中，路径中搜索的结点的父亲的变为祖宗)
        parent[v] = get_boss(parent[v]);
        return parent[v];
    }
}

void Merge(int v,int u) //u合并到v
{
    int t1 = get_boss(v);
    int t2 = get_boss(u);
    parent[t2] = t1;
    num[t1]+=num[t2];
    return;
}

