struct UnionFind {
    vector<int> data;
    UnionFind(int size) : data(size, -1) { }
    bool unionSet(int x, int y) {
        x = root(x); y = root(y);
        if (x != y) {
            if (data[y] < data[x]) swap(x, y);
            data[x] += data[y]; data[y] = x;
        }
        return x != y;
    }
    bool findSet(int x, int y) {
        return root(x) == root(y);
    }
    int root(int x) {
        return data[x] < 0 ? x : data[x] = root(data[x]);
    }
    int size(int x) {
        return -data[root(x)];
    }
};

template<class Type>
Type solve(Type res = Type()){
    int N; cin >> N;

    using Item = tuple<int,int,int>;
    vector<Item> ps(N);
    for(int i = 0; i < N;i++){
        int x,y; cin >> x >> y;
        x--; y--;
        ps[i] = Item(x,y,i);
    }

    sort(ps.begin(),ps.end());

    UnionFind UF(N);
    {
        set<pii> st;
        for(int i = 0; i < N;i++){
            int x,y,id; tie(x,y,id) = ps[i];

            while(st.size() && st.begin()->first < y){
                UF.unionSet(st.begin()->second, id);
                st.erase(st.begin());
            }
            st.emplace(y,id);
        }
    }
    {

        set<pii> st;
        for(int i = N-1; i >= 0; i--){
            int x,y,id; tie(x,y,id) = ps[i];

            while(st.size() && st.begin()->first < -y){
                UF.unionSet(st.begin()->second, id);
                st.erase(st.begin());
            }
            st.emplace(-y,id);
        }
    }
    for(int i = 0; i < N; i++){
        cout << UF.size(i) << endl;
    }
    return res;
}
