class ds
{

    vector<int> v1;
    vector<int> parent;
    vector<int> rank1;

public:
    unordered_map<int, int> siz;
    ds(vector<int> v)
    {
        v1 = v;
        parent.resize(v1.size());
        rank1.resize(v1.size());
        for (int t : v1)
        {
            parent[t] = t;
            rank1[t] = 0;
            siz[t] = 1;
        }
    }
    void union1(int a, int b)
    {
        a = find(a);
        b = find(b);
        if(a==b){
            return;
        }
        if (rank1[a] > rank1[b]){
                parent[b] = a;
                siz[a] += siz[b];
            }
        else if (rank1[b] > rank1[a]){

            parent[a] = b;
            siz[b] += siz[a];
        }
        else{
            parent[a] = b;
            siz[b] += siz[a];
            rank1[b]++;
        }
    }
    int find(int x)
    {
        if (parent[x] == x)
            return x;
        else
            return find(parent[x]);
    }
};
