        auto it = st.lower_bound(pii);
        if (it == st.begin()) {
            st.insert(pii);
        }else {
            auto it2 = st.begin();
            uf.unite((*it2).second, pii.second);
            it2++;
            while (it2 != st.end() && (*it2).first < town[i].first.second) {
                uf.unite((*it2).second, pii.second);
                it2 = st.erase(it2);
            }
        }
    }

    for (int i = 0; i < N; i++) {
        cout << uf.getsize(i) << endl;
    }

    return 0;
}

