	}

	sort(ALL(v));
	UF uf(n);
	set<P> s;
	REP(i, n) {
		ll num = v[i].FI.SE;
		ll id = v[i].SE;
		ll min_num = num;
		s.insert(MP(num, id));
		vector<P> tmp;
		for (auto const ele: s) {
			if (ele.FI > num) break;
			uf.unite(id, ele.SE);
			if(min_num < ele.FI) {
				tmp.PB(ele);
			}
			min_num = min(min_num, ele.FI);
		}

		for (auto const ele: tmp) {
			s.erase(ele);
		}
	}

	REP(i, n) {
		cout << uf.size(i) << endl;
	}

	return 0;
}

