int const N = 2e5+5;
int const inf = 1e18;   

int par[N], sz[N];
int seg[4*N];

void build(int in,int l,int r){
    if(l==r){
        seg[in] = 0;
        return ;
    }
    int mid = (l+r)/2;
    build(2*in,l,mid);
    build(2*in+1,mid+1,r);
    seg[in] = max(seg[2*in] , seg[2*in+1]);
}

void update(int in,int l,int r,int lt,int rt,int val){
	if(rt<l || lt>r){
		return;
	}
	if(l>=lt && r<=rt){
        seg[in] = val;
		return ;
	}
	int mid = (l+r)/2;
	update(2*in,l,mid,lt,rt,val);
	update(2*in+1,mid+1,r,lt,rt,val);
	seg[in] = max(seg[2*in+1] , seg[2*in]);
}

int query(int in,int l,int r,int lt,int rt){
	if(rt<l || lt>r) return 0;
	if(l>=lt && r<=rt){
		return seg[in];
	}
	int mid = (l+r)/2;
	if(rt<=mid) return query(2*in,l,mid,lt,rt);
	else if(lt > mid) return query(2*in+1,mid+1,r,lt,rt);
	else{
		int p,q;
		p = query(2*in,l,mid,lt,mid);
		q = query(2*in+1,mid+1,r,lt,rt);
		return max(p,q);
	}
}

int findpar(int in){
    if(par[in] == in) return in;
    return par[in] = findpar(par[in]);
}

void union_set(int x,int y){
    int x1 = findpar(x);
    int y1 = findpar(y);

    if(x1 != y1){
        par[x1] = y1;
        sz[y1] += sz[x1];
    }
}

