struct UnionFind
{
    vector<int> par, sz;
    int n_cc;

    UnionFind(int N){
        par = vector<int>(N);
        REP(i, N) par[i] = i;
        sz = vector<int>(N, 1);
        n_cc = N;
    }

    int find(int x){
        if(par[x] == x) return x;
        else return par[x] = find(par[x]);
    }

    void unite(int x, int y){
        x = find(x);
        y = find(y);
        if(x == y) return;

        if(sz[x] < sz[y]) swap(x, y);

        par[y] = x;
        sz[x] += sz[y];
        n_cc--;
    }

    bool is_union(int x, int y){
        x = find(x);
        y = find(y);
        return x == y;
    }

    int union_size(int x){
        return sz[find(x)];
    }

};


signed main(){

    int N; cin >> N;
    vec x(N), y(N);
    REP(i, N){
        cin >> x[i] >> y[i];
        x[i]--; y[i]--;
    }

    v_Pii f(N);
    REP(i, N) f[x[i]] = Pii(y[i], i);
    UnionFind UF(N);

    set<Pii> s;
    Pii m = f[0];
    FOR(i, 1, N){
        if(f[i] < m){
            s.insert(m);
            m = f[i];
        }else{
            int i0 = f[i].se;
            UF.unite(i0, m.se);
            while(SZ(s)){
                auto it = s.begin();
                if(*it > f[i]) break;
                UF.unite(i0, (*it).se);
                s.erase(it);
            }
        }
    }
    REP(i, N) Out(UF.union_size(i));

    return 0;
}

