int main(void){
	int N;
	cin >> N;

	vector<int> points(N);
	vector<int> indexes(N);
	vector<int> rev_indexes(N);

	for(int i = 0; i < N; i ++){
		int x, y;
		cin >> x;
		cin >> y;
		x --;
		y --;
		points[y] = x;
		indexes[y] = i;
		rev_indexes[i] = y;
	}

	dsu d(N);

	for(int y = 0; y < N; y ++){
		if(d.leader(y) == y){
			bool found = false;
			for(int y2 = 0; y2 < y; y2 ++){
				if(points[y2] < points[y]){
					d.merge(y, y2);
					found = true;
					break;
				}
			}
			if(found){
				continue;
			}
			for(int y2 = y + 1; y2 < N; y2 ++){
				if(points[y2] > points[y]){
					d.merge(y, y2);
					break;
				}
			}
		}
	}

	for(int k = 0; k < N; k ++){
		cout << d.size(rev_indexes[k]) << endl;
	}

	return 0;
}

