int main() {
  i32 N;
  std::cin >> N;
  std::vector<i32> X(N), Y(N);
  for (auto i: range(0, N)) {
    std::cin >> X[i] >> Y[i];
    --X[i]; --Y[i];
  }
  union_find dsu(N);
  const auto solve = [&] {
    std::vector<i32> order(N);
    std::iota(order.begin(), order.end(), 0);
    std::sort(order.begin(), order.end(), [&](i32 i, i32 j) {
      return X[i] < X[j];
    });
    std::map<i32, i32> map;
    for (auto i: rev(order)) {
      if (map.empty()) {
        map[Y[i]] = i;
        continue;
      }
      if (Y[i] > map.rbegin() -> first) {
        map[Y[i]] = i;
        continue;
      }
      dsu.unite(i, map.rbegin() -> second);
      for (auto itr = map.lower_bound(Y[i]); std::next(itr) != map.end(); ++itr) {
        dsu.unite(itr -> second, std::next(itr) -> second);
      }
    }
  };
  solve();
  for (auto i: range(0, N)) {
    X[i] = N - X[i] - 1;
    Y[i] = N - Y[i] - 1;
  }
  for (auto i: range(0, N)) {
    std::cout << dsu.component_size(i) << '\n';
  }
