const int N = (int) 2e5 + 7;
int n;
int t[N];
int sz[N];
int mn[N];

int root(int a)
{
    if (t[a] == a)
    {
        return a;
    }
    else
    {
        return t[a] = root(t[a]);
    }
}

void unite(int a, int b)
{
    a = root(a);
    b = root(b);
    if (a != b)
    {
        t[a] = b;
        sz[b] += sz[a];
        mn[b] = min(mn[b], mn[a]);
    }
}

struct T
{
    int x;
    int y;
    int i;
};

bool cmp(T a, T b)
{
    return a.x < b.x;
}

T a[N];
int pos[N];
int sol[N];

int main()
{
    ios::sync_with_stdio(0);
    cin.tie(0);

    cin >> n;
    for (int i = 1; i <= n; i++)
    {
        t[i] = i;
        sz[i] = 1;
        mn[i] = i;
        cin >> a[i].x >> a[i].y;
        a[i].i = i;
    }
    sort(a + 1, a + n + 1, cmp);
    for (int i = 1; i <= n; i++)
    {
        pos[a[i].y] = i;
    }
    set<int> s;
    for (int i = 1; i <= n; i++)
    {
        int val = a[i].y;
        auto it = s.lower_bound(val);
        int cnt = 10;
        while (it != s.begin() && cnt--)
        {
            it--;
            unite(i, pos[*it]);
        }
        s.insert(val);
    }
    s.clear();
    for (int i = n; i >= 1; i--)
    {
        int val = a[i].y;
        auto it = s.lower_bound(val);
        int cnt = 10;
        while (it != s.end() && cnt--)
        {
            unite(i, pos[*it]);
            it++;
        }
        s.insert(val);
    }

    for (int i = 1; i <= n; i++)
    {
        sol[a[i].i] = sz[root(i)];
    }
    for (int i = 1; i <= n; i++)
    {
        cout << sol[i] << "\n";
    }
}

