template <typename T>
struct BIT {
      int n;
      vector <T> Tree;

      void init(int N) {
            n = N;
            Tree = vector <T> (n + 1);
      }
      void update(int pos, T val) {
            while (pos <= n) {
                  Tree[pos] += val;
                  pos += (pos & -pos);
            }
      }
      T query(int pos) {
            T sum = 0;
            while (pos > 0) {
                  sum += Tree[pos];
                  pos -= (pos & -pos);
            }
            return sum;
      }
      T query(int l, int r) {
            return query(r) - query(l - 1);
      }
      int lowerBound(T val) {
            T sum = 0;
            int pos = 0;
            for (int i = logn - 1; i >= 0; i--) {
                  int newpos = pos + (1LL << i);
                  if (newpos < n and sum + Tree[newpos] < val) {
                        sum += Tree[newpos];
                        pos = newpos;
                  }
            }
            return pos + 1; // +1 because 'pos' will have position of largest
                            // value less than 'val'
      }
};

template <typename T>
struct SparseTable
{
      int n;
      vector < vector <T> > Table;

      void init(int N) {
            n = N;
            Table.clear();
            Table.resize(logn, vector <T> (n));
      }
      void build(vector <int> arr) {
            for (int i = 0; i < n; i++) Table[0][i] = arr[i];
            for (int k = 1; (1 << k) <= n; k++) {
                  for (int i = 0; i + (1 << (k - 1)) < n; i++) {
                        T x = Table[k - 1][i];
                        T y = Table[k - 1][i + (1 << (k - 1))];
                        Table[k][i] = max(x, y);
                  }
            }
      }
      T query(int i, int j) {
            int k = log2(j - i + 1);
            T x = Table[k][i];
            T y = Table[k][j + 1 - (1 << k)];
            return max(x, y);
      }
};

struct Node {
      int x, y, id;
      Node(int x = 0, int y = 0, int id = 0)
            : x(x), y(y), id(id) {}

      bool operator < (const Node &other) const {
            if (x == other.x) {
                  return y < other.y;
            }
            return x < other.x;
      }
};

