// Default max, add
struct Segment_tree {
	static const int RANGE = MAXN; // here
	struct Node {
		LL minv, maxv, add;
		Node() {
			minv = maxv = add = 0;
		}
	} t[4*RANGE];

	// Assume add = 0 when unite.
	Node unite(const Node &a, const Node &b) {
		Node res;
		res.maxv = max(a.maxv, b.maxv); // here
		res.minv = min(a.minv, b.minv); // here
		return res;
	}
	void apply(LL x, Node &d, int l, int r) {
//		d.val += x; // here
//		d.add += x;
	}

	void pull(int idx) {
		t[idx] = unite(t[idx << 1], t[idx << 1 | 1]);
	}
	void push(int l, int r, int idx) {
		if (t[idx].add != 0) { // here
			int m = (l + r) >> 1;
			apply(t[idx].add, t[idx << 1], l, m);
			apply(t[idx].add, t[idx << 1 | 1], m + 1, r);
			t[idx].add = 0;
		}
	}

	void init(Pair *arr, int l, int r, int idx) {
		if (l == r) {
			t[idx] = Node();
			t[idx].maxv = arr[l].y;
			t[idx].minv = arr[l].y;
			return;
		}
		int m = (l + r) >> 1;
		init(arr, l, m, idx << 1);
		init(arr, m + 1, r, idx << 1 | 1);
		pull(idx);
	}	
	Node query(int ql, int qr, int l, int r, int idx) {
		if (ql <= l && r <= qr) {
			return t[idx];
		}
		LL m = (l + r) >> 1;
		push(l, r, idx);
		if (qr <= m) {
			return query(ql, qr, l, m, idx << 1);
		}
		if (ql > m) {
			return query(ql, qr, m + 1, r, idx << 1 | 1);
		}
		return unite(query(ql, qr, l, m, idx << 1), query(ql, qr, m + 1, r, idx << 1 | 1));
	}
	void update(int ql, int qr, LL v, int l, int r, int idx) {
		if (ql <= l && r <= qr) {
			apply(v, t[idx], l, r);
			return;
		}
		int m = (l + r) >> 1;
		push(l, r, idx);
		if (ql <= m) {
			update(ql, qr, v, l, m, idx << 1);
		}
		if (qr > m) {
			update(ql, qr, v, m + 1, r, idx << 1 | 1);
		}
		pull(idx);
	}
} tree;

bool converge(int l, int r) {
//	cout << "Q " << l << ' ' << r << endl;
	int ok = 1;
	if (l != 1) {
		ok &= tree.query(1, l - 1, 1, n, 1).minv > tree.query(l, r, 1, n, 1).maxv;
	}
	if (r != n) {
		ok &= tree.query(l, r, 1, n, 1).minv > tree.query(r + 1, n, 1, n, 1).maxv;
	}
	return ok;
}

void solve() {
	cin >> n;
	for (int i = 1; i <= n; i++) {
		int x, y;
		cin >> x >> y;
		ps[i] = {x, y, i};
	}
	sort(ps + 1, ps + 1 + n);
	tree.init(ps, 1, n, 1);

	int l = 1;
	while (l <= n) {
		int r = l;
		while (r < n && !converge(l, r)) {
			r++;
		}
//		cout << "Get " << l << ' ' << r << '\n';
		for (int i = l; i <= r; i++) {
			ans[ps[i].id] = r - l + 1;
		}
		l = r + 1;
	}

	for (int i = 1; i <= n; i++) {
		cout << ans[i] << '\n';
	}
}

