        v.emplace_back(x, y, i);
    }
    sort(v.begin(), v.end());
    set<pair<int, int>> st;
    UnionFind uf(N);
    for(auto [x, y, idx] : v){
        int mi = y;
        while(1){
            auto itr = st.lower_bound({y, INF});
            if(itr == st.begin()) break;
            --itr;
            uf.unite(idx, itr->second);
            chmin(mi, itr->first);
            st.erase(itr);
        }
        st.emplace(mi, idx);
    }
    REP(i,N) cout << uf.size(i) << endl;
}

