    set<int> s;
    UF uf(n);
    // up
    for(int i = 0; i < n; i++){
        auto it = s.lower_bound(x[yrev[i]]);
        if(it != s.begin()){
            it--;
            uf.unite(xrev[*it], yrev[i]);
        }
        s.insert(x[yrev[i]]);
    }
    s.clear();
    // down
    for(int i = n-1; i >= 0; i--){
        auto it = s.upper_bound(x[yrev[i]]);
        if(it != s.end()){
            uf.unite(xrev[*it], yrev[i]);
        }
        s.insert(x[yrev[i]]);
