    s.clear();
    // left
    for(int i = n-1; i >= 0; i--){
        auto it = s.upper_bound(y[xrev[i]]);
        if(it != s.end()){
            uf.unite(yrev[*it], xrev[i]);
        }
        s.insert(y[xrev[i]]);
