struct UnionFind{

    vector<int> M_par;
    vector<int> M_rank;
    vector<int> M_size;

private:
    void init(int n = 1){
        M_par.resize(n);
        M_rank.resize(n);
        M_size.resize(n);
        for(int i = 0; i < n; i++){
            M_par[i] = i;
            M_rank[i] = 0;
            M_size[i] = 1;
        }
    }

public:

    UnionFind(size_t n = 1){
        init(n);
    }

    size_t find(size_t x){
        if(M_par[x] == x) return x;
        size_t r = find(M_par[x]);
        return M_par[x] = r;
    }

    bool same(size_t x, size_t y){
        return find(x) == find(y);
    }

    bool unite(size_t x, size_t y){
        x = find(x);
        y = find(y);
        if(x == y) return false;
        if(M_rank[x] < M_rank[y]) swap(x, y);
        if(M_rank[x] == M_rank[y]) M_rank[x]++;
        M_par[y] = x;
        M_size[x] = M_size[x] + M_size[y];
        return true;
    }

    size_t size(size_t x){
        return M_size[find(x)];
    }

};

vector<lint> culc1(vector<pair<pair<int, int>, int>> v) {

  int n = v.size();

  // y について平面操作
  sort(RALL(v));
  using T = lint;  // type T
  using E = lint;  // type E
  auto f = [](T a, T b){ // return type T value
    return a + b;
  };
  auto g = [](T a, E b){ // return type T value
    return b;  // return b;
  };
  T ti = 0;  // identity element
  SegmentTree<T, E, decltype(f), decltype(g)> sg(f, g, ti);  // don't change
  sg.build(vector<lint> (n, 0));

  vector<lint> ans(n);
  for (int i = 0; i < n; i++) {

    int y = v[i].first.first;
    int x = v[i].first.second;
    int id = v[i].second;

    sg.update(x, 1);
    ans[id] += sg.query(x + 1, n);
  }

  // セグ木初期化
  for (int i = 0; i < n; i++) {
    sg.update(i, 0);
  }


  // 左で小さいやつ
  sort(ALL(v));
  for (int i = 0; i < n; i++) {

    int y = v[i].first.first;
    int x = v[i].first.second;
    int id = v[i].second;

    sg.update(x, 1);
    ans[id] += sg.query(0, x);
  }

  for (int i = 0; i < n; i++) {
    ans[i]++;
  }

  return ans;
}


vector<lint> culc2(map<lint, lint> xi, map<lint, lint> x2, vector<lint> dat) {

  int n = dat.size();

  using T = lint;

  auto f = [](T a, T b){ // return type T value
    return lint(max(a, b));
  };

  auto ti = []() {
    return T(-INF);
  };

  segtree<T, f, ti> sg(dat);

  UnionFind uf(n);
  for (int x = 0; x < n; x++) {
    target = sg.prod(x, x + 1);

    // cerr << "target = " << target << endl;
    int id = sg.max_right<find>(x);
    // cerr << "id = " << id << endl;

    // cerr << "id = " << id << endl;
    if (id == n) continue;
    // cerr << xi[x] << " " << xi[id] << endl;
    // cerr << "unite " << xi[x] + 1 << " " << xi[id] + 1 << endl;
    uf.unite(xi[x], xi[id]);
  }

  reverse(ALL(dat));

  auto f2 = [](T a, T b){ // return type T value
    return lint(min(a, b));
  };

  auto ti2 = []() {
    return T(INF);
  };
  segtree<T, f2, ti2> sg2(dat);
  for (int x = 0; x < n; x++) {
    target = sg2.prod(x, x + 1);

    // cerr << "target = " << target << endl;
    int id = sg2.max_right<find2>(x);
    // cerr << "id = " << id << endl;

    // cerr << "id = " << id << endl;
    if (id == n) continue;
    // cerr << xi[x] << " " << xi[id] << endl;

    uf.unite(xi[n - x - 1], xi[n - id - 1]);

  }

  vector<lint> ans(n);
  for (int x = 0; x < n; x++) {
    int id = xi[x];
    ans[id] = uf.size(id);
  }
  return ans;

}

