    UnionFind UF(N);

    ll town[N+1][N+1];
    for (ll i = 0; i < N; i++)
    {
        cin >> town[i][0] >> town[i][1];
    }

    for(ll i = 0; i < N; i++){
        for(ll j = i + 1; j < N; j++){
            if((town[i][0] - town[j][0]) > 0 && (town[i][1] - town[j][1]) > 0){
                UF.unite(i,j);
            }
            else if((town[i][0] - town[j][0]) < 0 && (town[i][1] - town[j][1]) < 0){
                UF.unite(i,j);
            }
        }
    }

    vector<ll> res(N+1,1);
    for (ll i = 0; i < N; i++){
        for(ll j = i + 1; j < N; j++){
            if(UF.same(i,j)){
                res[i] += 1;
                res[j] += 1;
                }
        }
    }

    for (ll i = 0; i < N; i++){
        cout << res[i] << endl;
    }

    return 0;
}

