void solve(int N, vi& x, vi& y) {
    map<int, int> rev;
    vii xy(N);
    rep(i, N) {
        xy[i] = ii(x[i], y[i]);
        rev[y[i]] = x[i];
    }
    sort(ALL(xy));
    vi f(N);
    rep(i, N) f[i] = xy[i].second;

    atcoder::dsu dsu(N + 1);

    set<int> sr;
    sr.insert(f[N - 1]);
    for (int i = N - 2; i >= 0; --i) {
        int h = f[i];
        vi to_erase;
        for (auto it = sr.upper_bound(h); it != sr.end(); ++it) {
            int u = rev[h], v = rev[*it];
            dsu.merge(u, v);
            to_erase.pb(*it);
        }
        for (int e : to_erase) sr.erase(e);
        sr.insert(h);
    }
    set<int> sl;
    sl.insert(-f[0]);
    for (int i = 1; i < N; ++i) {
        int h = -f[i];
        vi to_erase;
        for (auto it = sl.upper_bound(h); it != sl.end(); ++it) {
            int u = rev[-h], v = rev[-(*it)];
            dsu.merge(u, v);
            to_erase.pb(*it);
        }
        for (int e : to_erase) sl.erase(e);
        sl.insert(h);
    }

    rep(i, N) { printf("%d\n", (int)dsu.size(x[i])); }
}

