struct Coordinate {
	int x, y;
};
int main() {
	int n; std::cin >> n;
	std::vector<Coordinate> coordinate(n);
	for (auto& c : coordinate) {
		std::cin >> c.x >> c.y;
	}
	atcoder::dsu uft(n);
	std::stack<std::pair<int, int>> stack;
	std::vector<int> indices(n); std::iota(indices.begin(), indices.end(), 0);
	std::sort(indices.begin(), indices.end(), [&](const int i, const int j) {return coordinate[i].x < coordinate[j].x; });
	int min_y_pos = indices.front();
	for (const auto i : indices) {
		if (coordinate[min_y_pos].y < coordinate[i].y) {
			uft.merge(min_y_pos, i);
		}
		else {
			stack.emplace(min_y_pos, coordinate[min_y_pos].y);
			min_y_pos = i;
		}
		while (!stack.empty() && stack.top().second <= coordinate[i].y) {
			uft.merge(i, stack.top().first);
			stack.pop();
		}
		stack.emplace(i, coordinate[i].y);
	}
	std::reverse(indices.begin(), indices.end());
	while (!stack.empty()) stack.pop();
	int max_y_pos = indices.front();
	for (const auto i : indices) {
		if (coordinate[max_y_pos].y > coordinate[i].y) {
			uft.merge(max_y_pos, i);
		}
		else {
			stack.emplace(max_y_pos, coordinate[max_y_pos].y);
			max_y_pos = i;
		}
		while (!stack.empty() && stack.top().second >= coordinate[i].y) {
			uft.merge(i, stack.top().first);
			stack.pop();
		}
		stack.emplace(i, coordinate[i].y);
	}
	for (auto i = 0; i < n; ++i) {
		std::cout << uft.size(i) << '\n';
	}
}

