struct UnionFind {
    vector<int> r;
    int n;
    UnionFind(int a) {
        n = a;
        r.assign(a + 1, -1);
    }
    int root(int x) {
        if (r[x] < 0) return x;
        return r[x] = root(r[x]);
    }
    void unite(int a, int b) {
        int x = root(a);
        int y = root(b);
        if (r[x] > r[y]) swap(x, y);
        r[x] += r[y];
        r[y] = x;
        return;
    }
    int query(int x) {
        return -r[root(x)];
    }
};
