struct DSU {
  int n;
  std::vector<int> par;
  std::vector<int> rank;

  explicit DSU(int _n) : n(_n) {
    par.resize(n);
    rank.resize(n);
    for (int i = 0; i < n; ++i) {
      par[i] = i;
      rank[i] = 1;
    }
  }

  int root(int x) {
    return par[x] = (x == par[x]) ? x : root(par[x]);
  }

  bool unite(int x, int y) {
    x = root(x);
    y = root(y);
    if (x == y) return true;
    if (rank[x] < rank[y]) swap(x, y);
    par[y] = x;
//    if (rank[x] == rank[y]) rank[x]++;
    rank[x] += rank[y];
    return false;
  }

  int Count() {
    int cnt = 0;
    for (int i = 0; i < n; ++i) {
      if (root(i) == i) cnt++;
    }
    return cnt;
  }
};

class AReachableTowns {
public:

  void solve(std::istream& cin, std::ostream& cout) {
    int n;
    cin >> n;
    DSU dsu(n);
    vector<pair<pair<int, int>, int>> vec(n);
    for (int i = 0; i < n; ++i) {
      cin >> vec[i].first.first >> vec[i].first.second;
      vec[i].second = i;
    }
    sort(vec.begin(), vec.end());
    stack<pair<int, int>> st;
    for (auto v: vec) {
      auto[x, y, id] = tie(v.first.first, v.first.second, v.second);
      int z = y;
      while (!st.empty() && st.top().first < y) {
        mini(z, st.top().first);
        dsu.unite(id, st.top().second);
        st.pop();
      }
      st.push({z, id});
    }
    for (int i = 0; i < n; ++i) {
      cout << dsu.rank[dsu.root(i)] << '\n';
    }
  }
};

