    while(tmp){
        tree[tmp] = min(tree[tmp<<1],tree[(tmp<<1)|1]);
        tmp>>=1;
    }

    return;
}

int getans(int L,int R)
{
    int res = INF;

    while(L<=R){
        if(L&1){
            res = min(res,tree[L]);
            L++;
        }
        if(!(R&1)){
            res = min(res,tree[R]);
            R--;
        }
        L>>=1; R>>=1;
    }

    return res;
}

