	cin >> n >> m;
	UnionFind UF(n);
	rep(i,m) {
		int a, b;
		cin >> a >> b;
		a--;b--;
		UF.unite(a,b);
	}
	int ans=0;
	rep(i,n) {
		ans = max(ans, UF.size(i));
	}
	cout << ans << endl;
	return 0;
}

