struct UnionFind{
	vl p;
	vl rank;
	vl cnt;

	UnionFind(ll n){
		rank.resize(n,0);
		p.resize(n,0);
		cnt.resize(n,0);
		rep(i,n){
			p[i] = i;
			rank[i] = 0;
			cnt[i] = 1;
		}
	}

	ll find(ll x){
		if(x != p[x]) p[x] = find(p[x]);
		return p[x];
	}

	bool same(ll x, ll y){
		return find(x) == find(y);
	}

	void unite(ll x, ll y){
		x = find(x);
		y = find(y);
		if(x == y) return;
		if(rank[x] > rank[y]){
			p[y] = x;
			cnt[x] += cnt[y];
		}else{
			p[x] = y;
			cnt[y] += cnt[x];
			if(rank[x] == rank[y]) rank[y]++;
		}
	}

	ll size(ll x){
		return cnt[find(x)];
	}
};

int main(){
	int n; cin >> n;
	UnionFind uf(n);
	vector<P> ls(n);
	rep(i,n){
		int x,y; cin >> x >> y; x--;
		ls[x] = P(y,i);
	}
	set<P> se;
	rep(i,n){
		auto itr = se.upper_bound(ls[i]);
		if(itr == se.begin()){
			se.emplace(ls[i]);
		}else{
			for(auto it = se.begin(); it != itr; it++){
				uf.unite(ls[i].second, (*it).second);
			}
			int a = (*se.begin()).first;
			se.erase(se.begin(), itr);
			se.emplace(a,ls[i].second);
		}
	}
	rep(i,n) cout << uf.size(i) << "\n";
}

