class UnionFind {
    vector<int> par, rank, size;
public:
    explicit UnionFind(int n) : par(n), rank(n, 0), size(n, 1) {
        iota(par.begin(), par.end(), 0);
    }

    int find(int i) {
        return (par[i] == i) ? i : (par[i] = find(par[i]));
    }

    void unite(int i, int j) {
        int x = find(i), y = find(j);
        if (x != y) {
            if (rank[x] < rank[y]) {
                par[x] = y;
                size[y] += size[x];
            } else {
                par[y] = x;
                size[x] += size[y];
                if (rank[x] == rank[y]) rank[x]++;
            }
        }
    }

    int card(int i) { return size[find(i)]; }
};

int main() {
    int n; cin >> n;
    int xy[n], xinv[n];
    for (int i = 0; i < n; i++) {
        int x, y; cin >> x >> y;
        xy[x-1] = y-1;
        xinv[x-1] = i;
    }
    set<pair<int, int> > s; // (y, x)
    UnionFind uf(n);
    for (int x = 0; x < n; x++) {
        pair<int, int> p = {xy[x], x};
        for (auto it = s.begin(); it != s.end() && it->first < xy[x]; ) {
            uf.unite(xinv[x], xinv[it->second]);
            it = s.erase(it);
            if (p.second > it->first) p = *it;
        }
        s.insert(p);
    }
    for (int i = 0; i < n; i++) cout << uf.card(i) << endl;
}

