// UnionFind
struct UnionFind {
    vector<ll> par;
    vector<ll> siz;

    UnionFind(ll N) : par(N), siz(N, 1LL) {
        for(int i = 0; i < N; i++)
            par[i] = i;
    }
    int root(int x) {
        if(par[x] == x)
            return x;
        return par[x] = root(par[x]);
    }
    void unite(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        if(rx == ry)
            return;
        if(siz[rx] < siz[ry])
            swap(rx, ry);
        siz[rx] += siz[ry];
        par[ry] = rx;
    }
    bool same(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
    ll size(ll x) { return siz[root(x)]; }
};

int main() {
    int N;
    cin >> N;
    vector<pii> city(N);
    vector<int> place(N);
    rep(i, N) {
        cin >> city[i].first >> city[i].second;
        city[i].first--;
        city[i].second--;
        place[city[i].first] = i;
    }
    vector<int> X(N);
    rep(i, N) { X[city[i].second] = city[i].first; }
    sort(All(city));
    UnionFind uf(N);
    set<int> se;
    for(int i = 0; i < N; i++) {
        se.insert(city[i].second);
        auto stop = se.find(city[i].second);
        int cnt = 0;
        auto it = se.begin();
        while(it != stop) {
            uf.unite(i, X[*it]);
            cnt++;
            if(it != se.begin()) {
                se.erase(it++);
            } else
                it++;
        }
        if(cnt)
            se.erase(stop);
    }
    vector<int> res(N);
    rep(i, N) { res[place[i]] = uf.size(i); }
    rep(i, N) { cout << res[i] << endl; }
}

