inline int lowbit(int x){return x&(-x);}inline int Find(int x){return bin[x]==x?x:bin[x]=Find(bin[x]);}
void join(int x,int y)
{
	bin[Find(y)]=Find(x);
}

void update(int x,int p)
{
	while(x<=n)
	{
		tree[x].pb(p);
		x+=lowbit(x);
	}
}
void query(int x,int q)
{
	while(x)
	{
		if(!tree[x].empty())
		{
			int lst=tree[x].size()-1;
			while(Find(tree[x][lst])!=tree[x][lst]&&lst>=0)
				join(q,Find(tree[x][lst--]));
			if(lst>=0)join(q,Find(tree[x][lst]));
		}
		x-=lowbit(x);
	}
}
