void mdf(int a,int k)
{
	while(a<=p)
	{
		bit[a]=min(bit[a], k);
		a+=a&(-a);
	}
}

int qry(int a)
{
	int res=1e9;
	while(a)
	{
		res=min(res, bit[a]);
		a-=a&(-a);
	}
	return res;
}

