ll findp(ll u)
{
    return lab[u] < 0 ? u : lab[u] = findp(lab[u]);
}
void hop(ll u, ll v)
{
    if(lab[u] > lab[v])swap(u, v);
    lab[u] += lab[v];
    lab[v] = u;
}
struct dang
{
    ll l, r, pos;
} a[N];
bool cmp(const dang& X, const dang& Y)
{
    return X.l > Y.l;
}
bool cmt(const dang& X, const dang& Y)
{
    return X.l < Y.l;
}
void dfs(ll u)
{
    b[u] = 1;
    for(ll v : adj[u])
    {
        if(lab[v] == 0)
        {
            lab[v] = lab[u];
            dfs(v);
            b[u] += b[v];
        }
    }
}
void sol()
{
    cin >> n;
    for(int i = 1; i <= n; i ++)
    {
        cin >> a[i].l >> a[i].r;
        a[i].pos = i;
        b[a[i].l] = i;
        lab[i] = -1;
    }
    sort(a+1, a+1+n, cmt);
    set<ll> ds;
    for(int i = 1; i <= n; i ++)
    {

        auto it = ds.lower_bound(-a[i].r);
        if(it != ds.end())
        {
            //cout << b[-*it] <<" "<<a[i].pos << '\n';
            ll u = findp(b[-*it]), v = findp(a[i].pos);
            if(u != v)hop(u, v);
        }
        b[a[i].r] = a[i].pos;
        ds.insert(-a[i].r);
    }
    for(int i = 1; i <= n; i ++)
    {
        ll u = findp(i);
        cout << - lab[u] << '\n';
    }

}
