struct UnionFind
{
    vector<int> par, rank, sz, maxv;
    UnionFind(int N) : par(N), rank(N), sz(N), maxv(N)
    {
        REP(i, N)
        {
            par[i] = i;  //the parent of the node
            rank[i] = 0; //the rank of the tree
            sz[i] = 1;
            maxv[i] = 1;
        }
    }
    int find(int x)
    { //Find the root of x
        if (par[x] == x)
        {
            return x;
        }
        else
        {
            return par[x] = find(par[x]);
        }
    }
    int size(int x)
    {
        return sz[find(x)];
    }
    int maxval(int x)
    {
        return maxv[find(x)];
    }
    void unite(int x, int y)
    { //Unite (the set of x) and (the set of y)
        x = find(x), y = find(y);
        if (x == y)
            return;
        if (rank[x] < rank[y])
        { //larger rank is above
            sz[y] += sz[x];
            maxv[y] = max(maxv[y], maxv[x]);
            par[x] = y;
        }
        else
        {
            sz[x] += sz[y];
            maxv[x] = max(maxv[y], maxv[x]);
            par[y] = x;
            if (rank[x] == rank[y])
                rank[x]++;
        }
    }
    bool same(int x, int y)
    {
        return find(x) == find(y);
    }
};

