    for (int i = 0; i < n; i++)
    {
        int Y = si[i].second;
        while (s.size())
        {
            auto it = s.begin();
            pii z = *it;
            if (z.first < Y)
            {
                D.Merge(z.second, si[i].first);
                s.erase(s.begin());
            }
