int ar[N+2], l[4*N], r[4*N], x[N+2], y[N+2], ans[N+2];

void upd(int *st, int idx, int l, int r, int target, int val) {
    if (l == r) {
        st[idx] = val;
        return;
    }
    int m = (l+r) / 2;
    if (target <= m) 
        upd(st,2*idx,l,m,target,val);
    else 
        upd(st,2*idx+1,m+1,r,target,val);
    st[idx] = st[2*idx] + st[2*idx+1];
}

int getSum(int *st, int idx, int l, int r, int x, int y) {
    if (l > r || l > y || r < x)
        return 0;
    if (l >= x && r <= y)
        return st[idx];
    int m = (l+r) / 2;
    return getSum(st,2*idx,l,m,x,y) + getSum(st,2*idx+1,m+1,r,x,y);
}

