int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  int n;
  cin >> n;
  vector<P> pts(n);
  for (int i=0; i<n; ++i) {
    P& p = pts[i];
    cin >> p.x >> p.y;
    --p.x; --p.y;
    p.ind = i;
  }
  sort(pts.begin(), pts.end(), [](const P& p1, const P& p2) { return p1.x < p2.x; });
  set<pii> before;
  scc_graph graph(n);
  for (int i=0; i<n; ++i) {
    auto it = before.lower_bound({pts[i].y,0});
    while (it != before.begin()) {
      --it;
      graph.add_edge(pts[i].ind, it->second);
      graph.add_edge(it->second, pts[i].ind);
    }
    before.insert({pts[i].y, pts[i].ind});
  }
  set<pii> after;
  for (int i=n-1; i>=0; --i) {
    auto it = after.lower_bound({pts[i].y, 0});
    while (it != after.end()) {
      graph.add_edge(pts[i].ind, it->second);
      graph.add_edge(it->second, pts[i].ind);
      ++it;
    }
    after.insert({pts[i].y, pts[i].ind});
  }
  vector<vector<int>> sccs = graph.scc();
  vector<int> sccsz(n);
  for (const vector<int>& scc: sccs) {
    for (int v : scc) {
      sccsz[v] = scc.size();
    }
  }
