///===========================================  template  =======================================================

#define lc (id<<1)
#define rc ((id<<1)|1)

int arr[nmax];
pair<int, int> tree[4*nmax];

pair<int, int> op(pair<int, int> p, pair<int, int> q){
    if(p.first == -1) return q;
    if(q.first == -1) return p;
    return {arr[p.first] < arr[q.first]? p.first: q.first, arr[p.second] > arr[q.second]? p.second : q.second};
}

void build(int id, int l, int r)
{
    if(l == r)
    {
        tree[id] = {l, l};
        return;
    }
    int mid = (l+r)/2;
    build(lc, l, mid);
    build(rc, mid+1, r);
    tree[id] = op(tree[lc], tree[rc]);
}

pair<int, int> query(int id, int l, int r, int L, int R)
{
    if(R < l || r < L) return {-1, -1};	//Disjoint case, return identity
    if(L <= l && r <= R) return tree[id];	//Subinterval case, return value

    int mid = (l+r)/2;
    auto p = query(lc, l, mid, L, R);
    auto q = query(rc, mid+1, r, L, R);
    return op(p, q);
}

void update(int id, int l, int r, int k)
{
    if(l == r)
    {
    	tree[id] = {-1, -1};
        return;
    }

    int mid = (l+r)/2;
    if(k <= mid) update(lc, l, mid, k);
    else update(rc, mid+1, r, k);

    tree[id] = op(tree[lc], tree[rc]);
}

int comp[nmax];
int sz[nmax];
int id[nmax];


int ans[nmax];


void bfs(int root, int n){
    queue<int> q;
    q.push(root);

    update(1, 1, n, root);

    while(!q.empty()){
        int u = q.front();
        q.pop();
        comp[u] = root;
        sz[root]++;

        while(true){
            auto p = query(1, 1, n, u+1, n);
            if(p.first == -1 || arr[p.second] < arr[u]) break;
            q.push(p.second);
            update(1, 1, n, p.second);
        }

        while(true){
            auto p = query(1, 1, n, 1, u-1);
            if(p.first == -1 || arr[p.first] > arr[u]) break;
            q.push(p.first);
            update(1, 1, n, p.first);
        }
    }
}

