class solver{
    istream& is;
    ostream& os;

public:
    solver(istream& I, ostream& O) :is(I), os(O) {}

    int N;
    vector<pair<int, int>> xy;
    bool input() {
        is >> N;
        xy.resize(N);
        is >> xy;
        return !!is;
    }

    void run();
};

void solver::run(){
    if(!input()) return;
    map<int, int> rx, ry;
    UFF uf(N);
    for (int i = 0; i < N; ++i) {
        rx[xy[i].first] = i;
        ry[xy[i].second] = i;
    } // end i
    for (auto &&xi : rx) {
        int x, i;
        tie(x, i) = xi;
        ry.erase(xy[i].second);
        auto p = ry.upper_bound(xy[i].second);
        if(xy[p->second].second < xy[i].second) continue;
        vector<int> rmy;
        while(p != ry.end()){
            int id = p->second;
            if(x >= xy[id].first){
                auto r = p;
                p++;
                ry.erase(r);
                continue;
            }
            assert(xy[i].second < xy[id].second);
            uf.unite(i, id);
            rmy.emplace_back(id);
            p++;
        }
        if(rmy.empty()) continue;
        int mxi = i, mx= x;
//        cerr << "f = " << x << ' ' << xy[i].second << endl;
        for (int ind : rmy) {
            if(CHMAX(mx, xy[ind].first)){
                mxi = ind;
            }
//            skip[ind] = true;
//            cerr << "DEL" << xy[ind].first << ' '<< xy[ind].second << endl;
            ry.erase(xy[ind].second);
        } // end k
        ry[mx] = mxi;
    } // end xi
    for (int i = 0; i < N; ++i) {
        cout << uf.size(i) << '\n';
    } // end i

}

