	segtree_t(int n) : n(n) {
		for(base=1;base<n;base*=2)
			;
		v.assign(base*2, -1);
	}
	void seti(int x)
	{
		if(x<=0) return;
		if(v[x]<0) v[x]=max(v[x*2], v[x*2+1]);
		seti(x/2);
	}
	void set(int idx, int val)
	{
		int x=base+idx;
		v[x]=val;
		seti(x/2);
	}
	int geti(int x)
	{
		if(x<=0) return -1;
		if(x&1) if(v[x-1]>=0) return v[x-1];
		return geti(x/2);
	}
	int get(int idx)
	{
		int x=base+idx;
		if(v[x]>=0) return v[x];
		return geti(x);
	}
};




