template<class T, class Op = std::plus<>>class binary_indexed_tree
{
	std::vector<T> vec;
	std::size_t sz;
	Op op;
public:
	binary_indexed_tree(std::size_t size, Op f = Op()) :vec(size), sz(size), op(f)
	{

	}
	void add(int i, T const& val)
	{
		++i;
		while (i <= sz)
		{
			vec[i - 1] = op(vec[i - 1], val);
			i += i & -i;
		}
	}
	auto get(int i)const
	{
		++i;
		T ret{};
		while (i != 0)
		{
			ret += vec[i - 1];
			i -= i & -i;
		}
		return ret;
	}
};

class union_find
{
	mutable std::vector<std::optional<index_t>> parent;
	std::vector<index_t> rank, elem;
	std::set<index_t> tops;
	std::size_t sz;
public:
	union_find(std::size_t N) :parent(N), rank(N), elem(N, 1), tops(), sz(N)
	{
		for (index_t i = 0; i < N; ++i)
		{
			tops.emplace(i);
		}
	}
	index_t find(index_t a)const
	{
		if (!parent[a])
		{
			return a;
		}
		else
		{
			return *(parent[a] = find(*parent[a]));
		}
	}
	void merge(index_t a, index_t b)
	{
		auto x = find(a);
		auto y = find(b);
		if (x != y)
		{
			--sz;
			if (rank[x] < rank[y])
			{
				tops.erase(x);
				parent[x] = y;
				elem[y] += elem[x];
			}
			else if (rank[y] < rank[x])
			{
				tops.erase(y);
				parent[y] = x;
				elem[x] += elem[y];
			}
			else
			{
				tops.erase(y);
				parent[y] = x;
				elem[x] += elem[y];
				++rank[x];
			}
		}
	}
	std::size_t size(std::optional<index_t> index = std::nullopt)const
	{
		return index ? elem[find(*index)] : sz;
	}
	auto begin()const
	{
		return tops.begin();
	}
	auto end()const
	{
		return tops.end();
	}
};

