        else return par[x] = root(par[x]);
    }

    bool issame(ll x, ll y) {
        return root(x) == root(y);
    }

    bool unite(ll x, ll y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (par[x] > par[y]) swap(x, y); // merge technique
        par[x] += par[y];
        par[y] = x;
        return true;
    }

    ll size(ll x) {
        return -par[root(x)];
    }
};

int solve(){
    ll n;
    cin>>n;
    Vec x(n);
    Vec y(n);
    vector<pair<ll,P>> point(n);
    rep(i,n){
        cin>>x[i]>>y[i];
    }
    rep(i,n){
        point[i] = mp(x[i],mp(y[i],i));
    }

    UnionFind uf(n);
    sort(ALL(point));

    stack<P> stk;
    rep(i, n){
        auto [y, id] = point[i].se;
        if(stk.empty()){
            stk.emplace(y,id);
        }else{
            P tp  = stk.top();
            if(tp.fi < y){
                while(!stk.empty() && stk.top().fi < y){
                    P p  = stk.top();
                    uf.unite(p.se, id);
                    stk.pop();
                }
                stk.emplace(tp);
            }else{
                stk.emplace(y,id);
            }
        }
    }

    rep(i,n){
        out(uf.size(i));
    }

    return  0;
}

