class UnionFind{
public:
    int n;
    vector<int> v;

    UnionFind():n{0}{}
    UnionFind(int n_in):n{n_in}{
        v.assign(n,-1);
    }

    int find(int x){
        assert(0<=x && x<n);
        if(v[x]<0) return x;
        v[x]=find(v[x]);
        return v[x];
    }

    bool same(int a,int b){
        assert(0<=a && a<n);
        assert(0<=b && b<n);
        if(find(a)==find(b)) return true;
        return false;
    }

    int merge(int a,int b){
        assert(0<=a && a<n);
        assert(0<=b && b<n);
        int a_p=find(a),b_p=find(b);
        if(a_p==b_p) return a_p;
        if(a_p>b_p) swap(a_p,b_p);
        v[a_p]+=v[b_p]; v[b_p]=a_p;
        return a_p;
    }

    int size(int a){
        assert(0<=a && a<n);
        return -v[find(a)];
    }

    int group_cnt(){
        int res=0;
        for(auto p:v)if(p<0) res++;
        return res;
    }

    vector<std::vector<int>> groups(){
        vector<int> leader_buf(n),group_size(n);
        for (int i=0;i<n;i++){
            leader_buf[i]=find(i);
            group_size[leader_buf[i]]++;
        }
        vector<vector<int>> result(n);
        for (int i=0;i<n;i++){
            result[i].reserve(group_size[i]);
        }
        for (int i=0;i<n;i++){
            result[leader_buf[i]].push_back(i);
        }
        //空である配列要素を消去する
        result.erase(
            remove_if(result.begin(),result.end(),
                           [&](const vector<int>& _v) {return _v.empty();}),
            result.end());
        return result;
    }
};

