vector<int> solver1(int n,vector<pair<Pair,int>> xy){
  sort(xy.begin(), xy.end());
  stack<Pair> s;
  dsu d(n);
  rep(i, n) {
    if (!s.empty()) {
      Pair mn = s.top();
      if (mn.first < xy[i].first.second) {
        s.pop();
        d.merge(i, mn.second);
        while (!s.empty() && s.top().first < xy[i].first.second) {
          d.merge(i, s.top().second);
          s.pop();
        }
        s.push(mn);
      } else {
        s.push(Pair(xy[i].first.second, i));
      }
    }else s.push(Pair(xy[i].first.second, i));
  }
  vector<int> ret(n);
  rep(i, n) ret[xy[i].second] = d.size(i);
  return ret;
}
