struct TCalcSegTree {
    using Type = i64;
    const Type Zero = 0;

    inline Type Combine(Type a, Type b) {
        return a + b;
    }

    i64 N = 0;
    vector<Type> St;

    TCalcSegTree() {}

    TCalcSegTree(i64 size) {
        Init(size);
    }

    void Init(i64 size) {
        N = 1;
        while (N < size) {
            N *= 2;
        }
        St.assign(N * 2, Zero);
    }

    void Set(i64 i, Type v, i64 x, i64 lx, i64 rx) {
        if (rx - lx == 1) {
            St[x] = v;
            return;
        }

        i64 m = (lx + rx) / 2;
        if (i < m) {
            Set(i, v, x * 2 + 1, lx, m);
        }
        else {
            Set(i, v, x * 2 + 2, m, rx);
        }

        St[x] = Combine(St[x * 2 + 1], St[x * 2 + 2]);
    }

    void Set(i64 i, Type v) {
        Set(i, v, 0, 0, N);
    }

    Type Calc(i64 l, i64 r, i64 x, i64 lx, i64 rx) {
        if (lx >= r || l >= rx) {
            return Zero;
        }

        if (l <= lx && rx <= r) {
            return St[x];
        }

        i64 m = (lx + rx) / 2;
        Type v1 = Calc(l, r, x * 2 + 1, lx, m);
        Type v2 = Calc(l, r, x * 2 + 2, m, rx);
        return Combine(v1, v2);
    }

    Type Calc(i64 l, i64 r) {
        return Calc(l, r, 0, 0, N);
    }
};

struct TDsu {
    vector<i64> Dsu;

    TDsu();

    TDsu(i64 size) {
        Init(size);
    }

    void Init(i64 size) {
        Dsu.resize(size);

        for (i64 i = 0; i < size; i++) {
            Dsu[i] = i;
        }
    }

    i64 FindSet(i64 v) {
        if (v == Dsu[v]) {
            return v;
        }
        return Dsu[v] = FindSet(Dsu[v]);
    }

    void UnionSets(i64 a, i64 b) {
        a = FindSet(a);
        b = FindSet(b);
        if (a != b) {
            Dsu[b] = a;
        }
    }
};


