    for (i64 i = 1; i <= n; i++) {
        z.push_back({ a[i], i });
    }

    TDsu dsu(n + 1);

    sort(z.begin(), z.end());

    set<pair<i64, i64>> q;
    for (auto e : z) {
        auto eit = q.insert({ e.first.second, e.second }).first;
        if (eit == q.begin()) {
            continue;
        }
        auto it = q.begin();
        it++;

        while (it != eit) {
            dsu.UnionSets(q.begin()->second, it->second);
            q.erase(it++);
        }

        dsu.UnionSets(q.begin()->second, eit->second);
        q.erase(eit++);
    }

    reverse(z.begin(), z.end());

