using namespace std;
const int N=200000;
int Root[N],Rank[N],Size[N];
int find(int x){
    if(Root[x]==x)return x;
    else return Root[x]=find(Root[x]);
}
void unite(int x,int y){
    int X=find(x);
    int Y=find(y);
    if(X==Y)return;
    if(Rank[X]<Rank[Y]){
        Root[X]=Y;
        Size[Y]+=Size[X];
    }
    else{
        Root[Y]=X;
        Size[X]+=Size[Y];
        if(Rank[X]==Rank[Y])Rank[X]++;
    }
    return;
}
int main(){
    int n;
    cin>>n;
    set<int>s;
    for(int i=0;i<n;i++)Root[i]=i,Rank[i]=0,Size[i]=1,s.insert(i);
    pair<int,int>point[n];
    int num[n],num_rev[n];
    for(int i=0;i<n;i++){
        int x,y;
        cin>>x>>y;
        point[i]={x-1,y-1};
        num[y-1]=i;
        num_rev[n-y]=i;
    }
    sort(point,point+n);
    vector<int>v(n);
    for(int i=0;i<n;i++)v[i]=point[i].second;
    int used[n]={};
    for(int i=0;i<n-1;i++){
        s.erase(v[i]);
        if(used[v[i]])continue;
        for(auto itr=s.upper_bound(v[i]);itr!=s.end();itr=s.erase(itr)){
            used[*itr]=1;
            unite(num[v[i]],num[*itr]);
        }
    }
    reverse(v.begin(),v.end());
    for(int i=0;i<n;i++)v[i]=n-v[i]-1,used[i]=0,s.insert(i);
    for(int i=0;i<n-1;i++){
        s.erase(v[i]);
        if(used[v[i]])continue;
        for(auto itr=s.upper_bound(v[i]);itr!=s.end();itr=s.erase(itr)){
            used[*itr]=1;
            unite(num_rev[v[i]],num_rev[*itr]);
        }
    }
    for(int i=0;i<n;i++)cout<<Size[find(i)]<<endl;
    return 0;
}

