int getCities(int id, vector<pair<int, int> > &arr, map<int, int> &mmap)
{
	if(mmap.count(id))
	{
		return mmap[id];
	}

	int n = arr.size();

	for(int i = 0; i < n; i++)
	{
		if((arr[i].first < arr[id].first && arr[i].second < arr[id].second) || (arr[i].first > arr[id].first && arr[i].second > arr[id].second))
