        auto itr=st.begin();
        while(itr!=st.end()){
            auto [mi,ind]=*itr;
            if(mi>y) break;
            uf.unite(i,ind);
            if(chmin(ne.fi,mi)){
                ne.se=ind;
            }
            itr=st.erase(itr);
        }
        st.insert(ne);
    }
    vector<int> ans(n);
