class UnionFindTree {
private:
    vector<int> parent;
    vector<int> count;
    vector<set<int>> group;

public:
    UnionFindTree(int n)
        : parent(n), count(n, 1), group(n) {
        set<int> all;
        for (int i = 0; i < n; i++) all.insert(i);
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            group[i] = all;
            group[i].erase(i);
        }
    }
    int get_root(const int x) {
        if (parent[x] == x) return x;
        return parent[x] = get_root(parent[x]);
    }
    void unite(const int x, const int y) {
        int rx = get_root(x), ry = get_root(y);
        if (rx == ry) return;
        parent[rx] = ry;
        count[ry] += count[rx];
        count[rx] = 0;
        for (auto& elm : group[rx]) group[ry].erase(elm);
        group[ry].erase(rx), group[ry].erase(ry);
    }
    bool is_same_root(const int x, const int y) {
        return get_root(x) == get_root(y);
    }
    int get_size(const int x) { return count[get_root(x)]; }
    set<int> get_group(const int x) {
        return group[get_root(x)];
    }
    void print() {
        for (auto elm : parent) cout << elm << " ";
        cout << endl;
        for (auto elm : count) cout << elm << " ";
        cout << endl;
    }
};
int main() {
    int n;
    cin >> n;
    vector<pair<int, int>> p(n), x(n), y(n);
    UnionFindTree tree(n);
    for (auto i = 0; i < n; i++) {
        cin >> p[i].first >> p[i].second;
        x[i] = {p[i].first, i}, y[i] = {p[i].second, i};
    }
    sort(x.begin(), x.end());
    sort(y.begin(), y.end());
    for (auto i = 0; i < n; i++) {
        auto group = tree.get_group(i);
        for (auto& elm : group) {
            if ((p[i].first < p[elm].first and
                 p[i].second < p[elm].second) or
                (p[i].first > p[elm].first and
                 p[i].second > p[elm].second))
                tree.unite(i, elm);
        }
    }
    for (auto i = 0; i < n; i++)
        cout << tree.get_size(i) << endl;
    return 0;
}

