// Complexity: O(logN)
template <typename T>
struct BinaryIndexedTree {
    int sz;
    vector<T> data;
    BinaryIndexedTree(int sz) : sz(sz), data(sz + 1) {}
    T sum(int k) {
        // [0, k]
        T res = 0;
        for (k++; k > 0; k -= k & -k) res += data[k];
        return res;
    }
    T sum(int l, int r) {
        // [l, r)
        return sum(r - 1) - sum(l - 1);
    }
    void add(int k, T x) {
        for (k++; k <= sz; k += k & -k) data[k] += x;
    }
    // sum(a1, ... , ax)>=wを満たす最小のx(0-indexed)
    // assert(all ai is non-negative)
    int lower_bound(T w) {
        if (w <= 0) return 0;
        int x = 0;
        int k = 1;
        while ((k << 1) <= sz) k <<= 1;
        for (; k > 0; k >>= 1) {
            if (x + k <= sz && data[x + k] < w) {
                w -= data[x + k];
                x += k;
            }
        }
        return x;
    }
};
