    while(true)
    {
        pii mv=sgt.query(0,x).first;
        if(mv.first>=h[x]) break;
        sgt.erase(mv.second);
        dsu.merge(mv.second,x);
        dfs(mv.second);
    }
    while(true)
    {
        pii mv=sgt.query(x+1,n).second;
        if(mv.first<=h[x]) break;
        sgt.erase(mv.second);
        dsu.merge(mv.second,x);
        dfs(mv.second);
    }
}

