        while (itr != ylist.end()) {
            int j = itr->second;
            uf.unite(i, j);
            s.insert(j);
            itr++;
        }
    }
    map<int, int> m;
    rep(i, N) m[uf.par[i]]++;
    rep(i, N) cout << m[uf.par[i]] << endl;
}

