		{
			up[i]=i;
		}
	}
	void grp(int a, int b)
	{
		int ap=getp(a);
		int bp=getp(b);
		if(ap==bp) return;
		if(un[ap]<un[bp])
		{
			swap(a, b);
			swap(ap, bp);
		}
		un[ap]+=un[bp];
		un[bp]=0;
		up[bp]=ap;
	}
	int getp(int idx)
	{
		int p=up[idx];
		if(idx==p) return p;
		return up[idx]=getp(p);
	}
	int get(int idx)
	{
		return un[getp(idx)];
	}
};


