struct dsu {
    vector<int> dsu{};

    void build(int k) {
        dsu.resize(k+1);
        range(i, k + 1) dsu[i] = i;
    }

    int get_dsu(int a) {
        if (dsu[a] == a) return a;
        return dsu[a] = get_dsu(dsu[a]);
    }

    void unio(int a, int b) {
        a = get_dsu(a), b = get_dsu(b);
        if (rand() % 2) swap(a, b);
        dsu[a] = b;
    }
};

