struct UnionFind {
    vector<int> par; // par[i]:iの親の番号　(例) par[3] = 2 : 3の親が2
    vector<int> cnt;

    UnionFind(int N) : par(N), cnt(N) { //最初は全てが根であるとして初期化
        for(int i = 0; i < N; i++) {
        par[i] = i;
        cnt[i] = 1;  
        }
    }

    int root(int x) { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    int count(int x) { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
        return cnt[root(x)];
    }

    void unite(int x, int y) { // xとyの木を併合
        int rx = root(x); //xの根をrx
        int ry = root(y); //yの根をry
        if (rx == ry) return; //xとyの根が同じ(=同じ木にある)時はそのまま
        par[rx] = ry; //xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
        cnt[ry] = cnt[ry] + cnt[rx];
    }

    bool same(int x, int y) { // 2つのデータx, yが属する木が同じならtrueを返す
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
};

int main() {
    int N;
    cin >> N;

    UnionFind tree(N);

    int x[N], y[N];
    for(int i = 0; i < N; i++) {
        cin >> x[i] >> y[i];
    }

    for(int i = 0; i < N; i++){
      for(int j = 0; j < N; j++){
        if((x[i] < x[j] && y[i] < y[j]) || (x[i] > x[j] && y[i] > y[j])){
          tree.unite(i, j); // iの木とjの木を併合する
        }
      }
    }

    for(int i = 0; i < N; i++){
      cout << tree.count(i) << endl;
    }
    return 0;
}

