typedef long long ll;
class UnionFindTree
{
private:
   int N;
   int *rootnum;
   int *rank;
   int *unionnum;

public:
   UnionFindTree(int n)
   {
      /*0からn-1までの要素をunionとしてもつ*/
      N = n;
      rootnum = new int[N];
      rank = new int[N];
      unionnum = new int[N];
      for (int i = 0; i < N; i++)
      {
         rootnum[i] = i;
         rank[i] = 0;
         unionnum[i] = 1;
      }
   }

   int Find(int j)
   {
      if (rootnum[j] == j)
      {
         return j;
      }
      else
      {
         return rootnum[j] = Find(rootnum[j]);
      }
   }

   void Union(int i, int j)
   {
      int x = Find(i);
      int y = Find(j);
      if (x == y)
         return;
      N--;
      if (rank[x] < rank[y])
      {
         rootnum[y] = x;
         unionnum[x] += unionnum[y];
      }
      else
      {
         rootnum[x] = y;
         unionnum[y] += unionnum[x];
         if (rank[x] == rank[y])
            rank[x]++;
      }
   }

   int Num(int j)
   {
      /*与えられた要素の入っている集合の要素数を答える*/
      int x = Find(j);
      return unionnum[x];
   }

   int UnionNum()
   {
      /*集合の数を答える*/
      return N;
   }

   ~UnionFindTree()
   {
      delete rootnum;
      delete rank;
      delete unionnum;
   }
};

int main()
{
   int N;
   cin >> N;
   vector<pair<pair<int, int>, int>> point(N);
   for (int i = 0; i < N; i++)
   {
      cin >> point[i].first.first >> point[i].first.second;
      point[i].second = i;
   }
   sort(point.begin(), point.end());
   UnionFindTree uft(N);
   set<pair<int, int>> ys;
   for (int i = 0; i < N; i++)
   {
      int x = point[i].first.first;
      int y = point[i].first.second;
      int id = point[i].second;
      for (auto it = ys.begin(); it != ys.lower_bound(make_pair(y, id));)
      {
         uft.Union((*it).second, id);
         if (it == ys.begin())
            it++;
         else
            it = ys.erase(it);
      }
      ys.insert(make_pair(y, id));
   }
   for (int i = 0; i < N; i++)
   {
      cout << uft.Num(i) << endl;
   }
