  rep( i, N )
    ps.emplace_back( x[i], y[i], i );

  std::sort(all(ps));

  std::set<P> prs;

  rep( i, N ) {
    auto [px, py, pi] = ps[i];

    auto bound = prs.lower_bound( P( -py, -INF ) );

    for( auto it = bound; it != prs.end(); ++it ) {
      uf.unite( it->second, pi );
    }

    prs.emplace( -py, pi );
  }

  return;
}

