        get(0, 0, n, 0, rr, 0, vv[i].Y - 1);
        mnans = min(mn, vv[i].Y);
        mx = -1e9;
        get(0, 0, n, ll, n, vv[i].Y + 1, n + 1);
        mxans = max(mx, vv[i].Y);
        ans = get(0, 0, n, mm[mnans] - 1, n, mnans, n + 1) + get(0, 0, n, 0, mm[mxans], 0, mxans);
        if (mnans <= mxans)
            ans -= get(0, 0, n, mm[mnans] - 1, mm[mxans], mnans, mxans);
        cout << ans << '\n';
    }
}

