}arr[N];
bool cmpx(info a , info b)
{
    return a.x<b.x;
}

bool cmpy(info a , info b)
{
    return a.y<b.y;
}

int trr[N<<2] , par[N] , idx[N] , idy[N] , cnt[N];

void update(int idx , int b , int e , int i , int x)
{
    if(i<b || i>e) return;
    if(b == e){
        trr[idx] = x;
        return;
    }

    int mid = (b+e)>>1;
    update(LEF,b,mid,i,x);
    update(RIG,mid+1,e,i,x);
    trr[idx] = max(trr[LEF],trr[RIG]);
}

int get(int idx , int b , int e , int i , int j )
{
    if(j<b || e<i || i>j) return 0;
    if(i<=b && j>=e) return trr[idx];
    int mid = (b+e)>>1;
    return max(get(LEF,b,mid,i,j),get(RIG,mid+1,e,i,j));
}

int findpar(int a)
{
    if(a == par[a]) return a;
    return par[a] = findpar(par[a]);
}

void connect(int a , int b)
{
    if(findpar(a) != findpar(b)){
        a = findpar(a);
        b = findpar(b);
        cnt[a] += cnt[b];
        par[b] = a;
    }
}

