int fin(int v) 
{
    if (v == par[v])    return v;
    return par[v] = fin(par[v]);
}
//union by size
void make_set(int v) {
    par[v] = v;
    sz[v] = 1;
}

void uni(int a, int b) 
{
    a = fin(a);
    b = fin(b);
    if(a == b) return;
    if(sz[a] < sz[b]) swap(a, b);
    par[b] = a;
    sz[a] += sz[b];
}

