	int cur=1;
	while(!s.empty())
	{
		auto it=s.find(pos[cur]);
		if(it==s.end())
		{
			cur++;
			continue;
		}
		auto it2 = s.upper_bound(*it);
		if(it2!=s.end())
		{
			uni(ind[cur],ind[inv[*it2]]);
		}
		s.erase(it);
		cur++;
	}
	for(int i=1;i<=n;i++) cout<<sz[fin(i)]<<'\n';
}

