const int N=200005;
int n,a[N],id[N],ans[N];
struct UnionFind
{
	int parent[N],rnk[N];
	int init(int n)
	{
		for(int i=1;i<=n;i++)
			parent[i]=i,rnk[i]=1;
	}
	int root(int x)
	{
		if(parent[x]!=x)
			parent[x]=root(parent[x]);
		return parent[x];
	}
	int connect(int x,int y)
	{
		int rx=root(x),ry=root(y);
		if(rx==ry)
			return 0;
		if(rnk[rx]>rnk[ry])
		{
			parent[ry]=rx;
			rnk[rx]+=rnk[ry];
		}
		else
		{
			parent[rx]=ry;
			rnk[ry]+=rnk[rx];
		}
		return 1;
	}
}uf;
set<int>s;
