	}
	uf.init(n);
	for(int i=1;i<=n;i++)
	{
		auto it=s.lower_bound(a[i]);
		if(i!=1&&it!=s.begin())
		{
			it--;
			uf.connect(a[i],*it);
		}
		s.insert(a[i]);
	}
	s.clear();
	uf.init(n);
	for(int i=n;i>=1;i--)
	{
		auto it=s.lower_bound(a[i]);
		if(i!=n&&it!=s.end())
		{
			uf.connect(a[i],*it);
		}
		s.insert(a[i]);
