/**
 * @brief Union-Find
 * @docs docs/union-find.md
 */
struct UnionFind {
  vector< int > data;

  UnionFind() = default;

  explicit UnionFind(size_t sz) : data(sz, -1) {}

  bool unite(int x, int y) {
    x = find(x), y = find(y);
    if(x == y) return false;
    if(data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    data[y] = x;
    return true;
  }

  int find(int k) {
    if(data[k] < 0) return (k);
    return data[k] = find(data[k]);
  }

  int size(int k) {
    return -data[find(k)];
  }

  bool same(int x, int y) {
    return find(x) == find(y);
  }
};


int main() {
  int N;
  cin >> N;
  vector< int > id(N), Y(N);
  for(int i = 0; i < N; i++) {
    int x, y;
    cin >> x >> y;
    --x, --y;
    id[x] = i;
    Y[x] = y;
  }
  UnionFind uf(N);
  set< pair< int, int > > st;
  for(int i = N - 1; i >= 0; i--) {
    auto it = st.lower_bound(make_pair(Y[i], id[i]));
    pair< int, int > last(Y[i], id[i]);
    while(it != end(st)) {
      uf.unite(it->second, id[i]);
      last = *it;
      it = st.erase(it);
    }
    st.emplace(last);
  }
  for(int i = 0; i < N; i++) {
    cout << uf.size(i) << "\n";
  }
}

