//以下、素集合と木は同じものを表す
class UnionFind {
public:
    vector<ll> parent; //parent[i]はiの親
    vector<ll> siz; //素集合のサイズを表す配列(1で初期化)
    map<ll,vector<ll>> group;//素集合ごとに管理する連想配列(keyはそれぞれの素集合の親、valueはその素集合の要素の配列)

    //コンストラクタ
    UnionFind(ll n):parent(n),siz(n,1){ 
        //全ての要素の根が自身であるとして初期化
        for(ll i=0;i<n;i++){parent[i]=i;}
    }

    //データxの属する木の根を取得(経路圧縮も行う)
    ll root(ll x){
        if(parent[x]==x) return x;
        return parent[x]=root(parent[x]);//代入式の値は代入した変数の値なので、経路圧縮できる
    }

    //xとyの木を併合
    void unite(ll x,ll y){
        ll rx=root(x);//xの根
        ll ry=root(y);//yの根
        if(rx==ry) return;//同じ木にある時
        //小さい集合を大きい集合へと併合(ry→rxへ併合)
        if(siz[rx]<siz[ry]) swap(rx,ry);
        siz[rx]+=siz[ry];
        parent[ry]=rx;//xとyが同じ木にない時はyの根ryをxの根rxにつける
    }

    //xとyが属する木が同じかを判定
    bool same(ll x,ll y){
        ll rx=root(x);
        ll ry=root(y);
        return rx==ry;
    }

    //xの素集合のサイズを取得
    ll size(ll x){
        return siz[root(x)];
    }

    //素集合をそれぞれグループ化
    void grouping(ll n){
        //経路圧縮を先に行う
        REP(i,n)root(i);
        //mapで管理する(デフォルト構築を利用)
        REP(i,n)group[parent[i]].PB(i);
    }
};

signed main(){
    //入力の高速化用のコード
    //ios::sync_with_stdio(false);
    //cin.tie(nullptr);
    ll n;cin>>n;
    vector<ll> ind(n,0);
    vector<ll> checky(n,0);
    vector<ll> checkx(n,0);
    UnionFind uf(n);
    REP(i,n){
        ll x,y;cin>>x>>y;
        checky[x-1]=y-1;
        checkx[y-1]=x-1;
        ind[x-1]=i;
    }
    //checkyの中からそれより小さいものを探す(探す順番は値の順番)
    //値の順番なので、それ以降の省略ができる
    REPD(i,n){
        ll j=checkx[i];
        while(true){
            j--;
            if(j<0)break;
            if(i>checky[j]){
                if(uf.same(ind[checkx[i]],ind[j])){
                    break;
                }else{
                    uf.unite(ind[checkx[i]],ind[j]);
                }
            }
        }
    }
    uf.grouping(n);
    REP(i,n){
        cout<<uf.size(i)<<endl;
    }
}

