int fnd(int a) {
  return a == dsu[a] ? a : dsu[a] = fnd(dsu[a]);
}

void Union(int a, int b) {
  if (fnd(a) == fnd(b)) return;
  sze[fnd(b)] += sze[fnd(a)];
  dsu[fnd(a)] = fnd(b);
}

