class unionfind {
    VI par, rank;
    int forest_num;
public:
    unionfind(const int& n) : par(n), rank(n, 1), forest_num(n) {
        FOR(i, 0, n)par[i] = i;
    }
    int root(int x) {
        if (par[x] == x)return x;
        return par[x] = root(par[x]);
    }
    int size(int x) {
        if (par[x] == x)return rank[x];
        return size(par[x]);
    }
    void unite(int x, int y) {
        int rx = root(x), ry = root(y);
        if (rx == ry)return;
        if (rank[rx] < rank[ry]) {
            par[rx] = ry;
            rank[ry] += rank[rx];
        }
        else {
            par[ry] = rx;
            rank[rx] += rank[ry];
        }
        --forest_num;
    }
    bool same(int x, int y) { return root(x) == root(y); }
    int fnum() { return forest_num; }
};

int main() {
    init();

    int n; cin >> n;
    vector<pair<int, int>> xy(n); cin >> xy;
    VI a(n);
    FOR(i, 0, n)a[i] = i;
    fSORT(a, [&](int s, int t) { return xy[s].first < xy[t].first; });
    unionfind uf(n);
    set<pair<int, int>> se;
    for (int i : a) {
        bool f = false;
        for (; !se.empty() && se.begin()->first < xy[i].second;) {
            uf.unite(i, se.begin()->second);
            if (f)se.erase(se.begin());
            else f = true;
        }
        if (!f)se.emplace(xy[i].second, i);
    }
    FOR(i, 0, n)print(uf.size(i));

    return 0;
}

