using namespace std;

struct UnionFind{
    vector<int> par;//親のid

    UnionFind(int N) : par(N) { //最初は全てが根であるとして初期化
        for(int i = 0; i < N; i++) par[i] = i;
    }

    int root(int x){// データxが属する木の根を再帰で得る：root(x) = {xの木の根}
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    bool unite(int x, int y){// xとyの木を併合
        int rx = root(x);//xの根
        int ry = root(y);//yの根
        if (rx == ry) return false; //xとyの根が同じ(=同じ木にある)時はそのまま
        par[rx] = ry; //xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
        return true;
    }

    bool same(int x, int y){// 2つのデータx, yが属する木が同じならtrueを返す
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
};

int main()
{
    int N;
    cin >> N;

    UnionFind UF(N);

    int town[N][N];
    for (int i = 0; i < N; i++)
    {
        cin >> town[i][0] >> town[i][1];
    }

    for(int i = 0; i < N; i++){
        for(int j = i + 1; j < N; j++){
            if((town[i][0] - town[j][0])*(town[i][1] - town[j][1]) > 0){
                UF.unite(i,j);
            }
        }
    }

    for (int i = 0; i < N; i++){
        int res = 0;
        for(int j = 0; j < N; j++){
            if(UF.same(i,j)) res += 1;
        }
        cout << res << endl;
    }

    return 0;
}

