struct UF{
  vi sz, p;
  int comps;

  UF(int s) : comps(s) {
    sz.resize(comps + 1);
    p.resize(comps + 1);
    init();
  }

  void init(){
    for(int i = 0; i <= comps; i++){
      sz[i] = 1;
      p[i] = i;
    }
  }

  int fset(int u){
    return u == p[u] ? u : p[u] = fset(p[u]);
  }

  bool connect(int u, int v){
    u = fset(u);
    v = fset(v);
    if(u != v){
      if(sz[v] > sz[u]){
        swap(u, v);
      }
      sz[u] += sz[v];
      p[v] = u;
      comps--;
      return true;
    }
    return false;
  }
};

