class UnionFind {
private:
	std::vector<int> par;
	std::vector<int> siz;

public:
	UnionFind(int sz_) : par(sz_), siz(sz_, 1) {
		for (int i = 0; i < sz_; ++i) par[i] = i;
	}
	void init(int sz_) {
		par.resize(sz_);
		siz.resize(sz_, 1);
		for (int i = 0; i < sz_; ++i) par[i] = i;
	}
	int find(int x) {
		while (par[x] != x) x = par[x] = par[par[x]];
		return x;
	}
	void unite(int x, int y) {
		x = find(x);
		y = find(y);
		if (x == y) return;
		if (siz[x] < siz[y]) std::swap(x, y);
		siz[x] += siz[y];
		par[y] = x;
	}
	bool same(int x, int y) {
		return find(x) == find(y);
	}
	int size(int x) {
		return siz[find(x)];
	}
};

signed main() {
	INIT;

	VAR(int, n);
	VEC_ROW(int, n, a, b);

	UnionFind uf(n);
	V<int> o(n);
	std::iota(ALL(o), 0);
	std::sort(ALL(o), [&](int l, int r) { return a[l] < a[r]; });

	std::stack<PAIR> st;
	REP(i_, n) {
		int i = o[i_];
		if (st.empty() || st.top().first > b[i]) {
			st.emplace(b[i], i);
		}
		else {
			PAIR mi = st.top();
			while (!st.empty() && st.top().first < b[i]) {
				uf.unite(st.top().second, i);
				st.pop();
			}
			st.emplace(mi);
		}
	}
	REP(i, n) {
		OUT(uf.size(i))BR;
	}

	return 0;
}

