	vector<int> p;
public:
	union_find(int n):n(n),p(n,-1){}
	int find(int u){ return p[u]<0?u:p[u]=find(p[u]); }
	void unite(int u,int v){
		u=find(u); v=find(v);
		if(u!=v){
			if(p[v]<p[u]) swap(u,v);
			p[u]+=p[v]; p[v]=u; n--;
		}
	}
	bool is_same(int u,int v){ return find(u)==find(v); }
	int size()const{ return n; }
	int size(int u){ return -p[find(u)]; }
};

int main(){
	int n; scanf("%d",&n);
	vector<int> x(n),y(n);
	rep(i,n) scanf("%d%d",&x[i],&y[i]), x[i]--, y[i]--;

	vector<int> p(n);
	iota(p.begin(),p.end(),0);
	sort(p.begin(),p.end(),[&](int i,int j){
		return x[i]<x[j];
	});

	union_find U(n);
	map<int,int> L,R;
	for(int i:p){
		auto it=L.lower_bound(y[i]);
		if(it!=L.begin()){
			--it;
			U.unite(i,it->second);
		}
		L[y[i]]=i;
	}
	reverse(p.begin(),p.end());
	for(int i:p){
		auto it=R.lower_bound(y[i]);
		if(it!=R.end()){
			U.unite(i,it->second);
		}
		R[y[i]]=i;
	}

	rep(i,n) printf("%d\n",U.size(i));

	return 0;
}

