struct UnionFind{
  vector<int> data;
  int __size;
  UnionFind(int sz) {
  data.assign(sz, -1);
  __size = sz;
  }

  bool unite(int x, int y) {
    x = find(x), y = find(y);
    if(x == y) return (false);
    if(data[x] > data[y]) swap(x, y);//親は負でサイズを保存
    __size--;
    data[x] += data[y];
    data[y] = x;
    return (true);
  }

  int find(int k) {
    if(data[k] < 0) return (k);
    return (data[k] = find(data[k]));
  }

  bool same(int x, int y){
    return find(x) == find(y);
  }

  int size(int k) {
    return (-data[find(k)]);
  }

  int union_count() {
    return (__size);
  }
};
int main() {
  int n;
  cin >> n;
  UnionFind uf(n);
  vector<P> p;
  vector<int> idx(n, -1), idy(n, -1);
  rep(i,n) {
    int x, y;
    cin >> x >> y;
    x--; y--;
    idx[x] = idy[y] = i;
    p.emplace_back(make_pair(x, y));
  }
  sort(p.begin(), p.end());
  vector<int> ok(n, 0);
  for (int i = 0; i < n; i++) {
    int j = p[i].second;
    int u = idy[j];
    while ((j < n) && !ok[j]) {
      uf.unite(u, idy[j]);
      j++;
      //cout << p[i].second << " " << j << endl;
    }
    ok[p[i].second] = 1;
  }
  rep(i,n) ok[i] = 0;

  for (int i = n - 1; i >= 0; i--) {
    int j = p[i].second;
    int u = idy[j];
    while ((j >= 0 && !ok[j])) {
      uf.unite(u, idy[j]);
      j--;
    }
    ok[p[i].second] = 1;
  }

  rep(i,n) {
    cout << uf.size(i) << endl;
  }
  return 0; 
}

