	{
		return x < b.x;
	}
} c[maxn];

int n;

int f[maxn];

int lowbit(int x)
{
	return x & - x;
}

void update(int x)
{
	for (int i = x; i < maxn; i += lowbit(i))
	{
		f[i]++;
	}
}

int query(int x)
{
	int ret = 0;
	for (int i = x; i; i -=lowbit(i))
	{
		ret += f[i];
	}
	return ret;
}

int ans[maxn], put[maxn];

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(0);
