	{
		//cout << c[i].x << " " << c[i].y << " " << c[i].num << endl;
		ans[i] = query(c[i].y - 1);
		if (c[i].x != c[i + 1].x)
		{
			for (int j = i; c[j].x == c[i].x; j--)
			{
				update(c[j].y);
			}
		}
	}
	memset(f, 0, sizeof(f));
