vector<ll>counts(200001,-1);

void BFS(vector<ll>arr[], ll size, ll start){
  queue<ll>q;
  vector<bool>visited(size, false);
  visited[start] = true;
  vector<ll> v;
  v.push_back(start);
  ll count = 1;
  q.push(start);
  while(!q.empty()){
    ll d= q.front();
    q.pop();
    for(auto i = arr[d].begin(); i != arr[d].end(); i++){
      ll x = *i;
      if(!visited[x]){
        q.push(x);
        visited[x] = true;
        count++;
        v.push_back(x);
      }
    }
  }
  for(int i = 0; i < v.size(); i++){
    counts[v[i]] = count;
  }
}
