struct BIT
{
    int tree[maxn];

    void Reset()
    {
        memset(tree, 0, sizeof(tree));
    }

    void Update1(int x, int val)
    {
        for (; x <= n; x += x & -x)
            tree[x] += val;
    }

    void Update2(int x, int val)
    {
        for (; x; x -= x & -x)
            tree[x] += val;
    }

    int Get1(int x)
    {
        int res = 0;
        for (; x; x -= x & -x)
            res += tree[x];
        return res;
    }

    int Get2(int x)
    {
        int res = 0;
        for (; x <= n; x += x & -x)
            res += tree[x];
        return res;
    }
}T[2];

