void solve(){
	int n;
	rd(n);
	vector<pint>a;
	map<pint,int>loc;
	FOR(i,n){
		int l,r;
		rd(l,r);
		a.pb({l,r});
		loc[{l,r}]=i;
	}	
	sort(all(a));
	unordered_map<int,int>f;
	map<int,int>A;
	f[n-1]=n-1;
	A[n-1]=1;
	int mv=a[n-1].se;
	int mi=n-1;
	for(int i=n-2;i>=0;i--){
		if(a[i].se<mv){
			f[i]=mi;
		}
		else{
			f[i]=i;
			mv=a[i].se;
			mi=i;
		}
		A[f[i]]++;
	}
	//Second part
	unordered_map<int,int>f2;
	map<int,int>A2;
	f2[0]=0;
	A2[0]=1;
	 mv=a[0].se;
	 mi=0;
	for(int i=1;i<n;i++){
		if(a[i].se>mv){
			f2[i]=mi;
		}
		else{
			f2[i]=i;
			mv=a[i].se;
			mi=i;
		}
		A2[f2[i]]++;
	}
	vector<int>Ans(n);
	for(int i=0;i<n;i++){
		Ans[loc[a[i]]]=max({1LL,A[f[i]],A2[f2[i]]});
	}
	for(auto v:Ans)pp(v);
	return;	
}


