struct segtree{//maxをとるseg木
    int n;
    int size;
    vector<ll> seg;
    segtree(const int n_): n(1<<20) , size(n_) , seg(1<<21 , 0){};
    ll get(int l,int r){//[l,r)
        return get_sub(l,r,0,0,n);
    }
    ll get_sub(int l,int r,int k,int a,int b){//[l,r)での答えがほしい いま[a,b)を見ている kは[a,b)を持っているところ(vector segのindex)
        if(l>=b || r<=a)return 0;//完全に外にいるときは小さいのを返しておけばよい
        if(l<=a && b<=r)return seg[k];//完全に中にいるときはそのまま返せばよい
        //子供をたどる
        return max(get_sub(l,r,2*k+1,a,(a+b)/2) , get_sub(l,r,2*k+2,(a+b)/2,b));
    }
    void change(int i,ll x){//0_indexedでi番めをxに変える
        i+=n-1;
        seg[i]=x;
        while(i>0){
            i=(i-1)/2;
            ll t=seg[i];
            seg[i]=max(seg[2*i+1],seg[2*i+2]);
            if(t==seg[i])break;
        }
        return;
    }
    void add(int i,ll x){//i番めにxを加算
        i+=n-1;
        seg[i]+=x;
        while(i>0){
            i=(i-1)/2;
            ll t=seg[i];
            seg[i]=max(seg[2*i+1],seg[2*i+2]);
            if(t==seg[i])break;
        }
        return;
    }
    int lower_bound(int i,int v){//v以上の値を持つindexをreturnする
        return lower_bound_sub(i,size,0,0,n,v);
    }
    int lower_bound_sub(int l,int r,int k,int a,int b,ll v){//[l,r)においてv以上の値を持つ最小のindexを返すのが目標 今[a,b)を持つようなseg[k]を見ている
        if(r<=a||l>=b)return size;
        if(seg[k]<v)return size;
        if(k>=n-1)return k-n+1;
        int res;
        res=lower_bound_sub(l,r,2*k+1 , a,(a+b)/2,v);
        if(res!=size)return res;
        else return lower_bound_sub(l,r,2*k+2,(a+b)/2,b,v);
    }
};
struct unionfind{
    vector<int> par;
    vector<int> high;
    vector<int> size;
    int num;
    unionfind(int n): par(n,-1), high(n,1), size(n,1),num(n){}
    int find(const int x){
        if(par[x]==-1)return x;
        return par[x]=find(par[x]);
    }
    void unite(int x,int y){
        x=find(x);
        y=find(y);
        if(x==y)return;
        if(high[x]>high[y])swap(x,y);
        if(high[x]==high[y])high[y]++;
        par[x]=y;
        size[y]+=size[x];
        num--;
        return;
    }
    int getsize(const int i){
        return size[find(i)];
    }
    void get(const int m){
        rep(i,m){
            int a,b;cin >> a >> b;
            unite(a-1,b-1);
        }
        return;
    }
};

int main(){
    ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    cout << fixed << setprecision(10);
    /*--------------------------------*/

    int n;cin >> n;
    vector<pair<pair<int,int>,int>> x(n);
    rep(i,n){
        cin >> x[i].first.first >> x[i].first.second;x[i].first.first--;x[i].first.second--;
        x[i].second=i;
    }
    sort(all(x));
    segtree seg(n);
    rep(i,n){
        seg.change(i,x[i].first.second);
    }
    unionfind uf(n);
    rep(i,n){
        if(seg.lower_bound(i+1,x[i].first.second)==n)continue;
        uf.unite(i,seg.lower_bound(i+1,x[i].first.second));
    }

    reverse(all(x));
    rep(i,n)x[i].first.second=n-x[i].first.second;
    segtree se(n);
    rep(i,n){
        se.change(i,x[i].first.second);
    }
    rep(i,n){
        //cout << n-se.lower_bound(i+1,x[i].first.second)-1 << ' ' << n-1-i << endl;
        if(se.lower_bound(i+1,x[i].first.second)==n)continue;
        uf.unite(n-1-i,n-se.lower_bound(i+1,x[i].first.second)-1);
    }

    vector<int> ans(n);
    reverse(all(x));
    rep(i,n)ans[x[i].second]=uf.getsize(i);
    rep(i,n)cout << ans[i] << endl;
}

