    sort(all(P), [](p a, p b) { return a.x < b.x; });

    UF uf(N);
    auto comp = [](p a, p b) { return a.y < b.y; };
    set<p, decltype(comp)> st{comp};

    st.emplace(P[0]);

    repe(i, 1, N){
        auto [x, y, id] = P[i];
        bool merged = false;

        for (auto it = st.begin(); it != st.lower_bound(P[i]); ){
            auto [tx, ty, tid] = *it;
            uf.unite(id, tid);
            if (merged)
                it = st.erase(it);
            else
                it++;
            merged = true;
        }
        if (!merged) st.emplace(P[i]);
    }

    rep(i, N) cout << uf.size(i) << '\n';
}

