namespace Dsu{
	int f[maxn],sz[maxn];
	void init(){
		for(int i=1;i<=n;i++)
			f[i]=i,sz[i]=1;
	}
	int find(int x){
		return f[x]==x?x:f[x]=find(f[x]);
	}
	void merge(int x,int y){
		x=find(x);y=find(y);
		if(x==y)return;
		f[x]=y;
		sz[y]+=sz[x];
	}
}

