        h[i] = a[i].y.x, id[i] = a[i].y.y;
    pre[1] = h[1];
    for (int i = 2; i <= n; ++i)
        pre[i] = min (pre[i - 1], h[i]);
    for (int i = n; i >= 1; --i)
        suf[i] = max (suf[i + 1], h[i]);
    for (int i = 1; i <= n; ++i) {
        if (tp && h[st[tp].y] < h[i]) st[tp].y = i;
        else st[++tp] = {i, i};
        while (tp > 1 && h[st[tp].y] > h[st[tp - 1].x])
            --tp, st[tp].y = st[tp + 1].y;
        int mx = suf[i];
        int l = 1, r = tp, mid, qwq = 0;
        while (l <= r) {
            mid = l + r >> 1;
            if (h[st[mid].x] <= mx) r = mid - 1, qwq = mid;
            else l = mid + 1;
        }
        if (qwq) res[id[i]] += i - st[qwq].x + 1;
    } tp = 0;
    for (int i = n; i >= 1; --i) {
        if (tp && h[st[tp].x] > h[i]) st[tp].x = i;
