            --tp, st[tp].x = st[tp + 1].x;
        int mn = pre[i];
        int l = 1, r = tp, mid, qwq = 0;
        while (l <= r) {
            mid = l + r >> 1;
            if (h[st[mid].y] >= mn) r = mid - 1, qwq = mid;
            else l = mid + 1;
        }
        if (qwq) res[id[i]] += st[qwq].y - i;
    }
    for (int i = 1; i <= n; ++i) printf ("%d\n", res[i]);
    return 0;
}

