using namespace std;
using ll = long long;
class UnionFind {
public:
    vector <ll> par; 
    vector <ll> siz;
    UnionFind(ll sz_): par(sz_), siz(sz_, 1LL) {
        for (ll i = 0; i < sz_; ++i) par[i] = i;
    }
    void init(ll sz_) {
        par.resize(sz_);
        siz.assign(sz_, 1LL);
        for (ll i = 0; i < sz_; ++i) par[i] = i;
    }
    ll root(ll x) {
        while (par[x] != x) {
            x = par[x] = par[par[x]];
        }
        return x;
    }
    bool merge(ll x, ll y) {
        x = root(x);
        y = root(y);
        if (x == y) return false;
        if (x > y) swap(x, y);
        siz[x] += siz[y];
        par[y] = x;
        return true;
    }
    bool issame(ll x, ll y) {
        return root(x) == root(y);
    }
    ll size(ll x) {
        return siz[root(x)];
    }
};

int main(){
  std::cin.tie(0);
  std::ios::sync_with_stdio(false);

  int32_t N;
  cin >> N; 
  vector<vector<int32_t>> cities(N, vector<int32_t>(3, 0));
  for (int i = 0; i < N; i++) {
    cin >> cities[i][0] >> cities[i][1];
    cities[i][2] = i;
  }
  sort (cities.begin(), cities.end(), [](const vector<int32_t>& r, const vector<int>& l) {return r[0] < l[0];});

  UnionFind uf(N);
  int32_t ymin_idx = 0;
  int32_t ymin = cities[0][1];
  stack<int32_t> s;
  s.push(ymin_idx);
  for (int i = 1; i < N; i++) {
    int32_t y = cities[i][1];
    if (y < ymin) {
      ymin_idx = i;
      ymin = y;
      s.push(ymin_idx);
    } else {
      uf.merge(ymin_idx, i);
      while (!s.empty() && cities[s.top()][1] < y) {
        uf.merge(ymin_idx, s.top());
        s.pop();
      }
      s.push(ymin_idx);
    }
  }

  vector<int32_t> res(N, 0);
  for (int i = 0; i < N; i++) {
    res[cities[i][2]] = uf.size(i);
  }
  for (auto r : res) {
    cout << r << endl;
  }

  return 0;
}

