int Find(int u) {
	return (par[u] == -1 ? u : par[u] = Find(par[u]));
}

void Union(int u, int v) {
	u = Find(u); v = Find(v);
	if (u == v) 
		return;
	par[v] = u;
	sz[u] += sz[v];
}

