    sort(P, P + n);
    for (int i = 0; i < n; i++) {
    	while (!vec.empty() && P[i].y > P[vec.back()].y) {
    		Union(P[i].ind, P[vec.back()].ind);
    		vec.pop_back();
    	}
    	vec.push_back(i);
    }
    for (int i = 0; i < n; i++) {
    	cout << sz[Find(i)] << endl;
    }
    return 0;
}

