int t[maxn];
int t2[maxn*4];

void add(int i, int x){
  for(;i<maxn; i+=i&-i)
    t[i] += x;
}

int get(int i){
  int res = 0;
  for(;i>0;i-=i&-i)
    res += t[i];
  return res;
}

int cnt2[maxn*4];

void push(int v, int l, int r){
  if(cnt2[v]!=0){
    t2[v] += cnt2[v]*(r-l+1);
    if(l!=r){
      cnt2[v*2] += cnt2[v];
      cnt2[v*2+1] += cnt2[v];
    }
    cnt2[v] = 0;
  }
}

void add(int v, int l, int r, int ql, int qr, int k){
  push(v, l, r);
  if(ql<=l && r<=qr){
    cnt2[v] += k;
    push(v, l, r);
  } else if(l>qr || ql>r){
    return;
  } else{
    int mid = (l+r)/2;
    add(v*2, l, mid, ql, qr, k);
    add(v*2+1, mid+1, r, ql, qr, k);
    t2[v] = t2[v*2] + t2[v*2+1];
    push(v, l, r);
  }
}

int get(int v, int l, int r, int k){
  push(v, l, r);
  if(l==r){
    return t2[v];
  } else{
    int mid = (l+r)/2;
    int ans = 0;
    if(k<=mid)
      ans = get(v*2, l, mid, k);
    else
      ans = get(v*2+1, mid+1, r, k);
    t2[v] = t2[v*2] + t2[v*2+1];
    return ans;
  }
}

