p decs[MAX_N];
p ascs[MAX_N];
// initialize for n items
void init(int n){
  for(int i=0;i<n;i++){
    par[i] = i;
    ran[i] = 0;
    c_size[i] = 1;
  }
}

// get the root of the tree of x
int find(int x){
  if(par[x] == x){
    return x;
  }else{
    return par[x] = find(par[x]);
  }
}

// unite the sets of x and y
void unite(int x,int y){
  x = find(x);
  y = find(y);
  if(x == y)
    return;

  if(ran[x] < ran[y]){
    par[x] = y;
  } else {
    par[y] = x;
    if(ran[x] == ran[y])
      ran[x]++;
  }
  c_size[x] = c_size[x] + c_size[y];
  c_size[y] = c_size[x];
}

bool same(int x,int y){
  return find(x) == find(y);
}


int main(void){
  int N;
  vector<t> v;
  cin >> N;
  init(N);
  for(int i=0;i<N;i++){
    int x,y;
    cin >> x >> y;
    t tmp(x-1,y-1,i);
    v.push_back(tmp);
  }
  sort(v.begin(),v.end());
  decs[0] = make_pair(get<1>(v[0]),0);
  ascs[N-1] = make_pair(get<1>(v[N-1]),N-1);
  for(int i=1;i<N;i++){
    if(decs[i-1].first > get<1>(v[i])){
      decs[i] = make_pair(get<1>(v[i]),i);
    }else{
      decs[i] = decs[i-1];
    }
    if(ascs[N-i].first < get<1>(v[N-i-1])){
      ascs[N-i-1] = make_pair(get<1>(v[N-i-1]),N-i-1);
    }else{
      ascs[N-i-1] = ascs[N-i];
    }
  }

  for(int i=0;i<N;i++){
    if(get<1>(v[i]) > decs[i].first){
      unite(get<2>(v[i]),decs[i].second);
    }
    if(get<1>(v[i]) < ascs[i].first){
      unite(get<2>(v[i]),ascs[i].second);      
    }
  }

  for(int i=0;i<N;i++){
    cout << c_size[i] << endl;
  }


  return 0;
}

