        mp[y][x] = i;
    }

    set<P> y;
    auto f = [](const P &lhs, const P &rhs) { return lhs.second < rhs.second; };
    std::set<P, std::function<bool (const P&, const P&)>> x(f);
    for (auto &p : v) {
        y.emplace(p), x.emplace(p);
    }

    dsu d(N);
    auto xitr = x.rbegin();
    P maxY = P(0, 0);
    for (auto &p : y) {
        int yy = p.first, yx = p.second;

        if (p.first < maxY.first) {
            d.merge(mp[yy][yx], mp[maxY.first][maxY.second]);
        }

        while (p.second < xitr->second) {
            int xy = xitr->first, xx = xitr->second;
            if (p.first < xitr->first) {
                d.merge(mp[yy][yx], mp[xy][xx]);
            }
            if (maxY.first < xitr->first) {
                maxY = *xitr;
            }
            xitr++;
        }
    }

    rep(i, N) {
        cout << d.size(i) << endl;
    }
}

