struct node{
    pii a;
    pii b;

    void merge(node &n1,node &n2){
        this->a=min(n1.a,n2.a);
        this->b=max(n1.b,n2.b);
    }
};

template<typename node>
struct segtree{
  node t[4*N];
  int tl[4*N];
  int tr[4*N];
  node nul;
  void build(int v,int start,int end,vector<pii>&arr){
      tl[v]=start;
      tr[v]=end;
      if(start==end){
          t[v].a={arr[start].x,tl[v]};
          t[v].b={arr[start].x,tl[v]};
      }
      else{
          int m=(start+end)/2;
          build(2*v,start,m,arr);
          build(2*v+1,m+1,end,arr);
          t[v].merge(t[2*v],t[2*v+1]);
     }
  }
  pii query_min(int v,int l,int r){
  	if(r<tl[v] || tr[v]<l)return {1e18,0};
  	if(l<=tl[v] && tr[v]<=r){
  		return t[v].a;
  	}
  	pii a=query_min(2*v,l,r);
  	mins(a,query_min(2*v+1,l,r));
  	return a;

  };
  pii query_max(int v,int l,int r){
  	if(r<tl[v] || tr[v]<l)return {-1,-1};
  	if(l<=tl[v] && tr[v]<=r){
  		return t[v].b;
  	}
  	pii a=query_max(2*v,l,r);
  	maxs(a,query_max(2*v+1,l,r));
  	return a;

  };

};
segtree<node>seg;
int solve(){
 	int n;cin>>n;
 	vector<pii>vec(n+1);
 	rep(i,1,n+1){
 		int x,y;cin>>x>>y;
 		vec[x]={y,i};
 	}
 	seg.build(1,1,n,vec);
 	vector<int>ans(n+1);
 	function<int(int,int)>dfs=[&](int l,int r){
 		int mn=seg.query_min(1,l,r).x;
 		pii mx=seg.query_max(1,r+1,n);
 		if(mx.x<mn)return r;
 		return dfs(l,mx.y);
 	};
 	int i=1;
 	while(i<=n){
 		int j=dfs(i,i);
 		for(int k=i;k<=j;k++)ans[vec[k].y]=j-i+1;
 		i=j+1;
 	}
 	rep(i,1,n+1)cout<<ans[i]<<endl;
 return 0;
}
