  for (int i = 1; i < n; ++i) {
    if (xy[i].second < g.begin()->first) {
      //! new group
      g[xy[i].second] = i;
    } else {
      //! merge
      auto bg = g.begin();
      ds.merge(i, bg->second);
      auto ub = g.upper_bound(xy[i].second);
      for (auto it = g.begin(); it != ub; ++it) {
        ds.merge(i, it->second);
      }
      ++bg;
      g.erase(bg, ub);
    }
  }

  rep(i, n) {
    cout << ds.size(ix[i]) << '\n';
  }
  cout << endl;  

  return 0;
}

