    DSU dsu(n);
    for (auto point : points) {
        int min_y = point.first.second;
        while (st.size() && st.back().first.second < point.first.second) {
            dsu.union_set(point.second, st.back().second);
            inmin(min_y, st.back().first.second);
            st.pop_back();
        }
        point.first.second = min_y;
