        int max_y = point.first.second;
        while (st.size() && st.back().first.second > point.first.second) {
            dsu.union_set(point.second, st.back().second);
            inmax(max_y, st.back().first.second);
            st.pop_back();
        }
        point.first.second = max_y;
        st.push_back(point);
    }

