        rank.resize(n);
        dat.assign(n, e);
        for(int i = 0; i < n; i++){
            par[i] = i;
            rank[i] = 0;
        }
    }

    int find(int i){
        if(i == par[i]) return i;
        return par[i] = find(par[i]);
    }

    bool same(int i, int j){
        return find(i) == find(j);
    }

    void unite(int i, int j){
        if(same(i, j)) return;
        i = find(i), j = find(j);
        if(rank[i] < rank[j]){
            par[i] = j;
            dat[j] = f(dat[i], dat[j]);
        }
        else{
            par[j] = i;
            dat[i] = f(dat[i], dat[j]);
            if(rank[i] == rank[j]) rank[i]++;
        }
    }

    S query(int i){
        return dat[find(i)];
    }
};

int main()
{
    int n;
    cin >> n;
    int x[200005], y[200005];
    PP pp[200005];
    for(int i = 0; i < n; i++){
        cin >> x[i] >> y[i];
        x[i]--;
        y[i]--;
        pp[i] = PP(P(x[i], y[i]), i);
    }
    sort(pp, pp + n);
    stack<int> st;
    st.push(pp[0].second);
    UnionFind<int> uf(n);
    for(int i = 0; i < n; i++){
        if(y[st.top()] > y[pp[i].second]){
            st.push(pp[i].second);
            continue;
        }
        int l = st.top();
        while(st.size()){
            if(y[st.top()] < y[pp[i].second]){
                uf.unite(st.top(), pp[i].second);
                st.pop();
            }
            else break;
        }
        st.push(l);
    }
    for(int i = 0; i < n; i++) cout << uf.query(i) << endl;
}

