    vector<pair<pair<int, int>, int> > z;  // x,y,id
    int i;
    for (i = 0; i < n; i++) {
        scanf("%d%d", &x[i], &y[i]);
        z.push_back(make_pair(make_pair(x[i], -y[i]), i));
    }
    sort(z.begin(), z.end());

    set<pair<int, int> > ss;   // y, id
    for (i = 0; i < n; i++) {
        int x = z[i].first.first;
        int y = -z[i].first.second;
        int id = z[i].second;

        auto it=ss.lower_bound(make_pair(y, -INF));
        if (it != ss.begin()) {
            vector<pair<int,int> > vdel;
            auto it2 = ss.begin();
            int idbegin = it2->second;
            uf.unite(idbegin, id);
            for (; it2 != it; ++it2) {
                if (it2 != ss.begin()) {
                    uf.unite(idbegin, it2->second);
                    vdel.push_back(*it2);
                }
            }
            int k;
            for (k = 0; k < vdel.size(); k++) {
                ss.erase(vdel[k]);
            }
        }
        else {
            ss.insert(make_pair(y, id));
        }
    }
    for (i = 0; i < n; i++) {
        printf("%d\n", uf.size(i));
    }

    return;
}

