SegmentTree<int> seg;
UnionFind uf;
V<bool> isUsed;
V<> valToIndY;  // Y 座標からソート後のインデックスへ
V<> indToInd;   // ソート後のインデックスからソート前のインデックスへ

void dfs(int i) {
    if(isUsed[i]) { return; }
    isUsed[i] = true;
    if(i >= N - 1) { return; }
    // 自分より右上に行く
    int res = seg.Query(i + 1, N);
    if(res > get<1>(XYi[i])) {
        int next_ind = valToIndY[res];
        uf.Unite(get<2>(XYi[i]), indToInd[next_ind]);
        dfs(next_ind);
    }
}

