const int L=1e6+7;
ll x[L], y[L], idx[L];
bool comp(int a, int b)
{
	return x[a] < x[b];
}
int children[L], parent[L];
int component(int x)
{
	if(parent[x] == x)return x;
	return parent[x] = component(parent[x]);
}
void merge(int a, int b)
{
	int pa = component(a);
	int pb = component(b);
	// debug(a,b,x[a], y[a], x[b], y[b], pa, pb);
	if(pa == pb)return;
	if(children[pa] > children[pb])
	{
		children[pb] += children[pa];
		parent[pa] = pb;
	}
	else
	{
		children[pa] += children[pb];
		parent[pb] = pa;
	}
	return;
}
void fff()
{
	ll n;
	cin >> n;
	pbds prv, nxt;
	std::vector<int> v;
	FOR(i,0,n)
	{
		parent[i] = i;
		children[i] = 1;
		cin >> x[i] >> y[i];
		idx[y[i]] = i;
		v.pb(i);
	}
	sort(all(v), comp);
	trace(v, i)
	{
		nxt.insert(y[i]);
	}
	int x;
	int co = 0, tmp;
	trace(v, i)
	{
		co = 0;
		nxt.erase(y[i]);
		x = nxt.order_of_key(y[i]);
		if(sz(nxt) == x)continue; 
		tmp = *nxt.find_by_order(x);
		merge(i, idx[tmp]);
		while(co<10)
		{
			x++;
			co++;
			if(sz(nxt) == x)break; 
			tmp = *nxt.find_by_order(x);
			// debug(y[i], tmp, idx[tmp]);
			merge(i, idx[tmp]);
		}
	}
	reverse(all(v));
	trace(v, i)
	{
		nxt.insert(y[i]);
	}
	trace(v, i)
	{
		co = 0;
		nxt.erase(y[i]);
		x = nxt.order_of_key(y[i]);
		if(x == 0)continue; 
		tmp = *nxt.find_by_order(x-1);
		merge(i, idx[tmp]);
		// debug(i,idx[tmp]);
		while(co<10)
