			x--;
			co++;
			if(x <= 0)break; 
			tmp = *nxt.find_by_order(x-1);
			// debug(y[i], tmp, idx[tmp]);
			merge(i, idx[tmp]);
		}
	}
	FOR(i,0,n)cout << children[component(i)]<<ln;
