 void updata(int i,int k){    //在i位置加上k
     while(i <= n){
         c[i] += k;
         i += lowbit(i);
     }
 }

 int getsum(int i){        //求A[1 - i]的和
     int res = 0;
     while(i > 0){
         res += c[i];
         i ^= lowbit(i);
     }
     return res;
 }   
void solve() {
    cin >> n;
    vii ax(n,vi(2));
    map<pii, int> idx;
    fori(i,0,n) {
        cin >> ax[i][0] >> ax[i][1];
        idx[{ax[i][0],ax[i][1]}] = i;
    }
    sort(all(ax));
    vi ans(n);
    memset(c,0,sizeof(c));
    memset(a,0,sizeof(a));
    fori(i,0,n) {
        ans[idx[{ax[i][0],ax[i][1]}]] += getsum(ax[i][1]);
        updata(ax[i][1], 1);
    }
    memset(c,0,sizeof(c));
    memset(a,0,sizeof(a));
    rep(i,n-1,0) {
        ans[idx[{ax[i][0],ax[i][1]}]] += getsum(n) - getsum(ax[i][1]);
        updata(ax[i][1], 1);
    }
    fori(i,0,n) cout << ans[i] + 1 << "\n";
}

