ll dud1[maxn];
void upd1(int x, ll val){
    while(x <= maxn){
        dud1[x] += val;
        x += x&(-x);
    }
}
ll query1(int x){
    ll sum = 0;
    while(x > 0){
        sum += dud1[x];
        x -= x&(-x);
    }
    return sum;
