ll bor[4*maxn];
void build(int v, int tl, int tr){
    if(tl == tr){
        bor[v] = kec[tl];
        return;
    }
    int mid = (tl + tr)/2;
    build(v*2, tl, mid);
    build(v*2+1, mid+1, tr);
    bor[v] = max(bor[v*2], bor[v*2+1]);
}
void update(int v, int tl, int tr, int poz, int vre){
    if(tl == tr){
        bor[v] += vre;
        return;
    }
    int mid = (tl+tr)/2;
    if(poz <= mid)update(v*2,tl,mid,poz,vre);
    else update(v*2+1,mid+1,tr,poz,vre);
    bor[v] = max(bor[v*2], bor[v*2+1]);
}
int kveri(int v, int tl, int tr, int l, int r){
    if(tl > r || l > tr)return 0;
    if(l <= tl && r >= tr)return bor[v];
    int mid = (tl + tr)/2;
    return max(kveri(v*2,tl,mid,l,r), kveri(v*2+1,mid+1,tr,l,r));
}
