    rep(i,N){
        int x,y; cin>>x>>y; x--; y--;
        ps.pb({x,y,i});
    }
    sort(all(ps));
    set<P> S;
    rep(i,N){
        int x,y,idx;
        tie(x,y,idx) = ps[i];
        S.ins({y,x,idx});
    }
    UnionFind uf(N);
    int now=0;
    while(!S.empty()){
        int y,x,idx;
        tie(y,x,idx) = *S.rbegin();
        S.erase({y,x,idx});
        while(now<x){
            int xx,yy,iidx;
            tie(xx,yy,iidx) = ps[now];
            uf.unite(iidx,idx);
            S.erase({yy,xx,iidx});
            now++;
        }
        now++;
    }

    rep(i,N){
        cout<<uf.size(i)<<"\n";
    }
    return 0;
}

