    for(int i=0; i<n; i++){
        inv_x[x[i]] = i;
        inv_y[y[i]] = i;
    }

    sort(x.begin(), x.end());

    UnionFind uf(n);
    set<pair<int, int>> st;
    for(int i=0; i<x.size(); i++){
        auto itr_lim = st.lower_bound(make_pair(y[inv_x[x[i]]], inv_x[x[i]]));
        bool f = true;
        for(auto itr = st.begin(); itr != itr_lim; itr++){
            uf.unite(inv_x[x[i]], itr->second);
            f = false;
        }


        auto itr_lim2 = itr_lim;
        if(itr_lim->first != st.begin()->first){
            itr_lim--;
            int y_prev = y[inv_x[x[i]]];
            bool flag = true;
            while(flag){
                if(itr_lim->first + 1 == y_prev){
                    auto itr_del = itr_lim;
                    y_prev--;
                    if(itr_lim->first == st.begin()->first) flag=false;
                    else itr_lim--;
                    st.erase(itr_del);
                }
                else break;
            }
        }

        if(itr_lim2 != st.end()){
            int y_prev = y[inv_x[x[i]]];
            itr_lim2++;
            while(itr_lim2 != st.end()){
                if(itr_lim2->first == y_prev+1){
