int find(int x) {
  return par[x] == x ? x : par[x] = find(par[x]);
}

void unite(int x, int y) {
  if ((x = find(x)) != (y = find(y))) {
    par[x] = y, sz[y] += sz[x];
  }
}

bool check(int i, int j) {
  return (A[i].x < A[j].x && A[i].y < A[j].y);
}

struct cmp {
  bool operator () (int P, int Q) const {
    return A[P].y < A[Q].y;
  }
};

