    return P.x < Q.x;
  });
  set <int, cmp> S;
  rep(i, 1, N) {
    while (!S.empty() && check(*S.begin(), i)) {
      unite(*S.begin(), i), S.erase(S.begin());
    }
    S.insert(i);
  }
  S.clear();
  per(i, N, 1) {
    while (!S.empty() && check(i, *S.rbegin())) {
      unite(*S.rbegin(), i), S.erase(*S.rbegin());
    }
    S.insert(i);
