struct segment_tree {
  int NV;
  vector<int> dat;
  segment_tree(int N) {
    NV = 1;
    while (NV < N) NV = NV << 1;
    dat.resize(NV*2 -1);
    //cout << "sg init: NV = " << NV << endl; 
    for (int i = 0; i < NV; i++) {
      dat[i+NV-1] = 0;
    }
    for (int i = NV - 2; i >=0; i--) {
      dat[i] = 0;
    }
  }

  void update(int idx, int val) {
    //cout << "update called: " << idx << "," << val << endl;
    if (idx < 0) return;
    idx += NV - 1;
    dat[idx] = val;
    //cout << idx << ":" << dat[idx].first << "," << dat[idx].second << endl;
    while (idx > 0) {
      idx = (idx - 1) / 2;
      dat[idx] = dat[idx*2 + 1] +  dat[idx*2 + 2];
      //cout << idx << ":" << dat[idx].first << "," << dat[idx].second << endl;
    }
    return;
  }

  int query(int a, int b) {
    return _query(a, b, 0, 0, NV);
  }
  int _query(int a, int b, int k, int l, int r) {
    //cout << "query called :" << a << "," << b << "," << k << "," << l << "," << r << endl;
    if (r <= a || b <= l) return 0;
    if (a <= l && r <= b) return dat[k];
    else {
      int vl = _query(a, b, k*2 + 1, l, (l + r) / 2);
      int vr = _query(a, b, k*2 + 2, (l + r) / 2, r);
      //cout << "querry return val: " << min(vr,vl).first << "," << min(vr,vl).second << endl;
      return vl + vr;
    }
  }
};

int main(){
  std::cin.tie(0);
  std::ios::sync_with_stdio(false);

  int32_t N;
  cin >> N; 
  vector<vector<int32_t>> cities(N, vector<int32_t>(3, 0));
  for (int i = 0; i < N; i++) {
    cin >> cities[i][0] >> cities[i][1];
    cities[i][2] = i;
  }
  sort (cities.begin(), cities.end(), [](const vector<int32_t>& r, const vector<int>& l) {return r[0] < l[0];});
  segment_tree sg(N);
  vector<int32_t> left(N, 1);
  for (int i = 0; i < N; i++) {
    int32_t y = cities[i][1];
    int32_t lty = sg.query(0, y - 1);
    left[i] += lty;
    sg.update(y - 1, 1);
  }
  int32_t ymax_idx = N - 1;
  int32_t ymax = cities[N-1][1];
  for (int i = N - 2; i >= 0; i--) {
    int32_t y = cities[i][1];
    if (y < ymax) {
      left[i] = left[ymax_idx];
    } else {
      ymax_idx = i;
      ymax = y;
    }
  }
  vector<int32_t> res(N, 0);
  for (int i = 0; i < N; i++) {
    res[cities[i][2]] = left[i];
  }
  for (auto r : res) {
    cout << r << endl;
  }

  return 0;
}

