struct SEG {
	int id[mxn], ls[mxn], rs[mxn], tot;

	int nd() {
		int x = ++ tot;
		id[x] = ND();
		ls[x] = rs[x] = 0;
		return x;
	}

	int cl(int y) {
		int x = ++ tot;
		id[x] = ND();
		ls[x] = ls[y]; rs[x] = rs[y];
		return x;
	}

	void clear() {
		tot = 0;
	}

	void link(int i, int a, int b, int l, int r, int v) {
		if (!i) return ;
		if (l <= a && b <= r) {
			g[v].pb(id[i]);
			return ;
		}
		int m = (a + b) >> 1;
		if (l < m) link(ls[i], a, m, l, r, v);
		if (r > m) link(rs[i], m, b, l, r, v);
	}

	void ins(int &i, int a, int b, int x, int v) {
		if (!i) i = nd();
		else i = cl(i);
		if (a + 1 == b) {
			g[id[i]].pb(v);
			return ;
		}
		int m = (a + b) >> 1;
		if (x < m) ins(ls[i], a, m, x, v);
		else ins(rs[i], m, b, x, v);
		if (ls[i]) g[id[i]].pb(id[ls[i]]);
		if (rs[i]) g[id[i]].pb(id[rs[i]]);
	}
} seg;

