	for(int i=0;i<n;i++)
	make_set(i);
	for(int i=0;i<n;i++) nxt[i]=i+1,prv[i]=i-1;
	for(int i=0;i<n;i++)
	{
		if(par[ind[i]]!=-1) continue;
		par[ind[i]]=ind[i];
		if(prv[i]>=0)
		nxt[prv[i]]=nxt[i];
		prv[nxt[i]]=prv[i];
