struct Num{
	int x,y,index;
}num[200005];
int right[200005],sz[200005],par[200005],left[200005],ans[200005];
bool cmp(Num a,Num b){
	return a.x<b.x;
}
int find(int x){
	if(x==par[x])
		return x;
	return par[x]=find(par[x]);
}
void unite(int x,int y){
	x=find(x);
	y=find(y);
	if(x==y)
		return;
	if(sz[x]<sz[y]){
		sz[y]+=sz[x];
		sz[x]=0;
		par[x]=y;
	}
	else{
		sz[x]+=sz[y];
		sz[y]=0;
		par[y]=x;
	}
}
stack<int> st;
int main(){
	int i,n;
	scanf("%d",&n);
	for(i=0;i<n;i++){
		scanf("%d%d",&num[i].x,&num[i].y);
		num[i].index=i;
		par[i]=i;
		sz[i]=1;
	}
	sort(num,num+n,cmp);
	right[n-1]=n;
	st.push(n-1);
	for(i=n-2;i>=0;i--){
		while(st.size()&&num[i].y>num[st.top()].y)
			st.pop();
		if(st.size())
			right[i]=st.top();
		else
			right[i]=n;
		st.push(i);
	}
	for(i=0;i<n;i++)
		if(right[i]!=n)
			unite(i,right[i]);
	while(st.size())
		st.pop();
	left[0]=-1;
	st.push(0);
	for(i=1;i<n;i++){
		while(st.size()&&num[i].y<num[st.top()].y)
			st.pop();
		if(st.size())
			left[i]=st.top();
		else
			left[i]=-1;
	}
	for(i=0;i<n;i++)
		if(left[i]!=-1)
			unite(i,left[i]);
	for(i=0;i<n;i++)
		ans[num[i].index]=sz[find(i)];
	for(i=0;i<n;i++)
		printf("%d\n",ans[i]);
}

