struct UnionFind {
  UnionFind(int n) : data(n, -1) {}

  int root(int ver) { return data[ver] < 0 ? ver : data[ver] = root(data[ver]); }

  bool unite(int u, int v) {
    u = root(u);
    v = root(v);
    if (u == v) return false;
    if (data[u] > data[v]) std::swap(u, v);
    data[u] += data[v];
    data[v] = u;
    return true;
  }

  bool same(int u, int v) { return root(u) == root(v); }

  int size(int ver) { return -data[root(ver)]; }

private:
  std::vector<int> data;
};

int main() {
  int n; cin >> n;
  vector<int> x(n), y(n); REP(i, n) cin >> x[i] >> y[i], --x[i], --y[i];
  vector<int> y_idx(n);
  REP(i, n) y_idx[y[i]] = i;
  vector<int> idx(n);
  iota(ALL(idx), 0);
  sort(ALL(idx), [&](int a, int b) { return x[a] < x[b]; });
  UnionFind uf(n);
  set<int> st;
  REP(i, n) {
    if (!st.empty() && *st.begin() < y[idx[i]]) uf.unite(idx[i], y_idx[*prev(st.lower_bound(y[idx[i]]))]);
    st.emplace(y[idx[i]]);
  }
  st.clear();
  for (int i = n - 1; i >= 0; --i) {
    if (!st.empty() && y[idx[i]] < *st.rbegin()) uf.unite(idx[i], y_idx[*st.upper_bound(y[idx[i]])]);
    st.emplace(y[idx[i]]);
  }
  REP(i, n) cout << uf.size(i) << '\n';
  return 0;
}

