struct DSU {
    vector<int> p, sz;
    DSU (int n) {
        p.assign(n, -1);
        for (int i = 0; i < n; i++) p[i] = i;
        sz.assign(n, 1);
    }

    int find (int a) {
        if (p[a] == a) return a;
        return p[a] = find(p[a]);
    }

    void uni(int a, int b) {
        int sa = find(a), sb = find(b);
        if (sa == sb) return;
        if (sz[sa] < sz[sb]) swap(a, b), swap(sa, sb);
        sz[sa] += sz[sb];
        p[sb] = sa;
    }
};

int main () {
    int n;
    while (scanf("%d", &n) == 1) {
        vector<int> x(n), y(n);
        for (int i = 0; i < n; i++) scanf("%d %d", &x[i], &y[i]);

        vector<int> ids;
        for (int i= 0; i < n; i++) ids.push_back(i);
        sort(ids.begin(), ids.end(), [&](int i, int j) { return x[i] < x[j]; });

        DSU dsu(n);
        set<pair<int, int>> s;
        for (auto &id : ids) {
            auto it = s.lower_bound({ y[id], -1 });
            if (it != s.begin()) dsu.uni(id, prev(it)->second);
            it = s.begin();
            if (it != s.end() && it->first < y[id]) dsu.uni(id, it->second);
            s.insert({ y[id], id });
        }

        s.clear();
        for (int i = n - 1; i >= 0; i--) {
            int id = ids[i];
            auto it = s.lower_bound({ y[id], -1 });
            if (it != s.end()) dsu.uni(id, it->second);
            it = s.end();
            if (it != s.begin() && prev(it)->first > y[id]) dsu.uni(id, prev(it)->second);
            s.insert({ y[id], id });
        }

        for (int id = 0; id < n; id++) printf("%d\n", dsu.sz[dsu.find(id)]);
        printf("\n");
    }
}

