  vi data;
  union_find(int size) : data(size, -1) {}
  bool join(int x, int y) {
    x = root(x);
    y = root(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y];
      data[y] = x;
    }
    return x != y;
  }
  bool same(int x, int y) { return root(x) == root(y); }
  int root(int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }
  int size(int x) { return -data[root(x)]; }
};

void solve(int N, vi x, vi y) {
  vi idx(all(x));
  vp yx = zip(y, x);
  SORT(yx);
  zip_sort(x, y);
  union_find uf(N);
  seti ys;
  rrep(i, N) {
    int t = y[i];
    while (true) {
      auto it = ys.upper_bound(t);
      if (it == ys.end()) break;
      uf.join(i, yx[*it].second);
      t = *it;
      ys.erase(it);
    }
    ys.insert(t);
  }
  rep(i, N) COUT(uf.size(idx[i]));
}


