            itr_lim2++;
            while(itr_lim2 != st.end()){
                if(itr_lim2->first == y_prev+1){
                    auto itr_del = itr_lim2;
                    y_prev++;
                    itr_lim++;
                    st.erase(itr_del);
                }
                else break;
            }
        }
    }

    for(int i=0; i<n; i++){
