struct IT
{
    vector <ll> tree,lazy;
    void fmat(int n)
    {
        tree.assign(4*n,0);
        lazy.assign(4*n,0);
    }
    void update(int node, int STart, int ENd, int l, int r, ll val)
    {
        if(lazy[node] != 0)
        {
            tree[node] += (ENd - STart + 1) * lazy[node];
            if(STart != ENd)
            {
                lazy[(node<<1)] += lazy[node];
                lazy[((node<<1)|(1))] += lazy[node];
            }
            lazy[node] = 0;
        }
        if(STart > ENd or STart > r or ENd < l)
            return;
        if(STart >= l and ENd <= r)
        {
            tree[node] += (ENd - STart + 1) * val;
            if(STart != ENd)
            {
                // Not leaf node
                lazy[(node<<1)] += val;
                lazy[((node<<1)|(1))] += val;
            }
            return;
        }
        int mid = (STart + ENd) / 2;
        update((node<<1), STart, mid, l, r, val);
        update(((node<<1)|(1)), mid + 1, ENd, l, r, val);
        tree[node] = tree[(node<<1)] + tree[((node<<1)|(1))];
    }

    ll get(int node, int STart, int ENd, int l, int r)
    {
        if(STart > ENd or STart > r or ENd < l)
            return 0;
        if(lazy[node] != 0)
        {

            tree[node] += (ENd - STart + 1) * lazy[node];
            if(STart != ENd)
            {
                lazy[(node<<1)] += lazy[node];
                lazy[((node<<1)|(1))] += lazy[node];
            }
            lazy[node] = 0;
        }
        if(STart >= l and ENd <= r)
            return tree[node];
        int mid = (STart + ENd) / 2;
        ll p1 = get((node<<1), STart, mid, l, r);
        ll p2 = get(((node<<1)|(1)), mid + 1, ENd, l, r);
        return (p1 + p2);
    }
};
