bool check(int x) {
    vector<bool> dp((1<<m), 0);
    dp[0] = 1;
    rep(bit, (1<<m)) {
        if(!dp[bit]) continue;
        rep(i, m) {
            if(!(bit & (1<<i))) {
                if(n - 1 - mae[bit] - mae[((1<<m) - 1) ^ (bit | (1<< i))] - co[i] <= x) {
                    dp[bit | (1<<i)] = 1;
                }
            }
        }
    }
    return dp[(1<<m) - 1];
}

void solve() {
	cin >> n >> m;
    a.resize(n);
    vector<vector<int>> cnt(m, vector<int>(m, 0));
    co.assign(m, 0);
    rep(i, n) {
        cin >> a[i];
        -- a[i];
        co[a[i]] ++;
    }
    rep(i, n - 1) {
        cnt[a[i]][a[i + 1]] ++;
        cnt[a[i + 1]][a[i]] ++;
    }
    mae.assign((1<<m), 0);
    rep(bit, (1<<m)) {
        rep(j, m) {
            if(bit & (1<<j)) {
                for(int k = j + 1; k < m; ++ k) {
                    if(bit & (1<<k)) mae[bit] += cnt[j][k];
                }
            }
        }
        // cerr << bit << " " << mae[bit] << endl;
    }
    int ng = -1, ok = n + 1;
    while(ok - ng > 1) {
        int mid = (ok + ng) / 2;
        if(check(mid)) ok = mid;
        else ng = mid;
    }
    cout << ok << endl;
}

