struct node{
    ll fi,sc,pos;
};
node A[DIM],B[DIM];
ll ans[DIM];
const bool operator<(const node &a,const node &b){
    if (a.fi==b.fi)return a.sc<b.sc;
    return a.fi<b.fi;
}

vector<ll> T[DIM*4];
void buildtree(ll t,ll tl,ll tr){
    if (tl==tr){
        T[t].pb(A[tl].sc);
        return;
    }
    ll tm = (tl+tr)/2;
    buildtree(t*2+1,tl,tm);
    buildtree(t*2+2,tm+1,tr);
    merge(T[t*2+1].begin(),T[t*2+1].end(),T[t*2+2].begin(),T[t*2+2].end(),back_inserter(T[t]));
}
ll query(ll t,ll tl,ll tr,pp x,pp y){
    if (tl>x.sc || x.fi>tr)return 0;
    if (x.fi<=tl && tr<=x.sc){
        ll pos = upper_bound(T[t].begin(),T[t].end(),y.sc)-T[t].begin();
        ll pos1 = lower_bound(T[t].begin(),T[t].end(),y.fi)-T[t].begin();

        return pos-pos1;
    }
    ll tm = (tl+tr)/2;
    return query(t*2+1,tl,tm,x,y)+query(t*2+2,tm+1,tr,x,y);
}
