    buildtree(0,1,n);
    pref[0][0] = pref[1][0] = INF;
    suf[0][n+1] = suf[1][n+1] = -INF;
    forn(i,n){
        pref[0][i] = min(pref[0][i-1],A[i].sc);
        pref[1][i] = min(pref[1][i-1],B[i].sc);
    }
    for(ll i = n;i>=1;--i){
        suf[0][i] = max(suf[0][i+1],A[i].sc);
        suf[1][i] = max(suf[1][i+1],B[i].sc);
