set<int> s;
int par[200009],sz[200009];
int fin(int v) 
{
	if(par[v]==-1) return par[v]=v;
    if (v == par[v])    return v;
    return par[v] = fin(par[v]);
}

void uni(int a, int b) 
{
    a = fin(a);
    b = fin(b);
    if(a == b) return;
    if(sz[a] < sz[b]) swap(a, b);
    par[b] = a;
    sz[a] += sz[b];
}
void solve()
{
	int n;
	cin>>n;
	for(int i=1;i<=n;i++)
	{
		int a,b;
