		pos[a]=b;
		ind[a]=i;
		inv[b]=a;
		s.insert(b);
		par[i]=i;
		sz[i]=1;
	}
	set<int> small;
	for(int i=1;i<=n;i++)
	{
		if(s.upper_bound(pos[i]) == s.end())
		{
			vector<int> temp;
			for(auto u:small)
			{
				if(u<pos[i])
				{
					temp.pb(u);
					uni(ind[i],ind[inv[u]]);
				}
			}
			for(auto u:temp) small.erase(u);
		}
		else small.insert(pos[i]);
		s.erase(pos[i]);
	}
	for(int i=1;i<=n;i++) cout<<sz[fin(i)]<<'\n';
}

