  for(int i=0;i<n;i++){
    scanf("%d%d",&x[i],&y[i]);
    xs[i].first=x[i];
    xs[i].second=i;
  }
  sort(xs.begin(),xs.end());
  priority_queue<pair<int,int>> pq;

  for(int i=0;i<n;i++){
    int v=xs[i].second;
    int ch=y[v];
    while(!pq.empty()){
      pair<int,int> ct=pq.top();
      pq.pop();
      //printf("%d %d %d\n",v,ct.first,ct.second);
      ct.first*=-1;
      if(ct.first>y[v]){
        ct.first*=-1;
        pq.push(ct);
        break;
      }
      else{
        //printf("%d %d\n",v,ct.second);
        uni(v,ct.second);
        ch=min(ch,ct.first);
      }
    }
    pq.push(make_pair(-ch,v));
  }

  for(int i=0;i<n;i++){
    printf("%d\n",size(i));
  }
  return 0;
}

