template <typename T>
struct FenwickTree
{
	const T E=0;
	T *bit;
	int nn;
	inline void init(int n)
	{
		n++;
		nn=1;
		while(nn<n) nn<<=1;
		bit=new T[nn+5];
		for(int i=0;i<=nn;i++)
		{
			bit[i]=0;
		}
	}
	inline void clear(int n)
	{
		nn=1;
		while(nn<n) nn<<=1;
		for(int i=0;i<=nn;i++)
		{
			bit[i]=0;
		}
	}
	inline void add(int x,T delta)
	{
		x++;
		while(x<=nn)
		{
			bit[x]+=delta;
			x+=x&-x;
		}
	}
	inline T query(int x)
	{
		T res=E;
		while(x)
		{
			res+=bit[x];
			x&=x-1;
		}
		return res;
	}
	inline T query(int l,int r)//[]
	{
		l++;
		r++;
		return query(r)-(l>1?query(l-1):0);
	}
};

template <typename T>
struct SegmentTreeIntervalSum
{
	const T E=0;
	int nn;
	T *data;
	T *tag;
	void init(int _n)
	{
		nn=1;
		while(nn<_n) nn<<=1;
		data=new T[nn*2+5];
		tag=new T[nn*2+5];
		for(int i=0;i<2*nn;i++)
		{
			tag[i]=E;
			data[i]=E;
		}
	}
	void pushdown(int x,int l,int r)
	{
		if(x>=nn) return;
		data[x*2]+=tag[x]*(r-l>>1);
		data[x*2+1]+=tag[x]*(r-l>>1);
		tag[x*2]+=tag[x];
		tag[x*2+1]+=tag[x];
		tag[x]=0;
	}
	void build(T a[],int n)
	{
		for(int i=0;i<n;i++)
		{
			data[i+nn]=a[i];
		}
		for(int i=nn-1;i>=1;i--)
		{
			data[i]=data[i*2]+data[i*2+1];
		}
	}
	void add(int x,int ql,int qr,int l,int r,T delta)
	{
		if(l>=qr || r<=ql) return;
		pushdown(x,l,r);
		if(l>=ql && r<=qr)
		{
			tag[x]+=delta;
			data[x]+=delta*(r-l);
			return;
		}
		add(x*2,ql,qr,l,l+r>>1,delta);
		add(x*2+1,ql,qr,l+r>>1,r,delta);
		data[x]=data[x*2]+data[x*2+1];
	}
	T query(int x,int ql,int qr,int l,int r)
	{
		if(l>=qr || r<=ql) return E;
		pushdown(x,l,r);
		if(l>=ql && r<=qr)
		{
			return data[x];
		}
		return query(x*2,ql,qr,l,l+r>>1)+query(x*2+1,ql,qr,l+r>>1,r);
	}
	inline void add(int l,int r,int delta)
	{
		add(1,l,r,0,nn,delta);
	}
	inline T query(int l,int r)
	{
		return query(1,l,r,0,nn);
	}
};

