				cv = (loc>>(dep-1))&1;
				if(cv && at->ch[0]) ans += at->ch[0]->sum;
				if(at->ch[cv]) at = at->ch[cv], dep--;
				else break;
			}
			return ans+(!dep?at->sum:0);
		}
