// 簡易UF
struct UF{
    vector<int> p, m;
    int n;

    UF(int siz){
        n = siz;
        p.resize(n, 0);
        m.resize(n, 1);
        for(int i = 0; i < n; i++)  p[i] = i;
    }

    int parent(int x){
        if(p[x] != x)   p[x] = parent(p[x]);
        return p[x];
    }

    bool same(int x, int y){
        return parent(x) == parent(y);
    }

    void unite(int x, int y){
        x = parent(x), y = parent(y);
        if(x == y)  return;
        m[y] += m[x];
        p[x] = y;
    }
};

int main(){
    int n;
    cin >> n;
    vector<int> x(n), y(n), xrev(n), yrev(n);
    for(int i = 0; i < n; i++)  cin >> x[i] >> y[i], xrev[--x[i]] = i, yrev[--y[i]] = i;
    set<int> s; // x-axis
    UF uf(n);
    // y-axis ascending
    for(int i = 0; i < n; i++){
        auto it = s.lower_bound(x[yrev[i]]);
        if(i > 0 && it != s.begin()){
            it--;
            uf.unite(xrev[*it], yrev[i]);
        }
        s.insert(x[yrev[i]]);
    }
    s.clear();
    // y-axis descending
    for(int i = n-1; i >= 0; i--){
        auto it = s.upper_bound(x[yrev[i]]);
        if(it != s.end()){
            uf.unite(xrev[*it], yrev[i]);
        }
        s.insert(x[yrev[i]]);
    }
    for(int i = 0; i < n; i++)  cout << uf.m[uf.parent(i)] << endl;
    return 0;
}

