struct dsu {
public:
	dsu() : _n(0) {}
	dsu(int n) : _n(n), sz(n, 1), parent(n) { std::iota(parent.begin(), parent.end(), 0); }

	void merge(int a, int b) {
		assert(0 <= a && a < _n);
		assert(0 <= b && b < _n);
		int x = find(a), y = find(b);
		if (x == y) return;
		if (sz[x] < sz[y]) std::swap(x, y);
		sz[x] += sz[y];
		parent[y] = parent[x];
	}

	bool same(int a, int b) {
		assert(0 <= a && a < _n);
		assert(0 <= b && b < _n);
		return find(a) == find(b);
	}

	int find(int a) {
		assert(0 <= a && a < _n);
		if (parent[a] == a) return a;
		return parent[a] = find(parent[a]);
	}

	int size(int a) {
		assert(0 <= a && a < _n);
		a = find(a);
		return sz[a];
	}

private:
	int _n;
	std::vector<int> parent;
	std::vector<int> sz;
};

void solve() {
	int n;
	cin >> n;
	vector<pair<int, pair<int, int>>> a(n);
	set<pair<int, int>> st, st2;
	for (int i = 0; i < n; i++) {
		cin >> a[i].first >> a[i].second.first;
		a[i].second.second = i;
	}
	sort(a.begin(), a.end());
	for (int i = 0; i < n; i++) {
		st.insert({ a[i].second.first, i });
	}

	dsu d(n);
	for (int i = 0; i < n; i++) {
		st.erase(make_pair(a[i].second.first, i));
		auto ub = st.rbegin();
		if (ub != st.rend() && ub->first > a[i].second.first) {
			d.merge(i, ub->second);
		}
		auto lb = st2.begin();
		if (lb != st2.end() && lb->first < a[i].second.first) {
			d.merge(i, lb->second);
		}
		st2.insert(make_pair(a[i].second.first, i));
	}

	vector<int> ans(n);
	for (int i = 0; i < n; i++) {
		ans[a[i].second.second] = d.size(i);
	}
	for (int x : ans) {
		cout << x << '\n';
	}
}

