    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
long long COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}


int main(){
  cin.tie(0);
  ios::sync_with_stdio(false); 
  //COMinit();

  int n;
  cin >> n;
  vi x(n),y(n),z(n),id(n),ans(n);
  rep(i,n){
    cin >> x[i] >> y[i];
    x[i]--;
    y[i]--;
    z[x[i]]=y[i];
    id[x[i]]=i;
  }

  UnionFind tree(n);
  int miny = n;
  int lastid = -1;

  stack<int>st;
  rep(i,n){
    if(z[i] < miny){
      miny = z[i];
      lastid = i;
    }else{
      while(!st.empty() && z[st.top()] < z[i]){
        tree.merge(st.top(),i);
        st.pop();
      }
    }
    st.push(lastid);
  }
  rep(i,n) ans[id[i]] = tree.size(i);
  rep(i,n) cout << ans[i] << endl;
  return 0;
}

