#include <vector>
#include <tuple>

struct union_find {
  std::vector<int> par;
  union_find(int N): par(N, -1) {}
  int root(int x) {
    return par[x] < 0 ? x : par[x] = root(par[x]);
  }
  std::tuple<int, int> unite(int x, int y) {
    x = root(x);
    y = root(y);
    if(x == y) return { -1, -1 };
    if(par[x] > par[y]) std::swap(x, y);
    par[x] += par[y];
    par[y] = x;
    return { x, y };
  }
  int size(int x) {
    return -par[root(x)];
  }
};

int main() {
  i64 N;
  cin >> N;
  vector<tuple<i64, i64, i64>> vec;
  rep(i,0,N) {
    i64 x, y;
    cin >> x >> y;
    x--;
    y--;
    vec.emplace_back(x, y, i);
  }
  sort(all(vec));
  reverse(all(vec));

  union_find uf(N);
  vector<pair<i64, i64>> st;
  for(auto [x, y, i]: vec) {
    while(!st.empty() && st.back().first > y) {
      uf.unite(i, st.back().second);
      st.pop_back();
    }
    st.push_back({ y, i });
  }
  st.clear();
  reverse(all(vec));
  for(auto [x, y, i]: vec) {
    while(!st.empty() && st.back().first < y) {
      uf.unite(i, st.back().second);
      st.pop_back();
    }
    st.push_back({ y, i });
  }
  rep(i,0,N) {
    cout << uf.size(i) << '\n';
  }
}

