}

int par[maxn];
int size1[maxn];

int find(int x)
{
	if(par[x]==x) return par[x];
	return par[x]=find(par[x]);
}
void merge(int x,int y)
{
	int parx=find(x);
	int pary=find(y);

	if(pary==parx) return;

	if(size1[parx]>=size1[pary])
	{
		size1[parx]+=size1[pary];
		par[pary]=parx;
		return;
	}
	size1[pary]+=size1[parx];
	par[parx]=pary;
}


