    {
        scanf("%d%d",a+i,b+i);
        a[i]--;
        b[i]--;
    }
    for(int i=0;i<n;i++)
    {
        vSort.push_back(mp(mp(a[i],b[i]),i));
    }
    sort(all(vSort));
    for(int i=0;i<n;i++)
    {
        h[i]=vSort[i].first.second;
    }
    dsu.init(n);
    sgt.init(n);
    sgt.build(h,n);
    for(int i=0;i<n;i++)
    {
        while(true)
        {
            pii mv=sgt.query(0,i).first;
            // cout<<mv.first<<' '<<h[i]<<endl;
            if(mv.first>=h[i]) break;
            // cout<<mv.second<<' '<<i<<endl;
            sgt.erase(mv.second);
            dsu.merge(mv.second,i);
        }
    }
    sgt.build(h,n);
    for(int i=n-1;i>=0;i--)
    {
        while(true)
        {
            pii mv=sgt.query(i+1,n).second;
            if(mv.first<=h[i]) break;
            sgt.erase(mv.second);
            dsu.merge(mv.second,i);
        }
    }
    for(int i=0;i<n;i++)
    {
        ans[vSort[i].second]=dsu.getSize(i);
    }
    for(int i=0;i<n;i++)
