void BFS(vector<ll>arr[], ll size, ll start){
  queue<ll>q;
  vector<bool>visited(size, false);
  visited[start] = true;
  ll count = 1;
  q.push(start);
  while(!q.empty()){
    ll d= q.front();
    q.pop();
    for(auto i = arr[d].begin(); i != arr[d].end(); i++){
      ll x = *i;
      if(!visited[x]){
        q.push(x);
        visited[x] = true;
        count++;
      }
    }
  }
  cout<<count<<endl;
}
