      t2.update(a[i].F.S,P(a[i].F.S,a[i].S));
    }
    rep(i,n) swap(a[i].F.F,a[i].F.S);
  }
  rep(k,2) {
    t.init(n);
    t2.init(n);
    sort(a,a+n);
    rrep(i,n) {
      P p=t.query(a[i].F.S+1,n);
      P q=t2.query(a[i].F.S+1,n);
      if(p.S!=-1) unite(a[i].S,p.S);
      if(q.S!=-1) unite(a[i].S,q.S);
      t.update(a[i].F.S,P(a[i].F.S,a[i].S));
      t2.update(a[i].F.S,P(a[i].F.S,a[i].S));
    }
    rep(i,n) swap(a[i].F.F,a[i].F.S);
  }
  rep(i,n) pr(c[find(i)]);
}

