// 簡易UF
struct UF{
    vector<int> p, m;
    int n;

    UF(int siz){
        n = siz;
        p.resize(n, 0);
        m.resize(n, 1);
        for(int i = 0; i < n; i++)  p[i] = i;
    }

    int parent(int x){
        if(p[x] != x)   p[x] = parent(p[x]);
        return p[x];
    }

    bool same(int x, int y){
        return parent(x) == parent(y);
    }

    void unite(int x, int y){
        x = parent(x), y = parent(y);
        if(x == y)  return;
        m[y] += m[x];
        p[x] = y;
    }
};

int main(){
    int n;
