struct segtree{
  node t[4*N];
  int tl[4*N];
  int tr[4*N];
  node nul;
  void build(int v,int start,int end,vector<pii>&arr){
      tl[v]=start;
      tr[v]=end;
      if(start==end){
          t[v].a=arr[start].x;
          t[v].b=t[v].a;
      }
      else{
          int m=(start+end)/2;
          build(2*v,start,m,arr);
          build(2*v+1,m+1,end,arr);
          t[v].merge(t[2*v],t[2*v+1]);
     }
  }
