//-------------------------------------------------
//--Union Find tree
//-------------------------------------------------
class UnionFind
{
private:
    vector<int> par;
    vector<int> rank;
    vector<int> sz;
public:
    UnionFind(int n):par(n),rank(n),sz(n){
        for(int i=0; i<n; i++){
            par[i] = i;
            rank[i] = 0;
            sz[i] = 1;
        }
    }
    int root(int x){
        if (par[x]==x) return x;
        return par[x] = root(par[x]);
    }
    bool same(int x, int y){
        return root(x)==root(y);
    }
    void unite(int x, int y){
        int rx = root(x);
        int ry = root(y);
        if (rx==ry) return;
        if (rank[rx]<rank[ry]){
            par[rx] = par[ry];
            sz[ry] += sz[rx];
        }else{
            par[ry] = par[rx];
            sz[rx] += sz[ry];
            if (rank[rx]==rank[ry]) rank[rx]++;
        }
    }
    int size(int x){
        return sz[root(x)];
    }
};

//-------------------------------------------------

int main(void)
{
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N; cin>>N;
    using P = tuple<int,int,int>;
    vector<P> ps;
    rep(i,N){
        int x,y; cin>>x>>y; x--; y--;
        ps.pb({x,y,i});
    }
    sort(all(ps));

    UnionFind uf(N);
    set<pi> Set;
    rep(i,N){
        int x,y,idx;
        tie(x,y,idx) = ps[i];
        Set.ins({y,idx});
    }
    rep(i,N){
        // for(auto e:Set){
        //     cout<<e<<" ";
        // }cout<<endl;
        int x,y,idx;
        tie(x,y,idx) = ps[i];
        Set.erase(pi(y,idx));
        if (uf.size(idx)>1) continue;
        auto itr = Set.lower_bound(pi(y,0));
        while(itr!=Set.end()){
            uf.unite(idx, itr->se);
            itr++;
        }
        itr = Set.lower_bound(pi(y,0));
    }

    rep(i,N){
        cout<<uf.size(i)<<"\n";
    }
    return 0;
}

