        }
    }
    for (int i = 0; i < N; i++) town[i] = {{-town[i].first.first, -town[i].first.second}, town[i].second};
    sort(town.begin(), town.end());
    st.clear();
    for (int i = 0; i < N; i++) {
        pair<int, int> pii = {town[i].first.second, town[i].second};
