			par[i] = i;
			size[i] = 1;
		}
	}

	ll getpar(ll ind) {
		while (par[ind] != ind) {
			ind = par[ind];
		}
		return ind;
	}

	void merge(ll ind1, ll ind2) {
		ll p1 = getpar(ind1);
		ll p2 = getpar(ind2);
		if (p1 == p2)return;
		if (size[p1] <= size[p2])par[p1] = p2;
		else par[p2] = p1;
		size[p1] = size[p1] + size[p2];
		size[p2] = size[p1];
	}
};


