struct UF{
  vector<int> par, dep, sz;
  UF(int n){
		n++;
    par.resize(n), dep.resize(n, 0), sz.resize(n, 1);
    re(i, n) par[i] = i;
  }
  int find(int xu){
    if(par[xu] == xu) return xu;
    return par[xu] = find(par[xu]);
  }
  void unite(int xu, int yu){
    xu=find(xu), yu=find(yu);
    if(xu == yu) return;
    if(dep[xu] < dep[yu]) sz[yu] += sz[xu], par[xu] = yu;
    else par[yu] = xu, sz[xu] += sz[yu];
    if(dep[xu] == dep[yu]) dep[xu]++;
  }
  bool same(int xu, int yu){ return find(xu) == find(yu);}
};

struct segtree{
  ll M=1, INIT;
  vector<ll> dat;
  segtree(ll N, ll num):INIT(num){
    while(M<N) M*=2;
    dat.resize(M*2-1, INIT);
  }
  void update(ll x, ll k){
    k+=M-1;
    dat[k] += x;
    while(k>0) k = (k-1)/2, dat[k] = dat[k*2+1] + dat[k*2+2];
  }
  ll query(ll a, ll b=-1, ll k=0, ll l=0, ll r=-1){
    if(r==-1) r = M;
    if(b==-1) b = M;
    if(r<=a || b<=l) return INIT;
    if(a<=l && r<=b) return dat[k];
    ll A = query(a, b, k*2+1, l, (l+r)/2);
    ll B = query(a, b, k*2+2, (l+r)/2, r);
    return A + B;
  }
};

int main(){
  ll n;std::cin >> n;
  UF uf(n+1);
  vvl d = VV(n, 4, 0, ll);
  vll y(n);
  for(int i=0;i<n;i++){
    std::cin >> d[i][0] >> d[i][1];
    d[i][0]--, d[i][1]--;
    d[i][2] = i;
  }

  sort(all(d));
  segtree seg(n, 0);

  ll max_idx = -1;
  ll max_ok_idx = -1;
  for(int i=0;i<n;i++) {
    y[d[i][1]] = i;
    d[i][3] = i;
  }
  auto pre = d;
  sort(all(d), [&](vll l, vll r){return l[1] < r[1];});
  reverse(all(d));

  for(int i=0;i<n;i++){
    //yをどこまでみたか
    //max_idx以下ならcontinue
    ll idx = y[d[i][1]];
    seg.update(1, idx);
    if(idx<max_idx) continue;
    ll q = seg.query(0, idx);

    if(q == idx) {
      max_idx = max(max_idx, idx);
      continue;//no_ok
    }

    //max_ok_idxとマージ、max_idx~iまでマージ
    if(max_ok_idx!=-1&&seg.query(0, max_ok_idx)!=max_ok_idx) {
      uf.unite(pre[max_ok_idx][2], d[i][2]);
    }

    for(int j=max_idx+1;j<idx;j++){
      if(pre[j][1]>d[i][1]) continue;
      uf.unite(pre[j][2], d[i][2]);
    }

    max_ok_idx = max(max_ok_idx, idx);
    max_idx = max(max_idx, idx);
  }

  for(int i=0;i<n;i++){
    ll p = uf.find(i);
    std::cout << uf.sz[p] << '\n';
  }
}

