class DisjointSet{
public:
  int N;
  vector<int> rank,p;
  vector<int> sz;

  DisjointSet(){}
  DisjointSet(int n):N(n),rank(n),p(n),sz(n){
    for(int i=0;i<N;i++) makeSet(i);
  }

  void makeSet(int x){
    p[x]=x;
    rank[x]=0;
    sz[x]=1;
  }

  bool same(int x,int y){
    return leader(x)==leader(y);
  }

  void unite(int x,int y){
    if(same(x,y)) return;
    link(leader(x),leader(y));
  }

  void link(int x,int y){
    if(rank[x]>rank[y]){
      p[y]=x;
      sz[x]+=sz[y];
    }else{
      p[x]=y;
      sz[y]+=sz[x];
      if(rank[x]==rank[y]){
        ++rank[y];
      }
    }
  }

  int leader(int x){
    if(x!=p[x]) p[x]=leader(p[x]);
    return p[x];
  }

  int size(int x){
    return sz[leader(x)];
  }
};

