struct node
{
    bool onecomp = true;
    int who = -1;
    int sz = 0;
    node(){}
};


node operator +(const node &a, const node &b) {
    if (a.sz == 0) {
        return b;
    }
    if (b.sz == 0) {
        return a;
    }
    node c;
    c.sz = a.sz + b.sz;
    if (a.onecomp && b.onecomp) {
        if (kek.leader(a.who) == kek.leader(b.who)) {
            c.who = kek.leader(a.who);
            c.onecomp = true;
            return c;
        }
    }
    c.who = -1;
    c.onecomp = false;
    return c;
}


node d[MAXN * 4];


void change(int i, int who) {
    i += ss - 1;
    d[i].who = who;
    d[i].onecomp = true;
    d[i].sz = 1;
    while (i >> 1 > 0) {
        i >>= 1;
        d[i] = d[i * 2] + d[i * 2 + 1];
    }
}


void merges(int v, int vl, int vr, int l, int r, int x) {
    if (l > r) {
        return;
    }
    if (d[v].sz == 0) {
        return;
    }
    if (vl > r || vr < l) {
        return;
    }
    if (l <= vl && vr <= r) {
        if (d[v].onecomp) {
            kek.merge(d[v].who, x);
            return;
        } else {
            merges(v * 2, vl, (vl + vr) / 2, l, r, x);
            merges(v * 2 + 1, (vl + vr) / 2 + 1, vr, l, r, x);
            d[v] = d[v * 2] + d[v * 2 + 1];
        }
        return;
    }
    merges(v * 2, vl, (vl + vr) / 2, l, r, x);
    merges(v * 2 + 1, (vl + vr) / 2 + 1, vr, l, r, x);
    d[v] = d[v * 2] + d[v * 2 + 1];
}

