        v_key_by_x[i] = x;
        y_to_x[y] = x;
    }
    sort(ALL(v));

    // anss[x] = answer
    vector<int> anss(N+1,-1);
    REPR(i,N-1) {
        auto [x,y] = v[i];
        if (called[y]) continue;
        int ans = 1;
        called[y] = true;
        auto ny = y - 1;
        // x座標
        set<int> st;
        while(!called[ny]) {
            ans++;
            called[ny] = true;
            st.insert(y_to_x[ny]);
            ny--;
        }
        anss[x] = ans;
        for(const auto &it: st) anss[it] = ans;
    }
    REP(i,N) cout << anss[v_key_by_x[i]] << endl;
}

