void solve(){
	int n;
	rd(n);
	vector<pint>a;
	map<pint,int>loc;
	FOR(i,n){
		int l,r;
		rd(l,r);
		a.pb({l,r});
		loc[{l,r}]=i;
	}	
	sort(all(a));
	map<int,int>f;
	f[n-1]=n-1;
	int mv=a[n-1].se;
	int mi=n-1;
	for(int i=n-2;i>=0;i--){
		if(a[i].se<mv){
			f[i]=mi;
		}
		else if(a[i].se>mv){
			f[i]=i;
			mv=a[i].se;
			mi=i;
		}
		else{
			f[i]=i;
		}
	}
	// for(auto v:f){
		// Error(v.ft,v.se);
	// }
	vector<int>prev;
	vector<int>ans(n);
	prev.pb(a[n-1].se);
	for(int i=n-2;i>=0;i--){
		int temp=upper_bound(all(prev),a[i].se)-prev.begin();
		if(temp==prev.size())ans[i]+=0;
		else ans[i]+=prev.size()-temp;
		prev.insert(prev.begin()+temp,a[i].se);
	}
	prev.clear();
	prev.pb(a[0].se);
	for(int i=1;i<n;i++){
		//val;
		int temp=upper_bound(all(prev),a[i].se)-prev.begin();
		if(temp==prev.size())ans[i]+=prev.size();
		else ans[i]+=temp;
		prev.insert(prev.begin()+temp,a[i].se);
	}
	vector<int>Ans(n);
	for(int i=0;i<n;i++){
		ans[i]=ans[f[i]];
	}
	for(int i=0;i<n;i++){
		Ans[loc[a[i]]]=ans[i];
	}
	for(auto v:Ans)pp(v+1);
	return;	
}


