using city = tuple<int, int, int>;

int N;
vector<city> c; // xについて昇順

void input(void){
  cin >> N;
  c.resize(N);
  for (int i = 0; i < N; ++i){
    int x, y; cin >> x >> y;
    --x, --y;
    c[i] = {x, y, i};
  }
  sort(c.begin(), c.end());
}

void random_case(int N_max){
  random_device seed_gen;
	mt19937_64 rnd(seed_gen());
  N = rnd() % N_max + 1;
  vector<int> y(N);
  for (int i = 0; i < N; ++i)
    y[i] = i;
  shuffle(y.begin(), y.end(), rnd);
  vector<int> id(N);
  for (int i = 0; i < N; ++i)
    id[i] = i;
  shuffle(id.begin(), id.end(), rnd);
  c.resize(N);
  for (int i = 0; i < N; ++i)
    c[i] = {i, y[i], id[i]};
}

vector<int> solve_naive(void){
  dsu uf(N);
  for (int i = 0; i < N; ++i){
    for (int j = i + 1; j < N; ++j){
      int x1 = get<0>(c[i]), y1 = get<1>(c[i]);
      int x2 = get<0>(c[j]), y2 = get<1>(c[j]);
      int id1 = get<2>(c[i]), id2 = get<2>(c[j]);
      if (x1 < x2 && y1 < y2)
        uf.merge(id1, id2);
    }
  }
  vector<int> ret(N);
  for (int i = 0; i < N; ++i)
    ret[i] = uf.size(i);
  return ret;
}

vector<int> solve(void){
  dsu uf(N);
  using pii = pair<int, int>;
  set<pii> seen;
  for (auto& ci : c){
    pii now = {get<1>(ci), get<2>(ci)};
    if (seen.size() == 0 || (*seen.begin()).first > now.first){
      seen.insert(now);
      continue;
    }
    auto iter = seen.lower_bound(now);
    --iter; // now以下の最後のiterator
    (void)uf.merge((*iter).second, now.second);
    for (auto i = seen.begin(); i != iter;){
      // iとi+1の間に辺を張る
      if (i == iter) break;
      int id1 = (*i).second;
      ++i;
      int id2 = (*i).second;
      (void)uf.merge(id1, id2);
      seen.erase(i);
    } 
  }
  vector<int> ret(N);
  for (int i = 0; i < N; ++i)
    ret[i] = uf.size(i);
  return ret;
}

void test(void){
  random_case(2000);
  vector<int> res1 = solve();
  vector<int> res2 = solve_naive();
  bool ok = true;
  for (int i = 0; i < N; ++i)
    ok &= res1[i] == res2[i];
  if (ok) cout << "OK." << endl;
  else cout << "!!!NG!!!" << endl;
}

