class UnionFind {
    vector<int> par;
    vector<int> rank;
    vector<int> size;
    vector<vector<int>> group;
public:
    UnionFind(int n = 1) {
        par.resize(n + 1);
        rank.resize(n + 1);
        size.resize(n + 1);
        group.resize(n + 1);
        for (int i = 0; i <= n; ++i) {
            par[i] = i;
            rank[i] = 0;
            size[i] = 1;
            group[i].push_back(i);
        }
    }

    int find(int x) {
        if (par[x] == x) {
            return x;
        } else {
            int r = find(par[x]);
            return par[x] = r;
        }
    }

    bool is_same(int x, int y) {
        return find(x) == find(y);
    }

    bool unit(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) {
            return false;
        } else {
            if (rank[x] < rank[y]) {
                swap(x, y);
            }
            if (rank[x] == rank[y]) {
                ++rank[x];
            }
            par[y] = x;
            size[x] += size[y];
            return true;
        }
    }

    int get_size(int x) {
        return size[find(x)];
    }

    void merge(int x, int y) {
        x = find(x);
        y = find(y);
        if (group[x].size() > group[y].size()) {
            swap(x, y);
        }
        copy(group[y].begin(), group[y].end(), back_inserter(group[x]));
        group[y].clear();
        par[y] = x;
    }
};

void solve() {
    ll N;
    cin >> N;
    vector<pair<P, ll>> items(N);
    rep(i, N) {
        ll x, y;
        cin >> x >> y;
        items[i] = make_pair(make_pair(x, y), i);
    }
    sort(items.begin(), items.end());
    set<P> used;
    UnionFind unionFind(N);
    rep(i, N) {
        ll x = items[i].first.first;
        ll y = items[i].first.second;
        ll idx = items[i].second;
        P p = make_pair(y, idx);
        if (!used.empty() && used.begin()->first < y) {
            for (auto it = used.begin(); it != used.end();) {
                auto u = *it;
                if (u.first < y) {
                    unionFind.unit(u.second, idx);
                    it = used.erase(it);
                    if (p.first > u.first) {
                        p = u;
                    }
                } else {
                    break;
                }
            }
        }
        used.insert(p);
    }
    rep(i, N) {
        cout << unionFind.get_size(i) << '\n';
    }
}

