void make_set(int v,int* parent) {
  parent[v] = v;
}

int find_set(int v,int* parent) {
    if (v == parent[v])
        return v;
    return parent[v] = find_set(parent[v],parent);
}

void union_sets(int a, int b,int* parent) {
  a = find_set(a,parent);
  b = find_set(b,parent);
  if (a != b)
    parent[b] = a;
}


