			if (points[p].x < points[n].x) {
				UF.unit(p, n);
				minx = p;
				q.pop();
			}
			else break;
		}
		q.push(minx);
	}
	VI ans(N);
	for (int n = 0; n < N; n++) {
		ans[points[n].id] = UF.size(n);
