struct UnionFind{
    vector<ll> parent;
    vector<ll> s;

    UnionFind(ll n){
        parent.resize(n);
        s.resize(n, 1);
        for(int i = 0; i < n; i++) parent[i] = i;
    }

    ll root(ll node){
        if(parent[node] == node){
            return node;
        } else {
            return parent[node] = root(parent[node]);
        }
    }

    void unite(ll x, ll y){
        ll rootx = root(x);
        ll rooty = root(y);
        if(rootx == rooty) return;
        if(s[rootx] < s[rooty]) swap(rootx, rooty);
        s[rootx] += s[rooty];
        parent[rooty] = rootx;
    }

    bool isSame(ll x, ll y){
        return root(x) == root(y);
    }

    ll size(ll x){
        return s[root(x)];
    }
};
