        return l.sec.fir<r.sec.fir;
    });
    for (int i=0;i<n;i++){
        upd(1,1,n,i+1,1,mp(a[i].sec.sec,i));
        upd(1,1,n,i+1,0,mp(a[i].sec.sec,i));
    }
    int cur_comp_id=0;
    for (int i=0;i<n;i++){
        if (!id_of_comp[i]){
            dfs(i,++cur_comp_id);
        }
    }
    for (int i=0;i<n;i++){
        int cur_ans=size_of_comp[id_of_comp[i]];
        ans[a[i].fir]=cur_ans;
    }
    for (int i=0;i<n;i++){
        cout<<ans[i]<<"\n";
    }
}

