	{
		++i;
		while (i <= sz)
		{
			vec[i - 1] = op(vec[i - 1], val);
			i += i & -i;
		}
	}
	auto get(int i)const
	{
		++i;
		T ret{};
		while (i != 0)
		{
			ret += vec[i - 1];
			i -= i & -i;
		}
		return ret;
	}
};

void Main()
{
	std::size_t N;
	std::cin >> N;
	std::vector<lib::pair<index_t>> points(N);
	std::vector<index_t> inverse(N), result(N), highest(N);
	binary_indexed_tree<index_t> count(N);
	for (auto& [x, y] : points)
	{
		std::cin >> x >> y;
		--x; --y;
		inverse[y] = x;
	}
	auto sorted = points;
	boost::sort(sorted);
	for (auto [x, y] : sorted)
	{
		count.add(y, 1);
		result[x] = count.get(y);
	}
	std::set<index_t> ys;
	for (auto [x, y] : sorted | adaptor::reversed)
	{
		auto ite = ys.lower_bound(y);
		if (ite != ys.end())
		{
			result[x] = result[inverse[*ite]];
		}
		ys.emplace(y);
	}
	for (auto [x, y] : points)
	{
		std::cout << result[x] << std::endl;
	}
}

