class Timer {
   private:
    chrono::system_clock::time_point start;  // 開始時間
    int limit;                               // 設定時間 [ms]

   public:
    // コンストラクタ l: 設定時間 [ms]
    Timer(int l) {
        start = chrono::system_clock::now();
        limit = l;
    }
    // 現在時間と開始時間の差[ms]
    int get() {
        chrono::system_clock::time_point now = chrono::system_clock::now();
        int dur =
            chrono::duration_cast<chrono::milliseconds>(now - start).count();
        return dur;
    }
    // 設定時間を経過したか
    bool isExpired() {
        int dur = get();
        if (limit < 0) return false;
        return dur > limit ? true : false;
    }
};

