template<class T> T gi() {
	T now = 0, s = 1; char d = ' ';
	while (d != '-' && (d < '0' || d > '9')) d = getchar();
	if (d == '-') s = -1; else now = d - '0';
	while (d = getchar(), d >= '0' && d <= '9') now = now * 10 + d - '0';
	return now * s;
}

