#include <bits/stdc++.h>
using namespace std;

const int maxn = 200010;
int n, tot, tmp[maxn], pre[maxn], suf[maxn], ans[maxn];
int mn[maxn][20], mx[maxn][20];
pair<int, int> p[maxn];

int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) {
        scanf("%d %d", &p[i].first, &p[i].second);
        tmp[i] = p[i].first;
    }
    sort(p + 1, p + n + 1);
    for (int i = 1; i <= n; i++) {
        mn[i][0] = mx[i][0] = p[i].second;
    }
    for (int i = 1; i < 20; i++) {
        for (int j = 1; j + (1 << i) - 1 <= n; j++) {
            mn[j][i] = min(mn[j][i - 1], mn[j + (1 << (i - 1))][i - 1]);
            mx[j][i] = max(mx[j][i - 1], mx[j + (1 << (i - 1))][i - 1]);
        }
    }
    auto qmin = [&](int x, int y) {
        int k = log2(y - x + 1);
        return min(mn[x][k], mn[y - (1 << k) + 1][k]);
    };
    auto qmax = [&](int x, int y) {
        int k = log2(y - x + 1);
        return max(mx[x][k], mx[y - (1 << k) + 1][k]);
    };
    for (int i = 1; i <= n; i++) {
        int l = 1, r = i, ans;
        while (l <= r) {
            int mid = (l + r) >> 1;
            if (qmin(1, mid) <= p[i].second) r = (ans = mid) - 1;
            else l = mid + 1;
        }
        pre[i] = ans;
    }
    for (int i = n; i; i--) {
        int l = i, r = n, ans;
        while (l <= r) {
            int mid = (l + r) >> 1;
            if (qmax(mid, n) >= p[i].second) l = (ans = mid) + 1;
            else r = mid - 1;
        }
        suf[i] = ans;
    }
    for (int i = 1; i <= n; i++) {
        ans[i] = suf[i] - pre[i] + 1;
    }
    for (int i = 1; i <= n; i++) {
        ans[i] = max({ans[i], ans[pre[i]], ans[suf[i]]});
    }
    for (int i = 1; i <= n; i++) {
        printf("%d\n", ans[tmp[i]]);
    }
    return 0;
}

