using namespace std;

class UnionFindTree {
private:
    vector<int> parent;
    vector<int> count;

public:
    UnionFindTree(int n) : parent(n), count(n, 1) {
        for (int i = 0; i < n; i++) parent[i] = i;
    }
    int get_root(const int x) {
        if (parent[x] == x) return x;
        return parent[x] = get_root(parent[x]);
    }
    void unite(const int x, const int y) {
        int rx = get_root(x), ry = get_root(y);
        if (rx == ry) return;
        parent[rx] = ry;
        count[ry] += count[rx];
        count[rx] = 0;
    }
    bool is_same_root(const int x, const int y) {
        return get_root(x) == get_root(y);
    }
    int get_size(const int x) { return count[get_root(x)]; }
    void print() {
        for (auto elm : parent) cout << elm << " ";
        cout << endl;
        for (auto elm : count) cout << elm << " ";
        cout << endl;
    }
};
int main() {
    int n;
    cin >> n;
    vector<pair<int, int>> p(n), x(n);
    set<pair<int, int>> y;
    UnionFindTree tree(n);
    for (auto i = 0; i < n; i++) {
        cin >> p[i].first >> p[i].second;
        x[i] = {p[i].first, i};
    }
    sort(x.begin(), x.end());
    for (auto i = 0; i < n; i++) {
        // auto tmp =
        //     y.lower_bound({p[x[i].second].second, 0});
        for (auto itr = y.begin(); itr != y.end();) {
            if (itr->first > p[x[i].second].second) break;
            tree.unite(x[i].second, itr->second);
            if (itr == y.begin()) ++itr;
            else
                itr = y.erase(itr);
        }
        if (y.empty() or
            p[x[i].second].second < y.begin()->first)
            y.insert({p[x[i].second].second, x[i].second});
    }
    for (auto i = 0; i < n; i++)
        cout << tree.get_size(i) << endl;
    return 0;
}

