const int max_n = 200222, inf = 1000111222;

struct point {
    int x, y, id;

    bool operator < (const point &p) const {
        return x < p.x;
    }
};

template<typename T>
struct segment_tree {
    pair<T, int> mn[4 * max_n];

    void build(int v, int l, int r, T a[]) {
        if (l == r) {
            mn[v] = {a[l], l};
            return;
        }
        int mid = (l + r) / 2;
        build(2 * v, l, mid, a);
        build(2 * v + 1, mid + 1, r, a);
        mn[v] = min(mn[2 * v], mn[2 * v + 1]);
    }

    void update(int v, int l, int r, int x, T value) {
        if (l == r) {
            mn[v] = {value, l};
            return;
        }
        int mid = (l + r) / 2;
        if (x <= mid) {
            update(2 * v, l, mid, x, value);
        } else {
            update(2 * v + 1, mid + 1, r, x, value);
        }
        mn[v] = min(mn[2 * v], mn[2 * v + 1]);
    }

    pair<T, int> get_min(int v, int tl, int tr, int l, int r) {
        if (tl == l && tr == r) {
            return mn[v];
        }
        int mid = (tl + tr) / 2;
        if (r <= mid) {
            return get_min(2 * v, tl, mid, l, r);
        } else if (l > mid) {
            return get_min(2 * v + 1, mid + 1, tr, l, r);
        }
        return min(get_min(2 * v, tl, mid, l, mid), get_min(2 * v + 1, mid + 1, tr, mid + 1, r));
    }
};

#define y1 qwe
#define y2 qwer

int n, ans[max_n], used[max_n], sz[max_n], comps;
int y1[max_n], y2[max_n];
point p[max_n];
segment_tree<int> t1, t2;

void dfs(int v) {
    //cout << v << endl;
    ++sz[comps];
    used[v] = comps;
    y1[v] = inf;
    y2[v] = inf;
    t1.update(1, 0, n - 1, v, y1[v]);
    t2.update(1, 0, n - 1, v, y2[v]);
    while (true) {
        pair<int, int> mn = t1.get_min(1, 0, n - 1, 0, v);
        if (mn.first >= p[v].y) {
            break;
        }
        dfs(mn.second);
    }
    while (true) {
        pair<int, int> mn = t2.get_min(1, 0, n - 1, v, n - 1);
        if (mn.first >= -p[v].y) {
            break;
        }
        //cout << "@" << mn.first << " " << mn.second << " " << p[v].y << endl;
        dfs(mn.second);
    }
}

int main() {
    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);
    scanf("%d", &n);
    for (int i = 0; i < n; ++i) {
        scanf("%d%d", &p[i].x, &p[i].y);
        --p[i].x;
        --p[i].y;
        p[i].id = i;
    }
    sort(p, p + n);
    for (int i = 0; i < n; ++i) {
        y1[i] = p[i].y;
        y2[i] = -p[i].y;
    }
    t1.build(1, 0, n - 1, y1);
    t2.build(1, 0, n - 1, y2);
    memset(used, -1, sizeof(used));
    for (int i = 0; i < n; ++i) {
        if (used[i] == -1) {
            dfs(i);
            ++comps;
        }
    }
    for (int i = 0; i < n; ++i) {
        ans[p[i].id] = sz[used[i]];
    }
    for (int i = 0; i < n; ++i) {
        printf("%d\n", ans[i]);
    }
    return 0;
}

