int find(int u){
    if(p[u]==u) return u;
    else return p[u] = find(p[u]);
}

void merge(int u,int v){
    int x = find(u), y = find(v);
    if(x!=y){
        p[y] = x;
        size[x] += size[y];
    }
}

void solve(int n){
    for(int i = 1; i <= n; i++) p[i] = i, size[i] = 1;
    int t = 0;
    for(int i = 1; i <= n; i++){
        int u = d[i];
        while(t!=0 && u>d[stack[t]]){ 
            int j = stack[t];
            merge(i,j);
            t--;
        }
        stack[++t] = i;
    }
    t = 0;
    for(int i = n; i >= 1; i--){
        int u = d[i];
        while(t!=0 && u<d[stack[t]]){ 
            int j = stack[t];
            merge(i,j);
            t--;
        }
        stack[++t] = i;
    }
}

