using namespace std;
typedef long long ll;

struct UnionFind{
    vector<ll> par;//親のid

    UnionFind(ll N) : par(N) { //最初は全てが根であるとして初期化
        for(ll i = 0; i < N; i++) par[i] = i;
    }

    ll root(ll x){// データxが属する木の根を再帰で得る：root(x) = {xの木の根}
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    bool unite(ll x, ll y){// xとyの木を併合
        ll rx = root(x);//xの根
        ll ry = root(y);//yの根
        if (rx == ry) return false; //xとyの根が同じ(=同じ木にある)時はそのまま
        par[rx] = ry; //xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
        return true;
    }

    bool same(ll x, ll y){// 2つのデータx, yが属する木が同じならtrueを返す
        ll rx = root(x);
        ll ry = root(y);
        return rx == ry;
    }
};

int main()
{
    ll N;
    cin >> N;

    UnionFind UF(N);

    vector<ll> x(N);
    vector<ll> y(N);

    for (ll i = 0; i < N; i++)
    {
        cin >> x[i] >> y[i];
    }

    for(ll i = 0; i < N; i++){
        for(ll j = i + 1; j < N; j++){
            if((x[i] - x[j]) > 0 && (y[i] - y[j]) > 0){
                UF.unite(i,j);
            }
            else if((x[i] - x[j]) < 0 && (y[i] - y[j]) < 0){
                UF.unite(i,j);
            }
        }
    }

    vector<ll> res(200010,1);
    for (ll i = 0; i < N; i++){
        for(ll j = i + 1; j < N; j++){
            if(UF.same(i,j)){
                res[i] += 1;
                res[j] += 1;
                }
        }
    }

    for (ll i = 0; i < N; i++){
        cout << res[i] << endl;
    }

    return 0;
}

