struct city{
	int x;
	int y;
	int num;
	int ans;
};

bool comp_city_x(city &c1,city &c2){
	return c1.x<c2.x;
}

bool comp_city_n(city &c1,city &c2){
	return c1.num<c2.num;
}

int main(){
	int N;
	cin >> N;
	vector<city> C(N);
	for(int i=0;i<N;i++){
		int X,Y;
		cin >> X >> Y;
		C[i].x=X;
		C[i].y=Y;
		C[i].num=i;
	}

	sort(C.begin(),C.end(),comp_city_x);

	if(C[N-1].y==N){
		for(int i=0;i<N;i++)cout << N << endl;
		return 0;
	}

	dsu d(N);

	vector<bool> flag(N,false);
	vector<int> m(N,0);
	m[N-1]=C[N-1].y;
	for(int i=N-2;i>=0;i--)m[i]=max(m[i+1],C[i].y);
	for(int i=0;i<N;i++){
		if(flag[i])continue;
		int M=0,Mi=i;
		for(int j=i+1;j<N;j++){
			if(C[i].y>m[j])break;
			if(C[i].y<C[j].y){
				d.merge(i,j);
				flag[j]=true;
				if(M<C[j].y){
					flag[Mi]=true;
					Mi=j;
					M=C[j].y;
				}
			}
		}
	}

	for(int i=0;i<N;i++)C[i].ans=d.size(i);

	sort(C.begin(),C.end(),comp_city_n);

	for(int i=0;i<N;i++)cout << C[i].ans << endl;

	return 0;
}

