vector<int>par;
vector<int>S;
void init(int N) {
  par.resize(N + 1);
  S.resize(N + 1);
  for (int i = 0; i <= N; i ++) {
    par[i] = i;
    S[i] = 1;
  }
}
int root(int v) {
  if (v == par[v]) return v;
  return par[v] = root(par[v]);
}
int siz(int v) {
  return S[root(v)];
}
void merge(int a, int b) {
  a = root(a);
  b = root(b);
  if (a == b) return;
  if (siz(a) < siz(b)) swap(a, b);
  par[b] = a;
  S[a] += S[b];
}

