	T(){}
	T(int _F , int _S , int _id):F(_F),S(_S),id(_id){}
	bool operator<(const T &x)const{
		if(F != x.F) return F < x.F;
		return S < x.S;
	}
};
struct dsu{
	vector<int> fa , sz;
	dsu(int _n){
		fa.resize(_n+1) , sz.resize(_n+1);
		for(int i=0 ; i<=_n ; ++i){
			fa[i] = i;
			sz[i] = 1;
		}
	}
	void resize(int _n){
		fa.resize(_n+1) , sz.resize(_n+1);
		for(int i=0 ; i<=_n ; ++i){
			fa[i] = i;
			sz[i] = 1;
		}
	}
	int Find(int _x){
		if(_x == fa[_x]) return _x;
		return fa[_x] = Find(fa[_x]);
	}
	void Union(int _a, int _b){
		_a = Find(_a) , _b = Find(_b);
		if(_a == _b) return;
		if(sz[_a] < sz[_b]) swap(_a , _b);
		fa[_b] = _a;
		sz[_a] += sz[_b];
	}

};
