int father(int a){
	if(fa[a]==a)return a;
	fa[a]=father(fa[a]);
	return fa[a];
}
int find(int a){
	if(cnt1>cnt2)return 0;
	if(a<k[cnt2])return 0;
	int l=cnt1,r=cnt2;
	while(l<r){
		int mid=(l+r)/2;
		if(k[mid]<=a)r=mid;
		else l=mid+1;
	}
	return l;
}
void add(int a,int b){
	int s=find(a);
	if(s==0){
		cnt2++;
		fa[cnt2]=cnt2;
		id[b]=cnt2;
		p[cnt2]=1;
		k[cnt2]=a;
	}else{
		id[b]=father(s);
		p[father(s)]++;
		for(int i=s+1;i<=cnt2;i++){
			if(father(i)!=father(s)){
				p[father(s)]=p[father(s)]+p[father(i)];
				p[father(i)]=0;
				fa[father(i)]=father(s);
			}
		}
	}
}
