  ans[xy[N-1].second]=count;
  for(int i=N-2;i>=0;i--){
    if(cnt[i+1]==1){
      count=cnt[i];
    }
    ans[xy[i].second]=count;
  }
  for(int i=0;i<N;i++){
    cout<<ans[i]<<endl;
  }
}

