            int sum = 0;
            int mymin = vec[i].y;
            {
                  int lo = 0;
                  int hi = i - 1;
                  int id = i;
                  while (lo <= hi) {
                        int mid = lo + hi >> 1;
                        int mini = mint.query(0, mid);
                        if (mini < mymax) {
                              id = mid;
                              hi = mid - 1;
                        }
                        else {
                              lo = mid + 1;
                        }
                  }
                  int lft = i - id;
                  sum += lft;
                  mymin = mint.query(id, i);
            }
            {
