using namespace std;

struct UnionFind{
  vector<int64_t> S;
  vector<int64_t> weight;

  UnionFind(int N){
    S = vector<int64_t>(N,0);
    weight = vector<int64_t>(N,1);
    for(int i = 0 ; i < N ; i++){
      S.at(i) = i;
      weight.at(i) = 1;
    }
  }

  int root(int x) { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
    if(S.at(x) == x){
     return x; 
    }
    return S.at(x) = root(S.at(x));
  }

  void unite(int x, int y) { // xとyの木を併合
    int rx = root(x); //xの根をrx
    int ry = root(y); //yの根をry
    //cout << rx << ":" << ry <<endl;
    if (rx == ry){
      return;
    }
    if (S.at(x) > S.at(y)){
      swap(x, y);
    }
    //cout << x << ":" << y <<endl;
    weight.at(S.at(x)) += weight.at(S.at(y));
    S.at(y) = S.at(x);
    return; //xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
  }

  int size(int x){
    int rx = root(x);
    return weight.at(rx);
  }

  bool same(int x, int y) { // 2つのデータx, yが属する木が同じならtrueを返す
    int rx = root(x);
    int ry = root(y);
    return rx == ry;
  }

};

int main(){//main_program
  int N;
  cin >> N;
  vector<tuple<int, int, int>> S(N);
  vector<int> x(N);
  vector<int> y(N);
  vector<int> z(N);


  UnionFind tree(N);

  for(int i = 0;i < N;i++){
    int a,b;
    cin >> a >> b;
    S.at(i) = make_tuple(a, b, i);
  }
  sort(S.begin(), S.end());

  for(int i = 0;i < N;i++){
    int a,b,c;
    tie(a,b,c) = S.at(i);
    x.at(i) = a;
    y.at(i) = b;
    z.at(i) = c;
  }


  for(int i = 0;i < N;i++){
    for(int l = 0;l < x.at(i);l++){
      if(tree.same(z.at(i),z.at(l)) ==0){
        if(y.at(l) < y.at(i)){
          tree.unite(z.at(i),z.at(l));
        }
      }
    }
    for(int l = x.at(i)+1;l < N;l++){
      int a,b,c;
      tie(a,b,c) = S.at(l);
      if(tree.same(z.at(i),z.at(l)) ==0){
        if(y.at(l) > y.at(i)){
          tree.unite(z.at(i),z.at(l));
        }
      }
    }
  }

  for(int i = 0;i < N;i++){
    cout << tree.size(i) << endl;
  }

}

