#define REP(i,n) for (ll i = 0; i < (n); ++i)
#define RREP(i, n) for (ll i = (n) - 1; i >= 0; --i)
#define ALL(v) (v).begin(), (v).end()
template<class T>
using reverse_priority_queue = priority_queue<T, vector<T>, greater<T>>;


struct union_find {
    vector<ll> par;
    vector<ll> rank;
    vector<ll> count;

    union_find(ll n) : par(n, 0), rank(n, 0), count(n, 1) {
        for(ll i = 0; i < n; ++i){ par.at(i) = i; }
    }

    ll find(ll x){
        if(par.at(x) == x){
            return x;
        }else{
            return par.at(x) = find(par.at(x));
        }
    }

    void unite(ll x, ll y){
        x = find(x);
        y = find(y);
        if(x == y){ return; }
        if(rank.at(x) < rank.at(y)){
            par.at(x) = y;
        }else{
            par.at(y) = x;
            if(rank.at(x) == rank.at(y)){
                rank.at(x)++;
            }
        }

        ll new_count = count.at(x) + count.at(y);
        count.at(find(x)) = new_count;
    }

    bool same(ll x, ll y){
        return find(x) == find(y);
    }

    ll size(ll x){
        return count.at(find(x));
    }
};


int main(){
    ll n;
    cin >> n;

    vector<array<ll, 3>> xy(n);
    REP(i, n){
        cin >> xy.at(i).at(0) >> xy.at(i).at(1);
        xy.at(i).at(0)--;
        xy.at(i).at(1)--;
        xy.at(i).at(2) = i;
    }
    sort(ALL(xy));

    union_find uf(n);

    {
        set<pair<ll, ll>> ys1;
        REP(i, n){
            const auto& a = xy.at(i);
            const ll idx = a.at(2);
            const ll y = a.at(1);
            auto it = ys1.lower_bound(make_pair(y, 0));
            if(it != ys1.begin()){
                --it;
                uf.unite(it->second, idx);
            }
            if(ys1.size() && ys1.begin()->first < y){
                uf.unite(ys1.begin()->second, idx);
            }

            ys1.insert(make_pair(y, idx));
        }
    }

    {
        set<pair<ll, ll>> ys2;
        RREP(i, n){
            const auto& a = xy.at(i);
            const ll idx = a.at(2);
            const ll y = a.at(1);
            auto it = ys2.lower_bound(make_pair(y, 0));
            if(it != ys2.end()){
                uf.unite(it->second, idx);
            }
            if(ys2.size() && ys2.rbegin()->first > y){
                uf.unite(ys2.rbegin()->second, idx);
            }

            ys2.insert(make_pair(y, idx));
        }
    }

    REP(i, n){
        cout << uf.size(i) << endl;
    }
    return 0;
}

