struct DSU
{
	vector<int>par;
	vector<int>sz;

	DSU(int n)
	{
		par.resize(n+1);
		iota(par.begin(),par.end(),0);
		sz.assign(n+1,1);
	}

	int Find(int a)
	{
		return par[a]==a?a:par[a]=Find(par[a]);
	}

	bool same(int a,int b)
	{
		a=Find(a);
		b=Find(b);
		return a==b;
	}

	void Union(int a,int b)
	{
		a=Find(a);
		b=Find(b);

		if(sz[a]<sz[b]) swap(a,b);
		sz[a]+=sz[b];
		par[b]=a;
	}
};


void solve()
{
	int n;
	cin>>n;

	vector<pair<pii,int>>edge(n);
	for(int i=0;i<n;i++)
	{
		pii x;
		cin>>x.first>>x.second;
		edge[i].first=x;
		edge[i].second=i+1;
	}

	sort(edge.begin(),edge.end());
	map<int,int>parent;
	for(auto it: edge) parent[it.first.second]=it.second;

	//for(auto it: edge) cout<<it.first.first<<" "<<it.first.second<<" "<<it.second<<"\n";

	DSU dsu(n);

	set<int>st;

	for(int i=n-1;i>=0;i--)
	{
		st.insert(edge[i].first.second);
		auto it=st.upper_bound(edge[i].first.second);
		int u=-1;
		while(it!=st.end())
		{
			u=*it;
			int v=parent[u];
			if(!dsu.same(v,edge[i].second)) dsu.Union(v,edge[i].second);
			parent[u]=dsu.Find(v);
			st.erase(u);
			it=st.upper_bound(u);
		}
		st.insert(u);
		if(u!=-1) st.erase(edge[i].first.second);
		debug(st);
	}

	for(int i=1;i<=n;i++)
	{
		int x=dsu.Find(i);
