	int p[200005];
	int s[200005];

	UFDS(){
		rep(x,0,200005){
			p[x]=x;
			s[x]=1;
		}
	}

	int parent(int i){
		if (p[i]==i) return i;
		else return p[i]=parent(p[i]);
	}

	void unions(int i,int j){
		i=parent(i),j=parent(j);

