struct UnionFind {
    vector<int> par; // par[i]:iの親の番号　(例) par[3] = 2 : 3の親が2

    UnionFind(int n) : par(n) { //最初は全てが根であるとして初期化
        for(int i = 0; i < n; i++) par[i] = i;
    }

    int root(int x) { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void unite(int x, int y) { // xとyの木を併合
        int rx = root(x); //xの根をrx
        int ry = root(y); //yの根をry
        if (rx == ry) return; //xとyの根が同じ(=同じ木にある)時はそのまま
        par[rx] = ry; //xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
    }

    bool same(int x, int y) { // 2つのデータx, yが属する木が同じならtrueを返す
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
};

int main() {
    input();
    UnionFind uf(N);
    set<P> ylist;
    vector<T> w;
    rep(i, N) {
        ylist.insert(P(y[i], i));
        w.push_back(tuple(x[i], y[i], i));
    }
    sort(w.begin(), w.end());
    set<int> s;
    for (T t : w) {
        int x_, y_, i;
        tie(x_, y_, i) = t;
        ylist.erase(P(y_, i));
        if (s.count(i)) continue;
        s.insert(i);
        auto itr = ylist.upper_bound(P(y_, i));
        while (itr != ylist.end()) {
            int j = itr->second;
            uf.unite(i, j);
            s.insert(j);
            itr++;
        }
    }
    map<int, int> m;
    rep(i, N) m[uf.root(i)]++;
    rep(i, N) cout << m[uf.root(i)] << endl;
}

