class DSU
{
	private:
	static bool verbose;
	int sz;
	vector<int> rank, parent, sizes;

	void printComponent(int id)
	{
		cout << "Component " << id << " size: " << getSize(id) << " | ";
		int p_id = Find(id);
		for(int i = 0; i < sz + 1; i++)
		{
			if(p_id == parent[i])
			{
				cout << i << " ";
			}
		}

		cout << endl;
	}

	void printMessage(string s)
	{
		cout << "================================" << endl;
		cout << s << endl;
		cout << "================================" << endl;
		cout << endl;
	}

	public:
	DSU(int n)
	{
		sz = n;
		rank.resize(n + 1, 0);
		parent.resize(n + 1);
		sizes.resize(n + 1, 1);

		for(int i = 0; i < n + 1; i++)
		{
			parent[i] = i;
		}

		if(verbose)
			printMessage("DSU Initialised.");
	}

	int Find(int i)
	{
		// use path compression
		if(i != parent[i])
		{
			parent[i] = Find(parent[i]);
		}

		return parent[i];
	}

	void Union(int i, int j)
	{
		int i_id = Find(i);
		int j_id = Find(j);

		if(i_id == j_id)
			return;

		if(rank[i_id] >= rank[j_id])
		{
			if(verbose)
				printMessage(to_string(i_id) + " size: " + to_string(sizes[i_id]) + " <-------------- " + to_string(j_id) + " size: " + to_string(sizes[j_id]) + " Final Size: " + to_string(sizes[i_id] + sizes[j_id]));
			sizes[i_id] += sizes[j_id];
			sizes[j_id] = 0;
			parent[j_id] = i_id;

			if(rank[i_id] == rank[j_id])
				rank[i_id] += 1;
		}
		else
		{
			if(verbose)
				printMessage(to_string(j_id) + " size: " + to_string(sizes[j_id]) + " <-------------- " + to_string(i_id) + " size: " + to_string(sizes[i_id]) + "Final Size: " + to_string(sizes[i_id] + sizes[j_id]));
			sizes[j_id] += sizes[i_id];
			sizes[i_id] = 0;
			parent[i_id] = j_id;
		}
	}

	void Print()
	{
		for(int i = 0; i < sz + 1; i++)
		{
			printComponent(i);
		}
	}

	int getSize(int i)
	{
		return sizes[Find(i)];
	}

	static void Verbose()
	{
		verbose = true;
	}
};

