int32_t main()
{
	int n;
	cin >> n;

	vector< pair<int, int> > arr(n);
	for(int i = 0; i < n; i++)
	{
		cin >> arr[i].first >> arr[i].second;
	}

	vector< pair<int, int> > temp = arr;

	sort(temp.begin(), temp.end());

	DSU dsu(n);

	// left pass
	int minm = temp[0].second;

	for(int i = 1; i < n; i++)
	{
		if(minm < temp[i].second)
		{
			dsu.Union(minm, temp[i].second);
		}
		else
		{
			minm = temp[i].second;
		}
	}

	// right pass
	int maxm = temp[n-1].second;
	for(int i = n-2; i >= 0; i--)
	{
		if(maxm > temp[i].second)
		{
			dsu.Union(maxm, temp[i].second);
		}
		else
		{
			maxm = temp[i].second;
		}

	}

	//dsu.Print();

	for(int i = 0; i < n; i++)
	{
		cout << dsu.getSize(arr[i].second) << endl;
	}
	return 0;
}

