vector<int> solve(ll N, vector<int>& X, vector<int>& Y) {
    vector<pii> P(N);
    for ( int i = 0; i < N; i++ ) {
        P[i] = pii(X[i],Y[i]);
    }
    sort(P.begin(), P.end());
    vector<int> yr(N);
    int ym = N;
    for ( int i = 0; i < N; i++ ) {
        int y = P[i].second;
        ym = min(ym, y);
        yr[ym] = max(yr[ym], y);
    }
    for ( int i = 1; i < N; i++ ) {
        yr[i] = max(yr[i],yr[i-1]);
    }
    atcoder::dsu uy(N);
    for ( int i = 0; i < N; i++ ) {
        uy.merge(i,yr[i]);
    }
    vector<int> ans(N);
    for ( int i = 0; i < N; i++ ) {
        ans[i] = uy.size(Y[i]);
    }

    return ans;
}

vector<int> solve_small_1(ll N, vector<int>& X, vector<int>& Y) {
    atcoder::dsu uf(N);
    for ( int i = 0; i < N; i++ ) {
        for ( int j = 0; j < N; j++ ) {
            if ( X[i] < X[j] && Y[i] < Y[j] ) {
                uf.merge(i,j);
            }
        }
    }
    vector<int> ans(N);
    for ( int i = 0; i < N; i++ ) {
        ans[i] = uf.size(i);
    }
    return ans;
}
