int bfs(pair<int, int> st, std::vector<pair<int, int>> arr, int n, int ind) {
	vector<bool> visited(n, false);
	queue<int> q;
	q.push(ind);
	while (!q.empty()) {
		int curr_ind = q.front();
		visited[curr_ind] = true;
		q.pop();
		pair<int, int> curr = arr[curr_ind];
		for (int i = 0; i < n; i++) {
			if (visited[i] == false) {
				if (arr[i].second > curr.second && arr[i].first > curr.first) {
					visited[i] = true;
					q.push(i);
				}
				if (arr[i].second < curr.second && arr[i].first < curr.first) {
					visited[i] = true;
					q.push(i);
				}
			}
		}
	}
	int count = 0;
	for (int i = 0; i < n; i++) if (visited[i]) count += 1;
	return count;
}
int main() {
	int n; cin >> n;
	std::vector<pair<int, int>> arr(n);
	for (int i = 0; i < n; i++) {
		cin >> arr[i].first >> arr[i].second;
	}

	for (int i = 0; i < n; i++) {
		cout << bfs(arr[i], arr, n, i) << endl;
	}
	return 0;
}

