struct segment_tree_max {
    static const int N = 1e6 + 5;
    int t[2 * N + 5];
    void update(int pos, int val) {
        for (t[pos += N] = val; pos > 1; pos >>= 1) {
            t[pos >> 1] = max(t[pos], t[pos ^ 1]);
        }
    }
    int get(int l, int r) {
        int res = 0;
        for (l += N, r += N; l <= r; l >>= 1, r >>= 1) {
            if (l & 1) res = max(res, t[l++]);
            if (!(r & 1)) res = max(res, t[r--]);
        }
        return res;
    }
} tree_max;

struct segment_tree_min {
    static const int N = 1e6 + 5;
    int t[2 * N + 5];
    void update(int pos, int val) {
        for (t[pos += N] = val; pos > 1; pos >>= 1) {
            t[pos >> 1] = min(t[pos], t[pos ^ 1]);
        }
    }
    int get(int l, int r) {
        int res = N;
        for (l += N, r += N; l <= r; l >>= 1, r >>= 1) {
            if (l & 1) res = min(res, t[l++]);
            if (!(r & 1)) res = min(res, t[r--]);
        }
        return res;
    }
} tree_min;

struct Point {
    int x, y, id;
    bool operator<(const Point& ot) const {
        return std::tie(x, y, id) < std::tie(ot.x, ot.y, ot.id);
    }
};

const int N = 2e5 + 10;
Point a[N];
int a_inv[N];
int rig[N], ans[N];
int sc[N];

void solve(int n) {
    sort(a + 1, a + n + 1);
    for (int i = 1; i <= n; i++) {
        a_inv[a[i].y] = i;
    }
    for (int i = 1; i <= n; i++) {
        tree_min.update(i, a[i].y);
    }
    for (int i = n; i >= 1; i--) {
        tree_max.update(a[i].y, i);
        rig[i] = tree_max.get(a[i].y, n);
    }
    vector<pii> vec;
    for (int i = 1; i <= n; i++) {
        vec.pb({a[i].y, i});
    }
    sort(vec.begin(), vec.end());
    for (auto [val, i] : vec) {
        rig[i] = max(rig[i], rig[a_inv[tree_min.get(1, rig[i])]]);
    }
    for (int i = 1; i <= n; i++) {
        if (i < rig[i]) {
            sc[i + 1]++;
            sc[rig[i] + 1]--;
        }
    }
    for (int i = 1; i <= n; i++) {
        sc[i] += sc[i - 1];
        ans[a[i].id] = rig[i] - i + 1 + sc[i];
    }
}

