  for(int i = 0;i < N;i++){
    int x,y,z;
    tie(x,y,z) = S.at(i);
    for(int l = 0;l < x;l++){
      int a,b,c;
      tie(a,b,c) = S.at(l);
      if(b < y){
        tree.unite(z,c );
      }
    }
    for(int l = x+1;l < N;l++){
      int a,b,c;
      tie(a,b,c) = S.at(l);
      if(b > y){
        tree.unite(z,c);
      }
    }
  }

  for(int i = 0;i < N;i++){
    cout << tree.size(i) << endl;
  }

}

