vll adj[200001];
ll ans[200001];
ll vis[200001];

ll dfs(ll node) {
	vis[node] = 1;
	ll k = 1;
	for(auto i : adj[node]) {
		if(vis[i]) continue;
		k += dfs(i);
	}
	return k;
}

void dfs2(ll node, ll k) {
	vis[node] = 2;
	ans[node] = k;
	for(auto i : adj[node]) {
		if(vis[i] == 2) continue;
		dfs2(i,k);
	}
}

void solve(){
	ll i,j,_;
	ll n;
	cin >> n;
	vector<pair<pll,ll> >  v(n);
	rep(i,0,n) cin >> v[i].F.F >> v[i].F.S, v[i].S = i;
	ll l[n] = {0}, r[n] = {0};
	sort(v.begin(),v.end());
	ll mn = -1, ind = -1;
	for(auto i : v) {
		if(mn == -1) {
			mn = i.F.S;
			ind = i.S;
			continue;
		}
		if(mn < i.F.S) {
			adj[ind].pb(i.S);
			adj[i.S].pb(ind);
		}else {
			mn = i.F.S;
			ind = i.S;
		}
	}
	reverse(v.begin(),v.end());
	mn = -1, ind = -1;
	for(auto i : v) {
		if(mn == -1) {
			mn = i.F.S;
			ind = i.S;
			continue;
		}
		if(mn > i.F.S) {
			adj[ind].pb(i.S);
			adj[i.S].pb(ind);
		}else {
			mn = i.F.S;
			ind = i.S;
		}
	}
	rep(i,0,n) {
		if(vis[i] == 0) {
			ll k = dfs(i);
			dfs2(i,k);
		}
	}
	rep(i,0,n) cout << ans[i] << endl;
}

