void solve(long long N, std::vector<long long> x, std::vector<long long> y) {
  auto dsu = atcoder::dsu(N + 1);
  vector<pair<ll, pair<ll, ll>>> v(N);
  REP(i, N) {
    v[i] = make_pair(x[i], make_pair(y[i], i));
  }
  sort(ALL(v));
  reverse(ALL(v));
  map<ll, ll> m;
  REP(i, N) {
    ll yy = v[i].second.first;
    ll ii = v[i].second.second;
    auto it = m.lower_bound(yy);
    while (it != m.end()) {
      dsu.merge(ii, it->second);
      it++;
    }
    m[yy] = ii;
  }
  REP(i, N) {
    cout << dsu.size(i) << endl;
  }
}

