struct UnionFind {
    vector<int> par, sz;

    UnionFind(int n) : par(n), sz(n, 1) {
        for (int i = 0; i < n; ++i) par[i] = i;
    }

    int root(int x) {
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void merge(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y) return;
        if (sz[x] < sz[y]) swap(x, y);
        par[y] = x;
        sz[x] += sz[y];
        sz[y] = 0;
    }

    bool issame(int x, int y) {
        return root(x) == root(y);
    }

    int size(int x) {
        return sz[root(x)];
    }
};

void solve() {
    int N;
    cin >> N;
    vector<pair<int, int>> xy(N);
    vector<pair<int, int>> xi(N);
    REP(i, N) {
        cin >> xy[i].first >> xy[i].second;
        xy[i].first--;
        xy[i].second--;
        xi[i] = {xy[i].first, i};
    }
    sort(ALL(xy));

    vector<int> gmin(N), gmax(N);
    for (int i = 0; i < N; ++i) {
        gmin[i] = xy[i].second;
        gmax[i] = xy[i].second;
    }

    UnionFind uf(N);
    while (true) {
        bool merge = false;
        for (int i = 0; i + 1 < N; ++i) {
            if (uf.issame(i, i + 1)) {
                continue;
            }
            if (gmin[uf.root(i)] < gmax[uf.root(i + 1)]) {
                gmin[uf.root(i)] = min(gmin[uf.root(i)], gmin[uf.root(i + 1)]);
                gmax[uf.root(i)] = max(gmax[uf.root(i)], gmax[uf.root(i + 1)]);

                gmin[uf.root(i + 1)] = gmin[uf.root(i)];
                gmax[uf.root(i + 1)] = gmax[uf.root(i)];

//                cerr << "merge " << uf.root(i) << " " << uf.root(i + 1) << endl;

                uf.merge(i, i + 1);
                merge = true;
            }
        }

        if (!merge) break;
    }
    for (int i = 0; i < N; ++i) {
        cout << uf.size(xi[i].first) << endl;
    }


}


