  vi ans(N, 1);

  UnionFindTree tree(N);
  set<pi> y_min; // y_min, root indices
  i64 x;
  REP(0, N, x) {
    i64 ym = y[x];
    for(auto p=y_min.begin(); p!=y_min.end();) {
      i64 yc = p->first;
      i64 rc = p->second;
      if(yc > y[x]) {
	break;
      }
      else {
	tree.merge(x, rc);
	ym = min(ym, yc);
	p = y_min.erase(p);
      }
    }
    y_min.insert({ym, tree.find_root(x)});
  }

  REP(0, N, i) {
    ans[idx[i]] = tree.count[tree.find_root(i)];
  }

  REP(0, N, i) {
    assert(ans[i] != -1);
    printf("%lld\n", ans[i]);
  }

  return 0;
}

