int main() {

	int N, M;
	cin >> N >> M;

	vector<string> S(N);
	rep(i, N)cin >> S[i];

	mcf_graph<int, int> G(N*M + 2);

	int s = N * M;
	int t = N * M + 1;
	int ans = 0;
	rep(i, N) {
		rep(j, M) {
			if (S[i][j] == '#') {
				continue;
			}
			//元、先、容量、コスト
			if (i != N - 1) {//一番下じゃない
				if (S[i + 1][j] != '#') {//行き先が障害物じゃない
					G.add_edge(i*M + j, (i + 1)*M + j, Inf, 0);
				}
			}
			if (j != M - 1) {//一番右じゃない
				if (S[i][j + 1] != '#') {//行き先が障害物じゃない
					G.add_edge(i*M + j, i*M + j + 1, Inf, 0);
				}
			}
			//tに
			G.add_edge(i*M + j, t, 1, (N + M) - (i + j));
			if (S[i][j] == 'o') {
				//sから
				G.add_edge(s, i*M + j, 1, 0);
				ans -= i;
				ans -= j;
				ans += (N + M);
			}
		}
	}

	ans -= G.flow(s, t).second;

	cout << ans << endl;

	return 0;
}

