struct DSU
{
	vector<int>par;
	vector<int>sz;

	DSU(int n)
	{
		par.resize(n+1);
		iota(par.begin(),par.end(),0);
		sz.assign(n+1,1);
	}

	int Find(int a)
	{
		return par[a]==a?a:par[a]=Find(par[a]);
	}

	bool same(int a,int b)
	{
		a=Find(a);
		b=Find(b);
		return a==b;
	}

	void Union(int a,int b)
	{
		if(same(a,b)) return;
		a=Find(a);
		b=Find(b);

		if(sz[b]>sz[a]) swap(a,b);
		sz[a]+=sz[b];
		par[b]=a;
	}
};


void solve()
{
	int n;
	cin>>n;

	vector<pair<pii,int>>edge(n);
	for(int i=0;i<n;i++)
	{
		pii x;
		cin>>x.first>>x.second;
		edge[i].first=x;
		edge[i].second=i+1;
	}

	sort(edge.begin(),edge.end());
	map<int,int>parent;
	for(auto it: edge) parent[it.first.second]=it.second;

	//for(auto it: edge) cout<<it.first.first<<" "<<it.first.second<<" "<<it.second<<"\n";

	DSU dsu(n);

	set<int>st;

	for(int i=n-1;i>=0;i--)
	{
		auto it=st.upper_bound(edge[i].first.second);
		if(it!=st.end())
		{
			do
			{
				int u=edge[i].second;
				int v=parent[*it];
				//cout<<u<<" "<<v<<"\n";
				dsu.Union(u,v);
				parent[*it]=dsu.Find(v);
				parent[u]=dsu.Find(u);
				u=*it;
				st.erase(it);
				it=st.upper_bound(u);
				if(it==st.end()) st.insert(u);
			}
			while(it!=st.end());
		}
		st.insert(edge[i].first.second);
	}

	for(int i=1;i<=n;i++)
	{
		int x=dsu.Find(i);
		cout<<dsu.sz[x]<<"\n";
	}

}		

