int rnk[200002];

int ds_find(int x) {
    if (rep[x] != x) {
        rep[x] = ds_find(rep[x]);
    }
    return rep[x];
}

void ds_union(int x, int y) {
    int xp = ds_find(x);
    int yp = ds_find(y);
    if (xp == yp) return;
    if (rnk[xp] < rnk[yp]) {
        rep[xp] = yp;
    } else if (rnk[xp] > rnk[yp]) {
        rep[yp] = xp;
    } else {
        rep[yp] = xp;
        rnk[xp]++;
    }
}


