struct DSU {
    vector <int> par, sz;
    int n;
    inline void init(int _n) {
        n = _n;
        par.resize(n + 1);
        sz.resize(n + 1, 1);
    }
    int root(int x) {
        if(par[x] == 0)
            return x;
        return par[x] = root(par[x]);
    }
    inline void join(int x, int y) {
        x = root(x), y = root(y);
        if(x != y) {
            par[x] = y;
            sz[y] += sz[x];
        }
    }
};


