        if(chmin(mi,val)){
            for(int i=x;i>lo;i--){
                chmin(mi,h[i]);
                if(i!=lo+1)uf.unite(i,i-1);
            }
            lo = x;
        }else{
            for(int i=x;i>lo;i--){
                chmin(mi,h[i]);
                uf.unite(i,i-1);    
            }
            lo = x;
        }
    }
