    sort(all(I), [&x](int i, int j){ return x[i] > x[j]; });

    set<pair<int, int>> S;

    DSU dsu(n);

    for (auto i : I)
    {
        auto iter = S.upper_bound(pair(y[i], 0));
        while (iter != S.end())
        {
            int j = iter->second;
            dsu.union_set(i, j);
            ++iter;
            if (iter != S.end()) S.erase(prev(iter));
        }
        S.insert(pair(y[i], i));
    }

    for (int i = 0; i < n; ++i)
        cout << dsu.set_size(i) << endl;

    exit(0);
}

