void update(int u,int c,int id){
  for (t[u+=MAX][id]+=c;u>1;u>>=1){
    t[u>>1][id]=t[u][id]+t[u^1][id];
  } 
} 

int query(int u,int v,int id){
  int sum=0;
  for (u+=MAX,v+=MAX+1;u<v;u>>=1,v>>=1){
    if (u&1)sum+=t[u++][id];
    if (v&1)sum+=t[--v][id];
  }
  return sum;
}

void update2(int u,int c,int id){
  for (t2[u+=MAX][id]=c;u>1;u>>=1){
    t2[u>>1][id]=max(t2[u][id],t2[u^1][id]);
  } 
} 

int query2(int u,int v,int id){
  int maxi=0;
  for (u+=MAX,v+=MAX+1;u<v;u>>=1,v>>=1){
    if (u&1)maxi=max(maxi,t2[u++][id]);
    if (v&1)maxi=max(maxi,t2[--v][id]);
  }
  return maxi;
}
