    sort(ind.begin(), ind.end(), [&](int i, int j){
        return x[i] < x[j];
    });
    int m;
    UnionFind U(N);
    for(int i = 0; i < N; i++){
        if(i == 0) m = ind[i];
        else{
            if(y[m] < y[ind[i]]){
                U.unite(m, ind[i]);
            }
            else m = ind[i];
        }
    }
    for(int i = N - 1; i >= 0; i--){
        if(i == N - 1) m = ind[i];
        else{
            if(y[m] > y[ind[i]]){
                U.unite(m, ind[i]);
            }
            else m = ind[i];
        }
    }
    for(int i = 0; i < N; i++){
        cout << U.size(i) << endl;
    }
}

