    seg_tree.Update(i, va[i]);
  }

  UnionFind uf(n);
  for (int i = 0; i < n; ++i) {
    int max_n = seg_tree.Query(i + 1, n + 1);
    if (va[i] <= max_n) {
      uf.Unite(va[i], max_n);
    }
  }

