	cin>>n;
	dsu save(n);
	vector<pair<int,int>>a(n);
	vector<pair<int,int>>idx(n);
	for(int i=0;i<n;i++){
		cin>>a[i].first>>a[i].second;
		idx[i]={a[i].first,i};
	}
	sort(all(a));
	sort(all(idx));
	pair<int,int>highest={a[n-1].second,a[n-1].first};
	for(int i=n-2;i>=0;i--){
		int y=a[i].second;
		int x=a[i].first;
		if(y>highest.first){
			highest={y,x};
		}else{
			save.unite(highest.second,x);
		}
	}
	pair<int,int>lowest={a[0].second,a[0].first};
	for(int i=1;i<n;i++){
		int y=a[i].second;
		int x=a[i].first;
		if(y<lowest.first){
			lowest={y,x};
		}else{
			save.unite(lowest.second,x);
		}
	}
	highest={a[n-1].second,a[n-1].first};
	for(int i=n-2;i>=0;i--){
		int y=a[i].second;
		int x=a[i].first;
		if(y>highest.first){
			highest={y,x};
		}else{
			save.unite(highest.second,x);
		}
	}
	lowest={a[0].second,a[0].first};
	for(int i=1;i<n;i++){
		int y=a[i].second;
		int x=a[i].first;
		if(y<lowest.first){
			lowest={y,x};
		}else{
			save.unite(lowest.second,x);
		}
	}
	vector<int>ans(n);
	for(int i=0;i<n;i++){
		ans[idx[i].second]=save.sz(idx[i].first);
	}
	for(int i=0;i<n;i++){
		cout<<ans[i]<<endl;
	}
}

