bool sortbysecDsec(const pair<int,int> &a, 
              const pair<int,int> &b) 
{ 
    return (a.second > b.second); 
} 

int maxElements(int point, int y, vector< pair<int ,int> > b, int n){
	sort(b.begin()+point,b.begin()+n,sortbysecDsec);

	int lo = point;
	int hi = n-1;
	int ans = -1;

	while(lo<=hi){
		int mid = lo + (hi-lo)/2;

		if(b[mid].second==y){
			ans = mid;
			break;
		}
		else if(b[mid].second<y){
			hi=mid-1;
		}
		else{
			ans = mid;
			lo = mid+1;
		}
	}
	sort(b.begin()+point,b.begin()+n);

	if(ans==-1)
	 	return 0;
	else
		return (ans - point +1);
}

int minElements(int point, int y, vector< pair<int ,int> > b, int n){
	sort(b.begin(),b.begin()+point,sortbysecAsec);

	int lo = 0;
	int hi = point-1;
	int ans = -1;

	while(lo<=hi){
		int mid = lo + (hi-lo)/2;

		if(b[mid].second>y){
			hi=mid-1;
		}
		else{
			ans = mid;
			lo = mid+1;
		}
	}
	sort(b.begin(),b.begin()+point);

	return (ans +1);
}

