int root(int u)
{
    if(u==par[u]) return u;
    return par[u] = root(par[u]);
}
void Merge(int u,int v)
{
    int uu = root(u);
    int vv = root(v);
    if(uu==vv) return;
    if(uu>vv) swap(uu,vv);
    par[vv] =uu;
    dd[uu] += dd[vv];
    dd[vv] = 0;
    return;
}
