int main() {
    int N;
    cin >> N;

    vector<int> x(N), y(N), ID(N + 1);
    for_(i,0,N) {
        cin >> x[i] >> y[i];
        ID[y[i]] = i;
    }

    vector<int> order(N);
    iota(ALL(order), 0);
    sort(ALL(order), [&](int i, int j) { return x[i] < x[j]; });

    vector<bool> vis(N + 1, false);
