#include <bits/stdc++.h>
using namespace std;

typedef tuple <int, int, int> iii;

bool comp1(iii l, iii r) {
	return get<0>(l) < get<0>(r);
}
bool comp2(iii l, iii r) {
	return get<1>(l) < get<1>(r);
}

int n;
iii xyi[200005];
int ans[200005];
int ft[200005];

void update(int x, int v) {
	while (x < n + 5) {
		ft[x] += v;
		x += (x&(-x));
	}
}
int query(int x) {
	int cur = 0;
	while (x > 0) {
		cur += ft[x];
		x -= (x&(-x));
	}
	return cur;
}

int main() {
	scanf("%d", &n);
	for (int i = 0; i < n; i++) {
		int x, y; scanf("%d%d", &x, &y);
		xyi[i] = iii(x, y, i);
		update(i + 1, 1);
	}
	sort(xyi, xyi + n, comp1);
	for (int i = 0; i < n; i++) {
		int x, y, index; tie(x, y, index) = xyi[i];
		ans[index] += query(n) - query(y);
		update(y, -1);
	}
	for (int i = 1; i <= n; i++) update(i, 1);
	for (int i = n - 1; i >= 0; i--) {
		int x, y, index; tie(x, y, index) = xyi[i];
		ans[index] += query(y - 1);
		update(y, -1);
	}
	for (int i = 0; i < n; i++) printf("%d\n", ans[i] + 1);
	return 0;
}

