    for (int i = 0; i < n; i++) {
        int x, y;
        cin >> x >> y;
        xy[i] = {{x, y}, i};
    }

    sort(xy.begin(), xy.end());

    dsu d(n);

    int min_y = INF;
    int min_y_i = 0;
    for (int i = 0; i < n; i++) {
        if (min_y < xy[i].first.second) {
            d.merge(xy[i].second, min_y_i);
        } else if (xy[i].first.second < min_y) {
            min_y = xy[i].first.second;
            min_y_i = xy[i].second;
        }
    }

    int max_y = -INF;
    int max_y_i = 0;
    for (int i = n - 1; i >= 0; i--) {
        if (max_y > xy[i].first.second) {
            d.merge(xy[i].second, max_y_i);
        } else if (xy[i].first.second > max_y) {
            max_y = xy[i].first.second;
            max_y_i = xy[i].second;
        }
    }

    while (!timer.isExpired()) {
        const int i = rng() % n, j = rng() % n;

        if ((xy[i].first.first < xy[j].first.first &&
             xy[i].first.second < xy[j].first.second) ||
            (xy[i].first.first > xy[j].first.first &&
             xy[i].first.second > xy[j].first.second)) {
            d.merge(xy[i].second, xy[j].second);
        }
    }

    for (int i = 0; i < n; i++) {
        cout << d.size(i) << "\n";
    }
