    minY[0] = ListY(town[0].y, town[0].idx, -1);
    FROM_S(i, 1, n)
    {
        if (town[i].y < minY[i - 1].y)
            minY[i] = ListY(town[i].y, town[i].idx, i - 1);
        else
            minY[i] = minY[i - 1];
