            maxY[i] = ListY(town[i].y, town[i].idx, i + 1);
        else
            maxY[i] = maxY[i + 1];
    }

    // graph
    atcoder::dsu graph(n);
    FROM_S(i, 0, n)
    {
        int before = i - 1;
        while (before >= 0 && minY[before].y < town[i].y)
        {
            graph.merge(minY[before].idx, town[i].idx);
            before = minY[before].next;
        }
        int next = i + 1;
        while (next < n && maxY[next].y > town[i].y)
        {
            graph.merge(maxY[next].idx, town[i].idx);
            next = maxY[next].next;
        }
    }
    auto groups = graph.groups();
    vector<int> ret(n);
    ITER_BEGIN_END(pGroup, groups)
    {
        const vector<int> & x = *pGroup;
        ITER_BEGIN_END(pIdx, x)
        {
            ret[*pIdx] = (int)x.size();
        }
    }
    FROM_0(i, n)
        cout << ret[i] << endl;

    return 0;
}

