            ymin = Y[i];
            yidx = i;
        }
    }

    int ymax = Y[N-1];
    yidx = N-1;
    for (int i = N-2; i >= 0; i--)
    {
        if(ymax > Y[i]){
            uf.merge(i, yidx);
        }
        else{
            ymax = Y[i];
            yidx = i;
        }
    }


    for (int i = 0; i < N; i++) Ans[Idx[i]] = uf.size(i);
    for(auto a:Ans) cout << a << "\n";    
    return 0;
}

