template<typename T>
class FenwickTree {
    const int n;
    std::vector<T> data;

public:
    FenwickTree(int count) : n(count), data(count, 0) { ; }

    void add(int pos, const T &value) {
        assert(0 <= pos && pos < n);
        for (int i = pos; i < n; i |= i + 1) data[i] += value;
    }

    // 区間 [0, pos) 番目の範囲の和を求める．(pos = 0 のときは 0 を返す．)
    T sum(int pos) const {
        assert(0 <= pos && pos <= n);
        T res = 0;
        for (int i = pos - 1; i >= 0; i = (i & (i + 1)) - 1) {
            res += data[i];
        }
        return res;
    }

    // 区間 [l, r) 番目の範囲の和を求める．(l = r のときは 0 を返す．)
    T sum(int l, int r) const {
        assert(0 <= l && l <= r && r <= n);
        return sum(r) + (-sum(l));
    }

    using value_type = T;
    using update_type = T;
};


