	for (int i = 0; i < n; i++) {
		cin >> a[i].first >> a[i].second.first;
		a[i].second.second = i;
	}
	sort(a.begin(), a.end());
	for (int i = 0; i < n; i++) {
		st.insert({ a[i].second.first, i });
	}

	dsu d(n);
	for (int i = 0; i < n; i++) {
		st.erase(make_pair(a[i].second.first, i));
		auto ub = st.upper_bound(make_pair(a[i].second.first, -1));
		if (ub != st.end()) {
			d.merge(i, ub->second);
		}
		ub = st2.lower_bound(make_pair(a[i].second.first, -1));
		if (ub != st2.begin()) {
			ub--;
		}
		if (ub != st2.end() && ub->first < a[i].second.first) {
			d.merge(i, ub->second);
		}
		st2.insert(make_pair(a[i].second.first, i));
	}

	vector<int> ans(n);
	for (int i = 0; i < n; i++) {
		ans[a[i].second.second] = d.size(i);
	}
	for (int x : ans) {
