using namespace std;
const int N=200000;
int Root[N],Rank[N],Size[N];
int find(int x){
    if(Root[x]==x)return x;
    else return Root[x]=find(Root[x]);
}
void unite(int x,int y){
    int X=find(x);
    int Y=find(y);
    if(X==Y)return;
    if(Rank[X]<Rank[Y]){
        Root[X]=Y;
        Size[Y]+=Size[X];
    }
    else{
        Root[Y]=X;
        Size[X]+=Size[Y];
        if(Rank[X]==Rank[Y])Rank[X]++;
    }
    return;
}
