int find(int u){
    if(p[u]==u) return u;
    else return p[u] = find(p[u]);
}

int merge(int u,int v){
    int x = find(u), y = find(v);
    if(x!=y){
        p[y] = x;
        size[x] += size[y];
        return 1;
    }
    else return 0;
}

void change(int p,int v,int n){
    while(p<=n){
        bit[p] += v;
        p += p&-p;
    }
}

int ask(int p){
    int res = 0;
    while(p!=0){
        res += bit[p];
        p -= p&-p;
    }
    return res;
}
//>u
int getNext(int u,int n){
    int base = ask(u);
    if(u+1>n || ask(n)==base) return -1;
    else{
        int need = base+1;
        int L = u+1, R = n;
        int res = -1;
        while(L<=R){
            int M = (L+R)/2;
            if(ask(M)>=need){
                res = M;
                R = M-1;
            }
            else L = M+1;
        }
        return res;
    } 
}

void solve(int n){
    for(int i = 1; i <= n; i++) p[i] = i, size[i] = 1, change(i,1,n);
    int prefix = n+1;
    for(int i = 1; i <= n; i++){
        int u = d[i];
        if(u>prefix){}
        else{
            prefix = u;
            int next = getNext(u,n);
            while(next!=-1){
                //printf("next = %d\n",next);
                int j = pos[next];
                if(merge(i,j)){
                    //printf("i = %d, j = %d\n",i,j);
                    next = getNext(next,n);
                }
                else break;
            }
        }
        change(u,-1,n);
    }
}

