	}

	~union_find(){
		//

	}

	void clear(){
		_setnum = 0;
		par.clear();
		nume.clear();
	}

	void init(){
		_setnum = par.size();
		for(int i = 0; i < par.size(); i++){
			par[i] = i;
			nume[i] = 1;
		}
	}

	void resize(int x){

		par.resize(x);
		nume.resize(x);
		init();
	}

	int find(int x){
		return par[x] == x ? x : par[x] = find(par[x]);
	}

	void unite(int x, int y){
		x = find(x);
		y = find(y);

		if(x == y)return;

		_setnum--;

		if(nume[x] > nume[y]) std::swap(x,y);

		par[x] = y;
		nume[y] += nume[x];
	}

	bool same(int x, int y){
		return find(x) == find(y);
	}

	int numel(int x){
		return nume[find(x)];
	}

	int size(){
		return par.size();
	}

	int setnum(){
		return _setnum;
	}
};

