    vector<Tuple> ps(N);
    rep(i, N) {
        int x, y;
        cin >> x >> y;
        ps[i] = make_tuple(x, y, i);
    }
    dsu uf(N);
    rep(_, 2) {
        sort(ps.begin(), ps.end());
        set<P> st;
        auto[x, y, id] = ps[0];
        st.emplace(y, id);
        for(int i = 1; i < N; ++i) {
            auto[x, y, id] = ps[i];
            auto [mn, mid] = *st.begin();
            if(mn < y) uf.merge(mid, id);
            else mn = y, mid = id;
            auto it = st.lower_bound({y, id});
            if(it != st.begin()) {
                it = prev(it);
                assert(it->first < y);
                uf.merge(id, it->second);
            }
            st.insert({y, id});
        }
        rep(i, N) {
            auto[x, y, id] = ps[i];
            ps[i] = make_tuple(-x, -y, id);
        }
    }
    rep(i, N) cout << uf.size(i) << '\n';
}

