{
    size_t N;
    cin >> N;

    vector<long long> x(N);
    vector<long long> y(N);
    for (size_t i = 0; i < N; i++)
    {
        cin >> x[i] >> y[i];
    }

    UnionFind uf(N);

    f(x, y, uf);
    for (size_t i = 0; i < N; i++)
    {
        x[i] = N - x[i] + 1;
        y[i] = N - y[i] + 1;
    }
    f(x, y, uf);

    for (size_t i = 0; i < N; i++)
    {
        cout << uf.size(i) << endl;
    }
}

