class FenwickTree{
private:
	int dat[maxn];
public:
	inline void update(int x){
		for(++x; x; x -= x & (-x))
			++dat[x];
		return;
	}
	inline int query(int x){
		int ret = 0;
		for(++x; x <= n; x += x & (-x))
			ret += dat[x];
		return ret;
	}
}fen1, fen2;

int main(){
	scanf("%d", &n);
	FOR(i, 0, n){
		scanf("%d%d", x + i, y + i);
		--x[i]; --y[i];
		xr[x[i]] = i; yr[y[i]] = i;
		p[x[i]] = y[i];
		q[y[i]] = x[i];
	}

	int val = n;
	FOR(i, 0, n){
		int id = xr[i];
		d[id] = min(val, y[id] - 1);
		val = min(val, y[id]);
	}
	val = n;
	FOR(i, 0, n){
		int id = yr[i];
		l[id] = min(val, x[id] - 1);
		val = min(val, x[id]);
	}
	val = -1;
	for(int i = n - 1; i >= 0; --i){
		int id = yr[i];
		r[id] = max(val, x[id] + 1);
		val = max(val, x[id]);
	}
	val = -1;
	for(int i = n - 1; i >= 0; --i){
		int id = xr[i];
		u[id] = max(val, y[id] + 1);
		val = max(val, y[id]);
	}

	FOR(i, 0, n){
		vecl[l[i]].PB(MP(u[i], i));
		vecd[d[i]].PB(MP(r[i], i));
	}
	FOR(i, 0, n){
		fen1.update(p[i]);
		fen2.update(q[i]);
		FOR(j, 0, vecl[i].size()){
			int id = vecl[i][j].snd, uj = vecl[i][j].fst;
			ans[id] -= fen1.query(uj);
		}
		FOR(j, 0, vecd[i].size()){
			int id = vecd[i][j].snd, rj = vecd[i][j].fst;
			ans[id] -= fen2.query(rj);
		}
	}


	FOR(i, 0, n)
		printf("%d\n", ans[i] + n);
	return 0;
}

