void make_set(int v)
{
	p[v] = v;
	sz[v] = 1;
}

int find_set(int v)
{
	if (v == p[v])
		return v;

	return p[v] = find_set(p[v]);
}

void union_sets(int a, int b)
{
	a = find_set(a);
	b = find_set(b);

	if (a != b)
	{
		if (sz[a] < sz[b])
			swap(a, b);

		sz[a] += sz[b];
		p[b] = a;
	}
}

