                idx[i].push_back(j);
            }
        }
        sort(idx[i].begin(), idx[i].end());
    }
    for(int i = 0; i < N; i++){
        out_idx[i] = idx[i];
        int diff = -1;
        for(int j = 0; j < N; j++){
