                for(int k = 0; k < idx[j].size(); k++){
                    diff = idx[j][k];
                    for(int l = 0; l < idx[i].size();l++){
                        if((idx[j][k]==idx[i][l]) || (k<l)){
                            diff = -1;
                            break;
                        } 
