inline int find_set(vi &st, int x) {
	int y = x, z;
	whl(y!=st[y])
		y = st[y];
	whl(x!=st[x])
		z = st[x], st[x] = y, x = z;
	rtn y;
}
inline bool union_set(vi &st, int a, int b) {
	a = find_set(st, a), b = find_set(st, b);
	rtn a != b ? st[a] = b, true : false;
}
inline void make_set(vpii &st) {
	rep(i,sz(st))
		st[i] = mp(i, 1);
