	} else if (st[x] == x) {
		rtn x;
	} else {
		rtn st[x] = find_set(st, st[x]);
	}
}
inline bool union_set(map<pii, pii> &st, pii a, pii b) {
	a = find_set(st, a), b = find_set(st, b);
	rtn a != b ? st[a] = b, true : false;
}

