struct union_find {
	int pr[nsz + 5], siz[nsz + 5];

	inline int operator [] (int id) { return qry(id); }

	void inline init() {
		cont (u, n) pr[u] = u, siz[u] = 1;
	}

	int inline qry(int u) { return pr[u] == u ? u : pr[u] = qry(pr[u]); }

	bool inline link(int u, int v) {
		u = qry(u), v = qry(v);
		if (u == v) return 1;
		pr[v] = u;
		siz[u] += siz[v], siz[v] = 0;
		return 0;
	}
};
union_find uf;

vector<int> inline merge(const vector<int> &a, const vector<int> &b) {
	int s1 = a.size(), s2 = b.size();
	vector<int> r;
	for (int i = 0, j = 0; i < s1 || j < s2;) r.push_back(j == s2 || (i < s1 && a[i] < b[j]) ? a[i++] : b[j++]);
	return r;
}

vector<int> solve(int l = 1, int r = n) {
	if (l == r) return vector<int>(1, p[l]);
	int md = (l + r) >> 1;
	vector<int> ls = solve(l, md), rs = solve(md + 1, r);
	int ls_mn = *ls.begin(), rs_mx = rs.back();
	loop (i, ls.size()) if (ls[i] < rs_mx) uf.link(q[ls[i]], q[rs_mx]);
	loop (i, rs.size()) if (rs[i] > ls_mn) uf.link(q[rs[i]], q[ls_mn]);
	return merge(ls, rs);
}

