class unionfind {
	vector<int> par;
	vector<int> sz;
public:
	unionfind(int n) {
		par = vector<int>(n);
		for (int i = 0; i < n; i++) par[i] = i;
		sz = vector<int>(n, 1);
	}
	int find(int x) {
		if (par[x] == x) return x;
		else return par[x] = find(par[x]);
	}
	int size(int x) { return sz[find(x)]; }
	bool same(int x, int y) { return find(x) == find(y); }
	void unite(int x, int y) {
		x = find(x);
		y = find(y);
		if (x == y) return;
		if (sz[x] < sz[y]) {
			par[x] = y;
			sz[y] += sz[x];
		}
		else {
			par[y] = x;
			sz[x] += sz[y];
		}
	}
};

int main() {
	int n;
	cin >> n;
	unionfind uni(n);
	vector<pair<P, int>> p(n);
	rep(i, n) {
		int x, y;
		cin >> x >> y;
		x--; y--;
		p[i].first.first = x;
		p[i].first.second = y;
		p[i].second = i;
	}
	sort(all(p));
	pque<P> que;
	rep(i, n) {
		P mi = { p[i].first.second,i };
		P t = mi;
		while (!que.empty()) {
			if (que.top() > t) break;
			P p = que.top(); que.pop();
			uni.unite(p.second, i);
			chmin(mi, p);
		}
		que.push(mi);
	}
	vector<int> ans(n);
	rep(i, n) ans[p[i].second] = uni.size(i);
	rep(i, n) cout << ans[i] << '\n';
}

