struct BitVector {
    vector<int> v;
    vector<int> r; //count 0
    BitVector(){}
    void build() {
        r.resize(v.size()+1);
        for (int i = 0; i < v.size(); i++) {
            r[i+1] = r[i] + (v[i] == 0);
        }
    }

    int access(int i) {return v[i];}
    int rank0(int i) {return r[i];}
    int rank1(int i) {return i-r[i];}
    int rank(int i, int j) {
        return j?rank1(i):rank0(i);
    }
};

template<int W, typename T = long long>
struct WaveletMatrix {
    BitVector bv[W];
    int zero[W];
    T pinf, minf;

    WaveletMatrix(vector<T> &a, T p = 1000000000000000000, T m = -1000000000000000000) {
        pinf = p, minf = m;
        for (int i = 0; i < W; i++) zero[i] = 0;
        int n = a.size();
        vector<T> tmp = a;
        for (int i = W-1; i >= 0; i--) {
            bv[i].v.resize(n);
            vector<T> v0, v1;
            for (int j = 0; j < n; j++) {
                if ((tmp[j]>>i)&1) {
                    bv[i].v[j] = 1;
                    v1.push_back(tmp[j]);
                } else {
                    bv[i].v[j] = 0;
                    zero[i]++;
                    v0.push_back(tmp[j]);
                }
            }
            for (int i = 0; i < (int)v0.size(); i++) {
                tmp[i] = v0[i];
            }
            for (int i = 0; i < (int)v1.size(); i++) {
                tmp[v0.size()+i] = v1[i];
            }
            bv[i].build();
        }
    }

    int count(int l, int r, int x) { //count x [l, r)
        for (int i = W-1; i >= 0; i--) {
            bool f = (x >> i) & 1;
            int st = bv[i].rank(l, f);
            int en = bv[i].rank(r, f);
            l = (f ? zero[i] : 0) + st;
            r = (f ? zero[i] : 0) + en;
        }
        return r-l;
    }

    int count_lower(int l, int r, T x) { //[0, x)
        int ret = 0;
        for (int i = W-1; i >= 0; i--) {
            bool f = (x >> i) & 1;
            int st = bv[i].rank(l, f);
            int en = bv[i].rank(r, f);
            if (f) {
                st += zero[i];
                en += zero[i];
                ret += bv[i].rank(r, 0) - bv[i].rank(l, 0);
            }
            l = st, r = en;
        }
        return ret;
    }

    int range_count(int l, int r, int x, int y) {//[l,r),[x,y)
        return count_lower(l, r, y) - count_lower(l, r, x);
    }

    T kth_min(int l, int r, int k) {
        T ans = 0;
        for (int i = W - 1; i >= 0; i--) {
            int st = bv[i].rank(l, 0);
            int en = bv[i].rank(r, 0);
            if (en - st <= k) {
                k -= en - st;
                l = zero[i] + bv[i].rank(l, 1);
                r = zero[i] + bv[i].rank(r, 1);
                ans += (1ll << i);
            } else {
                l = st, r = en;
            }
        }
        return ans;
    }

    //izyou
    pair<T, bool> next_value(int l, int r, T x) {
        int idx = count_lower(l, r, x);
        if (idx == r - l) return {1000000000000000000, false};
        return {kth_min(l, r, idx), true};
    }

    //ika
    pair<T, bool> prev_value(int l, int r, T x) {
        int idx = count_lower(l, r, x);
        if (idx == 0) return {-1, false};
        return {kth_min(l, r, idx-1), true};
    }
};

template<typename Monoid>
class SegTree {

//半開区間!!!!!!!!!!!!!!!
public:
    int p = 2;
    vector<Monoid> node;
    using Func = function<Monoid(Monoid,Monoid)>;
    Func pick; Monoid init;//操作と単位元

    SegTree(vector<Monoid> A, string type, Monoid m) {
        if (type == "min") {
            pick = [](Monoid a, Monoid b){return min(a,b);};
        } else if (type == "max") {
            pick = [](Monoid a, Monoid b){return max(a,b);};
        } else if (type == "sum") {
            pick = [](Monoid a, Monoid b){return a + b;};
        }

        init = m;
        while (A.size() > p) p *= 2;
        node = vector<Monoid>(2*p-1,init);

        for (int i = 0;i < A.size();i++) {
            node[p-1+i] = A[i];
        }

        for (int i = p - 2;i >= 0;i--) {
            node[i] = pick(node[i*2+1],node[i*2+2]);
        }
    }

    SegTree(vector<Monoid> A, Func f, Monoid m) {
        pick = f; init = m;
        while (A.size() > p) p *= 2;
        node = vector<Monoid>(2*p-1,init);

        for (int i = 0;i < A.size();i++) {
            node[p-1+i] = A[i];
        }

        for (int i = p - 2;i >= 0;i--) {
            node[i] = pick(node[i*2+1],node[i*2+2]);
        }
    }

    //1点更新
    void update(int i, Monoid v) {
        for (node[(i+=p)-1] = v; i >>= 1;) {
            node[i-1] = pick(node[i*2-1], node[i*2]);
        }
    }

    //1点加算
    void add(int i, Monoid v) {
        update(i, this[i] + v);
    }

    Monoid getval(int start,int end,int k = 0,int l = 0,int r = -1) {
        if (r < 0) r = p;
        if (r <= start || end <= l) {return init;}
        if (start <= l && r <= end) {return node[k];}
        Monoid L,R;
        L = getval(start,end,k*2+1,l,(l+r)/2);
        R = getval(start,end,k*2+2,(l+r)/2,r);
        return {pick(L,R)};
    }

    inline Monoid operator [] (int i) {
        return node[i+p-1];
    }
};

void solve() {
    int n; cin >> n;
    vector<int> y(n), ans(n);
    vector<vector<int>> p(n);
    rep (i, n) {
        int a, b; cin >> a >> b;
        --a, --b;
        y[a] = b;
        p[i] = {b, a, i};
    }
    sort(rall(p));
    set<int> X;
    WaveletMatrix<32> wm(y);


    rep (i, n) {
        X.insert(p[i][1]);
        ans[p[i][2]] += wm.range_count(*X.rbegin(), n, 0, wm.kth_min(0, p[i][1]+1, 0));
    }
    X.clear();
    reverse(all(p));

    rep (i, n) {
        X.insert(p[i][1]);
        ans[p[i][2]] += wm.range_count(0, *X.begin(), wm.kth_min(p[i][1], n, (wm.count_lower(p[i][1], n, n+1)-1)), n);
    }

    rep (i, n) cout << n-ans[i] << endl;
}

