int find(int X,vector<int> &P){
  if(P.at(X)<0){
    return X;
  }
  return P.at(X)=find(P.at(X),P);
}

void unite(int X,int Y,vector<int> &P){
  X=find(X,P);
  Y=find(Y,P);
  if(X==Y){
    return;
  }
  if(P.at(X)>P.at(Y)){
    swap(X,Y);
  }
  P.at(X)+=P.at(Y);
  P.at(Y)=X;
}

int func(int X,vector<int> &P){
  if(P.at(X)<0){
    return (-1)*P.at(X);
  }
  return func(find(P.at(X),P),P);
}

