typedef long long ll;

// https://pyteyon.hatenablog.com/entry/2019/03/11/200000
class UnionFind {
public:
    vector < ll > par; // 各元の親を表す配列
    vector < ll > siz; // 素集合のサイズを表す配列(1 で初期化)

    // Constructor
    explicit UnionFind(ll sz_): par(sz_), siz(sz_, 1) {
        REP(i,sz_) par[i] = i; // 初期では親は自分自身
    }
    void init(ll sz_) {
        par.resize(sz_);
        siz.assign(sz_, 1);
        for (ll i = 0; i < sz_; ++i) par[i] = i; // 初期では親は自分自身
    }

    // Member Function
    // Find
    ll root(ll x) { // 根の検索
        while (par[x] != x) {
            x = par[x] = par[par[x]]; // x の親の親を x の親とする
        }
        return x;
    }

    // Union(Unite, Merge)
    bool merge(ll x, ll y) {
        x = root(x);
        y = root(y);
        if (x == y) return false;
        // merge technique（データ構造をマージするテク．小を大にくっつける）
        if (siz[x] < siz[y]) swap(x, y);
        siz[x] += siz[y];
        par[y] = x;
        return true;
    }

    bool issame(ll x, ll y) { // 連結判定
        return root(x) == root(y);
    }

    ll size(ll x) { // 素集合のサイズ
        return siz[root(x)];
    }
};


void solve() {
    int N; cin >> N;
    vector<pair<int,int>> v(N);
    vector<int> v_key_by_x(N,-1);
    map<int,int> y_to_x;
    vector<bool> called(N+1,false);
    vector<bool> visited(N+1,false);
    called[0] = true;
    REP(i,N) {
        int x,y; cin >> x >> y;
        v[i] = make_pair(x,y);
        v_key_by_x[i] = x;
        y_to_x[y] = x;
    }
    sort(ALL(v));

    // anss[x] = answer
    // x座標管理
    UnionFind uf(N+1);

    REPR(i,N-1) {
        auto [x,y] = v[i];
        if (called[y]) continue;
        called[y] = true;
        visited[y] = true;
        auto ny = y - 1;
        // x座標
        set<int> st;
        while(!called[ny]) {
            if (visited[ny]) {
                ny--;
                continue;
            }
            called[ny] = true;
            uf.merge(x,y_to_x[ny]);
            ny--;
        }
        if (ny != 0 && !visited[ny]) uf.merge(x,y_to_x[ny]);
    }
    REP(i,N) cout << uf.size(v_key_by_x[i]) << endl;
}

