        if (t->first > p[i].first.second) {
            auto t2 = st.lower_bound({p[i].first.second,0});
            while(t2->first < t->first) {
                uf.unite(t2->second,t->second);
                t2 = st.erase(t2);
            }
            uf.unite(p[i].second,t->second);
        }
        else {
            st.insert({p[i].first.second,p[i].second});
        }
    }
    reverse(p.begin(), p.end());
