const int maxn = 200100;

int bit[maxn];

void update(int idx, int val, int n){
  for(;idx <= n; idx += (idx & -idx)){
     bit[idx] += val;
  }
}

int query(int idx){
    int val = 0;
    for(;idx > 0; idx -= (idx & -idx)) val += bit[idx];
    return val;
}

