using p = pair<ll, ll>;
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    cin >> n;
    vector<p> v(n);
    rep(i, n) {
        int x, y;
        cin >> x >> y;
        v[i] = p(x - 1, y - 1);
    }

    vector<int> index(n);
    iota(index.begin(), index.end(), 0);
    sort(index.begin(), index.end(),
         [&](const int &a, const int &b) { return v[a] < v[b]; });

    atcoder::dsu d(n);
    set<p> s;
    s.insert(p(v[index[0]].second, index[0]));

    repd(i, 1, n) {
        set<p> del_set;
        int j = index[i];
        del_set.insert(p(v[j].second, j));
        int remain_index = j;
        for (auto elem : s) {
            if (elem.first < v[j].second) {
                d.merge(elem.second, j);
                del_set.insert(elem);
                if (v[remain_index].second > v[elem.second].second) {
                    remain_index = elem.second;
                }
            } else {
                break;
            }
        }
        s.insert(p(v[j].second, j));
        for (auto elem : del_set) {
            s.erase(elem);
        }
        s.insert(p(v[remain_index].second, remain_index));
    }

    vector<int> ans(n);
    rep(i, n) { ans[index[i]] = d.size(index[i]); }
    rep(i, n) { cout << ans[i] << endl; }
    return 0;
}

