void solve(int N, vi& x, vi& y) {
    vi f(N + 1), rev(N + 1);
    rep(i, N) {
        rev[y[i]] = x[i];
        f[x[i]] = y[i];
    }

    atcoder::dsu dsu(N + 1);

    set<ii> sr;
    sr.emplace(-1, -1);
    sr.emplace(f[N], f[N]);
    for (int i = N - 1; i >= 1; --i) {
        int h = f[i], h_hi = h;
        vii to_erase;
        for (auto it = sr.upper_bound(ii(h, h)); it != sr.end(); ++it) {
            int lo = it->first, hi = it->second;
            amax(h_hi, hi);
            int u = rev[h], v = rev[lo];
            dsu.merge(u, v);
            to_erase.pb(*it);
        }
        auto it = sr.upper_bound(ii(h, h));
        --it;
        if (it != sr.begin() && h < it->second) {
            int lo = it->first, hi = it->second;
            int u = rev[h], v = rev[hi];
            if (h < hi) {
                amax(h_hi, hi);
                dsu.merge(u, v);
                to_erase.pb(*it);
            }
        }
        for (auto e : to_erase) sr.erase(e);
        sr.emplace(h, h_hi);
    }
