int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);

  int n; cin>>n;
  struct City {
    int x,y,i;
  };
  vector<City> C(n);
  for (int i = 0; i < n; i++) {
    int a,b; cin>>a>>b;
    C[i] = {a,b,i};
  }

  sort(C.begin(), C.end(), [](auto l, auto r) {return l.x<r.x;});
  atcoder::dsu cdsu(n);
  map<int,set<int>> ss;
  for (int i = 0; i < n; i++) {
    vector<int> ts;
    auto c = C[i];
    for (auto [j,s] : ss) {
      if (*s.begin() < c.y) {
        ts.push_back(j);
      }
    }
    if (ts.empty()) {
      ss[c.i] = {c.y};
    } else {
      for (auto j:ts) {
        cdsu.merge(j, c.i);
      }
      auto& f = ts[0];
      for (int j = 1; j < ts.size(); j++) {
        auto& t = ts[j];
        if (ss[f].size() < ss[t].size()) swap(f, t);
        auto sst = ss.find(t);
        ss[f].insert(sst->second.begin(), sst->second.end());
        ss.erase(sst);
      }
      ss[f].insert(c.y);
    }
  }

  for (int i = 0; i < n; i++) {
    cout << cdsu.size(i) << endl;
  }

  return 0;
}

