struct Segment_tree {
	vector <int> T[800010];
	int pos[800010];
	vector <int> merge(vector <int> &a, vector <int> &b) {
		vector <int> c; int p1 = 0, p2 = 0;
		while (p1 < a.size() || p2 < b.size()) {
			if (p2 == b.size() || p1 != a.size() && a[p1] < b[p2]) c.push_back(a[p1++]);
			else c.push_back(b[p2++]);
		}
		return c;
	}
	void Build(int now, int l, int r) {
		pos[now] = 0;
		if (l == r) {
			T[now].push_back(a[l]);
			return ;
		}
		int mid = l + r >> 1;
		Build(now << 1, l, mid), Build(now << 1 | 1, mid + 1, r);
		T[now] = merge(T[now << 1], T[now << 1 | 1]);
	}
	void get_s(int now, int l, int r, int L, int R, int val) {
		if (l == L && r == R) {
			while (pos[now] < T[now].size()) {
				int x = T[now][pos[now]];
				if (x > val) break;
				if (!vis[tox[x]]) {
					ord.push_back(tox[x]);
					vis[tox[x]] = 1;
				}
				pos[now]++;
			}
			return ;
		}
		int mid = l + r >> 1;
		if (R <= mid) get_s(now << 1, l, mid, L, R, val);
		else if (L > mid) get_s(now << 1 | 1, mid + 1, r, L, R, val);
		else get_s(now << 1, l, mid, L, mid, val), get_s(now << 1 | 1, mid + 1, r, mid + 1, R, val);
	}
	void get_b(int now, int l, int r, int L, int R, int val) {
		if (l == L && r == R) {
			while (pos[now] < T[now].size()) {
				int x = T[now].back();
				if (x < val) break;
				if (!vis[tox[x]]) {
					ord.push_back(tox[x]);
					vis[tox[x]] = 1;
				}
				T[now].pop_back();
			}
			return ;
		}
		int mid = l + r >> 1;
		if (R <= mid) get_b(now << 1, l, mid, L, R, val);
		else if (L > mid) get_b(now << 1 | 1, mid + 1, r, L, R, val);
		else get_b(now << 1, l, mid, L, mid, val), get_b(now << 1 | 1, mid + 1, r, mid + 1, R, val);
	}
