struct DSU
{
	ll connected;
	vector<ll> par, sz;

	void init(ll n)
	{
		par = sz = vector<ll> (n + 1, 0);
		for(ll i = 1; i <= n; i++)
			par[i] = i, sz[i] = 1;
		connected = n;
	}

	ll getPar(ll u)
	{
		while(u != par[u])
		{
			par[u] = par[par[u]];
			u = par[u];
		}
		return u;
	}

	ll getSize(ll u)
	{
		return sz[getPar(u)];
	}

	void unite(ll u, ll v)
	{
		ll par1 = getPar(u), par2 = getPar(v);

		if(par1 == par2)
			return;

		connected--;

		if(par1 < par2)
			swap(par1, par2);

		sz[par2] += sz[par1];
		sz[par1] = 0;
		par[par1] = par[par2];
	}
};

DSU ds;

int main()
{
  ios_base::sync_with_stdio(0);
