  }
  sort(p,p+n);
  vll ans(n,0);
  ds.init(n);

  set<ll> st;
  fori(i,0,n)
  {
    ll tmp = p[i].ff.ss;
    if(st.empty())
    {
      st.ins(tmp);
      continue;
    }
    auto it=st.begin();
    if(*it>tmp)
    {
      st.ins(tmp);
      continue;
    }
    ll root = ds.getPar(*it);
    vll rem;
    it++;
    while(it!=st.end())
    {
      if(*it>tmp) break;
      ds.unite(root,*it);
      rem.pb(*it);
      it++;
    }
    for(auto tt:rem)
    {
      st.erase(tt);
    }
    ds.unite(tmp,root);
  }
  fori(i,0,n)
  {
    ans[p[i].ss] = ds.sz[ds.getPar(p[i].ff.ss)];
  }
  fori(i,0,n) cout<<ans[i]<<endl;
