struct Point {
	long long x, y;
	int count;
	int pos;
};

Point pts[200010];
int n;

bool compare(Point &a, Point &b) {
	return a.x < b.x;
}

bool comparePos(Point &a, Point &b) {
	return a.pos < b.pos;
}

bool isUsed[200010];

int main()
{
	scanf("%d", &n);
	for (int i = 0 ; i < n ; i++) {
		scanf("%lld%lld", &(pts[i].x), &(pts[i].y));
		pts[i].count = 0;
		pts[i].pos = i;
	}

	sort(pts, pts + n, compare);
	memset(isUsed, false, sizeof(isUsed));

	int minY;
	int maxY = n;
	int l = 0;
	int h = 0;
	int sz;
	while (l < n) {
		h = l;
		minY = pts[l].y;

		while (h < n) {
			if (pts[h].y < minY) {
				minY = pts[h].y;
			}

			if (pts[h].y >= maxY) {
				break;
			}
			h++;
		}

		sz = h - l + 1;
		int dist = (maxY - minY) + 1;
		while (dist > sz) {
			h++;
			sz++;
			if (pts[h].y < minY) {
				minY = pts[h].y;
			}
			dist = (maxY - minY) + 1;
		}


		if (h >= n) {
			h--;
		}



		for (int p = l ; p <= h ; p++) {
			pts[p].count = sz;
			isUsed[pts[p].y] = true;
		}

		while (isUsed[maxY] == true) {
			maxY--;
		}

		l = h + 1;
	}

	sort(pts, pts + n, comparePos);

	for (int i = 0 ; i < n ; i++) {
		printf("%d\n", pts[i].count);
	}


	return 0;
}

