class UFF {
    using Int = int;
    std::vector<Int> parent;
    std::vector<Int> rank;

public:
    explicit UFF(Int n) : parent(n, -1), rank(n, 0) {}

    Int find(Int x) {
        auto &px = parent[x];
        if (px < 0) {
            return x;
        } else {
            return px = find(px);
        }
    }

    bool unite(Int a, Int b) {
        const auto pa = find(a);
        const auto pb = find(b);
        if (pa == pb) return false;

        if (rank[pa] > rank[pb]) {
            parent[pa] += parent[pb];
            parent[pb] = pa;
        } else {
            parent[pb] += parent[pa];
            parent[pa] = pb;

            if (rank[pa] == rank[pb]) {
                rank[pb]++;
            }
        }
        return true;
    };

    Int size(Int x) {
        const auto px = find(x);
        return -parent[px];
    }

    bool is_same(Int a, Int b) {
        const auto pa = find(a);
        const auto pb = find(b);
        return pa == pb;
    }

    vector<Int> get_all_dset() {
        unordered_set<Int> dset;
        for (Int i = 0; i < parent.size(); ++i) {
            dset.insert(find(i));
        } // end i
        vector<Int> v(dset.size());
        Int i = 0;
        for (auto &&d : dset) {
            v[i++] = d;
        } // end d
//        sort(v.begin(), v.end());
        return v;
    }
};


class solver{
    istream& is;
    ostream& os;

public:
    solver(istream& I, ostream& O) :is(I), os(O) {}

    int N;
    vector<pair<int, int>> xy;
    bool input() {
        is >> N;
        xy.resize(N);
        is >> xy;
        return !!is;
    }

    void run();
};

void solver::run(){
    if(!input()) return;
    map<int, int> rx, ry;
    UFF uf(N);
    for (int i = 0; i < N; ++i) {
        rx[xy[i].first] = i;
        ry[xy[i].second] = i;
    } // end i
    for (auto &&xi : rx) {
        int x, i;
        tie(x, i) = xi;
        ry.erase(xy[i].second);
        auto p = ry.upper_bound(xy[i].second);
//        if(xy[p->second].second < xy[i].second) continue;
        vector<int> rmy;
        while(p != ry.end()){
            int id = p->second;
            if(x >= xy[id].first or
                xy[i].second > xy[id].second){
                auto r = p;
                p++;
                ry.erase(r);
                continue;
            }
            uf.unite(i, id);
            rmy.emplace_back(id);
            p++;
        }

        if(rmy.empty()) continue;
        int mxi = i, mx= x;
//        cerr << "f = " << x << ' ' << xy[i].second << endl;
        for (int ind : rmy) {
            if(CHMAX(mx, xy[ind].first)){
                mxi = ind;
            }
//            skip[ind] = true;
//            cerr << "DEL" << xy[ind].first << ' '<< xy[ind].second << endl;
            ry.erase(xy[ind].second);
        } // end k
        ry[mx] = mxi;
    } // end xi
    for (int i = 0; i < N; ++i) {
        cout << uf.size(i) << '\n';
    } // end i

}

