const int N = 200200;
int t[N * 4];
int n;
void update(int pos, int delta, int v = 1, int tl = 1, int tr = n) {
    if (tl == tr) {
        t[v] = delta;
    } else {
        int tm = (tl + tr) >> 1;
        if (pos <= tm)
            update(pos, delta, v + v, tl, tm);
        else update(pos, delta, v + v + 1, tm + 1, tr);
        t[v] = max(t[v + v], t[v + v + 1]);
    }
}

int get(int l, int r, int v = 1, int tl = 1, int tr = n) {
    if (l > tr || r < tl)return 0;
    if (l <= tl && tr <= r) return t[v];
    int tm = (tl + tr) >> 1;
    return max(get(l, r, v + v, tl, tm), get(l, r, v + v + 1, tm + 1, tr));
}

