void solve(){
    ll n;
    scan(n);
    UnionFind uf(n);
    vl ord(n), ans(n), dp(n, INF);
    vector<set<pair<ll, ll>>> memo(n);
    points ps(n);
    rep(i, n){
        scan(ps[i].x, ps[i].y);
        ps[i] -= {1, 1};
        ord[ps[i].x] = i;
    }

    sort(all(ps));
    rep(i, n){
        ll lb = lower_bound(all(dp), ps[i].y) - dp.begin();
        dp[lb] = ps[i].y;
        memo[lb].insert({ps[i].y, i});
        if (lb - 1 >= 0){
            auto it = memo[lb - 1].begin();
            while (it != memo[lb - 1].end() && (*it).first < ps[i].y)
                uf.unite((*it).second, i), ++it;
        }
    }

    rep(i, n) ans[ord[i]] = uf.size(i);
    println(ans);
}

