        for (int j = i + 1; j < N; ++j) {
            if ((X[i].first < X[j].first && X[i].second < X[j].second) ||
                (X[i].first > X[j].first && X[i].second > X[j].second)) {
                ans.unite(i, j);
            }
        }
    }

    rep(i, N) { cout << ans.size(i) << endl; }
}

