solve :: Int -> U.Vector (Int, Int) -> U.Vector Int
solve n ps = runST $ do
    uf <- newUnionFind n
    heap <- buildMaxBinaryHeap (U.map swap ps)
    U.forM_ (U.modify Intro.sort ps) $ \(x, y) -> do
        fix $ \loop -> do
            viewBH heap >>= \case
                Nothing -> return ()
                Just (y', x')
                    | x' <= x -> do
                        unsafeDeleteBH heap
                        loop
                    | otherwise -> when (y < y') $ do
                        uniteUF uf x x'
                        return ()
    flip U.mapM ps $ \(x, y) -> do
        sizeUF uf x



