        fix $ \loop -> do
            viewBH heapR >>= \case
                Nothing -> return ()
                Just (y', x')
                    | x' <= x -> do
                        unsafeDeleteBH heapR
                        loop
                    | otherwise -> when (y < y') $ do
                        unsafeDeleteBH heapR
                        uniteUF uf x x'
                        loop

    flip U.mapM ps $ \(x, y) -> do
        sizeUF uf x



