typedef struct{ ll num , par , hei ,size; } UF;
void UFmake(ll n, UF b[]){ rep(i,0,n){ b[i].par = b[i].num = i;  b[i].hei = b[i].size = 1; }  }

ll UFroot(ll a,UF b[]){ return a==b[a].par?a:UFroot(b[a].par,b); }
ll UFsame(ll x, ll y, UF b[]){ return UFroot(x,b) == UFroot(y,b); }
ll UFsize(ll x, UF b[]){ return b[UFroot(x,b)].size; }
void UFunite(ll x, ll y, UF b[]){
    if(UFsame(x,y,b)) return;
    ll xroot=UFroot(x,b) , yroot=UFroot(y,b) , siz=UFsize(x,b)+UFsize(y,b);
    if(b[xroot].hei > b[yroot].hei) b[yroot].par = xroot;
    else{ b[xroot].par = yroot;  b[yroot].hei = max2( b[yroot].hei , b[xroot].hei+1 );}
    b[UFroot(x,b)].size=siz;
}

