#include <bits/stdc++.h>
using namespace std;

// one-based numbering
struct UnionFind {
    vector<int> data;
    // i: (data[i] < 0) -> group size, (data[i] > 0) -> parent;
    UnionFind(int n) {
        data.resize(n+1, -1);
    }
    int find(int x) {
        if(data[x] < 0) return x;
        else return data[x] = find(data[x]);
    }
    int size(int x) {
        return -data[find(x)];
    }
    bool unite(int x, int y) {
        x = find(x); y = find(y);
        if(x == y) return false;
        if (data[x] > data[y]) swap(x, y);
        data[x] += data[y];
        data[y] = x;
        return true;
    }
    bool same(int x, int y) {
        x = find(x); y = find(y);
        return x == y;
    }
};


int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    int N; cin >> N;
    vector<pair<int, int>> X(N+1), Y(N+1);
    UnionFind UF(N);
    for (int i = 1; i <= N; i++) {
        int x, y; cin >> x >> y;
        X[x] = {y, i};
        Y[y] = {x, i};
    }
    set<pair<int, int>> S;
    for (int i = 1; i <= N; i++) {
        bool ins = true;
        if (!S.empty()) {
            for (auto [y, z] : S) {
                if (y < X[i].first) {
                    UF.unite(X[i].second, z);
                    if (y > X[i].first) {
                        S.erase(S.begin());
                    } else ins = false;
                } else break;
            }
        }
        if (ins) S.emplace(X[i].first, X[i].second);
    }

    for (int i = 1; i <= N; i++) {
        cout << UF.size(i) << "\n";
    }

    return 0;
}

