#define SEG_MAX (1 << 19) /* 524288 */

struct snode_t {
	int value;
	struct snode_t *left, *right;
};

struct snode_t* sadd_i(struct snode_t* node, int ss, int se, int pos, int value) {
	if (pos < ss || se <= pos) {
		return node;
	} else if (se == ss + 1) {
		struct snode_t* nnode = malloc2(sizeof(*nnode));
		nnode->value = (node != NULL ? node->value : 0) + value;
		nnode->left = NULL;
		nnode->right = NULL;
		return nnode;
	} else {
		int sm = ss + (se - ss) / 2;
		struct snode_t* nnode = malloc2(sizeof(*nnode));
		nnode->left = sadd_i(node != NULL ? node->left : NULL, ss, sm, pos, value);
		nnode->right = sadd_i(node != NULL ? node->right : NULL, sm, se, pos, value);
		nnode->value = (nnode->left == NULL ? 0 : nnode->left->value) +
			(nnode->right == NULL ? 0 : nnode->right->value);
		return nnode;
	}
}

static struct snode_t* sadd(struct snode_t* node, int pos, int value) {
	return sadd_i(node, 0, SEG_MAX, pos, value);
}

int sget_i(const struct snode_t* node, int qs, int qe, int ss, int se) {
	if (qe <= ss || se <= qs) { /* はずれ */
		return 0;
	} else if (node == NULL) { /* ゼロ */
		return 0;
	} else if (qs <= ss && se <= qe) { /* セグメントがクエリに完全に含まれる */
		return node->value;
	} else {
		int sm = ss + (se - ss) / 2;
		int left = sget_i(node->left, qs, qe, ss, sm);
		int right = sget_i(node->right, qs, qe, sm, se);
		return left + right;
	}
}

static int sget(const struct snode_t* node, int qs, int qe) {
	return qs < qe ? sget_i(node, qs, qe, 0, SEG_MAX) : 0;
}

