		for (;;) {
			int nex = i + 1;
			int no = nex, yes = N2 - 1;
			int cache = sget(ruisekiwa[nex], mati[i].y, gokan);
			if (ruisekiwa_hani2(cache, mati[i].y, N2, gokan) == 0) break;
			if (mati[nex].y > mati[i].y && mati[nex].y < gokan) {
				yes = nex;
			} else {
				while (no + 1 < yes) {
					int m = no + (yes - no) / 2;
					int q = ruisekiwa_hani2(cache, mati[i].y, m + 1, gokan);
					if (q > 0) yes = m; else no = m;
				}
			}
			ki_merge(i, yes);
#if 0
			printf("(%d, %d) -> (%d, %d)\n", mati[i].x, mati[i].y, mati[yes].x, mati[yes].y);
#endif
			gokan = mati[yes].y;
		}
		if (mati[i].idx >= 0) genzan_idx[mati[i].idx] = i;
	}
	for (i = 0; i < N2; i++) {
		if (mati[i].idx >= 0) {
			int ko = ki_size(i);
			ko -= ruisekiwa_hit_hani(0, 0, genzan_idx[i], mati[i].y + 1);
			ko -= ruisekiwa_hit_hani(genzan_idx[i] + 1, mati[i].y, N, N * 2);
			kotae[mati[i].idx] = ko;
		}
	}
	for (i = 0; i < N; i++) {
		printf("%d\n", kotae[i]);
	}
	return 0;
}

