static int ruisekiwa_hani(int lu_x, int lu_y, int rd_x, int rd_y) {
	return sget(ruisekiwa[lu_x], lu_y, rd_y) - sget(ruisekiwa[rd_x], lu_y, rd_y);
}

static int ruisekiwa_hani2(int cache, int lu_y, int rd_x, int rd_y) {
	return cache - sget(ruisekiwa[rd_x], lu_y, rd_y);
}

static int ruisekiwa_hit_hani(int lu_x, int lu_y, int rd_x, int rd_y) {
	return sget(ruisekiwa_hit[lu_x], lu_y, rd_y) - sget(ruisekiwa_hit[rd_x], lu_y, rd_y);
}

