static void* malloc2(size_t s) {
	void* r = malloc(s);
	if (r == NULL) {
		perror("malloc");
		exit(2);
	}
	return r;
}

struct aaaaa {
	int x, y;
	int idx;
};

int nya(const void* x, const void* y) {
	struct aaaaa a = *(const struct aaaaa*)x, b = *(const struct aaaaa*)y;
	if (a.x != b.x) return a.x < b.x ? -1 : a.x > b.x;
	return a.y < b.y ? -1 : a.y > b.y;
}

#define KI_MAX 212345

int ki[KI_MAX];

void ki_init(void) {
	int i;
	for (i = 0; i < KI_MAX; i++) {
		ki[i] = -1;
	}
}

int ki_root(int n) {
	if (ki[n] < 0) return n;
	return ki[n] = ki_root(ki[n]);
}

static int ki_size(int n) {
	return -ki[ki_root(n)];
}

static void ki_merge(int a, int b) {
	int ar = ki_root(a);
	int br = ki_root(b);
	if (ar != br) {
		int as = ki_size(ar);
		int bs = ki_size(br);
		if (as <= bs) {
			ki[br] += ki[ar];
			ki[ar] = br;
		} else {
			ki[ar] += ki[br];
			ki[br] = ar;
		}
	}
}

#define SEG_MAX (1 << 18) /* 262144 */

struct snode_t {
	int value;
	struct snode_t *left, *right;
};

struct snode_t* sadd_i(struct snode_t* node, int ss, int se, int pos, int value) {
	if (pos < ss || se <= pos) {
		return node;
	} else if (se == ss + 1) {
		struct snode_t* nnode = malloc2(sizeof(*nnode));
		nnode->value = (node != NULL ? node->value : 0) + value;
		nnode->left = NULL;
		nnode->right = NULL;
		return nnode;
	} else {
		int sm = ss + (se - ss) / 2;
		struct snode_t* nnode = malloc2(sizeof(*nnode));
		nnode->left = sadd_i(node != NULL ? node->left : NULL, ss, sm, pos, value);
		nnode->right = sadd_i(node != NULL ? node->right : NULL, sm, se, pos, value);
		nnode->value = (nnode->left == NULL ? 0 : nnode->left->value) +
			(nnode->right == NULL ? 0 : nnode->right->value);
		return nnode;
	}
}

static struct snode_t* sadd(struct snode_t* node, int pos, int value) {
	return sadd_i(node, 0, SEG_MAX, pos, value);
}

int sget_i(const struct snode_t* node, int qs, int qe, int ss, int se) {
	if (qe <= ss || se <= qs) { /* はずれ */
		return 0;
	} else if (node == NULL) { /* ゼロ */
		return 0;
	} else if (qs <= ss && se <= qe) { /* セグメントがクエリに完全に含まれる */
		return node->value;
	} else {
		int sm = ss + (se - ss) / 2;
		int left = sget_i(node->left, qs, qe, ss, sm);
		int right = sget_i(node->right, qs, qe, sm, se);
		return left + right;
	}
}

static int sget(const struct snode_t* node, int qs, int qe) {
	return qs < qe ? sget_i(node, qs, qe, 0, SEG_MAX) : 0;
}

