fun solve() {
    val n = readInteger()
    val uf = UnionFind(n)
    val pointList = Array(n) {
        val (x, y) = readIntegerList()
        Triple(x, y, it)
    }
    val sortedX = pointList.sortedWith(compareBy {it.first})
    val sortedY  = pointList.sortedWith(compareBy {it.second})
    var maxYIndex = n - 1
    var minIndex = 0
    val checkedSet = mutableSetOf<Int>()
    for ((i, p) in sortedX.withIndex()) {
        checkedSet.add(p.third)
        if (p.second < sortedY[maxYIndex].second) uf.unite(p.third, sortedY[maxYIndex].third)
        if (p.second == sortedY[maxYIndex].second) {
            while (maxYIndex >= 0 && checkedSet.contains(sortedY[maxYIndex].third)) maxYIndex--
        }

        if (p.second > sortedX[minIndex].second) uf.unite(p.third, sortedX[minIndex].third)
        minIndex = if (p.second < sortedX[minIndex].second) i else minIndex
    }

    for (i in 0 until n) { out.println(uf.getSize(i)) }
}

/**　Union find 0 ~ (n - 1)　*/
class UnionFind(n: Int) {
    val parent = IntArray(n) { it }
    val rank = IntArray(n)
    val size = IntArray(n) { 1 }

    /** O(α(n)) */
    fun findRoot(x: Int): Int {
        if (parent[x] == x) return x

        parent[x] = findRoot(parent[x])
        return parent[x]
    }

    /** O(α(n)) */
    fun sameRoot(x: Int, y: Int) = findRoot(x) == findRoot(y)

    /** O(α(n)) */
    fun unite(x: Int, y: Int) {
        val x = findRoot(x)
        val y = findRoot(y)
        if (x == y) return

        if (rank[x] < rank[y]) {
            parent[x] = y
            size[y] += size[x]
        } else {
            parent[y] = x
            if (rank[x] == rank[y]) rank[x]++

            size[x] += size[y]
        }
    }

    /** O(α(n)) */
    fun getSize(x: Int) = size[findRoot(x)]
}


