class IntBIT(val size: Int) {
    private val A = IntArray(size + 1)

    // zeroes all the bits except the least significant one
    private inline fun lsb(i: Int) = i and -i

    fun sum(end: Int): Int {
        var i = minOf(end + 1, size) // BIT is internally 1-indexed
        var sum = 0
        while(i > 0) {
            sum += A[i]
            i -= lsb(i)
        }
        return sum
    }

    fun sum(start: Int, endx: Int) = sum(endx - 1) - sum(start - 1)
    fun sum(range: IntRange) = sum(range.last) - sum(range.first - 1)

    fun add(index: Int, value: Int) {
        var i = index + 1 // BIT is internally 1-indexed
        while(i <= size) {
            A[i] += value
            i += lsb(i)
        }
    }

    private val hsb = Integer.highestOneBit(size)

    fun lowerBound(value: Int): Int {
        var sum = 0
        var pos = 0

        var i = hsb
        while(i > 0) {
            val npos = pos + i
            if (npos <= size) {
                val nsum = sum + A[npos]
                if(nsum < value) { // for upper bound, replace with <=
                    sum = nsum
                    pos = npos
                }
            }
            i = i shr 1
        }

        return pos
    }
}

