    val k = (1..n*2).map { sc.nextLong() }

    println(calc(n, k))
}

fun calc(n: Long, k: List<Long>): List<Long> {
    var cnt = 1L
    val cntList = LongArray(k.size / 2).map { 1L }.toMutableList()
    for(i in k.indices step 2) {
        for(j in i + 2 until k.size - 1 step 2) {
            if((k[j] > k[i] && k[j+1] > k[i+1]) || k[j] < k[i] && k[j+1] < k[i+1]) {
                cntList[i/2] += 1L
                cntList[j/2] += 1L
            }
        }

        cnt = 1
    }
    return cntList.toList()
}

