	public void solve() {
		int N = ni();
		UF = new UnionFind(N);
		int x, y;
		for (int i = 0; i < N; i++) {
			x = ni();
			y = ni();
			list.add(new PP(x, y, i));
		}
		list.sort(comparing(PP::getKey));
		for(PP pp1 : list) {
