class UnionFind {
    int[] par;  
    int[] size; 

    int cnt;

    UnionFind(int n) {
        par = new int[n];
        for (int i = 0; i < n; i++) {
            par[i] = i;
        }

        size = new int[n];
        Arrays.fill(size, 1);
        cnt = n;
    }

    int rot(int x) {
        if (par[x] == x) return x;
        return par[x] = rot(par[x]);

    }

    void unite(int x, int y) {
        int rx = rot(x);
        int ry = rot(y);
        if (rx != ry) {
            par[ry] = rx;

            int resize = size[rx] + size[ry];
            size[rx] = resize;
            size[ry] = resize;
            cnt--;
        }
    }


    boolean eq(int x, int y) {
        int cx = rot(x);
        int cy = rot(y);
        return cx == cy;
    }
}

