		final long MOD = (long)1e9 + 7; // 998244353;
		long mod(long x) { x %= MOD; return x + (x < 0 ? MOD : 0); }
		void mod(long[] a) { for(int i = 0; i < a.length; i ++) a[i] = mod(a[i]); }
		void mod(long[][] a) { for(int i = 0; i < a.length; i ++) mod(a[i]); }
