public void solve() {
	int num = ni();
	PairII p[] = npii(num);
	PairII sorted[] = new PairII[num];
	for(int i = 0; i < num; i ++) sorted[p[i].a - 1] = new PairII(num - p[i].b, i);

	boolean b[] = new boolean[num];
	boolean connected[] = new boolean[num];
	int cnt = 0;

	for(int i = 0; i < num; i ++) {
		if(b[i]) cnt ++;
		if(sorted[i].a <= i) cnt ++;
		b[sorted[i].a] = true;
		connected[i] = cnt != i + 1;
	}
	cnt = 0;
	long ans[] = new long[num];
	ans[0] = 1;
	for(int i = 0; i < num - 1; i ++) ans[i + 1] = connected[i] ? ans[i] + 1 : 1;
	for(int i = num - 1; i > 0; i --) if(connected[i - 1]) ans[i - 1] = ans[i];
	long ans2[] = new long[num];
	for(int i = 0; i < num; i ++) ans2[sorted[i].b] = ans[i];
	for(int i = 0; i < num; i ++) prtln(ans2[i]);
}

class UnionFind { // N=numNode
	int num;
	int parent[];
	int size[];

	UnionFind(int num) { // O(N)
		this.num = num;
		parent = new int[num];
		size = new int[num];
		for(int i = 0; i < num; i ++) initNode(i);
	}

	void initNode(int i) { // O(1)
		parent[i] = i;
		size[i] = 1;
	}

	void unite(int x, int y) { // O(ﾎｱ(N))
		int xRoot = root(x);
		int yRoot = root(y);
		if(xRoot == yRoot) return;
		if(size[yRoot] > size[xRoot]) {
			parent[xRoot] = yRoot;
			size[yRoot] += size[xRoot];
		}else {
			parent[yRoot] = xRoot;
			size[xRoot] += size[yRoot];
		}
	}

	int size(int i) { return size[root(i)]; } // O(ﾎｱ(N))

	int root(int i) { // O(ﾎｱ(N))
		if(i != parent[i]) parent[i] = root(parent[i]);
		return parent[i];
	}

	boolean same(int x, int y) { return root(x) == root(y); } // O(ﾎｱ(N))

	HashMap<Integer, ArrayList<Integer>> groups() { // O(N)
		HashMap<Integer, ArrayList<Integer>> groups = new HashMap<>();
		for(int i = 0; i < num; i ++) {
			int root = root(i);
			if(!groups.containsKey(root)) groups.put(root, new ArrayList<>());
			groups.get(root).add(i);
		}
		return groups;
	}
}

