import java.io.*;
import java.math.*;
import java.util.*;
public class Main {
	static ArrayList<Integer>[] graph;
	static int[] seen;
	static int N;
	public static void main(String[] args) { 
		/*
		 * */
		FastScanner I = new FastScanner(); //Input
		OutPut O = new OutPut(); //Output
		StringBuilder ans = new StringBuilder();
		N = I.nextInt();
		int[][] town = new int[N][2];
		int[] min = new int[N+1]; //min[i] = minimum y-coordinate with coordinate <= i
		min[0]=(int)(1e9);
		int[] max = new int[N+5]; //max[i] = maximum y-coordinate with x-coordinate >= i
		int[] a = new int[N+1];
		int[] in = new int[N+1]; //in[i] = index of city with y-coordinate = i
		graph = new ArrayList[N+1];
		seen = new int[N];
		for (int i = 0; i <= N; i++) graph[i] = new ArrayList<Integer>();
		for (int i = 0; i < N; i++) {
			town[i][0]=I.nextInt();
			town[i][1]=I.nextInt();
			a[town[i][0]]=town[i][1]; //a[x]=y
			in[town[i][1]]=i;
		}
		for (int i = 1; i<=N; i++) {
			min[i]=min(min[i-1],a[i]);
		} 
		max[N]=a[N];
		for (int i = N-1; i >= 1; i--) {
			max[i]=max(max[i+1],a[i]);
		}
		for (int i = 0; i < N; i++) {
			int x = town[i][0];
			int y = town[i][1];
			int mn = min[x-1];
			int mx = max[x+1]; //No out of bounds
			if (mn<y) {
				int index = in[mn];
				graph[i].add(index);
				graph[index].add(i); //Maximum case is handled with opposite edge 
              	//of graph
			}
		}
		for (int i = 0; i < N; i++) {
			int size = seen[i];
			if (size==0) size=BFS(i);
			ans.append(size);
			ans.append("\n");
		}
		O.pln(ans);
	}
	public static int BFS(int start) {
		boolean[] vis = new boolean[N];
		int ans = 1;
		Queue<Integer> cur = new LinkedList<Integer>();
		cur.add(start);
		vis[start]=true;
		while (!cur.isEmpty()) {
			int size = cur.size();
			for (int i = 0; i < size; i++) {
				int now = cur.poll();
				for (int j = 0; j < graph[now].size(); j++) {
					int nbr = graph[now].get(j);
					if (!vis[nbr]) {
						vis[nbr]=true;
						ans++;
						cur.add(nbr);
					}
				}
			}
		}
		for (int i = 0; i < N; i++) {
			if (vis[i]) seen[i]=ans;
		}
		return ans;
	}
