public class Main {

  private static void solve() {
    int n = ni();
    int[][] p = new int[n][3];
    for (int i = 0; i < n; i++) {
      p[i][0] = i;
      p[i][1] = ni() - 1;
      p[i][2] = ni() - 1;
    }

    DisjointSet ds = new DisjointSet(n);

    Arrays.sort(p, (o1, o2) -> o1[1] - o2[1]);

    Deque<int[]> q = new ArrayDeque<>();

    for (int[] v : p) {
      int[] min = null;
      while (q.size() > 0 && q.peekFirst()[2] < v[2]) {
        int[] u = q.pollFirst();
        ds.union(u[0], v[0]);
        if (min == null) {
          min = u;
        }
      }
      if (min != null) {
        q.addFirst(min);
      } else {
        q.addFirst(v);
      }
