class UnionFindTree {
	int[] parent;
	int[] rank;
	int[] size;

	public UnionFindTree(int size) {
		this.parent = new int[size];
		this.rank = new int[size];
		this.size = new int[size];

		for (int i = 0; i < size; i++) {
			makeSet(i);
		}
	}

