        UnionFind uf = new UnionFind(n);

        // ←方向に舐める
        TreeMap<Integer, Integer> map = new TreeMap<Integer, Integer>();
        for (int i = n-1; i >= 0; i--) {
            int nowy = a[i][1];
            int idx = a[i][2];

            if (map.higherKey(nowy) != null) {
