        map = new TreeMap<Integer, Integer>();
        for (int i = 0; i < n; i++) {
            int nowx = b[i][0];
            int idx = b[i][2];

            if (map.lowerKey(nowx) != null) {
                int key = map.lowerKey(nowx);
