class UnionFind {
    int[] par;  // 自身の親
    int[] size; // ※(自身の属するグループの要素数はsize[uf.root(i)]。)
                // (※[i]全てに対して↑を更新するのは時間がかかるので)
    int connectedComponent;

    UnionFind(int n) {
        par = new int[n];
        for (int i = 0; i < n; i++) {
            par[i] = i;
        }

        size = new int[n];
        Arrays.fill(size, 1);
        connectedComponent = n;
    }

    int root(int x) {
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
        // 1-2-4の場合、4の親=2を4の根=1に繋ぎ変えた上で親を返す
        // ↑根まで辿る深さ(計算量)を減らす為
        // return a = b;とは、aにbを代入し、aを返すという意味
    }

    // 点x, yを連結させる=同じグループにする
    void unite(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        if (rx != ry) {
            par[ry] = rx;

            int resize = size[rx] + size[ry];
            size[rx] = resize;
            size[ry] = resize;
            connectedComponent--;
        }
    }

    // 同グループか否か
    boolean same(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
}

import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();

        int[] x = new int[n];
        int[] y = new int[n];
        boolean[][] answer = new boolean[n][n];

        for (int i = 0; i < n; i++) {
            x[i] = sc.nextInt();
            y[i] = sc.nextInt();
            for (int j = 0; j < n; j++) {
                answer[i][j] = (i == j);
            }
        }

        int counter = 1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (answer[i][j]) continue;
                if((x[j] < x[i] && y[j] < y[i]) || (x[j] > x[i] && y[j] > y[i]))
                    if(j < i) counter += fillWithTrue(i, j, n, answer);
                    else {
                        answer[i][j] = true;
                        counter++;
                    }
            }
            System.out.println(counter);
            counter = 1;
        }
    }

    private static int fillWithTrue(int current, int target, int n, boolean[][] answer) {
        int counter = 0;
        for (int j = 0; j < n; j++) {
            if (answer[target][j] && !answer[current][j]) {
                answer[current][j] = true;
                counter++;
            }
        }
        return counter;
    }
}

