                set.put(cities[i].y, cities[i].i);
            }
            set.clear();
            for (int i = n - 1; i >= 0; i--) {
                Map.Entry<Integer, Integer> lo = set.higherEntry(cities[i].y);
                if (lo != null) uf.union(cities[i].i, lo.getValue());
                set.put(cities[i].y, cities[i].i);
