    static class DSUExt extends DSU {
        int[] size;

        public DSUExt(int n) {
            super(n);
            size = new int[n];
        }

        public void reset() {
            super.reset();
            Arrays.fill(size, 1);
        }

        protected void preMerge(int a, int b) {
            super.preMerge(a, b);
            size[a] += size[b];
        }

    }
