    static class DSU{
        int dsu[];
        long dsu_size[];
        int unconnected=0;
        DSU(int n){
            dsu=new int[n];
            dsu_size=new long[n];
            Arrays.fill(dsu,-1);
            Arrays.fill(dsu_size,0l);
            unconnected=n-1;
            for(int i=1;i<=n-1;i++){
                makeSet(i);
            }
        }
        void makeSet(int v){
            dsu[v]=v;
            dsu_size[v]=1;
        }
        int findSet(int v){
            if(dsu[v]==v){
                return v;
            }
            return dsu[v]=findSet(dsu[v]); 
        }
        long getSize(int s){
            return dsu_size[findSet(s)];
        }
        void union(int s1,int s2){
            int a=findSet(s1);
            int b=findSet(s2);
            if(a!=b){
                unconnected--;
                if(dsu_size[a]>dsu_size[b]){
                    int temp=a;
                    a=b;
                    b=temp;
                }
                dsu[a]=b;
                dsu_size[b]+=dsu_size[a];
            }
        }
    }
