import java.io.*; import java.util.*;
public class Main {

    public static class Pair {
        int y; int ind;
        public Pair(int b, int c){
            this.y=b; this.ind=c;
        }

    }
    static int N;

    public static void main(String[] args) throws IOException {
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        N=Integer.parseInt(br.readLine());
        Pair[] pr=new Pair[N];
        Pair[] pr2=new Pair[N];
        for (int i = 0; i < N; i++) {
            StringTokenizer st=new StringTokenizer(br.readLine());
            int a=Integer.parseInt(st.nextToken())-1;
            int b=Integer.parseInt(st.nextToken())-1;
            pr[a]=new Pair(b,i); pr2[b]=new Pair(a,i);
        }
        int[] rank=new int[N];
        int[] par=new int[N]; int[] siz=new int[N];
        for (int i = 0; i < N; i++) {
            par[i]=i; siz[i]++;
        }
        int k,l;
        for (int i = 0; i < N; i++) {//Increasing order of x-coordinate
            //y[i] is known
            for (int j = pr[i].y+1; j < N; j++) {
                //merge pr[i].ind and pr2[j].ind
                if(pr2[j].y>i){
                    k=find(pr[i].ind,par); l=find(pr2[j].ind,par);
                    if(k!=l){
                        if(rank[k]>rank[l]){
                            par[l]=k; siz[k]+=siz[l];
                        }else if(rank[k]==rank[l]){
                            rank[l]++; par[k]=l; siz[l]+=siz[k];
                        }else{
                            par[k]=l; siz[l]+=siz[k];
                        }
                    }
                }


            }
        }
        for (int i = 0; i < N; i++) {
            System.out.println(siz[find(i,par)]);
        }
    }
    public static int find(int x, int[] p){
        if(p[x]==x)return x;
        int ans=find(p[x],p); p[x]=ans; return ans;
    }
}

import java.io.*;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class Main {

	class City {
		int index, x, y;

		public City(int x, int y, int index) {
			this.x = x;
			this.y = y;
			this.index = index;
		}
	}

	private int getMax(int[] l, int index) {

		int ans = 0;
		for (int i = index; i > 0; i -= i & (-i)) {
			ans += l[i];
		}

		return ans;
	}

	private void updateMax(int[] l, int index, int val) {

		for (int i = index; i < l.length; i++) {
			l[i] += val;
		}
	}

	public void getNumberOfReachableCities(int input) throws Exception {

		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

		if (input == 1) {
			br = new BufferedReader(new FileReader("test.txt"));
		}

		int n = Integer.parseInt(br.readLine());
		int[] ans = new int[n];

		List<City> cities = new ArrayList<City>();

		for (int i = 0; i < n; i++) {
			StringTokenizer st = new StringTokenizer(br.readLine(), " ");
			cities.add(new City(Integer.parseInt(st.nextToken()), Integer.parseInt(st.nextToken()), i));
		}

		cities.sort((City c1, City c2) -> c1.x - c2.x);

		int[] left = new int[n + 1];
		int[] right = new int[n + 1];

		for (int i = 0; i < n; i++) {
			int num = getMax(left, cities.get(i).y);
			ans[cities.get(i).index] = num + 1;
			updateMax(left, cities.get(i).y + 1, 1);
		}

		for (int i = n - 1; i >= 0; i--) {
			int num = getMax(right, n - cities.get(i).y + 1);
			ans[cities.get(i).index] += num;
			updateMax(right, n - cities.get(i).y + 2, 1);
		}

		for (int i = 0; i < n; i++) {
			System.out.println(ans[i] + " ");
		}
		// System.out.print(ans[n - 1] + " ");
	}

	public static void main(String[] args) throws Exception {

		A a = new A();

		a.getNumberOfReachableCities(0);

	}
}

import java.util.*;
import java.io.*;
import java.nio.charset.StandardCharsets;

public class Main {

	public static void main(String[] args) throws IOException {
		InputStreamReader reader = new InputStreamReader(System.in, StandardCharsets.UTF_8);
		BufferedReader in = new BufferedReader(reader);
		Main ins = new Main(in);
		ins.calc();
		ins.showResult();
	}

	int N;
	int[] x, y;
	List<Tuple> list;
	int[] counts;

	static class Tuple {
		int id, x, y, gid;
		Set<Integer> conns;

		Tuple(int id, int x, int y) {
			this.gid = -1;
			this.id = id;
			this.x = x;
			this.y = y;
			this.conns = new HashSet<>();
		}

	}

	Main(BufferedReader in) throws IOException {
		N = Integer.parseInt(in.readLine());
		x = new int[N];
		y = new int[N];
		for (int i = 0; i < N; ++i) {
			String[] tokens = in.readLine().split(" ");
			x[i] = Integer.parseInt(tokens[0]);
			y[i] = Integer.parseInt(tokens[1]);
		}
		list = new ArrayList<>(N);
		for (int i = 0; i < N; ++i) {
			list.add(new Tuple(i, x[i], y[i]));
		}
		Collections.sort(list, new Comparator<Tuple>() {
			@Override
			public int compare(Tuple o1, Tuple o2) {
				return Integer.compare(o1.x, o2.x);
			}
		});
	}

	void mark(int id, int gid, int parent) {
		list.get(id).gid = gid;
		for (Integer conn : list.get(id).conns) {
			if (conn != parent) {
				mark(conn, gid, id);
			}
		}
	}

	void update(Tuple tuple, Deque<Tuple> deque) {
		List<Tuple> list = new ArrayList<>();
		while (!deque.isEmpty() && deque.peek().y < tuple.y) {
			list.add(deque.poll());
		}

		// tupleとlistの各要素間にedgeを張る
		for (Tuple elem : list) {
			tuple.conns.add(elem.id);
			elem.conns.add(tuple.id);
		}
		if (list.isEmpty()) {
			deque.addFirst(tuple);
		} else {
			deque.addFirst(list.get(0));
		}
	}

	void calc() {
		Deque<Tuple> deque = new ArrayDeque<>();
		deque.add(list.get(0));
		for (int i = 1; i < list.size(); ++i) {
			update(list.get(i), deque);
		}

		Collections.sort(list, new Comparator<Tuple>() {
			@Override
			public int compare(Tuple o1, Tuple o2) {
				return Integer.compare(o1.id, o2.id);
			}
		});

		// gidをmarkする
		int gid = 0;
		for (int i = 0; i < list.size(); ++i) {
			if (list.get(i).gid < 0) {
				mark(i, gid, -1);
				++gid;
			}
		}

		counts = new int[gid + 1];
		Arrays.fill(counts, 0);
		for (int i = 0; i < list.size(); ++i) {
			counts[list.get(i).gid]++;
		}
	}

	void showResult() {
		for (int i = 0; i < list.size(); ++i) {
			System.out.println(counts[list.get(i).gid]);
		}
	}
}

