    private static class FFT {
        double[] roots;
        int maxN;

        public FFT(int maxN) {
            this.maxN = maxN;
            initRoots();
        }

        public long[] multiply(int[] a, int[] b) {
            int minSize = a.length + b.length - 1;
            int bits = 1;
            while (1 << bits < minSize) bits++;
            int N = 1 << bits;
            double[] aa = toComplex(a, N);
            double[] bb = toComplex(b, N);
            fftIterative(aa, false);
            fftIterative(bb, false);
            double[] c = new double[aa.length];
            for (int i = 0; i < N; i++) {
                c[2 * i] = aa[2 * i] * bb[2 * i] - aa[2 * i + 1] * bb[2 * i + 1];
                c[2 * i + 1] = aa[2 * i] * bb[2 * i + 1] + aa[2 * i + 1] * bb[2 * i];
            }
            fftIterative(c, true);
            long[] ret = new long[minSize];
            for (int i = 0; i < ret.length; i++) {
                ret[i] = Math.round(c[2 * i]);
            }
            return ret;
        }

        static double[] toComplex(int[] arr, int size) {
            double[] ret = new double[size * 2];
            for (int i = 0; i < arr.length; i++) {
                ret[2 * i] = arr[i];
            }
            return ret;
        }

        void initRoots() {
            roots = new double[2 * (maxN + 1)];
            double ang = 2 * Math.PI / maxN;
            for (int i = 0; i <= maxN; i++) {
                roots[2 * i] = Math.cos(i * ang);
                roots[2 * i + 1] = Math.sin(i * ang);
            }
        }

        int bits(int N) {
            int ret = 0;
            while (1 << ret < N) ret++;
            if (1 << ret != N) throw new RuntimeException();
            return ret;
        }

        void fftIterative(double[] array, boolean inv) {
            int bits = bits(array.length / 2);
            int N = 1 << bits;
            for (int from = 0; from < N; from++) {
                int to = Integer.reverse(from) >>> (32 - bits);
                if (from < to) {
                    double tmpR = array[2 * from];
                    double tmpI = array[2 * from + 1];
                    array[2 * from] = array[2 * to];
                    array[2 * from + 1] = array[2 * to + 1];
                    array[2 * to] = tmpR;
                    array[2 * to + 1] = tmpI;
                }
            }
            for (int n = 2; n <= N; n *= 2) {
                int delta = 2 * maxN / n;
                for (int from = 0; from < N; from += n) {
                    int rootIdx = inv ? 2 * maxN : 0;
                    double tmpR, tmpI;
                    for (int arrIdx = 2 * from; arrIdx < 2 * from + n; arrIdx += 2) {
                        tmpR = array[arrIdx + n] * roots[rootIdx] - array[arrIdx + n + 1] * roots[rootIdx + 1];
                        tmpI = array[arrIdx + n] * roots[rootIdx + 1] + array[arrIdx + n + 1] * roots[rootIdx];
                        array[arrIdx + n] = array[arrIdx] - tmpR;
                        array[arrIdx + n + 1] = array[arrIdx + 1] - tmpI;
                        array[arrIdx] += tmpR;
                        array[arrIdx + 1] += tmpI;
                        rootIdx += (inv ? -delta : delta);
                    }
                }
            }
            if (inv) {
                for (int i = 0; i < array.length; i++) {
                    array[i] /= N;
                }
            }
        }
    }
}

import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);
    int  n = scanner.nextInt();
    Tree tree = new Tree();
    Node[] nodes = new Node[n];
    for (int i = 0; i < n; i++) {
      int x = scanner.nextInt(), y = scanner.nextInt();
      nodes[i] = tree.insert(x,y);
    }
    for (Node node: nodes) {
      System.out.println(1+tree.findSmaller(node) + tree.findBigger(node));
    }
  }

  static class Tree {
    Node root = null;
    public Node insert(int x, int y) {
      Node node = new Node(x,y);
      root = insert(root, node, true);
      return node;
    }

    private Node insert(Node root, Node node, boolean sortByX) {
      if (root==null)
        return node;
      if (sortByX) {
        if (root.x<node.x)
          root.left = insert(root.left, node, !sortByX);
        else
          root.right = insert(root.right, node, !sortByX);
      } else {
        if (root.y<node.y)
          root.left = insert(root.left, node, !sortByX);
        else
          root.right = insert(root.right, node, !sortByX);
      }
      return root;
    }

    public int findSmaller(Node node) {
      return findSmaller(node, root, true);
    }

    private int findSmaller(Node node, Node root, boolean sortByX) {
      if (root==null)return 0;
      if (sortByX) {
        if (node.x<root.x) {
          return ((node.y<root.y)?1:0)+
              findSmaller(node, root.left, !sortByX)+
              findSmaller(node, root.right, !sortByX);
        } else {
          return findSmaller(node, root.left, !sortByX);
        }
      } else {
        if (node.y<root.y) {
          return ((node.x<root.x)?1:0)+
              findSmaller(node, root.left, !sortByX)+
              findSmaller(node, root.right, !sortByX);
        } else {
          return findSmaller(node, root.left, !sortByX);
        }
      }
    }

    public int findBigger(Node node) {
      return findBigger(node, root, true);
    }

    private int findBigger(Node node, Node root, boolean sortByX) {
      if (root==null)return 0;
      if (sortByX) {
        if (node.x>root.x) {
          return ((node.y>root.y)?1:0)+
              findBigger(node, root.left, !sortByX)+
              findBigger(node, root.right, !sortByX);
        } else {
          return findBigger(node, root.right, !sortByX);
        }
      } else {
        if (node.y>root.y) {
          return ((node.x>root.x)?1:0)+
              findBigger(node, root.left, !sortByX)+
              findBigger(node, root.right, !sortByX);
        } else {
          return findBigger(node, root.right, !sortByX);
        }
      }
    }
  }

  static class Node {
    final int x,y;
    Node left, right;

    Node(int x, int y) {
      this.x = x;
      this.y = y;
    }
  }
}

