public void solve() {
	int num = ni();
	TupleIII t[] = new TupleIII[num];
	for(int i = 0; i < num; i ++) {
		t[i] = new TupleIII(ni() - 1, ni() - 1, i);
	}

	UnionFind uf = new UnionFind(num);

	Arrays.sort(t);
	Queue<TupleIII> pq = new PriorityQueue<>();
	for(int i = 0; i < num; i ++) {
		TupleIII add = new TupleIII(t[i].b, t[i].a, t[i].c);
		while(!pq.isEmpty()) {
			TupleIII crt = pq.peek();
			if(crt.a >= t[i].b) break;
			pq.poll();
			uf.unite(crt.c, t[i].c);
			add.a = min(add.a, crt.a);
			add.b = min(add.b, crt.b);
		}
		pq.add(add);
	}
	for(int i = 0; i < num; i ++) {
		prtln(uf.size(i));
	}
}

class UnionFind { // N=numNode
	int num;
	int parent[];
	int size[];

	UnionFind(int num) { // O(N)
		this.num = num;
		parent = new int[num];
		size = new int[num];
		for(int i = 0; i < num; i ++) initNode(i);
	}

	void initNode(int i) { // O(1)
		parent[i] = i;
		size[i] = 1;
	}

	void unite(int x, int y) { // O(ﾎｱ(N))
		int xRoot = root(x);
		int yRoot = root(y);
		if(xRoot == yRoot) return;
		if(size[yRoot] > size[xRoot]) {
			parent[xRoot] = yRoot;
			size[yRoot] += size[xRoot];
		}else {
			parent[yRoot] = xRoot;
			size[xRoot] += size[yRoot];
		}
	}

	int size(int i) { return size[root(i)]; } // O(ﾎｱ(N))

	int root(int i) { // O(ﾎｱ(N))
		if(i != parent[i]) parent[i] = root(parent[i]);
		return parent[i];
	}

	boolean same(int x, int y) { return root(x) == root(y); } // O(ﾎｱ(N))

	HashMap<Integer, ArrayList<Integer>> groups() { // O(N)
		HashMap<Integer, ArrayList<Integer>> groups = new HashMap<>();
		for(int i = 0; i < num; i ++) {
			int root = root(i);
			if(!groups.containsKey(root)) groups.put(root, new ArrayList<>());
			groups.get(root).add(i);
		}
		return groups;
	}
}

	}
}

