	private void solve(FastIO io, String[] args) {
		/*
		 * author: 31536000
		 * ACL Contest 1 A問題
		 * 考察メモ
		 *
		 */
		io.setAutoFlush(false);
		io.setAutoOutFlush(false);
		int N = io.nextInt();
		Point[] p = io.nextPoint(N);
		PriorityQueue<Integer> pq = new PriorityQueue<>((l, r) -> Integer.compare(p[l].x, p[r].x));
		for (int i = 0;i < N;++ i) pq.add(i);
		ACL.DisjointSetUnion dsu = ACL.DisjointSetUnion.create(N);
		{
			ArrayDeque<Integer> stack = new ArrayDeque<>();
			stack.add(pq.poll());
			while(!pq.isEmpty()) {
				int x = pq.poll();
				if (p[x].y < p[stack.getLast()].y) {
					stack.addLast(x);
				} else {
					int last = stack.getLast();
					while(!stack.isEmpty() && p[x].y > p[stack.getLast()].y) {
						int poll = stack.pollLast();
						dsu.merge(x, poll);
					}
					stack.add(last);
				}
			}
		}
		for (int i = 0;i < N;++ i) io.println(dsu.getSize(i));
	}

