		int[][] town = new int[N][2];
		int[] in = new int[N+1]; //in[i] = index of town with y-coordinate i
		stmin = new int[4*N];
		stmax = new int[4*N];
		graph = new ArrayList[N+1];
		seen = new int[N];
		for (int i = 0; i <= N; i++) graph[i] = new ArrayList<Integer>();
		StringBuilder ans = new StringBuilder();
