public class Main {
    public static void main(String[] args) throws Exception {
        // Your code here!
        // Scanner sc = new Scanner(System.in);
        FastScanner sc = new FastScanner(System.in);
        int n = sc.nextInt();
        int[][] array = new int[n][3];
        for (int i = 0; i < n; i++) {
            array[i][0] = sc.nextInt()-1;   // x[i]
            array[i][1] = sc.nextInt()-1;   // y[i]
            array[i][2] = i;
        }

        // ans[i]:
        // 二次元座標において、「自分より左下の点」「自分より右上の点」に
        // 自由に行き来できる。ans[i] = 自分から行ける点の数(自分含め)
        // ex. (2,2) -> (4,5) -> (1,3)という移動が可能。

        // how:
        // 自分より右上、自分より左下の人をUnion-Findで結ぶ。
        // 1. 「←方向」に点を舐め、自分と自分のhigher(y)な点を結ぶ。
        // 2. 「↑方向」に点を舐め、自分と自分のlower(x)な点を結ぶ。
        // (それでなぜかうまく行く。)

        // a: xを昇順にソートした点
        int[][] a = new int[n][3];
        for (int i = 0; i < n; i++) {
            a[i][0] = array[i][0];
            a[i][1] = array[i][1];
            a[i][2] = array[i][2];
        }
        Arrays.sort(a, (ax, bx) -> Integer.compare(ax[0], bx[0]));

        // b: yを昇順にソートした点
        int[][] b = new int[n][3];
        for (int i = 0; i < n; i++) {
            b[i][0] = array[i][0];
            b[i][1] = array[i][1];
            b[i][2] = array[i][2];
        }
        Arrays.sort(b, (ax, bx) -> Integer.compare(ax[1], bx[1]));

        UnionFind uf = new UnionFind(n);

        // ←方向に舐める
        TreeMap<Integer, Integer> map = new TreeMap<Integer, Integer>();
        for (int i = n-1; i >= 0; i--) {
            int nowy = a[i][1];
            int idx = a[i][2];

            if (map.higherKey(nowy) != null) {
                int key = map.higherKey(nowy);
                int val = map.get(key);
                uf.unite(idx, val);
                // System.out.println(i + " " + idx + " " + val);
            }
            map.put(nowy, idx);
        }
        // System.out.println(map.toString());

        // ↑方向に舐める
        map = new TreeMap<Integer, Integer>();
        for (int i = 0; i < n; i++) {
            int nowx = b[i][0];
            int idx = b[i][2];

            if (map.lowerKey(nowx) != null) {
                int key = map.lowerKey(nowx);
                int val = map.get(key);
                uf.unite(idx, val);
                // System.out.println(i + " " + idx + " " + val);
            }
            map.put(nowx, idx);
        }
        // System.out.println(map.toString());

        // ans: 自分の属するグループの要素数
