import java.io.InputStream;
import java.util.Arrays;
import java.util.Objects;
import java.util.TreeSet;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;


public class Main {
    public static void main(String[] args) throws Exception {
        ExtendedScanner sc = new ExtendedScanner();
        FastPrintStream pw = new FastPrintStream();
        solve(sc, pw);
        sc.close();
        pw.flush();
        pw.close();
    }

    public static void solve(ExtendedScanner sc, FastPrintStream pw) {
        int n = sc.nextInt();
        IntPair3[] xy = new IntPair3[n];
        for (int i = 0; i < n; i++) {
            int x = sc.nextInt() - 1;
            int y = sc.nextInt() - 1;
            xy[i] = new IntPair3(x, y, i);
        }
        Arrays.sort(xy, (u, v) -> u.fst - v.fst);
        TreeSet<IntPair3> yset = new TreeSet<>((u, v) -> u.snd - v.snd);
        DSU dsu = new DSU(n);
        for (int i = 0; i < n; i++) {
            var p = xy[i];
            var pre = yset.lower(p);
            var last = p;
            while (pre != null) {
                last = pre;
                dsu.merge(p.trd, pre.trd);
                yset.remove(pre);
                pre = yset.lower(p);
            }
            yset.add(last);
        }
        int[][] groups = dsu.groups();
        int[] id = new int[n];
        for (int i = 0; i < groups.length; i++) {
            for (int j = 0; j < groups[i].length; j++) {
                id[groups[i][j]] = i;
            }
        }
        for (int i = 0; i < n; i++) {
            pw.println(groups[id[i]].length);
        }
    }
}

