            if(sols[0] > 0 && (int)(sols[0]) - sols[0] == 0){
                i = (int)(sols[0]);
                break;
            }
            if(sols[1] > 0 && (int)(sols[1]) - sols[0] == 0){
                i = (int)(sols[1]);
                break;
            }
        }

        System.out.println(i);

    }

    static double[] method(double a, double b, double c) {
		double[] x = {0,0};
		double d2=0, d=0;
		d2 = b*b - 4*a*c;
		if (d2 >= 0) {
			d = Math.sqrt(d2);
			x[0] = (-b + d)/(2*a);
			x[1] = (-b - d)/(2*a);
		} 
		return x;
	}
}

