	static class Tuple {
		int id, x, y, gid;
		Set<Integer> conns;

		Tuple(int id, int x, int y) {
			this.gid = -1;
			this.id = id;
			this.x = x;
			this.y = y;
			this.conns = new HashSet<>();
		}

	}

	Main(BufferedReader in) throws IOException {
		N = Integer.parseInt(in.readLine());
		x = new int[N];
		y = new int[N];
		for (int i = 0; i < N; ++i) {
			String[] tokens = in.readLine().split(" ");
			x[i] = Integer.parseInt(tokens[0]);
			y[i] = Integer.parseInt(tokens[1]);
		}
		list = new ArrayList<>(N);
		for (int i = 0; i < N; ++i) {
			list.add(new Tuple(i, x[i], y[i]));
		}
		Collections.sort(list, new Comparator<Tuple>() {
			@Override
			public int compare(Tuple o1, Tuple o2) {
				return Integer.compare(o1.x, o2.x);
			}
		});
	}

	void mark(int id, int gid, int parent) {
		list.get(id).gid = gid;
		for (Integer conn : list.get(id).conns) {
			if (conn != parent) {
				mark(conn, gid, id);
			}
		}
	}

	int update(Tuple tuple, Queue<Tuple> prevs, Queue<Tuple> nexts) {
		List<Tuple> list = new ArrayList<>();
		int yMin = tuple.y;
		while (!prevs.isEmpty()) {
			// tupleよりもyが小さいものをすべて見つける
			Tuple elem = prevs.poll();
			if (elem.y < tuple.y) {
				list.add(elem);
			} else {
				nexts.add(elem);
			}
			yMin = Math.min(yMin, elem.y);
		}
		// tupleとlistの各要素間にedgeを張る
		for (Tuple elem : list) {
			tuple.conns.add(elem.id);
			elem.conns.add(tuple.id);
		}

		Tuple next = tuple;
		for (Tuple elem : list) {
			if (elem.y < next.y) {
				next = elem;
			}
		}

		nexts.add(next);
		return yMin;
	}

	void calc() {
		Queue<Tuple> prevs = new LinkedList<>();
		Queue<Tuple> nexts = new LinkedList<>();
		prevs.add(list.get(0));
		int yMin = list.get(0).y;
		for (int i = 1; i < list.size(); ++i) {
			if (yMin > list.get(i).y) {
				// 移動できる要素がない
				prevs.add(list.get(i));
				yMin = list.get(i).y;
			} else {
				yMin = update(list.get(i), prevs, nexts);
				Queue<Tuple> temp = prevs;
				prevs = nexts;
				nexts = temp;
			}
		}

		Collections.sort(list, new Comparator<Tuple>() {
			@Override
			public int compare(Tuple o1, Tuple o2) {
				return Integer.compare(o1.id, o2.id);
			}
		});

		// gidをmarkする
		int gid = 0;
		for (int i = 0; i < list.size(); ++i) {
			if (list.get(i).gid < 0) {
				mark(i, gid, -1);
				++gid;
			}
		}

		counts = new HashMap<>();
		for (int i = 0; i < list.size(); ++i) {
			int g = list.get(i).gid;
			if (counts.containsKey(g)) {
				counts.put(g, counts.get(g) + 1);
			} else {
				counts.put(g, 1);
			}
		}

	}

	void showResult() {
		for (int i = 0; i < list.size(); ++i) {
			System.out.println(counts.get(list.get(i).gid));
		}
	}
}

import java.util.Scanner;
import java.util.Set;
import java.util.TreeSet;

public class Main {
	static int[] x;
	static int[] y;
	static Set<Integer>[] num;
	static int n;


	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);
		while(sc.hasNext()) {
			n = sc.nextInt();
			x = new int[n];
			y = new int[n];
			num = new TreeSet[n];

			for(int i = 0; i < n; i++) {
				x[i] = sc.nextInt();
				y[i] = sc.nextInt();
				num[i] = new TreeSet<Integer>();
			}

			for(int i = 0; i < n; i++) {
				System.out.println(search(i).size());
			}
		}

		sc.close();
	}

	public static Set search(int id) {
		if(!num[id].isEmpty()) {
			return num[id];
		}

		num[id].add(id);

		for(int i = 0; i < n; i++) {
			if((x[id] < x[i] && y[id] < y[i]) || (x[id] > x[i] && y[id] > y[i])) {
				num[id].addAll(search(i));
			}
		}

		return num[id];
	}
}

