public class Solver
{
    class Dsu
    {
        private readonly int[] parent;
        public int[] size;

        public Dsu(int n)
        {
            parent = Enumerable.Range(0, n).ToArray();
            size = Enumerable.Repeat(1, n).ToArray();
        }

        public int FindSet(int v)
        {
            if (v == parent[v])
                return v;
            return parent[v] = FindSet(parent[v]);
        }

        public void UnionSets(int a, int b)
        {
            a = FindSet(a);
            b = FindSet(b);
            if (a != b)
            {
                size[a] += size[b];
                parent[b] = a;
            }
        }
    }

    public void Solve()
    {
        int n = ReadInt();
        var a = new (int x, int y, int id)[n];
        for (int i = 0; i < n; i++)
            a[i] = (ReadInt(), ReadInt(), i);
        Array.Sort(a, (a1, a2) => a1.x.CompareTo(a2.x));

        var dsu = new Dsu(n);
        var stack = new Stack<int>();
        for (int i = 0; i < n; i++)
        {
            while (stack.Count > 0 && a[stack.Peek()].y > a[i].y)
                stack.Pop();
            if (stack.Count > 0)
                dsu.UnionSets(i, stack.Peek());
            stack.Push(i);
        }
        stack.Clear();
        for (int i = n - 1; i >= 0; i--)
        {
            while (stack.Count > 0 && a[stack.Peek()].y < a[i].y)
                stack.Pop();
            if (stack.Count > 0)
                dsu.UnionSets(i, stack.Peek());
            stack.Push(i);
        }

        var ans = new int[n];
        for (int i = 0; i < n; i++)
            ans[a[i].id] = dsu.size[dsu.FindSet(i)];
        WriteLines(ans);
    }

