    public void Solve()
    {
        var sc = new Scanner();
        int n = sc.NextInt();
        int[] x = new int[n];
        int[] y = new int[n];
        for (int i = 0; i < n; i++)
        {
            x[i] = sc.NextInt() - 1;
            y[i] = sc.NextInt() - 1;
        }
        var yy = new int[n];
        for (int i = 0; i < n; i++)
        {
            yy[x[i]] = y[i];
        }
        var uf = new UnionFind(n);

        var set = new Set<(int y, int leader)>((l, r) => l.y.CompareTo(r.y));
        for (int i = 0; i < n; i++)
        {
            var ny = yy[i];
            var nL = i;
            while (set.Count > 0 && set[0].y < yy[i])
            {
                var t = set[0];
                set.RemoveAt(0);
                uf.Connect(t.leader, i);
                nL = uf.Find(i);
                ny = Math.Min(ny, t.y);
            }

            set.Add((ny, nL));
        }

        var buf = new int[n];
        for (int i = 0; i < n; i++)
        {
            buf[uf.Find(i)]++;
        }

        for (int i = 0; i < n; i++)
        {
            Console.WriteLine(buf[uf.Find(x[i])]);
        }
