            if (prev >= 0) {
                d.Unite(prev, i);
            }
            var next = MoveUntil(i, n, p => segMax.Query(i, p + 1) <= y[i]) + 1;
            if (next < n) {
                d.Unite(next, i);
            }
            //new { i, prev, next, Y = y[i] }.TextDump();
