    public class DisjointSet {
        private readonly long[] group;
        public int GroupCount { get; private set; }
        public DisjointSet(int n, int[] size = null) {
            group = new long[n];
            Clear(size);
            GroupCount = n;
        }
        public bool Unite(int x, int y) {
            x = Root(x); y = Root(y);
            if (x == y) {
                return false;
            }

            if (group[y] < group[x]) {
                return Unite(y, x);
            }

            group[x] += group[y];
            group[y] = x;
            GroupCount--;
            return true;
        }
        public bool IsSameSet(int x, int y) { return Root(x) == Root(y); }
        public int Root(int x) { return group[x] < 0 ? x : (int)(group[x] = Root((int)group[x])); }
        public long Size(int x) { return -group[Root(x)]; }
        public void Clear(int[] size = null) {
            for (int i = 0; i < group.Length; i++) {
                group[i] = -(size == null ? 1 : size[i]);
            }
        }
    };

    public static int MoveUntil(int ok, int ng, Predicate<int> predicate) {
        if (ok == ng) throw new Exception();
        while (Math.Abs(ok - ng) > 1) {
            var mid = (ok + ng) >> 1;
            if (predicate(mid)) {
                ok = mid;
            } else {
                ng = mid;
            }
        }
        return ok;
    }
}


public sealed class SegmentTree<TMonoid> {
    public int Count { get; private set; }
    private TMonoid[] _node;
    private readonly TMonoid _identity;
    private readonly Func<TMonoid, TMonoid, TMonoid> _merge;

    public SegmentTree(Func<TMonoid, TMonoid, TMonoid> merge, TMonoid identity) {
        _merge = merge;
        _identity = identity;
    }

    public void Build(IList<TMonoid> array) {
        Build(array.Count, i => array[i]);
    }

    public void Build(int n, Func<int, TMonoid> create) {
        Count = n;

        _node = new TMonoid[2 * Count];

        for (int i = 0; i < n; i++) {
            _node[i + Count] = create(i);
        }

        for (int i = Count - 1; i > 0; i--) {
            _node[i] = _merge(_node[i << 1], _node[i << 1 | 1]);
        }
    }

    public void Set(int index, TMonoid val) {
        int p = index + Count;
        _node[p] = val;
        while (p > 0) {
            p >>= 1;
            _node[p] = _merge(_node[p << 1], _node[p << 1 | 1]);
        }
    }

    public TMonoid Query(int begin, int end) {
        TMonoid lv = _identity, rv = _identity;
        int l = begin + Count;
        int r = end + Count - 1;
        for (; l <= r; l >>= 1, r >>= 1) {
            if ((l & 1) == 1) { lv = _merge(lv, _node[l++]); }
            if ((r & 1) == 0) { rv = _merge(_node[r--], rv); }
        }
        return _merge(lv, rv);
    }

    public TMonoid this[int index] {
        get { return _node[index + Count]; }
        set { Set(index, value); }
    }
};
