        public PriorityQueue(Func<T, T, bool> func)
        {
            elements = new List<T>();
            compare = func;
        }

        Func<T, T, bool> compare; //T1がT2より優先度が高いか否か
        List<T> elements;
        public void Enqueue(T elem)
        {
            int n = elements.Count;
            elements.Add(elem);
            while (n != 0)
            {
                int i = (n - 1) / 2;
                //T1がT2より優先度が高ければ交換
                if (compare(elements[n], elements[i]))
                {
                    T temp = elements[n];
                    elements[n] = elements[i];
                    elements[i] = temp;
                }
                n = i;
            }
        }

        public T Dequeue()
        {
            var t = Peek();
            Pop();
            return t;
        }

        void Pop()
        {
            int n = elements.Count - 1;
            elements[0] = elements[n];
            elements.RemoveAt(n);
            for (int i = 0, j; (j = 2 * i + 1) < n;)
            {
                //左の子と右の子で右の子の方が優先度が高いなら右の子を処理したい
                if ((j != n - 1) && compare(elements[j], elements[j + 1]) == false) { j++; }
                //親より子が優先度が高いなら親子を入れ替える
                if (compare(elements[i], elements[j]) == false)
                {
                    T temp = elements[j];
                    elements[j] = elements[i];
                    elements[i] = temp;
                }
                i = j;
            }
        }

        public T Peek()
        {
            return elements[0];
        }

        public int Count()
        {
            return elements.Count;
        }
    }

    class UnionFind
    {
        int[] parents;
        public UnionFind(int n)
        {
            parents = new int[n];
            for (int i = 0; i < n; i++)
            {
                parents[i] = -1;
            }
        }

        public int Find(int x)
        {
            if (parents[x] < 0) return x;
            return parents[x] = Find(parents[x]);
        }

        public int Size(int x)
        {
            return -parents[Find(x)];
        }

        public bool Same(int x, int y)
        {
            return Find(x) == Find(y);
        }

        public bool Union(int x, int y)
        {
            x = Find(x);
            y = Find(y);
            if (x == y) return false;

            if (Size(x) < Size(y))
            {
                var tmp = x;
                x = y;
                y = tmp;
            }
            parents[x] += parents[y];
            parents[y] = x;
            return true;
        }
    }
}

