        public static void Solve()
        {
            var N = Scanner.Scan<int>();
            var IXY = new (int I, int X, int Y)[N];
            for (var i = 0; i < N; i++)
            {
                var (x, y) = Scanner.Scan<int, int>();
                IXY[i] = (i, x, y);
            }

            var dsu = new DisjointSetUnion(N);
            var remains = IXY.ToArray();
            while (remains.Any())
            {
                var item = remains[0];
                var next = new List<(int I, int X, int Y)>();
                foreach (var rem in remains)
                {
                    if (rem.I == item.I) continue;
                    if (item.X < rem.X && item.Y < rem.Y ||
                    item.X > rem.X && item.Y > rem.Y)
                        dsu.Merge(item.I, rem.I);
                    else next.Add(rem);
                }

                remains = next.ToArray();
            }

            for (var k = 0; k < N; k++)
            {
                Console.WriteLine(dsu.SizeOf(k));
            }
        }

        public static class Scanner
        {
            private static Queue<string> queue = new Queue<string>();
            public static T Next<T>()
            {
                if (!queue.Any()) foreach (var item in Console.ReadLine().Trim().Split(" ")) queue.Enqueue(item);
                return (T)Convert.ChangeType(queue.Dequeue(), typeof(T));
            }
            public static T Scan<T>() => Next<T>();
            public static (T1, T2) Scan<T1, T2>() => (Next<T1>(), Next<T2>());
