using System;
using System.Collections.Generic;
using System.Linq;

namespace AtCoderConsole
{
    class Program
    {
        static void Main(string[] args)
        {
            //入力
            int N = int.Parse(Console.ReadLine());
            var dataList = new List<int[]>();
            var ansList = new Dictionary<int, List<int[]>> ();
            for (int i = 0; i < N; i++)
            {
                // スペース区切りの整数の入力
                string[] input = Console.ReadLine().Split(' ');
                var data = new int[3];
                data[0] = i;
                data[1] = int.Parse(input[0]);
                data[2] = int.Parse(input[1]);
                dataList.Add(data);
            }

            //計算
            foreach (var ansData in dataList)
            {
                var candList = new List<int[]>();
                //数える
                candList.Add(ansData);
                candList.AddRange(dataList.Where(val => val[1] < ansData[1] && val[2] < ansData[2]));
                candList.AddRange(dataList.Where(val => val[1] > ansData[1] && val[2] > ansData[2]));

                ansList.Add(ansData[0], candList);
            }

            //計算
            foreach (var ansData in dataList)
            {
                var groupMembers = ansList.Where(val => val.Value.Contains(ansData));
                //出力
                Console.WriteLine(groupMembers.Select(val => val.Value.Count()).Max());

            }

        }
    }
}

