	static class Program
	{
		public static void Solve(Scanner cin)
		{
			int n = cin.ReadInt();
			var (x, y) = cin.ReadValueArray<int, int>(n);
			var uf = new UnionFind(n);
			var list = new List<(int x, int y, int index)>();
			for (int i = 0; i < n; i++)
			{
				list.Add((x[i], y[i], i));
			}
			list.Sort();
			var pq = new PriorityQueue<(int y, int index)>((s, t) => s.y - t.y);
			for (int i = 0; i < n; i++)
			{
				(int y, int index) min = (int.MaxValue, -1);
				while (pq.Count > 0 && pq.Peek.y < list[i].y)
				{
					var con = pq.Dequeue();
					uf.Unite(list[i].index, con.index);
					Chmin(ref min, con);
				}
				if (min.y != int.MaxValue) pq.Enqueue(min);
				pq.Enqueue((list[i].y, list[i].index));
			}
			var dic = new Dictionary<int, int>();
			for (int i = 0; i < n; i++)
			{
				var t = uf.Find(i);
				if (dic.ContainsKey(t)) dic[t]++;
				else dic.Add(t, 1);
			}
			var ans = new List<int>();
			for (int i = 0; i < n; i++)
			{
				ans.Add(dic[uf.Find(i)]);
			}
			foreach (var e in ans)
			{
				Console.WriteLine(e);
			}
		}

