public class UnionFind
{
    private int[] data;
    public UnionFind(int size)
    {
        data = new int[size];
        for (int i = 0; i < size; i++) data[i] = -1;
    }
    public bool Unite(int x, int y)
    {
        x = Root(x);
        y = Root(y);
        if (x != y)
        {
            if (data[y] < data[x])
            {
                var tmp = y;
                y = x;
                x = tmp;
            }
            data[x] += data[y];
            data[y] = x;
        }
        return x != y;
    }
    public bool IsSameGroup(int x, int y) => Root(x) == Root(y);
    public int Root(int x) => data[x] < 0 ? x : data[x] = Root(data[x]);
    public int getMem(int x) => -data[Root(x)];
}


public class P
{
    public int x { get; set; }
    public int y { get; set; }
    public int id { get; set; }
    public bool nottarg { get; set; }
}

public class Hello
{
    public static void Main()
    {
        var n = int.Parse(Console.ReadLine().Trim());
        var ps = new P[n];
        for (int i = 0; i < n; i++)
        {
            string[] line = Console.ReadLine().Trim().Split(' ');
            var x = int.Parse(line[0]);
            var y = int.Parse(line[1]);
            ps[i] = new P { id = i, x = x, y = y };
        }
        getAns(n, ps);
    }
    static void getAns(int n, P[] ps)
    {
        var uf = new UnionFind(n);
        ps = ps.OrderByDescending(x => x.x).ToArray();
        for (int i = 0; i < n - 1; i++)
        {
            var miny = int.MaxValue;
            for (int j = i + 1; j < n; j++)
            {
                if (ps[j].nottarg) continue;
                if (ps[i].y > ps[j].y)
                {
                    uf.Unite(ps[i].id, ps[j].id);
                    if (ps[j].y < miny) miny = ps[j].y;
                    else ps[j].nottarg = true;
                }
            }
        }
        var ans = new int[n];
        for (int i = 0; i < n; i++)
            ans[i] = uf.getMem(i);
        Console.WriteLine(string.Join("\n", ans));
    }
}

