    static void getAns(int n, P[] ps)
    {
        var uf = new UnionFind(n);
        ps = ps.OrderByDescending(x => x.x).ToArray();
        for (int i = 0; i < n - 1; i++)
            for (int j = i + 1; j < n; j++)
                if (ps[i].y > ps[j].y) uf.Unite(ps[i].id, ps[j].id);
