            Console.Out.Flush();
        }

        public static void Solve()
        {
            var N = Scanner.Scan<int>();
            var IXY = new (int I, int X, int Y)[N];
            for (var i = 0; i < N; i++)
            {
                var (x, y) = Scanner.Scan<int, int>();
                IXY[i] = (i, x, y);
            }

            var dsu = new DisjointSetUnion(N);
            var remains = IXY.ToArray();
            while (remains.Any())
            {
                // Console.WriteLine(string.Join(" ", remains.Select(x => x.I)));
                (int I, int X, int Y) max = (0, 0, 0);
                (int I, int X, int Y) min = (0, (int)1e9, (int)1e9);

                foreach (var rem in remains)
                {
                    if (rem.X > max.X && rem.Y > max.Y) max = rem;
                }

                foreach (var rem in remains)
                {
                    if (rem.X < min.X && rem.Y < min.Y) min = rem;
                }

                var rem1 = new List<(int I, int X, int Y)>();
                var rem2 = new List<(int I, int X, int Y)>();

                foreach (var rem in remains)
                {
                    if (max.I == rem.I) continue;
                    if (max.X > rem.X && max.Y > rem.Y) dsu.Merge(max.I, rem.I);
                    else rem1.Add(rem);
                }

                foreach (var rem in remains)
                {
                    if (min.I == rem.I) continue;
                    if (min.X < rem.X && min.Y < rem.Y) dsu.Merge(min.I, rem.I);
                    else rem2.Add(rem);
                }

                remains = rem1.Intersect(rem2).ToArray();
            }

            for (var k = 0; k < N; k++)
            {
                Console.WriteLine(dsu.SizeOf(k));
            }
        }

        public static class Scanner
        {
            private static Queue<string> queue = new Queue<string>();
            public static T Next<T>()
            {
                if (!queue.Any()) foreach (var item in Console.ReadLine().Trim().Split(" ")) queue.Enqueue(item);
                return (T)Convert.ChangeType(queue.Dequeue(), typeof(T));
            }
            public static T Scan<T>() => Next<T>();
            public static (T1, T2) Scan<T1, T2>() => (Next<T1>(), Next<T2>());
            public static (T1, T2, T3) Scan<T1, T2, T3>() => (Next<T1>(), Next<T2>(), Next<T3>());
            public static (T1, T2, T3, T4) Scan<T1, T2, T3, T4>() => (Next<T1>(), Next<T2>(), Next<T3>(), Next<T4>());
            public static (T1, T2, T3, T4, T5) Scan<T1, T2, T3, T4, T5>() => (Next<T1>(), Next<T2>(), Next<T3>(), Next<T4>(), Next<T5>());
            public static IEnumerable<T> ScanEnumerable<T>() => Console.ReadLine().Trim().Split(" ").Select(x => (T)Convert.ChangeType(x, typeof(T)));
        }
    }
}

namespace AtCoderLibraryCSharp
{
    public class DisjointSetUnion
    {
        private readonly int _n;
        private readonly int[] _parentOrSize;

        public DisjointSetUnion(int n = 0)
        {
            _n = n;
            _parentOrSize = Enumerable.Repeat(-1, n).ToArray();
        }

        public int Merge(int a, int b)
        {
            if (a < 0 || _n <= a) throw new IndexOutOfRangeException(nameof(a));
            if (b < 0 || _n <= b) throw new IndexOutOfRangeException(nameof(b));
            var (x, y) = (LeaderOf(a), LeaderOf(b));
            if (x == y) return x;
            if (-_parentOrSize[x] < -_parentOrSize[y]) (x, y) = (y, x);
            _parentOrSize[x] += _parentOrSize[y];
            _parentOrSize[y] = x;
            return x;
        }

        public bool IsSame(int a, int b)
        {
            if (a < 0 || _n <= a) throw new IndexOutOfRangeException(nameof(a));
            if (b < 0 || _n <= b) throw new IndexOutOfRangeException(nameof(b));
            return LeaderOf(a) == LeaderOf(b);
        }

        public int LeaderOf(int a)
        {
            if (a < 0 || _n <= a) throw new IndexOutOfRangeException(nameof(a));
            if (_parentOrSize[a] < 0) return a;
            return _parentOrSize[a] = LeaderOf(_parentOrSize[a]);
        }

        public int SizeOf(int a)
        {
            if (a < 0 || _n <= a) throw new IndexOutOfRangeException(nameof(a));
            return -_parentOrSize[LeaderOf(a)];
        }

        public IEnumerable<IEnumerable<int>> GetGroups()
        {
            var leaders = new int[_n];
            var groupSize = new int[_n];
            for (var i = 0; i < _n; i++)
            {
                leaders[i] = LeaderOf(i);
                groupSize[leaders[i]]++;
            }

            var ret = new List<int>[_n].Select(x => new List<int>()).ToArray();
            for (var i = 0; i < _n; i++) ret[leaders[i]].Add(i);
            return ret.Where(x => x.Any());
        }
    }
}

