class Solver {
    StreamWriter sw;
    Scan sc;
    void Prt(string a) => sw.WriteLine(a);
    void Prt<T>(IEnumerable<T> a) => Prt(string.Join(" ", a));
    void Prt(params object[] a) => Prt(string.Join(" ", a));
    public Solver(StreamWriter sw) {
        this.sw = sw;
        this.sc = new Scan();
    }

    public void solve() {
        int n = sc.Int;
        var p = new pair<P, int>[n];
        for (int i = 0; i < n; i++)
        {
            int x, y;
            sc.Multi(out x, out y);
            --x;
            --y;
            p[i] = new pair<P, int>(new P(x, y), i);
        }
        Array.Sort(p);
        var lower = new List<pair<P, int>>();
        int last = M;
        foreach (var item in p)
        {
            if (item.v1.v2 < last) {
                lower.Add(item);
                last = item.v1.v2;
            }
        }
        var uf = new UnionFind(n);
        int m = lower.Count;
        var connect = new int[m + 1];
        foreach (var item in p)
        {
            int l, r;
            {
                int ng = -1, ok = m;
                while (ng + 1 < ok) {
                    int mid = (ok + ng) / 2;
                    if (lower[mid].v1.v2 <= item.v1.v2) {
                        ok = mid;
                    }
                    else ng = mid;
                }
                l = ok;
            }
            {
                int ok = -1, ng = m;
                while (ok + 1 < ng) {
                    int mid = (ok + ng) / 2;
                    if (lower[mid].v1.v1 <= item.v1.v1) {
                        ok = mid;
                    }
                    else ng = mid;
                }
                r = ok;
            }
            if (l <= r) {
                ++connect[l];
                --connect[r];
                uf.unite(item.v2, lower[l].v2);
                uf.unite(item.v2, lower[r].v2);
            }
        }
        for (int i = 0; i < m; i++)
        {
            if (connect[i] > 0) {
                uf.unite(lower[i].v2, lower[i + 1].v2);
            }
            connect[i + 1] += connect[i];
        }
        for (int i = 0; i < n; i++)
        {
            Prt(uf.unionsize(i));
        }


    }
}

class pair<T, U> : IComparable<pair<T, U>> {
    public T v1;
    public U v2;
    public pair() : this(default(T), default(U)) {}
    public pair(T v1, U v2) { this.v1 = v1; this.v2 = v2; }
    public int CompareTo(pair<T, U> a) {
        int c = Comparer<T>.Default.Compare(v1, a.v1);
        return c != 0 ? c : Comparer<U>.Default.Compare(v2, a.v2);
    }
    public override string ToString() => v1 + " " + v2;
    public void Deconstruct(out T a, out U b) { a = v1; b = v2; }
}
