        static void Solve()
        {
            int N = Cin.Int;
            var pts = new List<(int x, int y, int id)>();
            for(var i = 0; i < N; i++)
            {
                Cin.Scanf(out int x, out int y);
                pts.Add((x, y, i));
            }
            var ans = new int[N];
            pts.Sort();
            var uf = new UnionFind(N);
            var res = new Priority_Queue<(int ymin, int id)>((x, y) => Sig(x.ymin - y.ymin));
            for(var i = 0; i < N; i++)
