using System;
using System.Collections.Generic;
using System.Linq;

namespace ProgramingLearning
{
    class Program
    {
        static void Main(string[] args)
        {
            var n = int.Parse(Console.ReadLine());
            var x = new int[n];
            var y = new int[n];

            for (int i = 0; i < n; i++)
            {
                var xy = Console.ReadLine().Split().Select(int.Parse).ToArray();
                x[i] = xy[0];
                y[i] = xy[1];
            }

            var ans = new int[n];
            var visited = new bool[n];

            for(int i = 0; i < n; i++)
            {
                if (visited[i])
                {
                    continue;
                }

                var cnt = 0;
                var list = new List<int>();
                var que = new Queue<(int, int)>();
                que.Enqueue((x[i], y[i]));

                while (que.Any())
                {
                    var (nx, ny) = que.Dequeue();

                    for(int j = 0; j < n; j++)
                    {
                        if(!list.Contains(j) 
                            && (x[j] >= nx && y[j] >= ny 
                            || x[j] <= nx && y[j] <= ny))
                        {
                            cnt++;
                            visited[j] = true;
                            list.Add(j);
                            que.Enqueue((x[j], y[j]));
                        }  
                    }
                }

                foreach(var k in list)
                {
                    ans[k] = cnt;
                }
            }

            for(int i = 0; i < n; i++)
            {
                Console.WriteLine(ans[i]);
            }
        }
    }
}

