	}

	sort.Slice(C, func(i, j int) bool {
		return C[i].x < C[j].x
	})
	uf := NewUnionFind(n)

	// 各座標を1つのスカイラインとunite
	for i := n - 1; i >= 0; i-- {
		cy := C[i].y

		j := len(S) - 1
		maxY := cy
		curIdx := C[i].idx
		for j >= 0 {
			if S[j].y > cy {
				if ChMax(&maxY, S[j].y) {
					curIdx = S[j].idx
				}
				uf.Unite(C[i].idx, S[j].idx)

				S = S[:j]
				j--
			} else {
				break
			}
		}

		S = append(S, Sky{maxY, curIdx})
	}

	for i := 0; i < n; i++ {
		ans := uf.CcSize(i)
		printf("%d\n", ans)
	}
