	})
	uf := NewUnionFind(n)

	// 各座標を1つのスカイラインとunite
	maxY := 0
	curIdx := -1
	for i := n - 1; i >= 0; i-- {
		cy := C[i].y

		if ChMax(&maxY, cy) {
			curIdx = C[i].idx
			// 追加
			S = append(S, Sky{maxY, curIdx})
		}
		uf.Unite(C[i].idx, curIdx)

		// 自分が含まれるスカイライン領域を調べる
		lbi := BinarySearch(len(S), -1, func(mid int) bool {
			return cy < S[mid].y
		})
		if lbi == len(S) {
			continue
		}
		imos[lbi]++
		imos[len(S)]--
	}
	debugf("S: %v\n", S)
	for i := 1; i <= n; i++ {
		imos[i] += imos[i-1]
