type Point struct {
	x, y, idx int
}

func main() {
	defer writer.Flush()
	N := ReadInt()
	points := make([]*Point, N)
	for i := 0; i < N; i++ {
		points[i] = &Point{
			idx: i,
			x:   ReadInt(),
			y:   ReadInt(),
		}
	}

	uf := MakeUnionFind(N)

	sort.Slice(points, func(i, j int) bool {
		return points[i].x < points[j].x
	})
	t := rbt.NewWithIntComparator()
	for _, point := range points {
		node, _ := t.Floor(point.y)
		for node != nil {
			uf.Unite(point.idx, node.Value.(*Point).idx)
			node = node.Left
		}
		t.Put(point.y, point)
	}

	sort.Slice(points, func(i, j int) bool {
		return points[i].x > points[j].x
	})
	t = rbt.NewWithIntComparator()
	for _, point := range points {
		node, _ := t.Ceiling(point.y)
		for node != nil {
			uf.Unite(point.idx, node.Value.(*Point).idx)
			node = node.Right
		}
		t.Put(point.y, point)
	}

	for i := 0; i < N; i++ {
		Println(uf.Size(i))
	}
}

type UnionFind []int

func MakeUnionFind(size int) UnionFind {
	uf := make([]int, size)
	for i := 0; i < size; i++ {
		uf[i] = -1
	}
	return uf
}
func (uf UnionFind) Root(x int) int {
	if uf[x] < 0 {
		return x
	}
	uf[x] = uf.Root(uf[x])
	return uf[x]
}
func (uf UnionFind) Unite(x, y int) {
	x, y = uf.Root(x), uf.Root(y)
	if x == y {
		return
	}
	if uf[x] > uf[y] {
		x, y = y, x
	}
	uf[x] += uf[y]
	uf[y] = x
}
func (uf UnionFind) Connected(x, y int) bool { return uf.Root(x) == uf.Root(y) }
func (uf UnionFind) Size(x int) int          { return -uf[uf.Root(x)] }

