func main(){
  var n,tmp_x, tmp_y int
  var town_x []int
  var town_y []int
  fmt.Scanf("%d", &n)
  for i:= 0 ; i < n ; i++{
    fmt.Scanf("%d %d", &tmp_x, &tmp_y)
    town_x = append(town_x, tmp_x)
    town_y = append(town_y, tmp_y)
  }

  //初期化
  var group []int
  var cnt []int
  for m:=0; m<n; m++{
    group = append(group, -1)
    cnt = append(cnt, 1)
  }

  var cnt_finished int
  cnt_finished = 0
  for j:=0; j<n; j++{
    if (cnt_finished == n){
      break;
    }
    if (group[j] != -1){//すでにグループが決まってれば抜ける
      //fmt.Printf("Town %d in Group %d/", j, group[j])
      continue
    }else{//グループが決まってなければ新しいグループを作る
        group[j] = j
        cnt_finished++
    }
    for k:= j+1; k<n; k++{
      if (cnt_finished == n){
        break;
      }
      //fmt.Printf("(%d, %d)",j,k,)
      //fmt.Println("Group:",group)
      if (group[k] != -1){//すでにグループが決まってれば抜ける
        continue
      }else if(
