type Point struct {
	x, y, idx int
}

func main() {
	N := ReadInt()
	points := make([]*Point, N)
	for i := 0; i < N; i++ {
		points[i] = &Point{
			idx: i,
			x:   ReadInt(),
			y:   ReadInt(),
		}
	}

	dsu := NewDSU(N)

	sort.Slice(points, func(i, j int) bool {
		return points[i].x < points[j].x
	})
	t := rbt.NewWithIntComparator()
	for _, point := range points {
		node, _ := t.Floor(point.y)
		for node != nil {
			dsu.Merge(point.idx, node.Value.(*Point).idx)
			node = node.Left
		}
		t.Put(point.y, point)
	}

	sort.Slice(points, func(i, j int) bool {
		return points[i].x > points[j].x
	})
	t = rbt.NewWithIntComparator()
	for _, point := range points {
		node, _ := t.Ceiling(point.y)
		for node != nil {
			dsu.Merge(point.idx, node.Value.(*Point).idx)
			node = node.Right
		}
		t.Put(point.y, point)
	}

	for i := 0; i < N; i++ {
		fmt.Println(dsu.Size(i))
	}
}

type DisjointSetUnion struct {
	n            int
	parentOrSize []int
}

func NewDSU(n int) *DisjointSetUnion {
	d := &DisjointSetUnion{
		n:            n,
		parentOrSize: make([]int, n),
	}
	for i := range d.parentOrSize {
		d.parentOrSize[i] = -1
	}
	return d
}

func (d *DisjointSetUnion) Merge(a, b int) int {
	if !(0 <= a && a < d.n) {
		panic("")
	}
	if !(0 <= b && b < d.n) {
		panic("")
	}
	x, y := d.Leader(a), d.Leader(b)
	if x == y {
		return x
	}
	if -d.parentOrSize[x] < -d.parentOrSize[y] {
		x, y = y, x
	}
	d.parentOrSize[x] += d.parentOrSize[y]
	d.parentOrSize[y] = x
	return x
}

func (d *DisjointSetUnion) Same(a, b int) bool {
	if !(0 <= a && a < d.n) {
		panic("")
	}
	if !(0 <= b && b < d.n) {
		panic("")
	}
	return d.Leader(a) == d.Leader(b)
}

func (d *DisjointSetUnion) Leader(a int) int {
	if !(0 <= a && a < d.n) {
		panic("")
	}
	if d.parentOrSize[a] < 0 {
		return a
	}
	d.parentOrSize[a] = d.Leader(d.parentOrSize[a])
	return d.parentOrSize[a]
}

func (d *DisjointSetUnion) Size(a int) int {
	if !(0 <= a && a < d.n) {
		panic("")
	}
	return -d.parentOrSize[d.Leader(a)]
}

func (d *DisjointSetUnion) Groups() [][]int {
	leaderBuf, groupSize := make([]int, d.n), make([]int, d.n)
	for i := 0; i < d.n; i++ {
		leaderBuf[i] = d.Leader(i)
		groupSize[leaderBuf[i]]++
	}
	result := make([][]int, d.n)
	for i := 0; i < d.n; i++ {
		result[i] = make([]int, 0, groupSize[i])
	}
	for i := 0; i < d.n; i++ {
		result[leaderBuf[i]] = append(result[leaderBuf[i]], i)
	}
	eraseEmpty := func(a [][]int) [][]int {
		result := make([][]int, 0, len(a))
		for i := range a {
			if len(a[i]) != 0 {
				result = append(result, a[i])
			}
		}
		return result
	}
	return eraseEmpty(result)
}

