func canReach(start int, end int, can [][]bool, path []int)bool{
  if start == end {
    return true
  }
  for i := 0; i< len(can) ; i++ {
    if !contains(path, i) && can[start][i] == true{
      path = append(path, start)
      //fmt.Printf("can reach %d to %d", start, i)
      return canReach(i, end, can, path)
    }
  }
  return false
}

func contains(s []int, e int) bool {
	for _, v := range s {
		if e == v {
			return true
		}
	}
	return false
}

