          (town_x[k] < town_x[j] && town_y[k] < town_y[j]) ){
          group[k] = group[j] //kとjがつながってる場合にJを同じグループにする
          cnt[group[k]]++ //group j の個数を増やす
          cnt_finished++
      }
    }
  }

  //fmt.Println("Group:", group)
  //fmt.Println("Cnt:", cnt)
  for l:=0 ; l< n; l++{
  	fmt.Println(cnt[group[l]])
  }
}

