        sum_size = self.sizes[self.p[x]]+self.sizes[self.p[y]]
        if self.rank[x]>self.rank[y]:
            self.p[y] = x
            self.sizes[x] = sum_size
        else:
            self.p[x] = y
            self.sizes[y] = sum_size
            if self.rank[x]==self.rank[y]:
                self.rank[y] += 1


