    styl = SegmentTree([0] * (N+1), max, 0)
    y2i = {}
    for x, y, i in xyi:
        styr.update(y, y)
        y2i[y] = i

    uf = UnionFind()
    for x, y, i in xyi:
        a = y
        while True:
            l = styl.query(0, a)
            if l == 0:
                break
            uf.union(i, y2i[l])
            a = l
            break

        a = y
        while True:
            r = styr.query(a+1, N+1)
            if r == INF:
                break
            uf.union(i, y2i[r])
            a = r + 1
            break

        styl.update(y, y)
        styr.update(y, INF)

    ans = [0] * N
    for i in range(N):
        ans[i] = uf.size(i)

    return ans


