class DisjointSet:
    def __init__(self,size):
        self.rank = [None]*size
        self.p = [None]*size
        self.sizes = [None]*size
        for i in range(size):
            self.make_set(i)
        return

    def make_set(self,x):
        self.p[x] = x
        self.rank[x] = 0
        self.sizes[x] = 1
        return

    def same(self,x,y):
        return self.find_set(x) == self.find_set(y)

    def unite(self,x,y):
        self.link(self.find_set(x),self.find_set(y))
        return

    def link(self,x,y):
        sum_size = self.sizes[self.p[x]]+self.sizes[self.p[y]]
        if self.rank[x]>self.rank[y]:
            self.p[y] = x
            self.sizes[x] = sum_size
        else:
            self.p[x] = y
            self.sizes[y] = sum_size
            if self.rank[x]==self.rank[y]:
                self.rank[y] += 1


    def find_set(self,x):
        if x != self.p[x]:
            self.p[x] = self.find_set(self.p[x])
        return self.p[x]

    def get_size(self,x):
        return self.sizes[self.find_set(x)]


