def main():
    n = int(read())
    txy = [(0, 0)] * n
    xt = [0] * n
    yt = [0] * n
    for i in range(n):
        x, y = [int(i) - 1 for i in read().split()]
        txy[i] = (x, y)
        xt[x] = i
        yt[y] = i
    x = [set() for _ in range(n)]
    y = [set() for _ in range(n)]
    for xi in range(n):
        if xi == 0:
            x[xi] = {xt[xi]}
        else:
            x[xi] = x[xi - 1] | {xt[xi]}
    for yi in range(n):
        if yi == 0:
            y[yi] = {yt[yi]}
        else:
            y[yi] = y[yi - 1] | {yt[yi]}
    seen = [False] * n
    uf = UnionFind(n)
    for i in range(n):
        if seen[i]:
            continue
        xi, yi = txy[i]
        if xi * yi == 0:
            continue
        for j in x[xi - 1] & y[yi - 1]:
            uf.union(i, j)
            seen[j] = True
    for i in range(n):
        print(uf.size(i))


