    let mut buf = ngtio::Buffer::new();
    let n = buf.usize();
    let (a, b): (Vec<_>, Vec<_>) = iter::repeat_with(|| (buf.usize() - 1, buf.usize() - 1))
        .take(n)
        .unzip();

    let mut c = vec![Max(0); n];
    for (&x, &y) in a.iter().zip(&b) {
        c[x] = Max(y);
    }
    let seg = segtree2::Segtree::from_slice(&c);
    let right = (0..n)
        .map(|i| seg.backward_partition_point(n, |&x| x < c[i]))
