    for i in 0..n {
        if i != 0 && right[i - 1] == right[i] {
            size[i] = size[i - 1];
        } else {
            size[i] = right[i] - i;
        }
    }

    let mut ans = vec![0; n];
    for (i, &x) in a.iter().enumerate() {
        ans[i] = size[x];
    }
    for &x in &ans {
        println!("{}", x);
    }
}

