struct UnionFind {
    n: usize,
    par: Vec<usize>,
    rank: Vec<usize>,
}
impl UnionFind {
    fn new(n: usize) -> Self {
        UnionFind {
            n,
            par: (0..n).collect(),
            rank: vec![1; n],
        }
    }
    fn unite(&mut self, x: usize, y: usize) {
        if self.same(x, y) {
            return;
        }
        let rx = self.par[x];
        let ry = self.par[y];
        if self.rank[rx] > self.rank[ry] {
            self.par[ry] = rx;
            self.rank[rx] += self.rank[ry];
        } else {
            self.par[rx] = ry;
            self.rank[ry] += self.rank[rx];
        }
    }
    fn same(&mut self, x: usize, y: usize) -> bool {
        self.root(x) == self.root(y)
    }
    fn root(&mut self, x: usize) -> usize {
        if self.par[x] == x {
            x
        } else {
            self.par[x] = self.root(self.par[x]);
            self.par[x]
        }
    }
    #[allow(dead_code)]
    fn size(&mut self, x: usize) -> usize {
        let r = self.root(x);
        self.rank[r]
    }
    #[allow(dead_code)]
    fn sizes(&mut self) -> Vec<usize> {
        let mut s = vec![];
        for x in 0..self.n {
            if x == self.root(x) {
                s.push(self.rank[x]);
            }
        }
        s
    }
}

#[fastout]
fn main() {
    input! {
       n: usize,
       xy: [(Usize1, Usize1); n]
    }
    let mut xyi = xy
        .iter()
        .enumerate()
        .map(|(i, &(x, y))| (x, y, i))
        .collect::<Vec<_>>();
    xyi.sort();
    let mut uf = UnionFind::new(n);
    let mut s = vec![xyi[0].1];
    for &(_, y, _) in xyi.iter().skip(1) {
        if s[s.len() - 1] < y {
            let yi = s[s.len() - 1];
            let mut yj = None;
            while let Some(s) = s.pop() {
                if s > y {
                    yj = Some(s);
                    break;
                }
                uf.unite(s, y);
            }
            if let Some(yj) = yj {
                s.push(yj);
            }
            s.push(yi);
        } else {
            s.push(y);
        }
    }
    let mut ans = vec![0; n];
    for &(_, y, i) in xyi.iter() {
        ans[i] = uf.size(y);
    }
    println!("{}", ans.iter().format("\n"));
}

