        g[x] = y;
    }
    let mut stack = vec![];
    let mut uf = UnionFind::new(N);
    for x in 0..N {
        let y = g[x];
        if stack.is_empty() {
            stack.push(x);
            continue;
        } else {
            let m = stack.len();
            if g[stack[m-1]] > y {
                stack.push(x);
                continue;
            }
            for idx in (0..m).rev() {
                if g[stack[idx]] < y {
                    uf.unite(stack[idx], x).ok();
                    if idx < m - 1 {
                        stack[idx] = stack[idx+1];
                        stack.pop();
                    }
                } else {
                    break;
                }
            }
        }
    }
    for &(x, _) in &l {
        println!("{}", uf.size(x));
    }
