        .iter()
        .enumerate()
        .map(|(i, &(x, y))| (x, y, i))
        .collect::<Vec<_>>();
    xyi.sort();
    let mut uf = UnionFind::new(n);
    let mut s = vec![];
    for &(_, y, _) in xyi.iter() {
        let mut next = vec![];
        let mut ym = y;
        for &s in s.iter() {
            if s < y {
                uf.unite(s, y);
                ym = min(ym, s);
            } else {
                next.push(s);
            }
        }
        next.push(ym);
        s = next;
    }
    let mut ans = vec![0; n];
    for &(_, y, i) in xyi.iter() {
        ans[i] = uf.size(y);
    }
    println!("{}", ans.iter().format("\n"));
}

