fn run<I: Input, O: Write>(mut kin: I, mut out: O) -> io::Result<()> {
    macro_rules! output { ($($args:expr),+) => { write!(&mut out, $($args),+)?; }; }
    macro_rules! outputln {
        ($($args:expr),+) => { output!($($args),+); outputln!(); };
        () => { output!("\n"); if cfg!(debug_assertions) { out.flush()?; } }
    }

    let n: usize = kin.input();
    let mut p = vec![0; n + 1];
    let mut t = vec![0; n + 1];
    for (i, (x, y)) in kin.iter::<(usize, usize)>().take(n).enumerate() {
        p[x] = y;
        t[y] = i;
    }

    let mut uf = UnionFind::new(n + 1);
    let mut sy = BTreeSet::new();
    for x in 1..=n {
        let mut f = false;
        for z in sy.range(..p[x]) {
            uf.unite(p[x], *z);
            f = true;
        }
        if !f {
            sy.insert(p[x]);
        }
    }

    let mut ans = vec![0; n];
    for y in 1..=n {
        ans[t[y]] = uf.size(y);
    }
    for i in 0..n {
        outputln!("{}", ans[i]);
    }

    Ok(())
}

pub struct UnionFind {
    p: Vec<isize>,
}
impl UnionFind {
    pub fn new(n: usize) -> Self {
        Self { p: vec![-1; n] }
    }
    pub fn root(&self, mut u: usize) -> usize {
        while self.p[u] >= 0 {
            u = self.p[u] as usize;
        }
        u
    }
    pub fn size(&self, u: usize) -> usize {
        (-self.p[self.root(u)]) as usize
    }
    pub fn unite(&mut self, u: usize, v: usize) -> bool {
        let mut u = self.root(u);
        let mut v = self.root(v);
        if u == v {
            return false;
        }
        if self.p[u] > self.p[v] {
            swap(&mut u, &mut v);
        }
        self.p[u] += self.p[v];
        self.p[v] = u as isize;
        true
    }
    pub fn is_same(&self, u: usize, v: usize) -> bool {
        self.root(u) == self.root(v)
    }
}

