struct UnionFind {
    size: usize,
    pos: Vec<isize>,
}
impl UnionFind {
    fn new(n: usize) -> Self {
        let size = n;
        let pos = vec![-1; n + 1];
        UnionFind { size, pos }
    }
    fn find(&mut self, x: usize) -> usize {
        if self.pos[x] < 0 {
            x
        } else {
            let v = self.pos[x] as usize;
            self.pos[x] = self.find(v) as isize;
            self.pos[x] as usize
        }
    }
    fn unite(&mut self, x: usize, y: usize) -> Result<(), ()> {
        let mut x = self.find(x);
        let mut y = self.find(y);
        if x == y {
            return Err(());
        };
        if self.pos[x] > self.pos[y] {
            std::mem::swap(&mut x, &mut y);
        }
        self.pos[x] += self.pos[y];
        self.pos[y] = x as isize;
        Ok(())
    }
    fn same(&mut self, x: usize, y: usize) -> bool {
        self.find(x) == self.find(y)
    }
    fn size(&mut self, x: usize) -> usize {
        let x = self.find(x);
        -self.pos[x] as usize
    }
}


#[fastout]
fn main() {
    input!{
        N: usize,
        l:[(Usize1, Usize1); N]
    }
    let mut g = vec![0; N];
    for &(x, y) in &l {
        g[x] = y;
    }
    let mut stack = vec![];
    let mut uf = UnionFind::new(N);
    for x in 0..N {
        let y = g[x];
        if !stack.is_empty() {
            let m = stack.len();
            for idx in (0..m).rev() {
                if g[stack[idx]] < y {
                    uf.unite(stack[idx], x).ok();
                    if idx < m - 1 {
                        stack[idx] = stack[idx+1];
                        stack.pop();
                    }
                } else {
                    break;
                }
            }
        }
        stack.push(x);
    }
    for &(x, _) in &l {
        println!("{}", uf.size(x));
    }
}

