fn solve() {
    let n = read!(usize);
    let xy = read!(usize,usize;n);
    let mut v = vec![];
    for (i,&(x,y)) in xy.iter().enumerate() {
        v.push((y,x,i));
    }
    v.sort();
    let mut id = vec![0;n];
    let mut set = BTreeSet::new();
    for &(y,x,i) in &v {
        set.insert((x,i));
    }
    let mut idx = 1;
    for (z,&(y,x,i)) in v.iter().enumerate() {
        set.remove(&(x,i));
        idx = max(idx,z+1);
        if id[i]==0 {
            id[i] = x;
        }
        for j in idx..n {
            if set.len()==0 {
                break;
            }
            let (nx,ni) = *set.iter().last().unwrap();
            if nx > x {
                set.remove(&(v[idx].1,v[idx].2));
                id[v[idx].2] = id[i];
                idx += 1;
            }
            else {
                break;
            }
        }
    }
    let mut count = vec![0;n+1];
    for &i in &id {
        count[i] += 1;
    }
    for i in 0..n {
        println!("{}",count[id[i]]);
    }
}

