use dsu::Dsu;
use seg_tree::{SegTree, SegTreeOracle};
use std::io::*;
use utils::*;

pub fn main() {
    let i = stdin();
    let mut o = Vec::new();
    run(i.lock(), &mut o).unwrap();
    stdout().write_all(&o).unwrap();
}

struct Sum;
impl SegTreeOracle for Sum {
    type S = usize;
    fn e() -> Self::S {
        0
    }
    fn op(l: Self::S, r: Self::S) -> Self::S {
        l + r
    }
}

pub fn run(i: impl BufRead, o: &mut impl Write) -> std::io::Result<()> {
    let mut i = CpReader::new(i);
    let n = i.read::<usize>();

    #[derive(Copy, Clone)]
    struct Item {
        idx: usize,
        x: usize,
    }
    let mut items = vec![
        Item {
            idx: usize::max_value(),
            x: usize::max_value()
        };
        n
    ];

    let mut idx = 0;
    for (x, y) in i.read_iter::<(usize, usize)>(n) {
        let x = x - 1;
        let y = y - 1;
        items[y] = Item { x, idx };
        idx += 1;
    }
    let mut dsu = Dsu::new(n);
    let mut t = SegTree::<Sum>::new(n);
    let mut x_to_y = vec![usize::max_value(); n];
    for y in 0..n {
        let Item { x, .. } = items[y];
        let mut has_link = false;
        for c in 0.. {
            let x1 = t.min_left(x, |i| i <= c);
            if x1 > 0 {
                let y1 = x_to_y[x1 - 1];
                has_link = true;
                dsu.merge(y, y1);
            } else {
                break;
            }
        }
        if !has_link {
            x_to_y[x] = y;
            t.set(x, 1);
        }
    }
    let mut rs = vec![0; n];
    for y in 0..n {
        let Item { idx, .. } = items[y];
        rs[idx] = dsu.size(y);
    }
    for r in rs {
        writeln!(o, "{}", r)?;
    }
    Ok(())
}

pub mod utils {
