    fn read_u64_fast<R: BufRead>(r: &mut R) -> u64 {
        let mut value = 0;
        loop {
            let buf = r.fill_buf().unwrap();
            assert!(!buf.is_empty());
            let mut idx = 0;
            while let Some(&c) = buf.get(idx) {
                if b'0' <= c && c <= b'9' {
                    value = value * 10 + (c - b'0') as u64;
                    idx += 1;
                } else {
                    r.consume(idx + 1);
                    return value;
                }
            }
            r.consume(idx);
        }
    }
    fn read_i64_fast<R: BufRead>(r: &mut R) -> i64 {
        let sign = match r.fill_buf().unwrap()[0] {
            b'+' => {
                r.consume(1);
                1
            }
            b'-' => {
                r.consume(1);
                -1
            }
            _ => 1,
        };
        read_u64_fast(r) as i64 * sign
    }
}

mod internal_bit {
    pub fn ceil_pow2(n: usize) -> usize {
        let mut x = 0;
        while (1 << x) < n {
            x += 1;
        }
        return x;
    }
}

mod helpers {
    #![allow(dead_code)]
    use std::ops::{Bound, Range, RangeBounds};

    pub fn to_range(len: usize, range: impl RangeBounds<usize>) -> Range<usize> {
        let start = match range.start_bound() {
            Bound::Included(idx) => *idx,
            Bound::Excluded(idx) => *idx + 1,
            Bound::Unbounded => 0,
        };
        let end = match range.end_bound() {
            Bound::Included(idx) => *idx + 1,
            Bound::Excluded(idx) => *idx,
            Bound::Unbounded => len,
        };
        debug_assert!(start <= end);
        debug_assert!(end <= len);
        start..end
    }
}

mod seg_tree {
    #![allow(dead_code)]
    use crate::{helpers::to_range, internal_bit::ceil_pow2};
    use std::ops::RangeBounds;

    pub struct SegTree<O: SegTreeOracle> {
        n: usize,
        d: Vec<O::S>,
        size: usize,
        log: usize,
    }

    impl<O: SegTreeOracle> SegTree<O> {
        pub fn new(n: usize) -> Self {
            let log = ceil_pow2(n);
            let size = 1 << log;
            let d = vec![O::e(); 2 * size];
            Self { n, d, size, log }
        }
        pub fn from_slice(v: &[O::S]) -> Self {
            let mut s = Self::new(v.len());
            s.d[s.size..s.size + v.len()].copy_from_slice(v);
            for i in (1..s.size).rev() {
                s.update(i);
            }
            s
        }
        pub fn from_iter(iter: impl Iterator<Item = O::S> + ExactSizeIterator) -> Self {
            let len = iter.len();
            let mut s = Self::new(len);
            let mut idx = s.size;
            for item in iter {
                s.d[idx] = item;
                idx += 1;
            }
            for i in (1..s.size).rev() {
                s.update(i);
            }
            s
        }

        #[inline]
        pub fn set(&mut self, index: usize, value: O::S) {
            let p = index + self.size;
            self.d[p] = value;
            for i in 1..=self.log {
                self.update(p >> i)
            }
        }

        #[inline]
        pub fn get(&self, index: usize) -> O::S {
            self.d[index + self.size]
        }

        pub fn prod(&self, range: impl RangeBounds<usize>) -> O::S {
            let range = to_range(self.n, range);
            let mut l = range.start;
            let mut r = range.end;
            let mut sml = O::e();
            let mut smr = O::e();
            l += self.size;
            r += self.size;
            while l < r {
                if l & 1 != 0 {
                    sml = O::op(sml, self.d[l]);
                    l += 1;
                };
                if r & 1 != 0 {
                    r -= 1;
                    smr = O::op(self.d[r], smr);
                }
                l >>= 1;
                r >>= 1;
            }
            return O::op(sml, smr);
        }
        #[inline]
        pub fn all_prod(&self) -> O::S {
            self.d[1]
        }

        pub fn max_right(&self, mut l: usize, f: impl Fn(O::S) -> bool) -> usize {
            debug_assert!(l <= self.n);
            debug_assert!(f(O::e()));
            if l == self.n {
                return self.n;
            }
            l += self.size;
            let mut sm = O::e();
            loop {
                while l % 2 == 0 {
                    l >>= 1;
                }
                if !f(O::op(sm, self.d[l])) {
                    while l < self.size {
                        l = 2 * l;
                        if f(O::op(sm, self.d[l])) {
                            sm = O::op(sm, self.d[l]);
                            l += 1;
                        }
                    }
                    return l - self.size;
                }
                sm = O::op(sm, self.d[l]);
                l += 1;
                if (l & l.wrapping_neg()) == l {
                    break;
                }
            }
            self.n
        }
        pub fn min_left(&self, mut r: usize, f: impl Fn(O::S) -> bool) -> usize {
            debug_assert!(r <= self.n);
            debug_assert!(f(O::e()));
            if r == 0 {
                return 0;
            }
            r += self.size;
            let mut sm = O::e();
            loop {
                r -= 1;
                while r > 1 && (r % 2) != 0 {
                    r >>= 1;
                }
                if !f(O::op(self.d[r], sm)) {
                    while r < self.size {
                        r = 2 * r + 1;
                        if f(O::op(self.d[r], sm)) {
                            sm = O::op(self.d[r], sm);
                            r -= 1;
                        }
                    }
                    return r + 1 - self.size;
                }
                sm = O::op(self.d[r], sm);
                if (r & r.wrapping_neg()) == r {
                    break;
                }
            }
            0
        }

        #[inline]
        fn update(&mut self, k: usize) {
            self.d[k] = O::op(self.d[2 * k], self.d[2 * k + 1]);
        }
    }

    pub trait SegTreeOracle {
        type S: Copy;
        fn e() -> Self::S;
        fn op(l: Self::S, r: Self::S) -> Self::S;
    }
}

mod dsu {
    #![allow(dead_code)]
    use std::mem::swap;

    pub struct Dsu {
        n: usize,
        parent_or_size: Vec<i32>,
    }

    impl Dsu {
        pub fn new(n: usize) -> Self {
            Self {
                n,
                parent_or_size: vec![-1; n],
            }
        }
        pub fn merge(&mut self, a: usize, b: usize) -> usize {
            debug_assert!(a < self.n);
            debug_assert!(b < self.n);
            let mut x = self.leader(a);
            let mut y = self.leader(b);
            if x == y {
                return x;
            }
            if -self.parent_or_size[x] < -self.parent_or_size[y] {
                swap(&mut x, &mut y);
            }
            self.parent_or_size[x] += self.parent_or_size[y];
            self.parent_or_size[y] = x as i32;
            x
        }
        pub fn same(&mut self, a: usize, b: usize) -> bool {
            debug_assert!(a < self.n);
            debug_assert!(b < self.n);
            self.leader(a) == self.leader(b)
        }

        pub fn leader(&mut self, a: usize) -> usize {
            debug_assert!(a < self.n);
            if self.parent_or_size[a] < 0 {
                return a;
            }
            let leader = self.leader(self.parent_or_size[a] as usize);
            self.parent_or_size[a] = leader as i32;
            leader
        }
        pub fn size(&mut self, a: usize) -> usize {
            debug_assert!(a < self.n);
            let leader = self.leader(a);
            -self.parent_or_size[leader] as usize
        }

        pub fn groups(&mut self) -> Vec<Vec<usize>> {
            let mut leader_buf = vec![0; self.n];
            let mut group_size = vec![0; self.n];
            for i in 0..self.n {
                leader_buf[i] = self.leader(i);
                group_size[leader_buf[i]] += 1;
            }
            let mut result = Vec::with_capacity(self.n);
            for i in 0..self.n {
                result.push(Vec::with_capacity(group_size[i]));
            }
            for i in 0..self.n {
                result[leader_buf[i]].push(i);
            }
            result.retain(|x| !x.is_empty());
            result
        }
    }
}

