use type_traits::{Assoc, Element};

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct Max<T>(pub T);
impl<T> Assoc for Max<T>
where
    T: Ord + Element,
