fn main() {
    let mut buf = ngtio::Buffer::new();
    let n = buf.usize();
    let (a, b): (Vec<_>, Vec<_>) = iter::repeat_with(|| (buf.usize() - 1, buf.usize() - 1))
        .take(n)
        .unzip();

    let mut c = vec![Max(0); n];
    for (&x, &y) in a.iter().zip(&b) {
        c[x] = Max(y);
    }
    let seg = segtree2::Segtree::from_slice(&c);
    let right = (0..n)
        .map(|i| seg.backward_partition_point(n, |&x| x < c[i]))
        .collect::<Vec<_>>();

    let mut size = vec![0; n];
    let mut start = 0;
    let mut end = 0usize;
    for i in 0..n {
        end.change_max(right[i]);
        if i + 1 == end {
            (start..end).for_each(|j| size[j] = end - start);
            start = end;
        }
    }

    let mut ans = vec![0; n];
    for (i, &x) in a.iter().enumerate() {
        ans[i] = size[x];
    }
    for &x in &ans {
        println!("{}", x);
    }
}

