use std::{
    fs::{File, Permissions},
    io::{self, Write as _},
    os::unix::{fs::PermissionsExt as _, process::CommandExt as _},
    process::Command,
};

fn main() -> io::Result<()> {
    let mut file = File::create(PATH)?;
    file.write_all(&decode())?;
    file.set_permissions(Permissions::from_mode(0o755))?;
    file.sync_all()?;
    drop(file);
    Err(Command::new(PATH).exec())
}

fn decode() -> Vec<u8> {
    let mut table = [0; 256];
    for (i, &c) in b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        .iter()
        .enumerate()
    {
        table[usize::from(c)] = i as u8;
    }

    let mut acc = vec![];

    for chunk in BASE64.as_bytes().chunks(4) {
        let index0 = table[usize::from(chunk[0])];
        let index1 = table[usize::from(chunk[1])];
        let index2 = table[usize::from(chunk[2])];
        let index3 = table[usize::from(chunk[3])];
        acc.push((index0 << 2) + (index1 >> 4));
        acc.push((index1 << 4) + (index2 >> 2));
        acc.push((index2 << 6) + index3);
    }

    if BASE64.ends_with("==") {
        acc.pop();
        acc.pop();
    } else if BASE64.ends_with('=') {
        acc.pop();
    }

    acc
}

static PATH: &str = "/tmp/a.out";
static BASE64: &str = "";

use io_ext::Reader;
use parse::ParseAll;
use std::io;
use std::collections::HashSet;

fn main() {
    let stdin = io::stdin();
    let mut r = Reader::new(stdin.lock());
    let n: usize = r.read_line().parse().unwrap();
    let mut buf = Vec::with_capacity(n);
    for _ in 0..n {
        let pos: (i64, i64) = r.read_line().split_whitespace().parse_all();
        buf.push(pos);
    }
    let answers = answer(&buf);
    for k in answers {
        println!("{}", k);
    }
}

fn can_arrive(p: &(i64, i64), q: &(i64, i64)) -> bool {
    (p.0 > q.0 && p.1 > q.1) || (p.0 < q.0 && p.1 < q.1)
}

fn add_arrivables(arrived: &mut HashSet<(i64, i64)>, inarrived: &mut HashSet<(i64, i64)>, pos: &(i64, i64)) {
    let ina = inarrived.clone();
    for p in &ina {
        if can_arrive(&pos, p) {
            arrived.insert(*p);
            inarrived.remove(p);
            add_arrivables(arrived, inarrived, p);
        }
    }
}

fn answer(poses: &[(i64, i64)]) -> Vec<i64> {
    let mut arrivables: Vec<HashSet<(i64, i64)>> = Vec::new();
    let mut inarrived: HashSet<_> = poses.iter().copied().collect();
    'outer: for pos in poses {
        for arrivable in &arrivables {
            if arrivable.contains(pos) {
                continue 'outer;
            }
        }
        let mut buf = HashSet::new();
        buf.insert(*pos);
        add_arrivables(&mut buf, &mut inarrived, pos);
        arrivables.push(buf);
    }

    let mut ans = Vec::with_capacity(poses.len());
    'outer: for pos in poses {
        for arrivable in &arrivables {
            if arrivable.contains(pos) {
                ans.push(arrivable.len() as i64);
                continue 'outer;
            }
        }
    }
    ans
}

