pub fn solve<R: BufRead>(mut reader: StdinReader<R>) {
    let n = reader.u();
    let xy = reader.uv2(n);

    //y[index] = x;
    //x[index]= y;
    let mut y = vec![0; n + 1];
    let mut x = vec![0; n + 1];
    for i in 0..n {
        y[xy[i].1] = xy[i].0;
        x[xy[i].0] = xy[i].1;
    }

    let mut uf = UnionFind::new(n + 1);
    let mut m = n;
    let mut y_min = n + 1;
    for i in 1..=n {
        for j in x[i]..=m {
            if y[j] > i {
                uf.unite(i, y[j]);
            }
        }
        if y_min != n + 1 {
            if x[i] > y_min {
                uf.unite(i, y[y_min]);
            }
        }
        m = min(m, x[i]);
        y_min = min(y_min, x[i]);
    }

    let mut y_max = 0;
    let mut m = 0;
    for i in (1..=n).rev() {
        for j in m..x[i] {
            if y[j] < i {
                uf.unite(i, y[j]);
            }
        }
        if y_max != 0 {
            if x[i] < y_max {
                uf.unite(i, y[y_max]);
            }
        }
        m = max(m, x[i]);
        y_max = max(y_max, x[i]);
    }

    let mut root = vec![0; n + 1];
    for i in 1..=n {
        root[i] = uf.root(i);
    }
    let mut map = HashMap::new();
    for i in 1..=n {
        *map.entry(root[i]).or_insert(0) += 1;
    }
    for i in 0..n {
        println!("{}", map.get(&root[xy[i].0]).unwrap());
    }
}

