}

impl UnionFindTree {
    fn new(n: usize) -> UnionFindTree {
        UnionFindTree {
            parent: vec![-1; n],
            size: vec![1usize; n],
            height: vec![0u64; n],
        }
    }

    fn find(&mut self, index: usize) -> usize {
        if self.parent[index] == -1 {
            return index;
        }
        let idx = self.parent[index] as usize;
        let ret = self.find(idx);
        self.parent[index] = ret as isize;
        ret
    }

    fn same(&mut self, x: usize, y: usize) -> bool {
        self.find(x) == self.find(y)
    }

    fn get_size(&mut self, x: usize) -> usize {
        let idx = self.find(x);
        self.size[idx]
    }

    fn unite(&mut self, index0: usize, index1: usize) -> bool {
        let a = self.find(index0);
        let b = self.find(index1);
        if a == b {
            false
        } else {
            if self.height[a] > self.height[b] {
                self.parent[b] = a as isize;
                self.size[a] += self.size[b];
            } else if self.height[a] < self.height[b] {
                self.parent[a] = b as isize;
                self.size[b] += self.size[a];
            } else {
                self.parent[b] = a as isize;
                self.size[a] += self.size[b];
                self.height[a] += 1;
            }
            true
        }
    }
}

use proconio::input;
use std::cmp::Ordering;

enum ParRank {
    Parent(usize),
    Rank(usize),
}

struct UnionFind {
    v: Vec<ParRank>,
}

impl UnionFind {
    fn new(n: usize) -> UnionFind {
        let mut v = Vec::new();
        for _ in 0..n {
            v.push(ParRank::Rank(1));
        }
        UnionFind { v }
    }

    fn root(&self, i: usize) -> usize {
        match self.v[i] {
            ParRank::Rank(_) => i,
            ParRank::Parent(j) => {
                let r = self.root(j);
                // self.v[i] = ParRank::Parent(r);
                r
            }
        }
    }

    fn size(&self, i: usize) -> usize {
        if let ParRank::Rank(r) = self.v[self.root(i)] {
            r
        } else {
            panic!("UnionFind: root is not root");
        }
    }

    fn unite(&mut self, i1: usize, i2: usize) -> bool {
        let r1 = self.root(i1);
        let r2 = self.root(i2);
        if r1 == r2 {
            return false;
        }
        let rank1 = if let ParRank::Rank(r) = self.v[r1] { r } else {
            panic!("UnionFind: root is not root");
        };
        let rank2 = if let ParRank::Rank(r) = self.v[r2] { r } else {
            panic!("UnionFind: root is not root");
        };
        match self.size(r1).cmp(&self.size(r2)) {
            Ordering::Less => {
                self.v[r1] = ParRank::Parent(r2);
                self.v[r2] = ParRank::Rank(rank1 + rank2);
            },
            Ordering::Equal => {
                self.v[r1] = ParRank::Parent(r2);
                self.v[r2] = ParRank::Rank(rank1 + rank2);
            },
            Ordering::Greater => {
                self.v[r2] = ParRank::Parent(r1);
                self.v[r1] = ParRank::Rank(rank1 + rank2);
            },
        }
        return true;
    }
}

fn same(xy0: (usize, usize), xy1: (usize, usize)) -> bool {
    if xy0.0 < xy1.0 && xy0.1 < xy1.1 {
        return true;
    }
    if xy0.0 > xy1.0 && xy0.1 > xy1.1 {
        return true;
    }
    return false;
}

