    };
    let mut uf = UnionFind::new(n);
    for i in 0..n {
        for j in 0..i {
            if same(xy[i], xy[j]) {
                uf.unite(i, j);
            }
        }
    }
    for i in 0..n {
        println!("{}", uf.size(i));
    }
}

