        pub fn new(n_:usize, e:i64, ini:i64)->Self{
            BIT2{n:n_, bit:vec![e;n_+1], e:e, ini:ini}
        }
        pub fn sum(&self, i:usize)->i64{
            let mut s = self.ini;
            let mut i = i as i64;
            while(i>0){
                s = s+self.bit[i as usize];
                i -= i & -i;
            }
            return s;
        }
