struct Dsu {
    n: usize,
    parent_or_size: Vec<usize>,
}

impl Dsu {
    fn new(n: usize) -> Dsu {
        Dsu { n, parent_or_size: vec![!1; n] }
    }

    fn merge(&mut self, a: usize, b: usize) -> usize {
        let (mut x, mut y) = (self.leader(a), self.leader(b));
        if x == y { return x; }
        if !self.parent_or_size[x] < !self.parent_or_size[y] {
            std::mem::swap(&mut x, &mut y);
        }
        self.parent_or_size[x] -= !self.parent_or_size[y];
        self.parent_or_size[y] = x;
        x
    }

    fn leader(&mut self, a: usize) -> usize {
        if self.parent_or_size[a] >= self.n { return a; }
        self.parent_or_size[a] = self.leader(self.parent_or_size[a]);
        self.parent_or_size[a]
    }

    fn size(&mut self, a: usize) -> usize {
        let x = self.leader(a);
        !self.parent_or_size[x]
    }
}

use std::collections::BTreeSet;

fn main() {
    let n = read_line_to_tuple!(usize);

    let mut v = Vec::with_capacity(n);
    for i in 0..n {
        let (x, y) = read_line_to_tuple!(usize, usize);
        v.push((x, y, i));
    }

    let mut dsu = Dsu::new(n);

    v.sort();
    let mut set = BTreeSet::new();
    for i in 0..n {
        if let Some(&(_, j)) = set.range(..(v[i].1, n)).next() {
            dsu.merge(i, j);
        }
        set.insert((v[i].1, i));
    }

    let mut set = BTreeSet::new();
    for i in (0..n).rev() {
        if let Some(&(_, j)) = set.range((v[i].1, 0)..).next() {
            dsu.merge(i, j);
        }
        set.insert((v[i].1, i));
    }

    let mut ans = vec![0; n];
    for i in 0..n {
        ans[v[i].2] = i;
    }

    println!(
        "{}",
        ans.iter()
            .map(|&i| dsu.size(i).to_string())
            .collect::<Vec<_>>()
            .join("\n")
    );
}

