fn solve(){
    let sssss = std::io::stdin();
    let mut sc = Scanner { stdin: sssss.lock() };
    let mut N:usize = sc.read();
    fn xxx1(a:i64, b:i64)->i64{
        cmp::max(a, b)
    }
    fn xxx2(a:i64, b:i64)->i64{
        cmp::min(a, b)
    }
    let mut stmin = segtree::new(N, xxx2, INF);
    let mut stmax = segtree::new(N, xxx1, -INF);
    let mut v = vec![vec![0i64, 0, 0];N];
    for i in 0..N{
        v[i][0] = sc.read();
        v[i][1] = sc.read();
        v[i][0]-=1;
        v[i][1]-=1;
        v[i][2] = i as i64;
    }
    v.sort();
    for i in 0..N{
        stmin.update(i, v[i][1] as i64);
        stmax.update(i, v[i][1] as i64);
    }
    let mut uf = UnionFind::init(N);
    for i in 0..N{
        let mut ub = N;
        let mut lb = i+1;
        while(ub-lb>1){
            let mut mid = (ub+lb)/2;
            if stmax.query(i+1, mid, 0, 0, stmax.n)>=v[i][1]{
                ub = mid;
            }
            else{
                lb = mid;
            }
        }
        if stmax.query(i+1, ub ,0 ,0, stmax.n)>=v[i][1]{
            uf.unite(i, ub-1);
        }

        let mut ub = 0;
        let mut lb = i;
        while(lb-ub>1){
            let mut mid = (ub+lb)/2;
            if stmin.query(mid, i, 0, 0, stmin.n)<=v[i][1]{
                ub = mid;
            }
            else{
                lb = mid;
            }
        }
        if stmin.query(ub, i ,0 ,0, stmin.n)<=v[i][1]{
            uf.unite(i, ub);
        }
    }
    let mut res = vec![0;N];
    for i in 0..N{
        res[v[i][2] as usize] = uf.check_size(i);
    }
    for i in 0..N{
        println!("{}", res[i]);
    }







}

