        self.add(a, b, x, k * 2 + 1, l, (l + r) / 2);
        self.add(a, b, x, k * 2 + 2, (l + r) / 2, r);
        self.segMin[k] = cmp::max(self.segMin[k * 2 + 1] + self.segAdd[k * 2 + 1], self.segMin[k * 2 + 2] + self.segAdd[k * 2 + 2]);
