                C[i][j] += A[i][k]*B[k][j];
            }
        }
    }
    return C;
}
fn matpow2(A:&mut Vec<Vec<ModInt>>, n:usize) -> Vec<Vec<ModInt>>{
    let mut B = vec![vec![ModInt(0);A.len()];A.len()];
    for i in 0..A.len(){
        B[i][i] = ModInt(1);
    }
    let mut n = n;
    let mut tmp = A.clone();
    while(n>0){
        if n&1 == 1{B = matmul2(&B, &tmp);}
        tmp = matmul2(&tmp, &tmp);
        n>>=1;
    }
    return B;
}




